use vstd::prelude::*;

verus! {
    fn max(a: &Vec<i32>) -> (x: usize)
        requires
            a.len() != 0,
        ensures
            0 <= x && x < a.len(),
            forall|i: int| 0 <= i && i < a.len() ==> a[i] <= a[x as int],
    {
        let mut x: usize = 0;
        let mut y: usize = a.len() - 1;
        let mut m: usize = y; // ghost candidate index

        while x != y
                invariant
                    0 <= x && x <= y && y < a.len(),
                    m == x || m == y,
                    forall|i: int| 0 <= i && i < x ==> a[i] <= a[m as int],
                    forall|i: int| y < i && i < a.len() ==> a[i] <= a[m as int],
             decreases
                y - x
        {
            if a[x] <= a[y] {
                x = x + 1;
                m = y;
            } else {
                y = y - 1;
                m = x;
            }
        }

        x
    }

    // Helper to check postcondition at runtime
    fn is_max_index(a: &Vec<i32>, idx: usize) -> bool {
        if a.len() == 0 { return false; }
        if idx >= a.len() { return false; }
        let v = a[idx];
        let mut i: usize = 0;
        while i < a.len() {
            if a[i] > v { return false; }
            i += 1;
        }
        true
    }

    fn compute_max_i32(a: &Vec<i32>) -> i32 {
        let mut m = a[0];
        let mut i: usize = 1;
        while i < a.len() {
            if a[i] > m { m = a[i]; }
            i += 1;
        }
        m
    }

    fn main() {
        // 1) Single element
        let a1 = vec![42];
        let i1 = max(&a1);
        assert!(i1 == 0);
        assert!(is_max_index(&a1, i1));
        assert!(a1[i1] == compute_max_i32(&a1));

        // 2) Strictly increasing
        let a2 = vec![1, 2, 3, 4, 5];
        let i2 = max(&a2);
        assert!(is_max_index(&a2, i2));
        assert!(a2[i2] == 5);

        // 3) Strictly decreasing
        let a3 = vec![9, 7, 5, 3, 1];
        let i3 = max(&a3);
        assert!(is_max_index(&a3, i3));
        assert!(i3 == 0);
        assert!(a3[i3] == 9);

        // 4) Multiple maxima
        let a4 = vec![5, 3, 5, 2, 5];
        let i4 = max(&a4);
        assert!(is_max_index(&a4, i4));
        assert!(a4[i4] == 5);

        // 5) Negative values with repeated maxima
        let a5 = vec![-10, -3, -4, -3];
        let i5 = max(&a5);
        assert!(is_max_index(&a5, i5));
        assert!(a5[i5] == -3);

        // 6) Max in the middle
        let a6 = vec![1, 3, 7, 4, 2];
        let i6 = max(&a6);
        assert!(is_max_index(&a6, i6));
        assert!(i6 == 2);
        assert!(a6[i6] == 7);

        // 7) All elements equal
        let a7 = vec![8, 8, 8, 8];
        let i7 = max(&a7);
        assert!(is_max_index(&a7, i7));
        assert!(a7[i7] == 8);

        // 8) Two elements
        let a8 = vec![0, -1];
        let i8 = max(&a8);
        assert!(is_max_index(&a8, i8));
        assert!(a8[i8] == 0);

        // 9) Values near i32 boundaries
        let a9 = vec![i32::MIN, 0, i32::MAX - 1, i32::MAX];
        let i9 = max(&a9);
        assert!(is_max_index(&a9, i9));
        assert!(a9[i9] == i32::MAX);
    }
}

