use vstd::prelude::*;
use vstd::seq::*;

verus! {

fn MaxDifference(a: Vec<int>) -> (diff: int)
    requires a.len() > 1,
    ensures forall|i: int, j: int| 
        0 <= i && i < a.len() && 0 <= j && j < a.len() ==> a[i] - a[j] <= diff,
{
    let mut minVal = a[0];
    let mut maxVal = a[0];

    let mut i = 1;
    while i < a.len() 
        invariant 
            1 <= i <= a.len(),
            minVal <= maxVal,
            forall|k: int| 0 <= k < i ==> minVal <= a[k] && a[k] <= maxVal,
        decreases
            a.len()-i
    {
        if a[i] < minVal {
            minVal = a[i];
        } else if a[i] > maxVal {
            maxVal = a[i];
        }
        i += 1;
    }

    maxVal - minVal
}

fn main() {
    // Length-2 minimal valid input
    let a1: Vec<int> = vec![1, 2];
    let r1 = MaxDifference(a1);
    assert!(r1 == 1);

    // All elements equal
    let a2: Vec<int> = vec![5, 5, 5, 5];
    let r2 = MaxDifference(a2);
    assert!(r2 == 0);

    // Mixed positive and negative values
    let a3: Vec<int> = vec![5, -2, 9, 4];
    let r3 = MaxDifference(a3);
    assert!(r3 == 11); // 9 - (-2)

    // All negative values
    let a4: Vec<int> = vec![-10, -3, -7, -1];
    let r4 = MaxDifference(a4);
    assert!(r4 == 9); // -1 - (-10)

    // Includes zeroes
    let a5: Vec<int> = vec![0, 0, 0, 0];
    let r5 = MaxDifference(a5);
    assert!(r5 == 0);

    // Large magnitude values (no overflow in mathematical integers)
    let a6: Vec<int> = vec![1000000, -1000000];
    let r6 = MaxDifference(a6);
    assert!(r6 == 2000000);

    // General case with varied values
    let a7: Vec<int> = vec![3, 1, 2, 100, 50, -50];
    let r7 = MaxDifference(a7);
    assert!(r7 == 150); // 100 - (-50)
}
}

