fn main() {
    // Test 1: Standard rotation
    let a1: Vec<int> = vec![1, 2, 3, 4, 5];
    let r1 = rotate(a1.clone(), 2usize);
    let expected1: Vec<int> = vec![3, 4, 5, 1, 2];
    assert(r1 == expected1);

    // Test 2: Zero offset should return the same array
    let a2: Vec<int> = vec![7, 8, 9];
    let r2 = rotate(a2.clone(), 0usize);
    assert(r2 == a2);

    // Test 3: Offset equal to length should return the same array
    let a3: Vec<int> = vec![10, 20, 30, 40];
    let r3 = rotate(a3.clone(), 4usize);
    assert(r3 == a3);

    // Test 4: Offset greater than length
    let a4: Vec<int> = vec![1, 2, 3];
    let r4 = rotate(a4.clone(), 5usize);
    let expected4: Vec<int> = vec![3, 1, 2];
    assert(r4 == expected4);

    // Test 5: Single element array with large offset
    let a5: Vec<int> = vec![42];
    let r5 = rotate(a5.clone(), 100usize);
    assert(r5 == a5);

    // Test 6: Empty array with non-zero offset
    let a6: Vec<int> = Vec::new();
    let r6 = rotate(a6.clone(), 3usize);
    assert(r6.len() == 0);

    // Test 7: Very large offset within bounds
    let a7: Vec<int> = vec![1, 2, 3, 4];
    let r7 = rotate(a7.clone(), 999999usize);
    let expected7: Vec<int> = vec![4, 1, 2, 3];
    assert(r7 == expected7);

    // Test 8: Boundary offset just below 1,000,000
    let a8: Vec<int> = vec![5, 6];
    let r8 = rotate(a8.clone(), 999999usize);
    let expected8: Vec<int> = vec![6, 5];
    assert(r8 == expected8);
}
