use vstd::prelude::*;
use vstd::seq::*;

verus! {

/// Finds the index of the maximum element in a non-empty array.
fn find_max(a: &[i32]) -> (max_idx: usize)
    requires
        a.len() > 0,
    ensures
        0 <= max_idx && max_idx < a.len(),
        forall|j: int| 0 <= j < a.len() ==> a[max_idx as int] >= a[j],
{
    let mut max_idx: usize = 0;
    let mut i: usize = 1;

    while i < a.len()
        invariant
            1 <= i && i <= a.len(),
            0 <= max_idx && max_idx < i,
            forall|j: int| 0 <= j < i as int ==> a[max_idx as int] >= a[j],
        decreases a.len() - i
    {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
        i += 1;
    }

    max_idx
}

} // end verus!

fn main() {
    // 1. Single element
    let a1 = [42];
    let idx1 = find_max(&a1);
    assert_eq!(idx1, 0);
    assert!(idx1 < a1.len());
    assert_eq!(a1[idx1], *a1.iter().max().unwrap());

    // 2. All equal elements
    let a2 = [7, 7, 7, 7];
    let idx2 = find_max(&a2);
    assert!(idx2 < a2.len());
    assert_eq!(a2[idx2], *a2.iter().max().unwrap());
    // Given the implementation, the first occurrence is chosen
    assert_eq!(idx2, 0);

    // 3. Strictly increasing
    let a3 = [1, 2, 3, 4, 5];
    let idx3 = find_max(&a3);
    assert_eq!(idx3, a3.len() - 1);
    assert_eq!(a3[idx3], 5);

    // 4. Strictly decreasing
    let a4 = [9, 7, 5, 3, 1];
    let idx4 = find_max(&a4);
    assert_eq!(idx4, 0);
    assert_eq!(a4[idx4], 9);

    // 5. Mixed negatives
    let a5 = [-10, -3, -20, -3, -1, -100];
    let idx5 = find_max(&a5);
    assert_eq!(a5[idx5], *a5.iter().max().unwrap());

    // 6. Contains extreme values
    let a6 = [i32::MIN, -1, 0, i32::MAX, 123456789, -987654321];
    let idx6 = find_max(&a6);
    assert_eq!(a6[idx6], i32::MAX);
    assert_eq!(idx6, 3);

    // 7. Multiple maxima (should choose first occurrence)
    let a7 = [5, 3, 5, 2, 5];
    let idx7 = find_max(&a7);
    assert_eq!(a7[idx7], 5);
    assert_eq!(idx7, 0);

    // 8. Boundary: two elements
    let a8 = [100, 50];
    let idx8 = find_max(&a8);
    assert_eq!(idx8, 0);
    assert_eq!(a8[idx8], 100);

    // 9. Boundary: two elements with second larger
    let a9 = [-100, 0];
    let idx9 = find_max(&a9);
    assert_eq!(idx9, 1);
    assert_eq!(a9[idx9], 0);

    // Note: Do not call find_max with an empty array because its precondition requires a non-empty input.
    let empty: [i32; 0] = [];
    assert!(empty.len() == 0);
}

