use vstd::prelude::*;

verus! {

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> (result: bool)
    ensures
        result ==> exists|i: int, j: int| 0 <= i < a.len() && 0 <= j < b.len() && a[i] == b[j],
        !result ==> forall|i: int, j: int| 0 <= i < a.len() && 0 <= j < b.len() ==> a[i] != b[j],
{
    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i && i <= a.len(),
            forall|k: int, j: int| 0 <= k && k < i as int && 0 <= j && j < b.len() ==> a[k] != b[j],
        decreases
            a.len() - i
    {
        let mut j: usize = 0;
        while j < b.len()
            invariant
                0 <= j && j <= b.len(),
                forall|k: int| 0 <= k && k < j as int ==> a[i as int] != b[k],
                i < a.len(),
            decreases
            b.len() - j
        {
            if a[i] == b[j] {
                return true;
            }
            j += 1;
        }
        i += 1;
    }

    false
}

fn main() {
    // 1. Both arrays empty -> no common element
    assert_eq!(has_common_element(vec![], vec![]), false);

    // 2. One empty, one non-empty -> no common element
    assert_eq!(has_common_element(vec![1, 2, 3], vec![]), false);

    // 3. Single-element arrays with the same element -> common
    assert_eq!(has_common_element(vec![7], vec![7]), true);

    // 4. Single-element arrays with different elements -> no common
    assert_eq!(has_common_element(vec![7], vec![8]), false);

    // 5. Multiple elements with a common value
    assert_eq!(has_common_element(vec![1, 2, 3], vec![4, 5, 3]), true);

    // 6. Multiple elements with no common value
    assert_eq!(has_common_element(vec![1, 2, 3], vec![4, 5, 6]), false);

    // 7. Duplicates present with a common value
    assert_eq!(has_common_element(vec![1, 1, 1], vec![2, 1]), true);

    // 8. Negative and positive values with common element
    assert_eq!(has_common_element(vec![-10, 0, 5], vec![-10, 10]), true);

    // 9. Negative and positive values with no common element
    assert_eq!(has_common_element(vec![-1, -2], vec![1, 2]), false);

    // 10. Boundary values: i32::MIN and i32::MAX
    assert_eq!(has_common_element(vec![i32::MIN], vec![i32::MIN, i32::MAX]), true);
    assert_eq!(has_common_element(vec![i32::MIN, 0], vec![i32::MAX, 100]), false);
}

}

