use vstd::prelude::*;

verus! {

// Specification helpers
spec fn contains(v: int, a: &Seq<int>, n: int) -> bool {
    exists|j: int| 0 <= j && j < n && a[j] == v
}

spec fn upper_bound(v: int, a: &Seq<int>, n: int) -> bool {
    forall|j: int| 0 <= j && j < n ==> a[j] <= v
}

spec fn is_max(m: int, a: &Seq<int>, n: int) -> bool {
    &&& contains(m, a, n)
    &&& upper_bound(m, a, n)
}

// Target function
fn max(a: &Vec<int>, n: usize) -> (max: int)
    requires
        0 < n && n <= a.len(),
        n < 1000,
    ensures
        is_max(max, &a@, n as int),
{
    let mut i: usize = 1;
    let mut max = a[0];

    while i < n
        invariant
            1 <= i && i <= n,
            n <= a.len(),
            is_max(max, &a@, i as int),
        decreases
            n - i
    {
        if a[i] > max {
            max = a[i];
        }
        i = i + 1;
    }

    max
}

fn main() {
    // Test 1: ascending sequence, n = full length
    let a1: Vec<int> = vec![1, 2, 3, 4, 5];
    let r1 = max(&a1, 5);
    assert!(r1 == 5);

    // Test 2: single element
    let a2: Vec<int> = vec![42];
    let r2 = max(&a2, 1);
    assert!(r2 == 42);

    // Test 3: mixed negatives
    let a3: Vec<int> = vec![-10, -3, -100, -1];
    let r3 = max(&a3, 4);
    assert!(r3 == -1);

