fn main() {
    // 1) Empty vector
    let v: Vec<i128> = vec![];
    let r = square_elements(v);
    assert_eq!(r, Vec::<i128>::new());

    // 2) Single element zero
    let v = vec![0_i128];
    let r = square_elements(v);
    assert_eq!(r, vec![0_i128]);

    // 3) Single negative element
    let v = vec![-5_i128];
    let r = square_elements(v);
    assert_eq!(r, vec![25_i128]);

    // 4) Positive small numbers
    let v = vec![1_i128, 2, 3, 4];
    let r = square_elements(v);
    assert_eq!(r, vec![1_i128, 4, 9, 16]);

    // 5) Mixed negatives and positives
    let v = vec![-3_i128, 7, -2, 5];
    let r = square_elements(v);
    assert_eq!(r, vec![9_i128, 49, 4, 25]);

    // 6) Large values within i128 range
    let v = vec![1_000_000_000_i128, -1_000_000_000_i128]; // 1e9
    let r = square_elements(v);
    assert_eq!(r, vec![1_000_000_000_000_000_000_i128, 1_000_000_000_000_000_000_i128]); // 1e18

    // 7) Powers of two near the high range (still safe in i128)
    let p: i128 = 1_i128 << 60; // 2^60
    let v = vec![p, -p];
    let r = square_elements(v);
    // (2^60)^2 = 2^120 fits in i128
    let expected = vec![(p * p), (p * p)];
    assert_eq!(r, expected);

    // 8) Duplicates and zeros
    let v = vec![0_i128, -1, 1, -1, 0];
    let r = square_elements(v);
    assert_eq!(r, vec![0_i128, 1, 1, 1, 0]);

    // 9) Mixed including one large and small values
    let v = vec![2_i128, -3, 10_000_i128, -10_000_i128, 1];
    let r = square_elements(v);
    assert_eq!(r, vec![4_i128, 9, 100_000_000, 100_000_000, 1]);

    println!("All tests passed.");
}

