fn invert_array(a: &mut Vec<i32>) {
    let n = a.len();
    let mut i = 0usize;
    while i < n / 2 {
        let j = n - 1 - i;
        a.swap(i, j);
        i += 1;
    }
}

fn assert_eq_vec<T: PartialEq + Debug>(a: &Vec<T>, b: &Vec<T>) {
    assert_eq!(a, b, "left: {:?}, right: {:?}", a, b);
}

fn main() {
    // Edge case: empty array
    let mut v0: Vec<i32> = vec![];
    invert_array(&mut v0);
    assert_eq_vec(&v0, &vec![]);

    // Edge case: single element
    let mut v1 = vec![42];
    invert_array(&mut v1);
    assert_eq_vec(&v1, &vec![42]);

    // Small even length
    let mut v2 = vec![1, 2];
    invert_array(&mut v2);
    assert_eq_vec(&v2, &vec![2, 1]);

    // Small odd length
    let mut v3 = vec![1, 2, 3];
    invert_array(&mut v3);
    assert_eq_vec(&v3, &vec![3, 2, 1]);

