fn is_decimal_with_two_precision(s: &[u8]) -> (result: bool)
    ensures
        result ==> exists|i: int| 0 <= i < s.len() && s[i] == '.' as u8 && s.len() - i - 1 == 2,
        !result ==> !(exists|i: int| 0 <= i < s.len() && s[i] == '.' as u8 && s.len() - i - 1 == 2),
{
    let mut result = false;
    let mut i: usize = 0;

    while i < s.len()
        invariant
            0 <= i && i <= s.len(),
            result <==> exists|k: int| 0 <= k && k < i && s[k as int] == '.' as u8 && s.len() - k - 1 == 2,
        decreases 
            s.len() - i
    {
        if s[i] == '.' as u8 && s.len() - i - 1 == 2 {
            result = true;
        }
        i += 1;
    }

    result
}

fn main() {
    // Happy path: dot with exactly two trailing characters at end
    assert(is_decimal_with_two_precision(b"12.34"));
    assert(is_decimal_with_two_precision(b"ab.cd"));

    // Edge cases: empty and single/triple-length variations
    assert(!is_decimal_with_two_precision(b""));
    assert(!is_decimal_with_two_precision(b".a")); // only one char after dot
    assert(is_decimal_with_two_precision(b".ab")); // exactly two after dot

    // Multiple dots: true if any dot is positioned so exactly two chars follow to the end
    assert(is_decimal_with_two_precision(b"....")); // dot at index 1 satisfies condition

    // No matching dot position
    assert(!is_decimal_with_two_precision(b"abc.")); // dot at last position -> 0 trailing chars
    assert(!is_decimal_with_two_precision(b"12.3")); // only one trailing char
    assert(!is_decimal_with_two_precision(b"12.345")); // three trailing chars
    assert(!is_decimal_with_two_precision(b"xyz")); // no dot at all

    // Dot present but not at required position
    assert(!is_decimal_with_two_precision(b"x.yz!"));
}

}

