use std::fmt::Debug;

fn max_array_std(a: &[i64]) -> i64 {
    // Precondition: non-empty array
    assert!(!a.is_empty(), "Input array must be non-empty");
    let mut m = a[0];
    for &x in a.iter().skip(1) {
        if x > m {
            m = x;
        }
    }
    m
}

fn assert_max_properties<T: PartialOrd + Eq + Copy + Debug>(a: &[T], m: T) {
    // Postcondition 1: m >= a[k] for all valid k
    for &x in a {
        assert!(m >= x, "Returned value must be >= every element; m={:?}, x={:?}", m, x);
    }
    // Postcondition 2: exists k such that m == a[k]
    assert!(a.iter().any(|&x| x == m), "Returned value must equal some element in the array");
}

fn main() {
    // 1. Single element
    let a1 = vec![42i64];
    let m1 = max_array_std(&a1);
    assert_eq!(m1, 42);
    assert_max_properties(&a1, m1);

    // 2. Two elements ascending
    let a2 = vec![1, 2];
    let m2 = max_array_std(&a2);
