fn max(a: Vec<u64>) -> i64 {
    if a.is_empty() {
        return -1;
    }
    let mut i: usize = 0;
    let mut m: i64 = a[0] as i64;
    while i < a.len() {
        let v = a[i] as i64;
        if v >= m {
            m = v;
        }
        i += 1;
    }
    m
}

fn main() {
    // Edge case: empty array
    assert_eq!(max(vec![]), -1);

    // Single element
    assert_eq!(max(vec![10_u64]), 10_i64);

    // Happy path: increasing values
    assert_eq!(max(vec![1, 2, 3, 50, 5, 51]), 51);

    // Decreasing values
    assert_eq!(max(vec![5, 4, 3, 2, 1]), 5);

    // All equal values
    assert_eq!(max(vec![3, 3, 3]), 3);

    // Boundary: value exceeding i64::MAX when interpreted as u64; cast to i64 becomes -1
    assert_eq!(max(vec![u64::MAX]), -1_i64);

    // Mixed around i64::MAX boundary
    assert_eq!(max(vec![i64::MAX as u64, (i64::MAX as u64) + 1, 7]), i64::MAX);

    // Middle element is the maximum
    assert_eq!(max(vec![9, 100, 8]), 100);
}

