fn find(a: Vec<i32>, key: i32) -> usize {
    let mut index: usize = 0;
    while index < a.len() && a[index] != key {
        index += 1;
    }
    index
}

fn assert_first_occurrence_properties(a: &Vec<i32>, key: i32, idx: usize) {
    // Range property
    assert!(idx <= a.len());
    if idx < a.len() {
        // Element at idx equals key
        assert!(a[idx] == key);
        // No earlier element equals key (first occurrence property)
        for j in 0..idx {
            assert!(a[j] != key);
        }
    } else {
        // Absent case: verify that key does not appear anywhere
        for j in 0..a.len() {
            assert!(a[j] != key);
        }
    }
}

fn main() {
    // 1) Single-element array, key present at index 0
    let a1 = vec![42];
    let idx1 = find(a1.clone(), 42);
    assert_first_occurrence_properties(&a1, 42, idx1);
    assert!(idx1 == 0);

    // 2) Single-element array, key absent -> return len (1)
    let a2 = vec![7];
    let idx2 = find(a2.clone(), 5);
    assert_first_occurrence_properties(&a2, 5, idx2);
    assert!(idx2 == a2.len());

    // 3) Multiple elements, key appears once in the middle
    let a3 = vec![1, 3, 5, 7, 9];
    let idx3 = find(a3.clone(), 7);
    assert_first_occurrence_properties(&a3, 7, idx3);
    assert!(idx3 == 3);

    // 4) Multiple elements, key appears multiple times; must return first occurrence
    let a4 = vec![2, 4, 4, 4, 6];
    let idx4 = find(a4.clone(), 4);
    assert_first_occurrence_properties(&a4, 4, idx4);
    assert!(idx4 == 1);

    // 5) Key present at the last index
    let a5 = vec![10, 20, 30];
    let idx5 = find(a5.clone(), 30);
    assert_first_occurrence_properties(&a5, 30, idx5);
    assert!(idx5 == 2);

    // 6) Key absent in larger array
    let a6 = vec![5, 6, 7, 8, 9, 10];
    let idx6 = find(a6.clone(), 4);
    assert_first_occurrence_properties(&a6, 4, idx6);
    assert!(idx6 == a6.len());

    // 7) Contains negative numbers; key negative present
    let a7 = vec![-3, -2, -1, 0, 1];
    let idx7 = find(a7.clone(), -2);
    assert_first_occurrence_properties(&a7, -2, idx7);
    assert!(idx7 == 1);

    // 8) Larger array with no key
    let a8: Vec<i32> = (0..100).collect();
    let idx8 = find(a8.clone(), 200);
    assert_first_occurrence_properties(&a8, 200, idx8);
    assert!(idx8 == a8.len());
}

