use std::vec::Vec;

fn reverse(a: &[char]) -> Vec<char> {
    // Simple reference implementation for testing
    let mut b: Vec<char> = Vec::with_capacity(a.len());
    let mut i = 0usize;
    while i < a.len() {
        b.push(a[a.len() - 1 - i]);
        i += 1;
    }
    b
}

fn to_chars(s: &str) -> Vec<char> {
    s.chars().collect()
}

fn main() {
    // Constraint boundary: minimum allowed size (1)
    let input1 = to_chars("a");
    let out1 = reverse(&input1);
    assert_eq!(out1, to_chars("a"));

    // Small even length
    let input2 = to_chars("ab");
    let out2 = reverse(&input2);
    assert_eq!(out2, to_chars("ba"));

    // Palindrome
    let input3 = to_chars("racecar");
    let out3 = reverse(&input3);
    assert_eq!(out3, to_chars("racecar"));

    // Typical word
    let input4 = to_chars("hello");
    let out4 = reverse(&input4);
    assert_eq!(out4, to_chars("olleh"));

    // Repeated characters
    let input5 = to_chars("aaab");
    let out5 = reverse(&input5);
    assert_eq!(out5, to_chars("baaa"));

    // Unicode emojis
    let input6 = to_chars("🙂🙃😉");
    let out6 = reverse(&input6);
    assert_eq!(out6, to_chars("😉🙃🙂"));

    // Whitespace and punctuation
    let input7 = to_chars("A b!");
    let out7 = reverse(&input7);
    assert_eq!(out7, to_chars("!b A"));

    // Digits sequence
    let input8 = to_chars("12345");
    let out8 = reverse(&input8);
    assert_eq!(out8, to_chars("54321"));
}

