verus! {

fn min_array(a: Vec<int>) -> (r: int)
    requires
        a.len() > 0,
    ensures
        forall|i: int| 0 <= i < a.len() ==> r <= a[i],
        exists|i: int| 0 <= i < a.len() && r == a[i],
{
    let mut r = a[0];
    let mut i = 1;
    while i < a.len() 
        invariant
            0 <= i && i <= a.len(),
            forall|x: int| 0 <= x < i ==> r <= a[x],
            exists|x: int| 0 <= x < i && r == a[x],
        decreases
            a.len() - i
    {
        if r > a[i] {
            r = a[i];
        }
        i = i + 1;
    }
    r
}

fn main() {
    // Happy path
    let v1: Vec<int> = vec![5, 3, 8, 2, 7];
    assert(min_array(v1) == 2);

    // Single-element array
    let v2: Vec<int> = vec![42];
    assert(min_array(v2) == 42);

    // Negative values
    let v3: Vec<int> = vec![-1, -2, -3, -4];
    assert(min_array(v3) == -4);

    // Duplicates including multiple minima
    let v4: Vec<int> = vec![7, 7, 7, 7];
    assert(min_array(v4) == 7);

    // Ascending sorted array
    let v5: Vec<int> = vec![1, 2, 3, 4, 5];
    assert(min_array(v5) == 1);

    // Descending sorted array
    let v6: Vec<int> = vec![9, 8, 7, 6, 5];
    assert(min_array(v6) == 5);

    // Mixed with zero
    let v7: Vec<int> = vec![0, 10, -10, 5, -3];
    assert(min_array(v7) == -10);

    // Large magnitude integers (Verus 'int' is unbounded)
    let v8: Vec<int> = vec![1_000_000_000_000, -1_000_000_000_000, 999_999_999_999];
    assert(min_array(v8) == -1_000_000_000_000);

    // Edge case: empty array would violate the precondition and is intentionally not tested.
}

}

