use std::vec::Vec;

fn linear_search(a: &Vec<i32>, target: i32) -> usize {
    let mut n: usize = 0;
    while n != a.len() {
        if a[n] == target {
            return n;
        }
        n += 1;
    }
    n
}

fn check_spec(a: &Vec<i32>, target: i32, idx: usize) {
    // Postcondition 1: 0 <= idx <= a.len()
    assert!(idx <= a.len());

    if idx < a.len() {
        // Postcondition 2: a[idx] == target
        assert!(a[idx] == target);
        // Postcondition 3: no earlier index holds target
        for i in 0..idx {
            assert!(a[i] != target);
        }
    } else {
        // idx == a.len(): target not present anywhere
        for i in 0..a.len() {
            assert!(a[i] != target);
        }
    }
}

fn main() {
    // 1) Empty array
    let a1: Vec<i32> = vec![];
    let t1 = 5;
    let r1 = linear_search(&a1, t1);
    assert!(r1 == 0);
    check_spec(&a1, t1, r1);

    // 2) Single-element, target present
    let a2 = vec![3];
    let t2 = 3;
    let r2 = linear_search(&a2, t2);
    assert!(r2 == 0);
    check_spec(&a2, t2, r2);

    // 3) Single-element, target absent
    let a3 = vec![3];
    let t3 = 4;
    let r3 = linear_search(&a3, t3);
    assert!(r3 == 1);
    check_spec(&a3, t3, r3);

    // 4) Multiple elements with duplicates; first occurrence should be returned
    let a4 = vec![1, 2, 3, 2, 2];
    let t4 = 2;
    let r4 = linear_search(&a4, t4);
    assert!(r4 == 1);
    check_spec(&a4, t4, r4);

    // 5) Target absent in non-empty array
    let a5 = vec![1, 1, 1];
    let t5 = 2;
    let r5 = linear_search(&a5, t5);
    assert!(r5 == 3);
    check_spec(&a5, t5, r5);

    // 6) Target at the first position
    let a6 = vec![7, 8, 9];
    let t6 = 7;
    let r6 = linear_search(&a6, t6);
    assert!(r6 == 0);
    check_spec(&a6, t6, r6);

    // 7) Target at the last position
    let a7 = vec![4, 5, 6];
    let t7 = 6;
    let r7 = linear_search(&a7, t7);
    assert!(r7 == 2);
    check_spec(&a7, t7, r7);

    // 8) Negative numbers and duplicates
    let a8 = vec![-1, -2, -3, -2];
    let t8 = -2;
    let r8 = linear_search(&a8, t8);
    assert!(r8 == 1);
    check_spec(&a8, t8, r8);

    // 9) All elements equal to target: should return 0
    let a9 = vec![5, 5, 5, 5];
    let t9 = 5;
    let r9 = linear_search(&a9, t9);
    assert!(r9 == 0);
    check_spec(&a9, t9, r9);
}

