use std::i64;

fn has_close_elements(numbers: &[i64], threshold: i64) -> bool {
    // If threshold is non-positive, no absolute difference can be strictly less than it.
    if threshold <= 0 {
        return false;
    }
    let t = threshold as i128;
    let n = numbers.len();
    for i in 0..n {
        for j in (i + 1)..n {
            let a = numbers[i] as i128;
            let b = numbers[j] as i128;
            if (a - b).abs() < t {
                return true;
            }
        }
    }
    false
}

fn main() {
    // Edge: empty array
    assert_eq!(has_close_elements(&[], 5), false);

    // Edge: single element
    assert_eq!(has_close_elements(&[10], 1), false);

    // Threshold zero and negative thresholds must yield false
    assert_eq!(has_close_elements(&[1, 2], 0), false);
    assert_eq!(has_close_elements(&[1, 2], -3), false);

    // No pair with difference strictly less than threshold
    // Differences: |1-3|=2, |1-6|=5, |3-6|=3; none < 2
    assert_eq!(has_close_elements(&[1, 3, 6], 2), false);

    // Pair exists with difference strictly less than threshold
    // |1-3|=2 < 3
    assert_eq!(has_close_elements(&[1, 3, 6], 3), true);

    // Duplicates: difference 0 < threshold when threshold > 0
    assert_eq!(has_close_elements(&[7, 7], 1), true);

    // Near upper bound values
    assert_eq!(has_close_elements(&[i64::MAX, i64::MAX - 1], 2), true);

    // Extreme opposite ends: difference is huge; threshold not large enough
    assert_eq!(has_close_elements(&[i64::MIN, i64::MAX], i64::MAX), false);

    // Near lower bound values
    assert_eq!(has_close_elements(&[i64::MIN, i64::MIN + 1], 2), true);

    println!("All tests passed.");
}

