use std::u64;

fn check_intersperse_properties(input: Vec<u64>, delim: u64) {
    let output = intersperse(input.clone(), delim);
    if input.len() == 0 {
        assert_eq!(output.len(), 0);
    } else if input.len() == 1 {
        assert_eq!(output, input);
        assert_eq!(output.len(), 1);
    } else {
        assert_eq!(output.len(), 2 * input.len() - 1);
        for i in 0..input.len() {
            assert_eq!(output[2 * i], input[i]);
        }
        for i in 0..(input.len() - 1) {
            assert_eq!(output[2 * i + 1], delim);
        }
    }
}

fn main() {
    // 1. Empty array
    let v1: Vec<u64> = vec![];
    let out1 = intersperse(v1.clone(), 999);
    assert_eq!(out1, vec![]);
    check_intersperse_properties(v1, 999);

    // 2. Single element
    let v2: Vec<u64> = vec![5];
    let out2 = intersperse(v2.clone(), 0);
    assert_eq!(out2, vec![5]);
    check_intersperse_properties(v2, 0);

    // 3. Two elements
    let v3: Vec<u64> = vec![1, 2];
    let out3 = intersperse(v3.clone(), 0);
    assert_eq!(out3, vec![1, 0, 2]);
    check_intersperse_properties(v3, 0);

    // 4. Multiple elements
    let v4: Vec<u64> = vec![3, 4, 5];
    let out4 = intersperse(v4.clone(), 9);
    assert_eq!(out4, vec![3, 9, 4, 9, 5]);
    check_intersperse_properties(v4, 9);

    // 5. Delimiter equals elements
    let v5: Vec<u64> = vec![7, 7, 7, 7];
    let out5 = intersperse(v5.clone(), 7);
    assert_eq!(out5, vec![7, 7, 7, 7, 7, 7, 7]);
    check_intersperse_properties(v5, 7);

    // 6. Includes u64::MAX and zero
    let v6: Vec<u64> = vec![u64::MAX, 0];
    let out6 = intersperse(v6.clone(), u64::MAX);
    assert_eq!(out6, vec![u64::MAX, u64::MAX, 0]);
    check_intersperse_properties(v6, u64::MAX);

    // 7. Single element with large delimiter
    let v7: Vec<u64> = vec![0];
    let out7 = intersperse(v7.clone(), u64::MAX);
    assert_eq!(out7, vec![0]);
    check_intersperse_properties(v7, u64::MAX);

    // 8. Longer array
    let v8: Vec<u64> = vec![10, 20, 30, 40, 50, 60];
    let out8 = intersperse(v8.clone(), 1);
    assert_eq!(out8, vec![10, 1, 20, 1, 30, 1, 40, 1, 50, 1, 60]);
    check_intersperse_properties(v8, 1);
}

