use vstd::prelude::*;

verus! {
    fn expected(numbers: &Vec<u32>) -> (u64, Option<u32>) {
        let mut s: u64 = 0;
        let mut p: Option<u32> = Some(1);
        let n = numbers.len();
        for i in 0..n {
            let x = numbers[i];
            s += x as u64;
            p = match p {
                Some(v) => v.checked_mul(x),
                None => None,
            };
        }
        (s, p)
    }

    fn main() {
        // 1) Empty array
        let a1: Vec<u32> = vec![];
        let (sum1, prod1) = sum_product(a1.clone());
        let (es1, ep1) = expected(&a1);
        assert!(sum1 == es1 && prod1 == ep1);

        // 2) Single element
        let a2: Vec<u32> = vec![5];
        let (sum2, prod2) = sum_product(a2.clone());
        let (es2, ep2) = expected(&a2);
        assert!(sum2 == es2 && prod2 == ep2);

        // 3) Small product fits
        let a3: Vec<u32> = vec![2, 3, 7];
        let (sum3, prod3) = sum_product(a3.clone());
        let (es3, ep3) = expected(&a3);
        assert!(sum3 == es3 && prod3 == ep3);

        // 4) Contains zero, product remains zero
        let a4: Vec<u32> = vec![0, u32::MAX, 17];
        let (sum4, prod4) = sum_product(a4.clone());
        let (es4, ep4) = expected(&a4);
        assert!(sum4 == es4 && prod4 == ep4);

        // 5) Overflow on second multiplication step
        let a5: Vec<u32> = vec![u32::MAX, 2];
        let (sum5, prod5) = sum_product(a5.clone());
        let (es5, ep5) = expected(&a5);
        assert!(sum5 == es5 && prod5 == ep5);

        // 6) Overflow: 65536 * 65536 = 2^32 (exceeds u32::MAX)
        let a6: Vec<u32> = vec![65536, 65536];
        let (sum6, prod6) = sum_product(a6.clone());
        let (es6, ep6) = expected(&a6);
        assert!(sum6 == es6 && prod6 == ep6);

        // 7) Near-bound product fits: 65535 * 65535 * 1
        let a7: Vec<u32> = vec![65535, 65535, 1];
        let (sum7, prod7) = sum_product(a7.clone());
        let (es7, ep7) = expected(&a7);
        assert!(sum7 == es7 && prod7 == ep7);

        // 8) Multiple max values: overflow occurs early
        let a8: Vec<u32> = vec![u32::MAX, u32::MAX, u32::MAX];
        let (sum8, prod8) = sum_product(a8.clone());
        let (es8, ep8) = expected(&a8);
        assert!(sum8 == es8 && prod8 == ep8);

        // 9) Many ones: no overflow, product stays 1
        let a9: Vec<u32> = vec![1; 10];
        let (sum9, prod9) = sum_product(a9.clone());
        let (es9, ep9) = expected(&a9);
        assert!(sum9 == es9 && prod9 == ep9);
    }
}

