use vstd::prelude::*;

verus! {

fn str_to_vec(s: &str) -> Vec<char> {
    s.chars().collect()
}

fn vec_to_string(v: &Vec<char>) -> String {
    let mut s = String::new();
    for &c in v.iter() {
        s.push(c);
    }
    s
}

fn groups_to_strings(groups: &Vec<Vec<char>>) -> Vec<String> {
    let mut res = Vec::new();
    for g in groups.iter() {
        res.push(vec_to_string(g));
    }
    res
}

fn main() {
    // Edge case: empty input, parentheses-only subsequence is empty; result should be empty
    {
        let input = str_to_vec("");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == Vec::<String>::new());
    }

    // Single balanced group
    {
        let input = str_to_vec("()");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["()".to_string()]);
    }

    // Two consecutive balanced groups
    {
        let input = str_to_vec("()()");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["()".to_string(), "()".to_string()]);
    }

    // Nested group followed by a simple group
    {
        let input = str_to_vec("(()())()");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["(()())".to_string(), "()".to_string()]);
    }

    // Input with non-parenthesis characters interleaved; they are ignored
    {
        let input = str_to_vec("a(b)c()d");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["()".to_string(), "()".to_string()]);
    }

    // Single deeply nested balanced group
    {
        let input = str_to_vec("((()))");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["((()))".to_string()]);
    }

    // Interleaved non-parenthesis characters with multiple groups
    {
        let input = str_to_vec("xyz((a)b)12()");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["(())".to_string(), "()".to_string()]);
    }

    // Input with no parentheses at all; parentheses-only subsequence is empty
    {
        let input = str_to_vec("abc");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == Vec::<String>::new());
    }

    // Mixed simple and nested groups
    {
        let input = str_to_vec("()(())");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["()".to_string(), "(())".to_string()]);
    }

    // Non-parentheses around a single nested group
    {
        let input = str_to_vec("a(b(c)d)e");
        let groups = separate_paren_groups(&input);
        let got = groups_to_strings(&groups);
        assert!(got == vec!["(())".to_string()]);
    }
}

} // verus!

