use vstd::prelude::*;
use vstd::slice::*;

verus! {

fn string_xor(a: &[char], b: &[char]) -> (result: Vec<char>)
    requires
        a.len() == b.len(),
        forall|i: int| 0 <= i < a.len() ==> a[i] == '0' || a[i] == '1',
        forall|i: int| 0 <= i < b.len() ==> b[i] == '0' || b[i] == '1',
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> 
            (a[i] == b[i] ==> result[i] == '0') && 
            (a[i] != b[i] ==> result[i] == '1'),
        forall|i: int| 0 <= i < result.len() ==> result[i] == '0' || result[i] == '1',
{
    let a_len = a.len();
    let mut result = Vec::with_capacity(a_len);
    let mut pos: usize = 0;
    while pos < a_len
        invariant
            a_len == a.len(),
            a_len == b.len(),
            0 <= pos <= a_len,
            result.len() == pos,
            forall|i: int| 0 <= i < pos ==> 
                (a[i] == b[i] ==> result[i] == '0') && 
                (a[i] != b[i] ==> result[i] == '1'),
            forall|i: int| 0 <= i < pos ==> result[i] == '0' || result[i] == '1',
        decreases a_len - pos
    {
        if *slice_index_get(a, pos) == *slice_index_get(b, pos) {
            result.push('0');
        } else {
            result.push('1');
        }
        pos += 1;
    }
    result
}

fn main() {
    // Test 1: Empty inputs
    let a = "".chars().collect::<Vec<char>>();
    let b = "".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r.len(), 0);

    // Test 2: Single element, equal ('0' vs '0')
    let a = "0".chars().collect::<Vec<char>>();
    let b = "0".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r, "0".chars().collect::<Vec<char>>());

    // Test 3: Single element, different ('1' vs '0')
    let a = "1".chars().collect::<Vec<char>>();
    let b = "0".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r, "1".chars().collect::<Vec<char>>());

    // Test 4: All zeros, equal
    let a = "0000".chars().collect::<Vec<char>>();
    let b = "0000".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r, "0000".chars().collect::<Vec<char>>());

    // Test 5: All ones, equal -> all zeros
    let a = "11111".chars().collect::<Vec<char>>();
    let b = "11111".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r, "00000".chars().collect::<Vec<char>>());

    // Test 6: Alternating vs inverted -> all ones
    let a = "01010101".chars().collect::<Vec<char>>();
    let b = "10101010".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r, "11111111".chars().collect::<Vec<char>>());

    // Test 7: Mixed random pattern
    let a = "001011".chars().collect::<Vec<char>>();
    let b = "101001".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r, "100010".chars().collect::<Vec<char>>());

    // Test 8: Longer strings (50 chars) - zeros vs ones -> all ones
    let n = 50usize;
    let a_str = "0".repeat(n);
    let b_str = "1".repeat(n);
    let a = a_str.chars().collect::<Vec<char>>();
    let b = b_str.chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    let exp = "1".repeat(n).chars().collect::<Vec<char>>();
    assert_eq!(r, exp);

    // Test 9: Identical random pattern -> all zeros
    let a = "011010".chars().collect::<Vec<char>>();
    let b = "011010".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    assert_eq!(r, "000000".chars().collect::<Vec<char>>());

    // Test 10: Result characters are always '0' or '1'
    let a = "0100".chars().collect::<Vec<char>>();
    let b = "0111".chars().collect::<Vec<char>>();
    let r = string_xor(&a, &b);
    for c in &r {
        assert!(*c == '0' || *c == '1');
    }
}

}

