use std::u32;

fn is_prefix(substring: &[char], string: &[char]) -> bool {
    if substring.len() > string.len() {
        return false;
    }
    for i in 0..substring.len() {
        if substring[i] != string[i] {
            return false;
        }
    }
    true
}

fn how_many_times_impl(string: Vec<char>, substring: Vec<char>) -> Option<u32> {
    // Precondition: substring is non-empty
    assert!(!substring.is_empty(), "Precondition violated: substring must be non-empty");

    let n = string.len();
    let m = substring.len();

    let mut k: u64 = 0;
    let mut i = 0usize;
    while i + m <= n {
        if is_prefix(&substring, &string[i..]) {
            if k >= u32::MAX as u64 {
                return None; // would exceed u32::MAX if we counted this occurrence
            }
            k += 1;
        }
        i += 1;
    }

    Some(k as u32)
}

fn vec_from_str(s: &str) -> Vec<char> { s.chars().collect() }

fn main() {
    // Edge case: empty text, non-empty pattern
    assert_eq!(how_many_times_impl(vec_from_str(""), vec_from_str("a")), Some(0));

    // Single-character pattern counts occurrences at each position
    assert_eq!(how_many_times_impl(vec_from_str("aaa"), vec_from_str("a")), Some(3));

    // Overlapping matches: "aaaa" contains "aa" at positions 0,1,2
    assert_eq!(how_many_times_impl(vec_from_str("aaaa"), vec_from_str("aa")), Some(3));

    // Multiple matches including one at the end
    assert_eq!(how_many_times_impl(vec_from_str("abcabcab"), vec_from_str("abcab")), Some(2));

    // Overlapping pattern occurrences
    assert_eq!(how_many_times_impl(vec_from_str("abababa"), vec_from_str("aba")), Some(3));

    // Single-element inputs
    assert_eq!(how_many_times_impl(vec_from_str("b"), vec_from_str("a")), Some(0));
    assert_eq!(how_many_times_impl(vec_from_str("a"), vec_from_str("a")), Some(1));

    // Text shorter than pattern
    assert_eq!(how_many_times_impl(vec_from_str("hi"), vec_from_str("hii")), Some(0));

    // No matches at all
    assert_eq!(how_many_times_impl(vec_from_str("abcdef"), vec_from_str("gh")), Some(0));

    // Another overlapping example
    assert_eq!(how_many_times_impl(vec_from_str("aaaaa"), vec_from_str("aaa")), Some(3));
}

