use std::i32;

// Runtime helper: checks the stated precondition
fn precondition_holds(ops: &[i32]) -> bool {
    // For every prefix length i, the cumulative sum must be <= i32::MAX
    // We check this by iterating through prefixes and verifying the bound
    let mut sum: i128 = 0;
    // i = 0 prefix
    if sum > i32::MAX as i128 { return false; }
    for &x in ops {
        sum += x as i128;
        if sum > i32::MAX as i128 {
            return false;
        }
    }
    true
}

// Plain Rust implementation of the intended behavior for testing
fn below_zero_plain(ops: &[i32]) -> bool {
    let mut s: i64 = 0; // use wider type to avoid overflow in tests
    for &x in ops {
        s += x as i64;
        if s < 0 { return true; }
    }
    false
}

fn main() {
    // Each test asserts the precondition and then the expected result
    let tests: Vec<(Vec<i32>, bool)> = vec![
        // 1. Empty array: no negative prefix
        (vec![], false),
        // 2. Single positive element: no negative prefix
        (vec![5], false),
        // 3. Single negative element: negative prefix at i = 1
        (vec![-1], true),
        // 4. Multiple elements with a negative prefix sum
        (vec![1, -2, 1], true),
        // 5. All positive elements: no negative prefix
        (vec![100, 200, 300], false),
        // 6. Large value equal to INT32_MAX: still non-negative
        (vec![i32::MAX], false),
        // 7. Dip below zero late
        (vec![0, 0, 0, -1], true),
        // 8. Negative occurs after several steps
        (vec![3, -1, -2, -1, -1], true),
        // 9. Mix of positive/negative but never below zero
        (vec![5, -3, 2, -4, 1], false),
        // 10. Boundary behavior around INT32_MAX
        (vec![i32::MAX, -i32::MAX], false),
    ];

    for (i, (ops, expected)) in tests.iter().enumerate() {
        assert!(precondition_holds(&ops), "Precondition violated in test {}", i + 1);
        let res = below_zero_plain(&ops);
        assert_eq!(res, *expected, "Test {} failed: got {}, expected {}", i + 1, res, expected);
    }

    println!("All tests passed: {}", tests.len());
}

