    let mut out = Vec::with_capacity(input.len());
    for &c in input.iter() {
        if c >= 'a' && c <= 'z' {
            out.push(((c as u8) - 32) as char);
        } else if c >= 'A' && c <= 'Z' {
            out.push(((c as u8) + 32) as char);
        } else {
            out.push(c);
        }
    }
