use vstd::prelude::*;

verus! {

fn get_positive(input: Vec<i32>) -> (positive_list: Vec<i32>)
    ensures
        positive_list@ == input@.filter(|x: i32| x > 0),
{
    let mut positive_list = Vec::<i32>::new();
    let input_len = input.len();
    assert(input@.take(0int).filter(|x: i32| x > 0) == Seq::<i32>::empty());
    for pos in 0..input_len
        invariant
            input_len == input.len(),
            positive_list@ == input@.take(pos as int).filter(|x: i32| x > 0),
    {
        let n = input[pos];
        if n > 0 {
            positive_list.push(n);
        }
        assert(input@.take((pos + 1) as int).drop_last() == input@.take(pos as int));
        reveal(Seq::filter);
    }
    assert(input@ == input@.take(input_len as int));
    positive_list
}

} // verus!

description:
Implement a function that determines whether a given unsigned 8-bit integer is a prime number. The function takes any 8-bit value as input (no preconditions). It must return true if and only if the input is greater than 1 and has no divisors between 2 and the input minus 1, i.e., it satisfies: input > 1 and for all integers i with 1 < i < input, input mod i ≠ 0. For inputs less than 2, the result must be false.

If an iterative approach is used, it must conceptually examine all potential divisors in increasing order starting from 2 up to but not including the input. During such an iteration, at any point when a current bound k satisfies 2 ≤ k ≤ input, the partial result must exactly capture the property that there is no divisor in the range [2, k). The iteration must be guaranteed to terminate by using a well-founded measure that strictly decreases with each step (e.g., the distance from the input to the current bound). The returned boolean must be equivalent to the formal primality predicate described above.
fn is_prime_impl(n: u8) -> (res: bool)

