use vstd::prelude::*;

verus! {

pub open spec fn is_prime(n: nat) -> bool {
    (n > 1) && forall|i| 1 < i < n ==> #[trigger] (n % i) != 0
}

pub closed spec fn is_prime_so_far(n: nat, k: nat) -> bool
    recommends
        n >= k > 1,
{
    forall|i| 1 < i < k ==> #[trigger] (n % i) != 0
}

fn is_prime_impl(n: u8) -> (res: bool)
    ensures
        res == is_prime(n as nat),
{
    if n < 2 {
        return false;
    }
    let mut k = 2;
    let mut res = true;

    while (k < n)
        invariant
            2 <= k <= n,
            res == is_prime_so_far(n as nat, k as nat),
        decreases 
            n - k
    {
        assert((is_prime_so_far(n as nat, k as nat) && (n as nat) % (k as nat) != 0)
            == is_prime_so_far(n as nat, (k + 1) as nat));

        res = res && n % k != 0;
        k = k + 1;
    }
    return res;
}

} // verus!

fn main() {
    // Edge cases
    assert_eq!(is_prime_impl(0), false);
    assert_eq!(is_prime_impl(1), false);

    // Small primes and composites
    assert_eq!(is_prime_impl(2), true);
    assert_eq!(is_prime_impl(3), true);
    assert_eq!(is_prime_impl(4), false);
    assert_eq!(is_prime_impl(5), true);
    assert_eq!(is_prime_impl(6), false);

    // Larger values within u8 range
    assert_eq!(is_prime_impl(97), true);
    assert_eq!(is_prime_impl(101), true);

    // Boundary near u8::MAX
    assert_eq!(is_prime_impl(255), false);
}

