use std::collections::HashMap;

fn check_unchanged_non_multiples(input: &[i32], output: &[i32]) {
    assert_eq!(input.len(), output.len());
    for i in 0..input.len() {
        if i % 3 != 0 {
            assert!(output[i] == input[i], "Index {} (not divisible by 3) changed: {} -> {}", i, input[i], output[i]);
        }
    }
}

fn check_sorted_on_multiples_of_three(output: &[i32]) {
    let mut prev: Option<i32> = None;
    for i in (0..output.len()).step_by(3) {
        if let Some(p) = prev {
            assert!(p <= output[i], "Values at multiples-of-3 not nondecreasing: output[{}]={} > output[{}]={}", i - 3, p, i, output[i]);
        }
        prev = Some(output[i]);
    }
}

fn check_permutation(input: &[i32], output: &[i32]) {
    let mut a: HashMap<i32, i32> = HashMap::new();
    let mut b: HashMap<i32, i32> = HashMap::new();
    for &v in input.iter() { *a.entry(v).or_insert(0) += 1; }
    for &v in output.iter() { *b.entry(v).or_insert(0) += 1; }
    assert!(a == b, "Output is not a permutation of input. Counts differ: {:?} vs {:?}", a, b);
}

fn main() {
    // Test 1: Empty vector
    let v1: Vec<i32> = vec![];
    let r1 = sort_third(v1.clone());
    assert_eq!(r1, vec![]);
    check_unchanged_non_multiples(&v1, &r1);
    check_sorted_on_multiples_of_three(&r1);
    check_permutation(&v1, &r1);

    // Test 2: Single element
    let v2 = vec![5];
    let r2 = sort_third(v2.clone());
    assert_eq!(r2, vec![5]);
    check_unchanged_non_multiples(&v2, &r2);
    check_sorted_on_multiples_of_three(&r2);
    check_permutation(&v2, &r2);

    // Test 3: Two elements (index 1 must remain unchanged)
    let v3 = vec![7, -1];
    let r3 = sort_third(v3.clone());
    assert_eq!(r3, vec![7, -1]);
    check_unchanged_non_multiples(&v3, &r3);
    check_sorted_on_multiples_of_three(&r3);
    check_permutation(&v3, &r3);

    // Test 4: Three elements (only index 0 is in the sorted subsequence)
    let v4 = vec![3, 9, 1];
    let r4 = sort_third(v4.clone());
    assert_eq!(r4, vec![3, 9, 1]);
    check_unchanged_non_multiples(&v4, &r4);
    check_sorted_on_multiples_of_three(&r4);
    check_permutation(&v4, &r4);

    // Test 5: Sorting among indices divisible by 3 (0, 3, 6)
    let v5 = vec![9, 2, 2, 5, 3, 8, 1];
    let r5 = sort_third(v5.clone());
    let expected5 = vec![1, 2, 2, 5, 3, 8, 9]; // (0,3,6) values [9,5,1] -> [1,5,9]
    assert_eq!(r5, expected5);
    check_unchanged_non_multiples(&v5, &r5);
