use std::i32;

fn below_zero(operations: Vec<i32>) -> bool {
    // Compute prefix sums using unbounded precision (i128) and check for negativity.
    let mut acc: i128 = 0;
    for &x in operations.iter() {
        acc += x as i128;
        if acc < 0 {
            return true;
        }
    }
    false
}

fn main() {
    // Edge case: empty array
    assert_eq!(below_zero(vec![]), false);

    // Single-element inputs
    assert_eq!(below_zero(vec![5]), false);
    assert_eq!(below_zero(vec![-1]), true);
    assert_eq!(below_zero(vec![i32::MIN]), true);

    // Simple negative prefix appears later
    assert_eq!(below_zero(vec![3, -4]), true); // prefixes: [3, -1]

    // Prefix sums never negative
    assert_eq!(below_zero(vec![1, -1, 0, 0]), false); // prefixes: [1, 0, 0, 0]

    // Boundary values with potential i32 overflow if done naively (must behave as unbounded integers)
    // MAX + 1 + MIN = 0, so no negative prefix when computed in unbounded integers
    assert_eq!(below_zero(vec![i32::MAX, 1, i32::MIN]), false);

    // Same as above, then one more -1 makes the full prefix sum negative
    assert_eq!(below_zero(vec![i32::MAX, 1, i32::MIN, -1]), true);

    // All zeros
    assert_eq!(below_zero(vec![0, 0, 0]), false);

    // Multiple steps leading to negative
    assert_eq!(below_zero(vec![10, -5, -6]), true); // prefixes: [10, 5, -1]

    println!("All tests passed.");
}

