    let v8: Vec<char> = s8.chars().collect();
    let r8 = remove_vowels(&v8);
    let r8s: String = r8.into_iter().collect();
    assert!(r8s == "cfé");

    // 9. Single-element input: vowel
    let s9 = "a";
