use std::u32;

fn fib(n: u32) -> Option<u32> {
    if n == 0 {
        return Some(0);
    }
    if n == 1 {
        return Some(1);
    }
    // Known boundary: F(48) > u32::MAX, F(47) <= u32::MAX
    if n > 47 {
        return None;
    }
    let mut a: u32 = 0;
    let mut b: u32 = 1;
    for _ in 1..n {
        let sum = a.wrapping_add(b); // safe because n <= 47 ensures no overflow
        a = b;
        b = sum;
    }
    Some(b)
}

// Helper to compute the mathematical Fibonacci in a wider type for verification in tests
fn fib_u128(n: u32) -> u128 {
    if n == 0 { return 0; }
    if n == 1 { return 1; }
    let mut a: u128 = 0;
    let mut b: u128 = 1;
    for _ in 1..n {
        let sum = a + b;
        a = b;
        b = sum;
    }
    b
}

fn main() {
    // Base cases
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));

    // Small n
    assert_eq!(fib(2), Some(1));
    assert_eq!(fib(3), Some(2));
    assert_eq!(fib(10), Some(55));

    // Typical cases
    assert_eq!(fib(20), Some(6765));
    assert_eq!(fib(30), Some(832040));

    // Boundary values around overflow
    assert_eq!(fib(46), Some(1836311903));
    assert_eq!(fib(47), Some(2971215073));
    assert_eq!(fib(48), None);

    // Larger inputs must return None
    assert_eq!(fib(100), None);
    assert_eq!(fib(u32::MAX), None);

    // Cross-check correctness for all n in the safe range
    for n in 0..=47 {
        let expected = fib_u128(n);
        let got = fib(n);
        assert!(got.is_some());
        assert_eq!(got.unwrap() as u128, expected);
        assert!(expected <= (u32::MAX as u128));
    }

    println!("All tests passed.");
}

