verus! {

fn derivative(xs: &Vec<u32>) -> (ret: Vec<u64>)
    requires
        xs.len() <= u32::MAX,
    ensures
        if xs.len() == 0 {
            ret.len() == 0
        } else {
            ret@.map_values(|x| x as int) =~= xs@.map(|i: int, x| i * x).skip(1)
        },
{
    let mut ret = Vec::new();
    if xs.len() == 0 {
        return ret;
    }
    let mut i = 1;
    while i < xs.len()
        invariant
            xs@.map(|i: int, x| i * x).subrange(1, i as int) =~= ret@.map_values(|x| x as int),
            1 <= i <= xs.len() <= u32::MAX,
        decreases
            xs.len() - i
    {
        proof {
            // Prove that the multiplication does not overflow
            vstd::arithmetic::mul::lemma_mul_upper_bound(
                xs[i as int] as int,
                u32::MAX as int,
                i as int,
                u32::MAX as int,
            );
            assert(u32::MAX * u32::MAX <= u64::MAX);
            assert((i as u64) * (xs[i as int] as u64) == i as int * xs[i as int]);
        }
        ret.push((i as u64) * (xs[i] as u64));

        let ghost prods = xs@.map(|i: int, x| i * x);
        assert(prods.subrange(1, i as int).push(prods.index(i as int)) =~= prods.subrange(
            1,
            i + 1 as int,
        ));

        i += 1;
    }
    assert(xs@.map(|i: int, x| i * x).subrange(1, i as int) =~= xs@.map(|i: int, x| i * x).skip(1));
    ret
}

fn main() {
    // Test 1: Empty input
    let xs1: Vec<u32> = Vec::new();
    let out1 = derivative(&xs1);
    assert(out1.len() == 0);

    // Test 2: Single element -> derivative is empty
    let xs2 = vec![7u32];
    let out2 = derivative(&xs2);
    assert(out2 == Vec::<u64>::new());

    // Test 3: Two elements [0, 5] -> [1*5]
    let xs3 = vec![0u32, 5u32];
    let out3 = derivative(&xs3);
    assert(out3 == vec![5u64]);

    // Test 4: Multiple elements with zeros
    let xs4 = vec![3u32, 0u32, 4u32, 2u32];
    let out4 = derivative(&xs4);
    assert(out4 == vec![0u64, 8u64, 6u64]);

    // Test 5: u32::MAX coefficient to check 64-bit multiplication
    let xs5 = vec![0u32, u32::MAX];
    let out5 = derivative(&xs5);
    assert(out5 == vec![u32::MAX as u64]);

    // Test 6: Two large coefficients
    let xs6 = vec![1u32, u32::MAX, u32::MAX];
    let out6 = derivative(&xs6);
    assert(out6 == vec![u32::MAX as u64, (2u64) * (u32::MAX as u64)]);

