use vstd::prelude::*;

verus! {

spec fn is_upper_case(c: char) -> bool {
    c >= 'A' && c <= 'Z'
}

// This spec function computes uppercase character (i.e, ASCII code) sum.
spec fn count_uppercase_sum(seq: Seq<char>) -> int
    decreases seq.len(),
{
    if seq.len() == 0 {
        0
    } else {
        count_uppercase_sum(seq.drop_last()) + if is_upper_case(seq.last()) {
            seq.last() as int
        } else {
            0 as int
        }
    }
}

// This function takes a string as input and returns the sum of the upper characters only'
fn digit_sum(text: &[char]) -> (sum: u128)
    ensures
        count_uppercase_sum(text@) == sum,
{
    let mut index = 0;
    let mut sum = 0u128;

    while index < text.len()
        invariant
            0 <= index <= text.len(),
            count_uppercase_sum(text@.subrange(0, index as int)) == sum,
            forall|j: int|
                0 <= j <= index ==> (u64::MIN * index <= (count_uppercase_sum(
                    #[trigger] text@.subrange(0, j),
                )) <= u64::MAX * index),
            u64::MIN * index <= sum <= u64::MAX * index,
        decreases
            text.len() - index
    {
        if (text[index] >= 'A' && text[index] <= 'Z') {
            assert(text@.subrange(0, index as int) =~= text@.subrange(
                0,
                (index + 1) as int,
            ).drop_last());
            sum = sum + text[index] as u128;
        }
        index += 1;
        assert(text@.subrange(0, index - 1 as int) == text@.subrange(0, index as int).drop_last());

    }
    assert(index == text@.len());
    assert(text@ == text@.subrange(0, index as int));
    sum
}

} // verus!

description:
You are given an array of 64-bit signed integers. Define the prefix sum S(i) as the sum of the first i elements of the array, with S(0) = 0. Determine whether there exists any index i with 0 <= i <= n (where n is the length of the array) such that S(i) < 0. Return true if such an index exists; otherwise, return false. In other words, return true exactly when at least one prefix sum is negative, and return false exactly when all prefix sums (including the empty prefix) are nonnegative. The empty array is allowed and should return false. Assume prefix sums are taken over mathematical integers (i.e., conceptually unbounded for specification purposes).
spec fn sum(s: Seq<i64>) -> int
fn below_zero(operation: &[i64]) -> (r: bool)

meta.test_cases:
use std::i64;

fn below_zero(operation: &[i64]) -> bool {
    // Return true iff some prefix sum is negative
    let mut s: i128 = 0;
    for &x in operation {
        s += x as i128;
        if s < 0 {
            return true;
        }
    }
    false
}

fn main() {
    // Edge cases
    assert_eq!(below_zero(&[]), false, "empty array has no negative prefix");
    assert_eq!(below_zero(&[0]), false, "single zero is nonnegative");
    assert_eq!(below_zero(&[-1]), true, "single negative creates negative prefix");

    // Happy paths
    assert_eq!(below_zero(&[5, -3, -3]), true, "prefix dips below zero");
    assert_eq!(below_zero(&[1, 2, 3, 4]), false, "all positive stays nonnegative");
    assert_eq!(below_zero(&[0, 0, 0]), false, "all zeros stay nonnegative");

    // Boundary-style values exercising large magnitudes
    let a1 = [i64::MAX, -1, -i64::MAX + 1];
    // Prefix sums: MAX, MAX-1, 0 -> never negative
    assert_eq!(below_zero(&a1), false);

    let a2 = [i64::MAX, -i64::MAX, -1];
    // Prefix sums: MAX, 0, -1 -> negative at the end
    assert_eq!(below_zero(&a2), true);

    // Late negative after being nonnegative for a while
    let a3 = [10, -5, -5, -1];
    // Prefix sums: 10, 5, 0, -1
    assert_eq!(below_zero(&a3), true);

    // Mixed values that never go negative
    let a4 = [1, 1, 1, -2, 0, -1];
    // Prefix sums: 1, 2, 3, 1, 1, 0
    assert_eq!(below_zero(&a4), false);

    println!("All tests passed.");
}

