use std::i32;

// Euclidean division (positive divisor) returning the quotient
fn euclid_div_q(x: i128, d: i128) -> i128 {
    assert!(d > 0);
    let mut q = x / d; // Rust division truncates toward zero
    let mut r = x % d; // remainder may be negative
    if r < 0 {
        // Adjust to get non-negative remainder: x = d * q + r with 0 <= r < d
        q -= 1;
        r += d;
    }
    q
}

fn spec_mean_abs_dev(values: &[i32]) -> u32 {
    assert!(!values.is_empty());
    let n = values.len() as i128;
    let sum: i128 = values.iter().map(|&v| v as i128).sum();
    let mean = euclid_div_q(sum, n);
    let dev_sum: i128 = values
        .iter()
        .map(|&v| {
            let d = v as i128 - mean;
            if d >= 0 { d } else { -d }
        })
        .sum();
    let mad = euclid_div_q(dev_sum, n);
    mad as u32
}

fn main() {
    fn check_case(values: &[i32]) {
        let expected = spec_mean_abs_dev(values);
        let result = mean_absolute_deviation(values);
        println!("values={:?} => MAD result={}, expected={}", values, result, expected);
        assert_eq!(result, expected);
    }

    // Happy path tests
    check_case(&[1, 2, 3, 4]);                // mean=2, MAD=1
    check_case(&[-3, -1, 2, 8]);              // mean=1, MAD=2
    check_case(&[-100, -50, 0, 50, 100]);     // mean=0, MAD=60

    // Edge cases: single-element inputs
    check_case(&[5]);                          // MAD=0
    check_case(&[-7]);                         // MAD=0

    // Constraint boundaries and large values
    check_case(&[i32::MIN, i32::MAX]);         // mean=-1, MAD=2147483647
    check_case(&[i32::MIN, i32::MIN, i32::MAX]); // mixed extremes
    check_case(&[0, 1_000_000_000, -1_000_000_000]); // large differences, mean=0
    check_case(&[2, 2, 2, 3, 3, 3]);           // rounding behavior, MAD=0
}

