use vstd::prelude::*;

verus! {

fn is_greater(arr: &Vec<i32>, number: i32) -> (result: bool)
    ensures
        result == (forall|i: int| 0 <= i < arr.len() ==> number > arr[i]),
{
    let mut i = 0;
    while i < arr.len()
        invariant
            0 <= i <= arr.len(),
            forall|k: int| 0 <= k < i ==> number > arr[k],
        decreases
            arr.len() - i
    {
        if number <= arr[i] {
            return false;
        }
        i += 1;
    }
    true
}

fn main() {
    // Empty array: vacuous truth
    assert!(is_greater(&vec![], 42));

    // Single element: strictly greater
    assert!(is_greater(&vec![5], 6));

    // Single element: equal is not strictly greater
    assert!(!is_greater(&vec![5], 5));

    // Multiple elements: strictly greater than all
    assert!(is_greater(&vec![1, 2, 3], 4));

    // Multiple elements: not strictly greater due to equality with last element
    assert!(!is_greater(&vec![1, 2, 3, 4], 4));

    // Negative elements: positive number is greater than all
    assert!(is_greater(&vec![-10, -5, -1], 0));

    // All equal elements: greater value succeeds
    assert!(is_greater(&vec![7, 7, 7], 8));

    // All equal elements: equal value fails
    assert!(!is_greater(&vec![7, 7, 7], 7));

    // Boundary near i32::MAX: greater value succeeds
    assert!(is_greater(&vec![i32::MAX - 1], i32::MAX));

    // Boundary near i32::MAX: equal to element fails
    assert!(!is_greater(&vec![i32::MAX - 1], i32::MAX - 1));

    // Boundary near i32::MIN: extremely small value cannot be greater than -1
    assert!(!is_greater(&vec![-1, -2], i32::MIN));

    // Exact boundary equality with i32::MIN fails
    assert!(!is_greater(&vec![i32::MIN], i32::MIN));

    // Slightly greater than i32::MIN succeeds
    assert!(is_greater(&vec![i32::MIN], i32::MIN + 1));
}

} // verus!

