use vstd::prelude::*;

verus! {

fn max_length_list(seq: &Vec<Vec<i32>>) -> (max_list: &Vec<i32>)
    requires
        seq.len() > 0,
    ensures
        forall|k: int| 0 <= k < seq.len() ==> max_list.len() >= #[trigger] (seq[k]).len(),
        exists|k: int| 0 <= k < seq.len() && max_list@ =~= #[trigger] (seq[k]@),
{
    let mut max_list = &seq[0];
    assert(max_list@ =~= seq[0]@);
    let mut index = 1;

    while index < seq.len()
        invariant
            0 <= index <= seq.len(),
            forall|k: int| 0 <= k < index ==> max_list.len() >= #[trigger] (seq[k]).len(),
            exists|k: int| 0 <= k < index && max_list@ =~= #[trigger] (seq[k]@),
        decreases
            seq.len() - index
    {
        if ((seq[index]).len() > max_list.len()) {
            max_list = &seq[index];
        }
        index += 1;
    }
    max_list
}

// Helper to compute the first index of a maximum-length inner array for checking
fn first_max_index_runtime(seq: &Vec<Vec<i32>>) -> (mi: usize)
    requires
        seq.len() > 0,
    ensures
        mi < seq.len(),
        forall|k: int| 0 <= k < seq.len() ==> seq[mi].len() >= #[trigger] (seq[k]).len(),
{
    let mut mi: usize = 0;
    let mut i: usize = 1;
    while i < seq.len()
        invariant
            1 <= i <= seq.len(),
            mi < i,
            forall|k: int| 0 <= k < i ==> seq[mi].len() >= #[trigger] (seq[k]).len(),
        decreases
            seq.len() - i
    {
        if seq[i].len() > seq[mi].len() {
            mi = i;
        }
        i += 1;
    }
    mi
}

fn check(seq: Vec<Vec<i32>>) {
    // Satisfy the precondition
    assert(seq.len() > 0);

    let r = max_length_list(&seq);

    // Verify: r.len() >= len of each input inner array
    let mut k: usize = 0;
    while k < seq.len()
        invariant 0 <= k <= seq.len(),
        decreases seq.len() - k
    {
        assert(r.len() >= seq[k].len());
        k += 1;
    }

    // Verify: r equals one of the input arrays (choose the first maximum-length witness)
    let mi = first_max_index_runtime(&seq);
    assert(r@ =~= seq[mi]@);
}

fn main() {
    // 1) Single inner array
    check(vec![vec![1, 2, 3]]);

    // 2) Different lengths, second is longest
    check(vec![vec![], vec![1]]);

    // 3) Tie for maximum length (first maximum should be returned by this implementation)
    check(vec![vec![1, 2], vec![3, 4], vec![5]]);

    // 4) All inner arrays empty
    check(vec![vec![], vec![], vec![]]);

    // 5) Clear unique maximum among several arrays
    check(vec![vec![7], vec![8, 9, 10, 11], vec![12, 13, 14], vec![15, 16]]);

    // 6) Large lengths
    check(vec![vec![0; 1000], vec![1; 999]]);

    // 7) Mixed values, clear maximum at the end
    check(vec![vec![10, 20], vec![-1, -2], vec![5], vec![6, 7, 8, 9]]);

    // 8) Multiple ties for maximum length
    check(vec![vec![1], vec![], vec![1, 2, 3, 4, 5], vec![1, 2, 3, 4, 5], vec![1, 2, 3]]);

    // 9) Single empty inner array
    check(vec![vec![]]);
}

} // verus!

