use std::cmp::PartialEq;

fn list_deep_clone(arr: &Vec<u64>) -> Vec<u64> {
    let mut copied_array = Vec::with_capacity(arr.len());
    let mut index = 0;
    while index < arr.len() {
        copied_array.push(arr[index]);
        index += 1;
    }
    copied_array
}

fn assert_elementwise_equal(a: &Vec<u64>, b: &Vec<u64>) {
    assert_eq!(a.len(), b.len());
    for i in 0..a.len() {
        assert_eq!(a[i], b[i]);
    }
}

fn main() {
    // Test 1: Empty vector
    let v1: Vec<u64> = vec![];
    let c1 = list_deep_clone(&v1);
    assert_elementwise_equal(&v1, &c1);

    // Test 2: Single element
    let v2: Vec<u64> = vec![42u64];
    let c2 = list_deep_clone(&v2);
    assert_elementwise_equal(&v2, &c2);

    // Test 3: Multiple ascending elements
    let v3: Vec<u64> = vec![1, 2, 3, 4, 5];
    let c3 = list_deep_clone(&v3);
    assert_elementwise_equal(&v3, &c3);

    // Test 4: Repeated values and independence when original is mutated
    let mut v4: Vec<u64> = vec![7, 7, 7, 7];
    let c4 = list_deep_clone(&v4);
    assert_elementwise_equal(&v4, &c4);
    v4[0] = 9; // mutate original
    assert_eq!(c4[0], 7); // copy remains unchanged
    assert!(v4 != c4);

    // Test 5: Boundary values
    let v5: Vec<u64> = vec![0u64, u64::MAX, u64::MAX - 1, 12_345_678_901_234_567_890u64];
    let c5 = list_deep_clone(&v5);
    assert_elementwise_equal(&v5, &c5);

    // Test 6: Larger vector and independence when original is mutated
    let mut v6: Vec<u64> = Vec::with_capacity(100);
    for i in 0u64..100u64 {
        v6.push(i);
    }
    let c6 = list_deep_clone(&v6);
    assert_elementwise_equal(&v6, &c6);
    v6[50] = 999u64; // mutate original
    assert_eq!(c6[50], 50u64); // copy remains unchanged

    // Test 7: Independence when copy is mutated
    let v7: Vec<u64> = vec![10, 20, 30];
    let mut c7 = list_deep_clone(&v7);
    assert_elementwise_equal(&v7, &c7);
    c7[1] = 99u64; // mutate copy
    assert_eq!(v7[1], 20u64); // original remains unchanged

    // Test 8: Arbitrary values (Fibonacci-like sequence)
    let v8: Vec<u64> = vec![3, 5, 8, 13, 21, 34, 55];
    let c8 = list_deep_clone(&v8);
    assert_elementwise_equal(&v8, &c8);
}

