verus! {

fn contains(arr: &Vec<i32>, key: i32) -> (result: bool)
    ensures
        result == (exists|i: int| 0 <= i < arr.len() && (arr[i] == key)),
{
    let mut i = 0;
    while i < arr.len()
        invariant
            forall|m: int| 0 <= m < i ==> (arr[m] != key),
        decreases
            arr.len() - i
    {
        if (arr[i] == key) {
            return true;
        }
        i += 1;
    }
    false
}

fn intersection(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        forall|i: int|
            0 <= i < result.len() ==> (arr1@.contains(#[trigger] result[i]) && arr2@.contains(
                #[trigger] result[i],
            )),
        forall|i: int, j: int| 0 <= i < j < result.len() ==> result[i] != result[j],
{
    let mut output_arr = Vec::new();
    let ghost mut out_arr_len: int = 0;

    let mut index = 0;
    while index < arr1.len()
        invariant
            forall|i: int|
                0 <= i < output_arr.len() ==> (arr1@.contains(#[trigger] output_arr[i])
                    && arr2@.contains(#[trigger] output_arr[i])),
            forall|m: int, n: int| 0 <= m < n < output_arr.len() ==> output_arr[m] != output_arr[n],
        decreases
            arr1.len() - index
    {
        if (contains(arr2, arr1[index]) && !contains(&output_arr, arr1[index])) {
            output_arr.push(arr1[index]);
            proof {
                out_arr_len = out_arr_len + 1;
            }
        }
        index += 1;
    }
    output_arr
}

fn main() {
    // Test 1: Both arrays empty
    let a: Vec<i32> = vec![];
    let b: Vec<i32> = vec![];
    let r = intersection(&a, &b);
    assert!(r.is_empty());
    assert!(!contains(&a, 10));
    assert!(!contains(&b, 0));

    // Test 2: One empty, one non-empty
    let a2: Vec<i32> = vec![1, 2, 3];
    let b2: Vec<i32> = vec![];
    let r2 = intersection(&a2, &b2);
    assert_eq!(r2.len(), 0);

    // Test 3: No common elements
    let a3: Vec<i32> = vec![1, 4, 6];
    let b3: Vec<i32> = vec![2, 3, 5];
    let r3 = intersection(&a3, &b3);
    assert_eq!(r3.len(), 0);

    // Test 4: Common elements with duplicates across inputs
    let a4: Vec<i32> = vec![1, 2, 2, 3, 3];
    let b4: Vec<i32> = vec![2, 2, 3, 4];
    let r4 = intersection(&a4, &b4);
    assert!(contains(&r4, 2));
    assert!(contains(&r4, 3));
    assert!(!contains(&r4, 1));
    for i in 0..r4.len() {
        for j in (i + 1)..r4.len() {
            assert!(r4[i] != r4[j]);
        }
    }

    // Test 5: Negative numbers and zero
    let a5: Vec<i32> = vec![-1, 0, 5, 5, 7];
    let b5: Vec<i32> = vec![0, -1, 8, 8];
    let r5 = intersection(&a5, &b5);
    assert!(contains(&r5, -1));
    assert!(contains(&r5, 0));
    for i in 0..r5.len() {
        for j in (i + 1)..r5.len() {
            assert!(r5[i] != r5[j]);
        }
    }

    // Test 6: Single identical element
    let a6: Vec<i32> = vec![42];
    let b6: Vec<i32> = vec![42];
    let r6 = intersection(&a6, &b6);
    assert_eq!(r6.len(), 1);
    assert_eq!(r6[0], 42);
    assert!(contains(&a6, 42));
    assert!(contains(&b6, 42));

    // Test 7: Single different elements
    let a7: Vec<i32> = vec![1];
    let b7: Vec<i32> = vec![2];
    let r7 = intersection(&a7, &b7);
    assert_eq!(r7.len(), 0);

    // Test 8: Heavy duplicates in one array
    let a8: Vec<i32> = vec![5, 5, 5, 5, 5];
    let b8: Vec<i32> = vec![5];
    let r8 = intersection(&a8, &b8);
    assert_eq!(r8.len(), 1);
    assert!(contains(&r8, 5));
    for i in 0..r8.len() {
        for j in (i + 1)..r8.len() {
            assert!(r8[i] != r8[j]);
        }
    }

    // Test 9: Multiple common elements with duplicates and order unimportant
    let a9: Vec<i32> = (0..10).collect();
    let b9: Vec<i32> = vec![5, 6, 7, 5, 6, 7];
    let r9 = intersection(&a9, &b9);
    assert_eq!(r9.len(), 3);
    assert!(contains(&r9, 5));
    assert!(contains(&r9, 6));
    assert!(contains(&r9, 7));
    for i in 0..r9.len() {
        for j in (i + 1)..r9.len() {
            assert!(r9[i] != r9[j]);
        }
    }
}

