    let a = vec![9, 9];
    assert(has_only_one_distinct_element(&a));

    // Test 6: Two different elements -> false
    let a = vec![3, 4];
    assert(!has_only_one_distinct_element(&a));

    // Test 7: All negative and equal -> true
    let a = vec![-1, -1, -1, -1];
    assert(has_only_one_distinct_element(&a));

    // Test 8: All elements are i32::MIN -> true
    let a = vec![i32::MIN; 10];
    assert(has_only_one_distinct_element(&a));

    // Test 9: Distinct extremes -> false
    let a = vec![i32::MIN, i32::MAX];
    assert(!has_only_one_distinct_element(&a));

    // Test 10: Large vector, last element differs -> false
    let mut a = vec![0; 100];
    a[99] = 1;
    assert(!has_only_one_distinct_element(&a));
