verus! {

fn element_wise_multiplication(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (result: Vec<i32>)
    requires
        arr1.len() == arr2.len(),
        forall|i: int|
            (0 <= i < arr1.len()) ==> (i32::MIN <= #[trigger] (arr1[i] * arr2[i]) <= i32::MAX),
    ensures
        result.len() == arr1.len(),
        forall|i: int|
            0 <= i < result.len() ==> #[trigger] result[i] == #[trigger] (arr1[i] * arr2[i]),
{
    let mut output_arr = Vec::with_capacity(arr1.len());
    let mut index = 0;
    while index < arr1.len()
        invariant
            arr1.len() == arr2.len(),
            0 <= index <= arr2.len(),
            output_arr.len() == index,
            forall|i: int|
                (0 <= i < arr1.len()) ==> (i32::MIN <= #[trigger] (arr1[i] * arr2[i]) <= i32::MAX),
            forall|k: int|
                0 <= k < index ==> #[trigger] output_arr[k] == #[trigger] (arr1[k] * arr2[k]),
        decreases
            arr1.len() - index
    {
        output_arr.push((arr1[index] * arr2[index]));
        index += 1;
    }
    output_arr
}

fn main() {
    // Test 1: Empty arrays
    let a: Vec<i32> = vec![];
    let b: Vec<i32> = vec![];
    let r = element_wise_multiplication(&a, &b);
    assert!(r.is_empty());

    // Test 2: Single element with zero
    let a = vec![0];
    let b = vec![123];
    let r = element_wise_multiplication(&a, &b);
    assert_eq!(r, vec![0]);

    // Test 3: Standard small arrays
    let a = vec![1, 2, 3];
    let b = vec![4, 5, 6];
    let r = element_wise_multiplication(&a, &b);
    assert_eq!(r, vec![4, 10, 18]);

    // Test 4: Mix of positive and negative values
    let a = vec![-1, -2, 3];
    let b = vec![7, -8, -9];
    let r = element_wise_multiplication(&a, &b);
    assert_eq!(r, vec![-7, 16, -27]);

    // Test 5: Boundary near sqrt(i32::MAX)
    let a = vec![46340, -46340, 46340];
    let b = vec![46340, -46340, -46340];
    let r = element_wise_multiplication(&a, &b);
    assert_eq!(r, vec![2_147_395_600, 2_147_395_600, -2_147_395_600]);

    // Test 6: Include i32::MAX, i32::MIN boundary via products
    let a = vec![i32::MAX, -1, 1_073_741_824];
    let b = vec![1, 1, -2];
    let r = element_wise_multiplication(&a, &b);
    assert_eq!(r, vec![i32::MAX, -1, i32::MIN]);

    // Test 7: Zeros against large magnitude values
    let a = vec![0, 0, 0];
    let b = vec![i32::MIN, 12_345, -99_999];
    let r = element_wise_multiplication(&a, &b);
    assert_eq!(r, vec![0, 0, 0]);

    // Test 8: Larger magnitudes but safely within range
    let a = vec![10_000, -30_000, 20_000, -40_000];
    let b = vec![2_000, -1_000, -1_000, 1_000];
    let r = element_wise_multiplication(&a, &b);
    assert_eq!(r, vec![20_000_000, 30_000_000, -20_000_000, -40_000_000]);
}

