use std::iter::FromIterator;

fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    let mut out = Vec::with_capacity(str1.len());
    for &ch in str1.iter() {
        if ch >= 'a' && ch <= 'z' {
            out.push(((ch as u8) - 32) as char);
        } else if ch >= 'A' && ch <= 'Z' {
            out.push(((ch as u8) + 32) as char);
        } else {
            out.push(ch);
        }
    }
    out
}

fn main() {
    // Helper to convert &str to Vec<char>
    let to_vec = |s: &str| -> Vec<char> { s.chars().collect() };
    let to_string = |v: &Vec<char>| -> String { v.iter().copied().collect::<String>() };

    // 1) Edge case: empty input
    let v1: Vec<char> = vec![];
    let r1 = to_toggle_case(&v1);
    assert_eq!(r1.len(), 0);

    // 2) All lowercase letters
    let v2 = to_vec("abcxyz");
    let r2 = to_toggle_case(&v2);
    assert_eq!(r2.len(), v2.len());
    assert_eq!(to_string(&r2), "ABCXYZ");

    // 3) All uppercase letters
    let v3 = to_vec("ABCXYZ");
    let r3 = to_toggle_case(&v3);
    assert_eq!(r3.len(), v3.len());
    assert_eq!(to_string(&r3), "abcxyz");

    // 4) Mixed letters with punctuation and digits
    let v4 = to_vec("Hello, World! 123");
    let r4 = to_toggle_case(&v4);
    assert_eq!(r4.len(), v4.len());
    assert_eq!(to_string(&r4), "hELLO, wORLD! 123");

    // 5) Boundary letters around 'A'/'Z'/'a'/'z'
    let v5 = to_vec("AaZz");
    let r5 = to_toggle_case(&v5);
    assert_eq!(r5.len(), v5.len());
    assert_eq!(to_string(&r5), "aAzZ");

    // 6) Non-ASCII characters should remain unchanged
    let v6 = to_vec("éßΩあ");
    let r6 = to_toggle_case(&v6);
    assert_eq!(r6.len(), v6.len());
    assert_eq!(to_string(&r6), "éßΩあ");

    // 7) Digits and symbols only (unchanged)
    let v7 = to_vec("123!@#");
    let r7 = to_toggle_case(&v7);
    assert_eq!(r7.len(), v7.len());
    assert_eq!(to_string(&r7), "123!@#");

    // 8) Single-character inputs
    let v8a = to_vec("a");
    let r8a = to_toggle_case(&v8a);
    assert_eq!(r8a.len(), v8a.len());
    assert_eq!(to_string(&r8a), "A");

    let v8b = to_vec("Z");
    let r8b = to_toggle_case(&v8b);
    assert_eq!(r8b.len(), v8b.len());
    assert_eq!(to_string(&r8b), "z");
}

