verus! {

fn contains_z(text: &Vec<char>) -> (result: bool)
    ensures
        result == (exists|i: int| 0 <= i < text.len() && (text[i] == 'Z' || text[i] == 'z')),
{
    let mut index = 0;
    while index < text.len()
        invariant
            0 <= index <= text.len(),
            forall|k: int| 0 <= k < index ==> (text[k] != 'Z' && text[k] != 'z'),
        decreases
            text.len() - index
    {
        if text[index] == 'Z' || text[index] == 'z' {
            return true;
        }
        index += 1;
    }
    false
}

fn main() {
    // 1) Empty array: should be false
    let t1: Vec<char> = vec![];
    assert(!contains_z(&t1));

    // 2) Single uppercase 'Z': should be true
    let t2: Vec<char> = vec!['Z'];
    assert(contains_z(&t2));

    // 3) Single lowercase 'z': should be true
    let t3: Vec<char> = vec!['z'];
    assert(contains_z(&t3));

    // 4) No 'Z' or 'z' present: should be false
    let t4: Vec<char> = vec!['a', 'b', 'c'];
    assert(!contains_z(&t4));

    // 5) 'Z' in the middle: should be true
    let t5: Vec<char> = vec!['a', 'Z', 'b'];
    assert(contains_z(&t5));

    // 6) 'z' at the end: should be true
    let t6: Vec<char> = vec!['a', 'b', 'z'];
    assert(contains_z(&t6));

    // 7) Multiple 'Z's: should be true
    let t7: Vec<char> = vec!['Z', 'x', 'Z', 'y'];
    assert(contains_z(&t7));

    // 8) Mix of cases: should be true
    let t8: Vec<char> = vec!['x', 'z', 'Y', 'Z'];
    assert(contains_z(&t8));

    // 9) Longer array with none: should be false
    let t9: Vec<char> = vec!['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    assert(!contains_z(&t9));
}

