use vstd::prelude::*;

verus! {

fn element_wise_division(arr1: &Vec<u32>, arr2: &Vec<u32>) -> (result: Vec<u32>)
    requires
        arr1.len() == arr2.len(),
        forall|i: int| 0 <= i < arr2.len() ==> arr2[i] != 0,
        forall|m: int|
            0 <= m < arr1.len() ==> (u32::MIN <= #[trigger] arr1[m] / #[trigger] arr2[m]
                <= u32::MAX),
    ensures
        result.len() == arr1.len(),
        forall|i: int|
            0 <= i < result.len() ==> #[trigger] result[i] == #[trigger] (arr1[i] / arr2[i]),
{
    let mut output_arr = Vec::with_capacity(arr1.len());

    let mut index = 0;

    while index < arr1.len()
        invariant
            arr1.len() == arr2.len(),
            0 <= index <= arr2.len(),
            output_arr.len() == index,
            forall|i: int| 0 <= i < arr2.len() ==> arr2[i] != 0,
            forall|m: int|
                0 <= m < arr1.len() ==> (u32::MIN <= #[trigger] arr1[m] / #[trigger] arr2[m]
                    <= u32::MAX),
            forall|k: int|
                0 <= k < index ==> #[trigger] output_arr[k] == #[trigger] (arr1[k] / arr2[k]),
        decreases
            arr1.len() - index
    {
        output_arr.push((arr1[index] / arr2[index]));
        index += 1;
    }
    output_arr
}

fn main() {
    // Test 1: Empty arrays
    let a1_1: Vec<u32> = Vec::new();
    let a2_1: Vec<u32> = Vec::new();
    let r1 = element_wise_division(&a1_1, &a2_1);
    assert!(r1.len() == 0);

    // Test 2: Single-element division
    let mut a1_2: Vec<u32> = Vec::new(); a1_2.push(10);
    let mut a2_2: Vec<u32> = Vec::new(); a2_2.push(2);
    let r2 = element_wise_division(&a1_2, &a2_2);
    assert!(r2.len() == 1);
    assert!(r2[0] == 5);

    // Test 3: Dividing by ones yields the same array
    let mut a1_3: Vec<u32> = Vec::new(); a1_3.push(5); a1_3.push(7); a1_3.push(9);
    let mut a2_3: Vec<u32> = Vec::new(); a2_3.push(1); a2_3.push(1); a2_3.push(1);
    let r3 = element_wise_division(&a1_3, &a2_3);
    assert!(r3.len() == 3);
    assert!(r3[0] == 5);
    assert!(r3[1] == 7);
    assert!(r3[2] == 9);

    // Test 4: Quotients that truncate to zero
    let mut a1_4: Vec<u32> = Vec::new(); a1_4.push(0); a1_4.push(1); a1_4.push(2); a1_4.push(3);
    let mut a2_4: Vec<u32> = Vec::new(); a2_4.push(5); a2_4.push(2); a2_4.push(5); a2_4.push(10);
    let r4 = element_wise_division(&a1_4, &a2_4);
    assert!(r4.len() == 4);
    assert!(r4[0] == 0);
    assert!(r4[1] == 0);
    assert!(r4[2] == 0);
    assert!(r4[3] == 0);

    // Test 5: Large values and truncation
    let mut a1_5: Vec<u32> = Vec::new(); a1_5.push(u32::MAX); a1_5.push(u32::MAX - 1);
    let mut a2_5: Vec<u32> = Vec::new(); a2_5.push(2); a2_5.push(3);
    let r5 = element_wise_division(&a1_5, &a2_5);
    assert!(r5.len() == 2);
    assert!(r5[0] == u32::MAX / 2);
    assert!(r5[1] == (u32::MAX - 1) / 3);

    // Test 6: Mixed values
    let mut a1_6: Vec<u32> = Vec::new(); a1_6.push(100); a1_6.push(200); a1_6.push(300); a1_6.push(400);
    let mut a2_6: Vec<u32> = Vec::new(); a2_6.push(3); a2_6.push(4); a2_6.push(7); a2_6.push(8);
    let r6 = element_wise_division(&a1_6, &a2_6);
    assert!(r6.len() == 4);
    assert!(r6[0] == 33);
    assert!(r6[1] == 50);
    assert!(r6[2] == 42);
    assert!(r6[3] == 50);

    // Test 7: Zeros in the dividend
    let mut a1_7: Vec<u32> = Vec::new(); a1_7.push(0); a1_7.push(0); a1_7.push(0);
    let mut a2_7: Vec<u32> = Vec::new(); a2_7.push(1); a2_7.push(2); a2_7.push(3);
    let r7 = element_wise_division(&a1_7, &a2_7);
    assert!(r7.len() == 3);
    assert!(r7[0] == 0);
    assert!(r7[1] == 0);
    assert!(r7[2] == 0);

    // Test 8: Boundary quotients 0 and 1
    let mut a1_8: Vec<u32> = Vec::new(); a1_8.push(1); a1_8.push(99);
    let mut a2_8: Vec<u32> = Vec::new(); a2_8.push(100); a2_8.push(99);
    let r8 = element_wise_division(&a1_8, &a2_8);
    assert!(r8.len() == 2);
    assert!(r8[0] == 0);
