verus! {
fn assert_no_duplicates(v: &Vec<i32>) {
    let mut i = 0;
    while i < v.len() {
        let mut j = i + 1;
        while j < v.len() {
            assert!(v[i] != v[j]);
            j += 1;
        }
        i += 1;
    }
}

fn assert_membership_requirements(arr1: &Vec<i32>, arr2: &Vec<i32>, res: &Vec<i32>) {
    // For every element in arr1 not present in arr2, it must appear in res
    let mut i = 0;
    while i < arr1.len() {
        if !contains(arr2, arr1[i]) {
            assert!(contains(res, arr1[i]));
        }
        i += 1;
    }
    // For every element in arr2 not present in arr1, it must appear in res
    let mut j = 0;
    while j < arr2.len() {
        if !contains(arr1, arr2[j]) {
            assert!(contains(res, arr2[j]));
        }
        j += 1;
    }
}

fn main() {
    // Test 1: both arrays empty
    let arr1: Vec<i32> = vec![];
    let arr2: Vec<i32> = vec![];
    let res = find_dissimilar(&arr1, &arr2);
    assert!(res.len() == 0);
    assert!(!contains(&res, 1));
    assert_membership_requirements(&arr1, &arr2, &res);
    assert_no_duplicates(&res);

    // Test 2: second array non-empty with duplicates
    let arr1: Vec<i32> = vec![];
    let arr2: Vec<i32> = vec![1, 2, 2, 3];
    let res = find_dissimilar(&arr1, &arr2);
    assert_membership_requirements(&arr1, &arr2, &res);
    assert_no_duplicates(&res);
    assert!(contains(&res, 1));
    assert!(contains(&res, 2));
    assert!(contains(&res, 3));
    assert!(res.len() == 3);

    // Test 3: partial overlap
    let arr1 = vec![1, 2, 3];
    let arr2 = vec![3, 4, 5];
    let res = find_dissimilar(&arr1, &arr2);
    assert_membership_requirements(&arr1, &arr2, &res);
    assert_no_duplicates(&res);
    assert!(contains(&res, 1));
    assert!(contains(&res, 2));
    assert!(contains(&res, 4));
    assert!(contains(&res, 5));
    assert!(!contains(&res, 3));
    assert!(res.len() == 4);

    // Test 4: duplicates in both arrays
    let arr1 = vec![1, 1, 2];
    let arr2 = vec![2, 2, 3];
    let res = find_dissimilar(&arr1, &arr2);
    assert_membership_requirements(&arr1, &arr2, &res);
    assert_no_duplicates(&res);
    assert!(contains(&res, 1));
    assert!(contains(&res, 3));
    assert!(!contains(&res, 2));
    assert!(res.len() == 2);

    // Test 5: identical single elements in both arrays
    let arr1 = vec![7];
    let arr2 = vec![7];
    let res = find_dissimilar(&arr1, &arr2);
    assert_membership_requirements(&arr1, &arr2, &res);
    assert_no_duplicates(&res);
    assert!(res.is_empty());

    // Test 6: negative and zero values
    let arr1 = vec![0, -1, -1];
    let arr2 = vec![1, 0];
    let res = find_dissimilar(&arr1, &arr2);
    assert_membership_requirements(&arr1, &arr2, &res);
    assert_no_duplicates(&res);
    assert!(contains(&res, -1));
    assert!(contains(&res, 1));
    assert!(!contains(&res, 0));
    assert!(res.len() == 2);

    // Test 7: contains function behavior
    let v = vec![5, 5];
    assert!(contains(&v, 5));
    let v2: Vec<i32> = vec![];
    assert!(!contains(&v2, 42));
    let v3 = vec![1, 2, 3];
    assert!(contains(&v3, 2));
    assert!(!contains(&v3, 4));

    // Test 8: larger arrays
    let arr1 = vec![1, 2, 3, 4, 5];
    let arr2 = vec![4, 5, 6, 7];
    let res = find_dissimilar(&arr1, &arr2);
    assert_membership_requirements(&arr1, &arr2, &res);
    assert_no_duplicates(&res);
    assert!(contains(&res, 1));
    assert!(contains(&res, 2));
    assert!(contains(&res, 3));
    assert!(contains(&res, 6));
    assert!(contains(&res, 7));
    assert!(!contains(&res, 4));
    assert!(!contains(&res, 5));
    assert!(res.len() == 5);
}
