fn is_even_at_even_index(arr: &Vec<usize>) -> bool {
    let mut index: usize = 0;
    while index < arr.len() {
        if (index % 2) != (arr[index] % 2) {
            return false;
        }
        index += 1;
    }
    true
}

fn main() {
    // Edge case: empty array (vacuously true)
    assert_eq!(is_even_at_even_index(&vec![]), true);

    // Single-element cases
    assert_eq!(is_even_at_even_index(&vec![0]), true);  // index 0 even, value even
    assert_eq!(is_even_at_even_index(&vec![1]), false); // index 0 even, value odd

    // Happy paths: all indices match value parity
    assert_eq!(is_even_at_even_index(&vec![0, 1, 2, 3, 4]), true);
    assert_eq!(is_even_at_even_index(&vec![2, 1, 4, 3, 6, 5, 8, 7]), true);
    assert_eq!(is_even_at_even_index(&vec![10, 21, 42, 63, 84]), true);

    // Mismatches at various positions
    assert_eq!(is_even_at_even_index(&vec![1, 1, 2, 3]), false); // mismatch at index 0 (even index, odd value)
    assert_eq!(is_even_at_even_index(&vec![0, 2, 2, 3]), false); // mismatch at index 1 (odd index, even value)
    assert_eq!(is_even_at_even_index(&vec![0, 1, 4, 3, 6, 8]), false); // mismatch near end (index 5 odd, value even)
}

