description:
Given an array of signed 64-bit integers, compute the sum of all elements that are strictly negative. Return this sum as a signed 128-bit integer. The input array may be empty. The returned value must exactly equal the mathematical sum of the negative values in the entire array. Additionally, for any prefix of the array of length k (where 0 <= k <= n, n is the array length), the mathematical sum of the negative values in that prefix is guaranteed to lie between i64::MIN multiplied by k and 0. The algorithm should process the array sequentially and terminate after all elements are considered.
spec fn sum_negative_to(seq: Seq<i64>) -> int
fn sum_negatives(arr: &Vec<i64>) -> (sum_neg: i128)

meta.test_cases:
use vstd::prelude::*;

verus! {

spec fn sum_negative_to(seq: Seq<i64>) -> int
    decreases seq.len(),
{
    if seq.len() == 0 {
        0
    } else {
        sum_negative_to(seq.drop_last()) + if (seq.last() < 0) {
            seq.last() as int
        } else {
            0 as int
        }
    }
}

fn sum_negatives(arr: &Vec<i64>) -> (sum_neg: i128)
    ensures
        sum_negative_to(arr@) == sum_neg,
{
    let mut index = 0;
    let mut sum_neg = 0i128;

    while index < arr.len()
        invariant
            0 <= index <= arr.len(),
            forall|j: int|
                0 <= j <= index ==> (i64::MIN * index <= (sum_negative_to(
                    #[trigger] arr@.subrange(0, j),
                )) <= 0),
            sum_negative_to(arr@.subrange(0, index as int)) == sum_neg,
        decreases
            arr.len() - index
    {
        if (arr[index] < 0) {
            sum_neg = sum_neg + (arr[index] as i128);
        }
        index += 1;
        assert(arr@.subrange(0, index - 1 as int) == arr@.subrange(0, index as int).drop_last());

    }
    assert(arr@ == arr@.subrange(0, index as int));
    sum_neg
}

fn main() {
    // Happy path: mixed positives and negatives
    let v1: Vec<i64> = vec![1, -2, -3, 4];
    assert(sum_negatives(&v1) == -5);

    // Only positives
    let v2: Vec<i64> = vec![1, 2, 3];
    assert(sum_negatives(&v2) == 0);

    // Only negatives
    let v3: Vec<i64> = vec![-1, -2, -3];
    assert(sum_negatives(&v3) == -6);

    // Empty array
    let v4: Vec<i64> = vec![];
    assert(sum_negatives(&v4) == 0);

    // Single negative
    let v5: Vec<i64> = vec![-5];
    assert(sum_negatives(&v5) == -5);

    // Single zero
    let v6: Vec<i64> = vec![0];
    assert(sum_negatives(&v6) == 0);

    // Contains i64::MIN
    let v7: Vec<i64> = vec![-1, i64::MIN, 2];
    let expected7: i128 = -1i128 + (i64::MIN as i128);
    assert(sum_negatives(&v7) == expected7);

    // Multiple i64::MIN values
    let v8: Vec<i64> = vec![i64::MIN, i64::MIN];
    let expected8: i128 = (i64::MIN as i128) + (i64::MIN as i128);
    assert(sum_negatives(&v8) == expected8);

    // Alternating signs with zero
    let v9: Vec<i64> = vec![-1, 1, -2, 2, -3, 3, 0];
