fn split_array(list: &Vec<i32>, l: usize) -> (Vec<i32>, Vec<i32>) {
    // Enforce preconditions to mirror the specification
    assert!(!list.is_empty(), "Input array must be non-empty");
    assert!(l > 0 && l < list.len(), "Split index must satisfy 0 < l < len");

    let mut part1 = Vec::with_capacity(l);
    for i in 0..l {
        part1.push(list[i]);
    }
    let mut part2 = Vec::with_capacity(list.len() - l);
    for i in l..list.len() {
        part2.push(list[i]);
    }
    (part1, part2)
}

fn main() {
    fn check(input: Vec<i32>, l: usize, expected1: Vec<i32>, expected2: Vec<i32>) {
        let original = input.clone();
        let (a, b) = split_array(&input, l);
        assert_eq!(a, expected1, "First part should be the prefix of length l");
        assert_eq!(b, expected2, "Second part should be the suffix starting at l");
        assert_eq!(input, original, "Input must remain unchanged");
        assert_eq!(a.len(), l, "First part length must equal l");
        assert_eq!(b.len(), original.len() - l, "Second part length must equal len - l");
    }

    // 1. Typical middle split
    check(vec![1, 2, 3, 4, 5], 2, vec![1, 2], vec![3, 4, 5]);

    // 2. Boundary: l = 1
    check(vec![10, 20, 30, 40], 1, vec![10], vec![20, 30, 40]);

    // 3. Boundary: l = n - 1
