use std::cmp::PartialEq;

fn is_sub_list_at_index(first: &Vec<i32>, second: &Vec<i32>, start: usize) -> bool {
    // Precondition expectation: second.len() <= first.len() and start <= first.len() - second.len()
    if second.len() > first.len() {
        return false; // outside of the stated preconditions; safe guard for tests
    }
    if start > first.len().saturating_sub(second.len()) {
        return false; // outside of the stated preconditions; safe guard for tests
    }
    let m = second.len();
    &first[start..start + m] == &second[..]
}

fn is_sub_list(first: &Vec<i32>, second: &Vec<i32>) -> bool {
    // Precondition expectation: second.len() <= first.len()
    if second.len() > first.len() {
        return false; // outside of the stated preconditions; safe guard for tests
    }
    let n = first.len();
    let m = second.len();
    for start in 0..=n - m {
        if is_sub_list_at_index(first, second, start) {
            return true;
        }
    }
    false
}

fn main() {
    // 1) Happy path: contained in the middle
    let a1 = vec![1, 2, 3, 4, 5];
    let b1 = vec![2, 3];
    assert!(is_sub_list(&a1, &b1));
    assert!(is_sub_list_at_index(&a1, &b1, 1));
    assert!(!is_sub_list_at_index(&a1, &b1, 0));

    // 2) Not contained
    let a2 = vec![1, 2, 3, 4, 5];
    let b2 = vec![2, 4];
    assert!(!is_sub_list(&a2, &b2));
    assert!(!is_sub_list_at_index(&a2, &b2, 1));

    // 3) Both empty arrays: empty second occurs in empty first
    let a3: Vec<i32> = vec![];
    let b3: Vec<i32> = vec![];
    assert!(is_sub_list(&a3, &b3));
    assert!(is_sub_list_at_index(&a3, &b3, 0)); // valid start in [0, n] when m = 0

    // 4) Empty second array with non-empty first: occurs everywhere
    let a4 = vec![7];
    let b4: Vec<i32> = vec![];
    assert!(is_sub_list(&a4, &b4));
    assert!(is_sub_list_at_index(&a4, &b4, 0));
    assert!(is_sub_list_at_index(&a4, &b4, 1)); // k in [0, n] is valid when m = 0

    // 5) Repeated elements
    let a5 = vec![1, 1, 1, 1];
    let b5 = vec![1, 1];
    assert!(is_sub_list(&a5, &b5));
    assert!(is_sub_list_at_index(&a5, &b5, 0));
    assert!(is_sub_list_at_index(&a5, &b5, 1));
    assert!(is_sub_list_at_index(&a5, &b5, 2));

    // 6) Suffix match and nearby mismatch
    let a6 = vec![5, 6, 7, 8];
    let b6 = vec![7, 8];
    assert!(is_sub_list(&a6, &b6));
    assert!(is_sub_list_at_index(&a6, &b6, 2));
    assert!(!is_sub_list_at_index(&a6, &b6, 1));

    // 7) Single-element subarray present
    let a7 = vec![1, 2, 3];
    let b7 = vec![3];
    assert!(is_sub_list(&a7, &b7));
    assert!(is_sub_list_at_index(&a7, &b7, 2));
    assert!(!is_sub_list_at_index(&a7, &b7, 0));

    // 8) Exact full-array match
    let a8 = vec![0, 0, 0];
    let b8 = vec![0, 0, 0];
    assert!(is_sub_list(&a8, &b8));
    assert!(is_sub_list_at_index(&a8, &b8, 0));

    // 9) Single-element subarray absent
    let a9 = vec![1, 2, 3];
    let b9 = vec![4];
    assert!(!is_sub_list(&a9, &b9));
}

