verus! {

spec fn is_even(n: u32) -> bool {
    (n % 2) == 0
}

fn is_product_even(arr: &Vec<u32>) -> (result: bool)
    ensures
        result <==> (exists|k: int| 0 <= k < arr.len() && is_even(#[trigger] arr[k])),
{
    let mut index = 0;
    while index < arr.len()
        invariant
            0 <= index <= arr.len(),
            forall|k: int| 0 <= k < index ==> !(is_even(#[trigger] arr[k])),
        decreases
            arr.len() - index
    {
        if (arr[index] % 2 == 0) {
            return true;
        }
        index += 1;
    }
    false
}

fn main() {
    // 1. Empty array
    assert_eq!(is_product_even(&vec![]), false);

    // 2. Single odd
    assert_eq!(is_product_even(&vec![3u32]), false);

    // 3. Single even
    assert_eq!(is_product_even(&vec![4u32]), true);

    // 4. Mixed odd and even
    assert_eq!(is_product_even(&vec![1u32, 3, 5, 8]), true);

    // 5. All odd
    assert_eq!(is_product_even(&vec![1u32, 3, 5, 7, 9, 11]), false);

    // 6. All even
    assert_eq!(is_product_even(&vec![2u32, 4, 6, 8]), true);

    // 7. Contains zero (even)
    assert_eq!(is_product_even(&vec![0u32]), true);

    // 8. Even appears at the end
    assert_eq!(is_product_even(&vec![1u32, 3, 5, 7, 9, 10]), true);

    // 9. Large values: u32::MAX is odd; u32::MAX - 1 is even
    assert_eq!(is_product_even(&vec![u32::MAX, u32::MAX - 1]), true);
}

