use vstd::prelude::*;

verus! {

spec fn is_upper_case(c: char) -> bool {
    c >= 'A' && c <= 'Z'
}

spec fn shift32_spec(c: char) -> char {
    ((c as u8) + 32) as char
}

fn to_lowercase(str1: &Vec<char>) -> (result: Vec<char>)
    ensures
        str1@.len() == result@.len(),
        forall|i: int|
            0 <= i < str1.len() ==> result[i] == (if is_upper_case(#[trigger] str1[i]) {
                shift32_spec(str1[i])
            } else {
                str1[i]
            }),
{
    let mut lower_case: Vec<char> = Vec::with_capacity(str1.len());
    let mut index = 0;
    while index < str1.len()
        invariant
            0 <= index <= str1.len(),
            lower_case.len() == index,
            forall|i: int|
                0 <= i < index ==> lower_case[i] == (if is_upper_case(#[trigger] str1[i]) {
                    shift32_spec(str1[i])
                } else {
                    str1[i]
                }),
        decreases
            str1.len() - index
    {
        if (str1[index] >= 'A' && str1[index] <= 'Z') {
            lower_case.push(((str1[index] as u8) + 32) as char);
        } else {
            lower_case.push(str1[index]);
        }
        assert(lower_case[index as int] == (if is_upper_case(str1[index as int]) {
            shift32_spec(str1[index as int])
        } else {
            str1[index as int]
        }));
        index += 1;
    }
    assert(forall|i: int|
        0 <= i < str1.len() ==> lower_case[i] == (if is_upper_case(#[trigger] str1[i]) {
            shift32_spec(str1[i])
        } else {
            str1[i]
        }));
    lower_case
}

fn main() {
    // 1) Empty input
    let v1: Vec<char> = vec![];
    let r1 = to_lowercase(&v1);
    assert!(r1.is_empty());

    // 2) Single uppercase character
    let v2 = vec!['A'];
    let r2 = to_lowercase(&v2);
    assert_eq!(r2, vec!['a']);
    assert_eq!(r2.len(), v2.len());

    // 3) Single lowercase character (unchanged)
    let v3 = vec!['z'];
    let r3 = to_lowercase(&v3);
    assert_eq!(r3, vec!['z']);
    assert_eq!(r3.len(), v3.len());

    // 4) Mixed letters and punctuation
    let v4 = vec!['H', 'e', 'L', 'L', 'o', '!'];
    let r4 = to_lowercase(&v4);
    assert_eq!(r4, vec!['h', 'e', 'l', 'l', 'o', '!']);
    assert_eq!(r4.len(), v4.len());

    // 5) All uppercase letters
    let v5 = vec!['A', 'B', 'C', 'X', 'Y', 'Z'];
    let r5 = to_lowercase(&v5);
    assert_eq!(r5, vec!['a', 'b', 'c', 'x', 'y', 'z']);
    assert_eq!(r5.len(), v5.len());

    // 6) Digits and symbols (unchanged), boundary uppercase mapping
    let v6 = vec!['1', '?', 'Z', 'A'];
    let r6 = to_lowercase(&v6);
    assert_eq!(r6, vec!['1', '?', 'z', 'a']);
    assert_eq!(r6.len(), v6.len());

    // 7) Non-ASCII uppercase-like characters (unchanged)
    let v7 = vec!['Ω', 'Ç', 'Ü'];
    let r7 = to_lowercase(&v7);
    assert_eq!(r7, vec!['Ω', 'Ç', 'Ü']);
    assert_eq!(r7.len(), v7.len());

    // 8) Already lowercase word (unchanged)
    let v8 = vec!['a', 'l', 'r', 'e', 'a', 'd', 'y'];
    let r8 = to_lowercase(&v8);
    assert_eq!(r8, vec!['a', 'l', 'r', 'e', 'a', 'd', 'y']);
    assert_eq!(r8.len(), v8.len());

    // 9) Boundary letters only
    let v9 = vec!['A', 'Z'];
    let r9 = to_lowercase(&v9);
    assert_eq!(r9, vec!['a', 'z']);
    assert_eq!(r9.len(), v9.len());
}

} // verus!

