use std::cmp;

fn reverse_to_k(list: &Vec<i32>, n: usize) -> Vec<i32> {
    assert!(!list.is_empty(), "array must be non-empty");
    assert!(n > 0 && n < list.len(), "n must satisfy 0 < n < len(array)");
    let mut out = Vec::with_capacity(list.len());
    for i in (0..n).rev() {
        out.push(list[i]);
    }
    for i in n..list.len() {
        out.push(list[i]);
    }
    out
}

fn main() {
    // Happy path: typical case
    let a = vec![1, 2, 3, 4, 5];
    let r = reverse_to_k(&a, 3);
    assert_eq!(r, vec![3, 2, 1, 4, 5]);
    assert_eq!(a, vec![1, 2, 3, 4, 5]); // input not modified

    // Constraint boundary: minimal valid length (len = 2), n = 1
    let b = vec![7, 9];
    let r = reverse_to_k(&b, 1);
    assert_eq!(r, vec![7, 9]); // reversing first 1 element keeps it the same

    // Boundary for n: n = 1 on larger array
    let c = vec![9, 8, 7];
    let r = reverse_to_k(&c, 1);
    assert_eq!(r, vec![9, 8, 7]);

    // Boundary for n: n = len - 1
    let d = vec![1, 2, 3, 4];
    let r = reverse_to_k(&d, d.len() - 1);
    assert_eq!(r, vec![3, 2, 1, 4]);

    // Negative numbers
    let e = vec![-1, -2, -3, -4];
    let r = reverse_to_k(&e, 2);
    assert_eq!(r, vec![-2, -1, -3, -4]);

    // Duplicates
    let f = vec![5, 5, 5, 5];
    let r = reverse_to_k(&f, 2);
    assert_eq!(r, vec![5, 5, 5, 5]);

    // Mixed signs
    let g = vec![0, -1, 2, -3, 4];
    let r = reverse_to_k(&g, 4);
    assert_eq!(r, vec![-3, 2, -1, 0, 4]);

    // Extremes of i32
    let h = vec![i32::MIN, 0, i32::MAX];
    let r = reverse_to_k(&h, 2);
    assert_eq!(r, vec![0, i32::MIN, i32::MAX]);

    // Larger n in a longer array
    let i = vec![1, 3, 5, 7, 9, 11, 13];
    let r = reverse_to_k(&i, 5);
    assert_eq!(r, vec![9, 7, 5, 3, 1, 11, 13]);
}

