    ensures
        result <==> (exists|i: int| 0 <= i < str.len() && (str[i] == key)),
{
    let mut i = 0;
    while i < str.len()
        invariant
            forall|m: int| 0 <= m < i ==> (str[m] != key),
        decreases
            str.len() - i
    {
        if (str[i] == key) {
            return true;
        }
        i += 1;
    }
    false
