description:
Given a non-empty array of 32-bit unsigned integers and a non-negative integer n, return a new array representing the array rotated to the right by n positions. The rotation is cyclic: each element is shifted n positions to the right, wrapping around to the beginning as needed. Assume the input array length is positive. The output array must have the same length as the input and must not modify the input. If the array length is L and r = n mod L, the result is exactly the concatenation of the suffix starting at index L − r up to L followed by the prefix from index 0 up to L − r, preserving the relative order within each part. The value of n may be larger than L; only n mod L affects the result.
spec fn rotation_split(len: usize, n: usize) -> int
fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)

meta.test_cases:
use std::panic;

fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    // Precondition: input must be non-empty
    assert!(!list.is_empty(), "input array must be non-empty");
    let len = list.len();
    let r = n % len;
    let split = len - r;
    let mut out = Vec::with_capacity(len);
    out.extend_from_slice(&list[split..]);
    out.extend_from_slice(&list[..split]);
    out
}

fn main() {
    // Happy path: n = 0 (no rotation)
    let a: Vec<u32> = vec![1, 2, 3, 4, 5];
    let res = rotate_right(&a, 0);
    assert_eq!(res, vec![1, 2, 3, 4, 5]);
    assert_eq!(res.len(), a.len());

    // Happy path: n = 1
    let a: Vec<u32> = vec![1, 2, 3, 4, 5];
    let res = rotate_right(&a, 1);
    assert_eq!(res, vec![5, 1, 2, 3, 4]);

    // Happy path: n = 2
    let a: Vec<u32> = vec![1, 2, 3, 4, 5];
    let res = rotate_right(&a, 2);
    assert_eq!(res, vec![4, 5, 1, 2, 3]);

    // Boundary: n equals length
    let a: Vec<u32> = vec![10, 20, 30, 40];
    let res = rotate_right(&a, a.len());
    assert_eq!(res, vec![10, 20, 30, 40]);

    // Boundary: n larger than length (uses modulo)
    let a: Vec<u32> = vec![7, 8, 9, 10, 11];
    let res = rotate_right(&a, 7); // 7 % 5 = 2
    assert_eq!(res, vec![10, 11, 7, 8, 9]);

    // Single-element array with various n
    let a: Vec<u32> = vec![42];
    assert_eq!(rotate_right(&a, 0), vec![42]);
    assert_eq!(rotate_right(&a, 5), vec![42]);

    // Large n value
    let a: Vec<u32> = vec![1, 2, 3];
    let res = rotate_right(&a, 1_000_000_007); // 1_000_000_007 % 3 = 1
    assert_eq!(res, vec![3, 1, 2]);

    // Edge case: empty array should violate precondition (expect panic)
    let result = panic::catch_unwind(|| {
        let empty: Vec<u32> = vec![];
        let _ = rotate_right(&empty, 3);
    });
    assert!(result.is_err(), "expected a panic for empty input");

    println!("All tests passed.");
}

