use std::i32;

fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    assert_eq!(arr1.len(), arr2.len());
    let mut out = Vec::with_capacity(arr1.len());
    for i in 0..arr1.len() {
        // Preconditions reflected as runtime checks for testing
        assert!(arr2[i] != 0);
        let q = arr1[i] / arr2[i];
        assert!(q <= i32::MAX as u32);
        out.push(q);
    }
    out
}

fn main() {
    // Test 1: Empty arrays
    let a1: Vec<u32> = vec![];
    let a2: Vec<u32> = vec![];
    let r = element_wise_divide(&a1, &a2);
    assert_eq!(r.len(), 0);

    // Test 2: Single element
    let r = element_wise_divide(&vec![10u32], &vec![2u32]);
    assert_eq!(r, vec![5u32]);

    // Test 3: Mixed values
    let r = element_wise_divide(&vec![100u32, 50u32, 7u32], &vec![1u32, 5u32, 3u32]);
    assert_eq!(r, vec![100u32, 10u32, 2u32]);

    // Test 4: Boundary quotient equals i32::MAX
    let r = element_wise_divide(&vec![u32::MAX], &vec![2u32]);
    assert_eq!(r, vec![i32::MAX as u32]);

    // Test 5: More values, includes zero dividend and large quotient within bound
    let r = element_wise_divide(
        &vec![0u32, 1u32, 2u32, 3u32, 4u32, 2147483647u32],
        &vec![1u32, 1u32, 1u32, 3u32, 2u32, 1u32]
    );
