use std::cmp;

fn second_smallest(numbers: &Vec<i32>) -> (usize, usize) {
    assert!(numbers.len() >= 2, "Precondition violated: length must be >= 2");
    let mut min_index: usize = 0;
    let mut second_min_index: usize = 1;

    if numbers[1] < numbers[0] {
        min_index = 1;
        second_min_index = 0;
    }
    for index in 2..numbers.len() {
        if numbers[index] < numbers[min_index] {
            second_min_index = min_index;
            min_index = index;
        } else if numbers[index] < numbers[second_min_index] {
            second_min_index = index;
        }
    }
    (min_index, second_min_index)
}

fn check_properties(numbers: &Vec<i32>, i_min: usize, i_second: usize) {
    // Compute global minimum value
    let mut global_min = numbers[0];
    for &v in numbers.iter() {
        if v < global_min { global_min = v; }
    }

    // If the first index holds the global minimum, then the second index must be minimal among all indices except the first
    if numbers[i_min] == global_min {
        for k in 0..numbers.len() {
            if k != i_min {
                assert!(numbers[k] >= numbers[i_second], "Property violated: numbers[k] >= numbers[i_second]");
            }
        }
    }

    // Existence: there must be at least one index k != i_min with value equal to numbers[i_second]
    let mut found = false;
    for k in 0..numbers.len() {
        if k != i_min && numbers[k] == numbers[i_second] {
            found = true;
            break;
        }
    }
    assert!(found, "Existence property violated: no k != i_min with value equal to numbers[i_second]");
}

fn main() {
    // 1) Simple ascending
    let a1 = vec![2, 5];
    let (m1, s1) = second_smallest(&a1);
    assert_eq!((m1, s1), (0, 1));
    check_properties(&a1, m1, s1);

    // 2) Simple descending of two
    let a2 = vec![5, 2];
    let (m2, s2) = second_smallest(&a2);
    assert_eq!((m2, s2), (1, 0));
    check_properties(&a2, m2, s2);

    // 3) Duplicated minima
    let a3 = vec![3, 1, 4, 1, 5];
    let (m3, s3) = second_smallest(&a3);
    // Values at indices should be the two occurrences of the minimum (1)
    assert_eq!(a3[m3], 1);
    assert_eq!(a3[s3], 1);
    assert!(m3 != s3);
    check_properties(&a3, m3, s3);

    // 4) Mixed negatives
    let a4 = vec![-10, -20, -30, -5];
    let (m4, s4) = second_smallest(&a4);
    assert_eq!(a4[m4], -30);
    assert_eq!(a4[s4], -20);
    check_properties(&a4, m4, s4);

    // 5) All equal values
    let a5 = vec![7, 7, 7, 7];
    let (m5, s5) = second_smallest(&a5);
    assert_eq!(a5[m5], 7);
    assert_eq!(a5[s5], 7);
    check_properties(&a5, m5, s5);

    // 6) Strictly increasing
    let a6 = vec![1, 2, 3, 4];
    let (m6, s6) = second_smallest(&a6);
    assert_eq!((m6, s6), (0, 1));
    check_properties(&a6, m6, s6);

    // 7) Strictly decreasing
    let a7 = vec![4, 3, 2, 1];
    let (m7, s7) = second_smallest(&a7);
    assert_eq!((m7, s7), (3, 2));
    check_properties(&a7, m7, s7);

    // 8) Multiple minima, second index is another minima
    let a8 = vec![5, 1, 1, 2, 3];
    let (m8, s8) = second_smallest(&a8);
    assert_eq!(a8[m8], 1);
    assert_eq!(a8[s8], 1);
    assert!(m8 != s8);
    check_properties(&a8, m8, s8);

    // 9) Contains i32::MIN twice
    let a9 = vec![i32::MIN, i32::MIN, 0];
    let (m9, s9) = second_smallest(&a9);
    assert_eq!(a9[m9], i32::MIN);
    assert_eq!(a9[s9], i32::MIN);
    check_properties(&a9, m9, s9);

    // 10) Multiple equal negative minima
    let a10 = vec![0, -1, -1, -1];
    let (m10, s10) = second_smallest(&a10);
    assert_eq!(a10[m10], -1);
    assert_eq!(a10[s10], -1);
    check_properties(&a10, m10, s10);
}

