fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list@.len() > 0,
        0 < n < list@.len(),
    ensures
        new_list@ == list@.subrange(n as int, list@.len() as int).add(list@.subrange(0, n as int)),
{
    let mut new_list = Vec::new();
    let mut index = n;
    while index < list.len()
        invariant
            n <= index <= list.len(),
            list@.subrange(n as int, index as int) =~= new_list@,
        decreases
            list.len() - index
    {
        new_list.push(list[index]);
        index += 1;
    }
    let mut index = 0;
    while index < n
        invariant
            0 < n < list@.len(),
            0 <= index <= n,
            new_list@ =~= list@.subrange(n as int, list@.len() as int).add(
                list@.subrange(0, index as int),
            ),
        decreases
            n - index
    {
        new_list.push(list[index]);
        index += 1;
    }
    new_list
}

fn main() {
    // Happy path: rotate by 2
    let a1 = vec![1, 2, 3, 4, 5];
    let r1 = split_and_append(&a1, 2);
    assert_eq!(r1, vec![3, 4, 5, 1, 2]);

