    assert_eq!(r3, vec![-4, -1, -2, -3]);

    // All elements equal
    let a4 = vec![7, 7, 7, 7];
    let r4 = split_and_append(&a4, 2);
    assert_eq!(r4, vec![7, 7, 7, 7]);

    // Smallest array allowed by constraints (length 2)
    let a5 = vec![1, 2];
    let r5 = split_and_append(&a5, 1);
    assert_eq!(r5, vec![2, 1]);

    // Boundary: rotate by length - 1 (largest valid split)
