    assert_eq!(r7, vec![1, 0, 1, 0]);

    // Another standard case
    let a8 = vec![100, 200, 300, 400, 500];
    let r8 = split_and_append(&a8, 3);
    assert_eq!(r8, vec![400, 500, 100, 200, 300]);
}

