verus! {

spec fn is_space_comma_dot_spec(c: char) -> bool {
    (c == ' ') || (c == ',') || (c == '.')
}

fn replace_with_colon(str1: &Vec<char>) -> (result: Vec<char>)
    ensures
        str1@.len() == result@.len(),
        forall|k: int|
            0 <= k < result.len() ==> #[trigger] result[k] == (if is_space_comma_dot_spec(str1[k]) {
                ':'
            } else {
                str1[k]
            }),
{
    let mut result: Vec<char> = Vec::with_capacity(str1.len());
    let mut index = 0;
    while index < str1.len()
        invariant
            0 <= index <= str1.len(),
            result@.len() == index,
            forall|k: int|
                0 <= k < index ==> #[trigger] result[k] == (if is_space_comma_dot_spec(str1[k]) {
                    ':'
                } else {
                    str1[k]
                }),
        decreases
            str1.len() - index
    {
        if ((str1[index] == ' ') || (str1[index] == ',') || (str1[index] == '.')) {
            result.push(':');
        } else {
            result.push(str1[index]);
        }
        index += 1;
    }
    result
}

fn vec_from_str(s: &str) -> Vec<char> {
    s.chars().collect()
}

fn main() {
    // Test 1: Empty input
    let input1 = vec_from_str("");
    let out1 = replace_with_colon(&input1);
    assert(out1.len() == 0);

    // Test 2: Single space
    let input2 = vec![' '];
    let out2 = replace_with_colon(&input2);
    assert(out2 == vec![':']);

    // Test 3: Single non-punctuation character
    let input3 = vec!['x'];
    let out3 = replace_with_colon(&input3);
    assert(out3 == vec!['x']);

    // Test 4: Mixed punctuation and space
    let input4 = vec_from_str("Hello, world.");
    let out4 = replace_with_colon(&input4);
    let expected4 = vec_from_str("Hello::world:");
    assert(out4 == expected4);

    // Test 5: Space only replacement in a phrase
    let input5 = vec_from_str("No punctuation");
    let out5 = replace_with_colon(&input5);
    let expected5 = vec_from_str("No:punctuation");
    assert(out5 == expected5);

    // Test 6: All dots
    let input6 = vec_from_str("...");
    let out6 = replace_with_colon(&input6);
    let expected6 = vec_from_str(":::");
    assert(out6 == expected6);

    // Test 7: Non-ASCII characters mixed with punctuation and space
    let input7 = vec_from_str("á,β 中.");
    let out7 = replace_with_colon(&input7);
    let expected7 = vec_from_str("á:β:中:");
    assert(out7 == expected7);

    // Test 8: Existing colon remains, others replaced
    let input8 = vec_from_str("a:b c.d,:");
    let out8 = replace_with_colon(&input8);
    let expected8 = vec_from_str("a:b:c:d::");
    assert(out8 == expected8);

    // Test 9: Small mix of space, comma, dot
    let input9 = vec_from_str(" ,.");
    let out9 = replace_with_colon(&input9);
    let expected9 = vec_from_str(":::");
    assert(out9 == expected9);
}

