use vstd::prelude::*;

verus! {

fn main() {
    // Test 1: contains on empty vector
    let arr: Vec<i32> = Vec::new();
    assert!(!contains(&arr, 42));

    // Test 2: contains with present and absent keys
    let arr2 = vec![1, 2, 3];
    assert!(contains(&arr2, 2));
    assert!(!contains(&arr2, 4));

    // Test 3: difference with both arrays empty
    let a: Vec<i32> = Vec::new();
    let b: Vec<i32> = Vec::new();
    let d = difference(&a, &b);
    assert!(d.len() == 0);

    // Test 4: difference with one array empty and duplicates in the other
    let a = vec![1, 1, 2, 3];
    let b: Vec<i32> = Vec::new();
    let d = difference(&a, &b);
    assert!(d.len() == 3);
    assert!(contains(&d, 1) && contains(&d, 2) && contains(&d, 3));
    assert!(!contains(&d, 4));

    // Test 5: overlapping arrays with duplicates
    let a = vec![1, 2, 3];
