fn contains_consecutive_numbers(arr: &Vec<i32>) -> bool {
    // Enforce the problem's preconditions to mirror the specification
    assert!(!arr.is_empty(), "Input array must be non-empty.");
    for &x in arr {
        assert!(x + 1 >= 0 && x + 1 < i32::MAX, "Each element x must satisfy -1 <= x < i32::MAX - 1.");
    }

    for i in 0..(arr.len() - 1) {
        if arr[i] + 1 != arr[i + 1] {
            return false;
        }
    }
    true
}

fn main() {
    // Happy Path: single element (vacuously true)
    let a1 = vec![5];
    assert_eq!(contains_consecutive_numbers(&a1), true);

    // Happy Path: strictly consecutive starting from -1
    let a2 = vec![-1, 0, 1, 2];
    assert_eq!(contains_consecutive_numbers(&a2), true);

    // Edge Case: non-consecutive pair in the middle
    let a3 = vec![0, 1, 3, 4];
    assert_eq!(contains_consecutive_numbers(&a3), false);

    // Constraint Boundary near upper limit (valid values)
    let a4 = vec![i32::MAX - 3, i32::MAX - 2];
    assert_eq!(contains_consecutive_numbers(&a4), true);

    // Non-consecutive due to a gap later
    let a5 = vec![10, 11, 13];
    assert_eq!(contains_consecutive_numbers(&a5), false);

    // Boundary near lower limit (valid values)
    let a6 = vec![-1, 0];
    assert_eq!(contains_consecutive_numbers(&a6), true);

    // Not consecutive: skip from -1 to 1
    let a7 = vec![-1, 1];
    assert_eq!(contains_consecutive_numbers(&a7), false);

    // Longer consecutive sequence
    let a8 = vec![100, 101, 102, 103, 104];
    assert_eq!(contains_consecutive_numbers(&a8), true);

    // Single element at upper-valid boundary
    let a9 = vec![i32::MAX - 2];
    assert_eq!(contains_consecutive_numbers(&a9), true);

    // Another straightforward consecutive sequence
    let a10 = vec![7, 8, 9];
    assert_eq!(contains_consecutive_numbers(&a10), true);

    println!("All tests passed.");
}

