use std::cmp;

fn difference_max_min(arr: &Vec<i32>) -> i32 {
    // Enforce the same preconditions as the verified specification
    assert!(!arr.is_empty(), "input must be non-empty");
    let lower = i32::MIN / 2;
    let upper = i32::MAX / 2;
    for &x in arr {
        assert!(x >= lower && x <= upper, "element out of allowed range [i32::MIN/2, i32::MAX/2]");
    }

    let mut min_val = arr[0];
    let mut max_val = arr[0];
    let mut index = 1;
    while index < arr.len() {
        if arr[index] <= min_val {
            min_val = arr[index];
        } else if arr[index] > max_val {
            max_val = arr[index];
        }
        index += 1;
    }
    max_val - min_val
}

fn check_postconditions(a: &Vec<i32>, diff: i32) {
    // Ensures: for all i, j in range, a[i] - a[j] <= diff and diff >= 0
    for i in 0..a.len() {
        for j in 0..a.len() {
            assert!(a[i] - a[j] <= diff, "pairwise difference exceeded the result");
        }
    }
    assert!(diff >= 0, "result should be nonnegative");
}

fn main() {
    // 1) Single element (edge case): result must be 0
    let a1 = vec![5];
    let r1 = difference_max_min(&a1);
    assert_eq!(r1, 0);
    check_postconditions(&a1, r1);

    // 2) Two elements, increasing
    let a2 = vec![1, 2];
    let r2 = difference_max_min(&a2);
    assert_eq!(r2, 1);
    check_postconditions(&a2, r2);

    // 3) All equal elements
    let a3 = vec![7, 7, 7, 7];
    let r3 = difference_max_min(&a3);
    assert_eq!(r3, 0);
    check_postconditions(&a3, r3);

    // 4) Negative values
    let a4 = vec![-3, -1, -2];
    let r4 = difference_max_min(&a4);
    assert_eq!(r4, 2); // max=-1, min=-3
    check_postconditions(&a4, r4);

    // 5) Mixed negative and positive
    let a5 = vec![-10, 0, 10];
    let r5 = difference_max_min(&a5);
    assert_eq!(r5, 20); // max=10, min=-10
    check_postconditions(&a5, r5);

    // 6) Boundary values at the allowed extremes
    let lo = i32::MIN / 2; // -1_073_741_824
    let hi = i32::MAX / 2; //  1_073_741_823
    let a6 = vec![lo, hi];
    let r6 = difference_max_min(&a6);
    assert_eq!(r6, i32::MAX); // 2_147_483_647
    check_postconditions(&a6, r6);

    // 7) Larger array with varied values within the allowed range
    let a7 = vec![lo + 1, -100, 50, 999, hi - 1, -9999, 12345, -12345];
    let r7 = difference_max_min(&a7);
    // Compute expected manually: max = max(a7), min = min(a7)
    let expected7 = *a7.iter().max().unwrap() - *a7.iter().min().unwrap();
    assert_eq!(r7, expected7);
    check_postconditions(&a7, r7);
}

