use std::iter::FromIterator;

fn to_chars(s: &str) -> Vec<char> { s.chars().collect() }
fn to_string(v: &Vec<char>) -> String { String::from_iter(v.iter()) }

fn is_ws(c: char) -> bool { c == ' ' || c == '\t' || c == '\n' || c == '\r' }

// Self-contained implementation aligned with the problem specification
fn solve(input: Vec<char>) -> Vec<char> {
    assert!(input.len() > 0, "Precondition violated: input must be non-empty");

    // Trim a single trailing newline if present
    let mut processed = input.clone();
    if processed[processed.len() - 1] == '\n' {
        processed.pop();
    }

    // Strip leading and trailing whitespace (' ', '\t', '\n', '\r') until neither end is whitespace
    let mut start = 0usize;
    let mut end = processed.len();
    while start < end && is_ws(processed[start]) { start += 1; }
    while start < end && is_ws(processed[end - 1]) { end -= 1; }
    let stripped = if start == 0 && end == processed.len() {
        processed
    } else {
        processed[start..end].to_vec()
    };

    // Check the validity conditions
    let has_lower = stripped.iter().any(|&c| c >= 'a' && c <= 'z');
    let has_upper = stripped.iter().any(|&c| c >= 'A' && c <= 'Z');
    let has_digit = stripped.iter().any(|&c| c >= '0' && c <= '9');

    if stripped.len() >= 5 && has_lower && has_upper && has_digit {
        "Correct\n".chars().collect()
    } else {
        "Too weak\n".chars().collect()
    }
}

fn main() {
    // 1. Happy Path: valid with trailing newline
    let input1 = to_chars("Abcde1\n");
    let out1 = solve(input1);
    assert_eq!(to_string(&out1), "Correct\n");

    // 2. Valid with leading/trailing whitespace
    let input2 = to_chars(" \tAbc1D  ");
    let out2 = solve(input2);
    assert_eq!(to_string(&out2), "Correct\n");

    // 3. Missing uppercase
    let input3 = to_chars("abcd1\n");
    let out3 = solve(input3);
    assert_eq!(to_string(&out3), "Too weak\n");

    // 4. Too short
    let input4 = to_chars("Aa1\n");
    let out4 = solve(input4);
    assert_eq!(to_string(&out4), "Too weak\n");

    // 5. Leading newline removed by whitespace stripping (no trailing newline)
    let input5 = to_chars("\nAa1bc");
    let out5 = solve(input5);
    assert_eq!(to_string(&out5), "Correct\n");

    // 6. Trailing newline and trailing space
    let input6 = to_chars("Aa1bc \n");
    let out6 = solve(input6);
    assert_eq!(to_string(&out6), "Correct\n");

    // 7. Exactly length 5, meets all criteria
    let input7 = to_chars("Aaaa1");
    let out7 = solve(input7);
    assert_eq!(to_string(&out7), "Correct\n");

    // 8. Boundary: single newline (input non-empty), becomes empty after trim
    let input8 = to_chars("\n");
    let out8 = solve(input8);
    assert_eq!(to_string(&out8), "Too weak\n");

    // 9. Carriage returns and spaces at both ends
    let input9 = to_chars(" \rAa1b\r ");
    let out9 = solve(input9);
    assert_eq!(to_string(&out9), "Too weak\n");

    // 10. Uppercase and digits but no lowercase
    let input10 = to_chars("XYZ99");
    let out10 = solve(input10);
    assert_eq!(to_string(&out10), "Too weak\n");

    println!("All tests passed.");
}

