pub fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Preconditions: inputs must be within 1..=8
    assert!((1..=8).contains(&r1));
    assert!((1..=8).contains(&c1));
    assert!((1..=8).contains(&r2));
    assert!((1..=8).contains(&c2));

    let rook = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    let row_diff = if r1 >= r2 { r1 - r2 } else { r2 - r1 };
    let col_diff = if c1 >= c2 { c1 - c2 } else { c2 - c1 };

    let bishop = if r1 == r2 && c1 == c2 {
        0
    } else if row_diff == col_diff {
        1
    } else if ((r1 + c1) % 2) == ((r2 + c2) % 2) {
        2
    } else {
        0
    };

    let king = if row_diff >= col_diff { row_diff } else { col_diff };

    vec![rook, bishop, king]
}

fn main() {
    // Happy path: same square
    assert_eq!(solve(4, 4, 4, 4), vec![0, 0, 0]);

    // Same row, different column; bishop unreachable (different color); king distance is column diff
    assert_eq!(solve(1, 3, 1, 8), vec![1, 0, 5]);

    // Same column; bishop unreachable (different color); king distance is row diff
    assert_eq!(solve(2, 2, 5, 2), vec![1, 0, 3]);

