    assert_eq!(solve(1, 1, 2, 3), vec![2, 0, 1]);

    // Corners along a main diagonal
    assert_eq!(solve(1, 1, 8, 8), vec![2, 1, 7]);

    // Other diagonal corners
    assert_eq!(solve(8, 1, 1, 8), vec![2, 1, 7]);

    // Boundary values: same row at edges; bishop unreachable (different color)
    assert_eq!(solve(8, 8, 8, 1), vec![1, 0, 7]);

