    let product = count0 * count1;

    // Now break product into tens and ones
    let tens = product / 10;
    let ones = product % 10;

    let mut result = Vec::new();
    if tens > 0 {
        // Convert tens to char: tens is in [1,4]
        let tens_char = int_to_digit_char(tens);
        result.push(tens_char);
