    forall|i: int| 0 <= i < tasks.len() ==> 1 <= #[trigger] tasks[i] <= n
}

spec fn min_time_to_complete(n: int, tasks: Seq<int>, current_pos: int, task_index: int) -> int
    recommends 
        n >= 2,
        forall|i: int| 0 <= i < tasks.len() ==> 1 <= #[trigger] tasks[i] <= n,
        1 <= current_pos <= n,
        0 <= task_index < tasks.len()
{
