// <vc-spec>
fn solve(n: i8, m: i8, tasks: Vec<i8>) -> (result: i8)
    requires 
        valid_input(n as int, m as int, tasks@.map(|i, x: i8| x as int))
    ensures 
        result >= 0,
        m > 0 ==> result >= tasks@[(m as int) - 1] as int - 1,
        result <= ((m as int) - 1) * (n as int) + tasks@[(m as int) - 1] as int - 1,
// </vc-spec>
