{
    let len = tasks.len();

    proof {
        assert(tasks@.len() == m as int);
        assert(m as int >= 1);
        assert(tasks@.len() >= 1);
        assert(tasks.len() as int == tasks@.len());
    }
    assert(len == tasks@.len() as usize);
    assert(len > 0);

    let mut i: usize = 0;
    let mut last: i8 = 0;
    let mut seen: bool = false;

    while i < len
        invariant
            tasks.len() == len,
            0 <= i <= len,
            seen ==> last == tasks@[i as int - 1],
            !seen ==> i == 0,
        decreases len - i
    {
        let x = tasks[i];
        i = i + 1;
        last = x;
        seen = true;
        proof {
            assert(tasks@[i as int - 1] == x);
        }
    }

    proof {
        assert(seen);
        assert(i == len);
        assert(tasks@.len() == m as int);
        assert(len as int == tasks@.len());
        assert(last == tasks@[len as int - 1]);
        assert(last == tasks@[(m as int) - 1]);

