fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    let len: usize = participations.len();
    let n_usize: usize = n as usize;
    let limit: usize = min(len, n_usize);

    let mut i: usize = 0;
    let mut eligible_count: u8 = 0;

    while i < limit {
