    let n3: u8 = 4;
    let k3: u8 = 2;
    let arr3: Vec<u8> = vec![];
    assert_eq!(solve(n3, k3, arr3), 0);

    // 4) n greater than length -> process all available elements
    // eligibility: 5 - p >= 2 -> p <= 3; all four qualify
    let n4: u8 = 10;
    let k4: u8 = 2;
    let arr4 = vec![0u8, 1, 2, 3];
    // 4 eligible -> 1 team
    assert_eq!(solve(n4, k4, arr4), 1);

    // 5) k = 5: only zeros are eligible
    let n5: u8 = 7;
    let k5: u8 = 5;
    let arr5 = vec![0u8, 0, 1, 0, 2, 0, 5];
    // zeros among first 7: 4 -> 1 team
    assert_eq!(solve(n5, k5, arr5), 1);

    // 6) Exactly two full teams
    // eligibility: 5 - p >= 1 -> p <= 4, so only '5' is ineligible
    let n6: u8 = 9;
    let k6: u8 = 1;
    let arr6 = vec![0u8, 1, 2, 3, 4, 5, 0, 1, 2];
    // 8 eligible -> 2 teams
    assert_eq!(solve(n6, k6, arr6), 2);

    // 7) Array longer than n: ignore trailing items beyond first n
    // k = 2 -> p <= 3 eligible
    let n7: u8 = 3;
    let k7: u8 = 2;
    let arr7 = vec![2u8, 2, 2, 0, 0, 0];
    // first 3 all eligible -> 1 team
    assert_eq!(solve(n7, k7, arr7), 1);

    // 8) Single element, not enough for a team
    let n8: u8 = 1;
    let k8: u8 = 0;
    let arr8 = vec![0u8];
