use std::fmt::Debug;

fn last_index_of(arr: &Vec<i8>, v: i8) -> usize {
    for i in (0..arr.len()).rev() {
        if arr[i] == v {
            return i;
        }
    }
    unreachable!("value is guaranteed to be in the array in these tests")
}

fn expected_min_by_last(arr: &Vec<i8>) -> i8 {
    let mut min_val = arr[0];
    let mut min_last = last_index_of(arr, min_val);
    for i in 1..arr.len() {
        let v = arr[i];
        let l = last_index_of(arr, v);
        if l < min_last {
            min_last = l;
            min_val = v;
        }
    }
    min_val
}

fn assert_properties<T: Debug>(arr: &Vec<i8>, result: i8) {
    // Returned value appears in the array
    assert!(arr.iter().any(|&x| x == result), "Returned value must be in the array");
    // Its last occurrence position is minimal among all elements in the array
    let r_last = last_index_of(arr, result);
    for &v in arr.iter() {
        let l = last_index_of(arr, v);
        assert!(r_last <= l, "Last occurrence of result is not minimal: {:?}", (r_last, v, l));
    }
}

fn main() {
    // 1) Single-element array
    let a1 = vec![5];
    let e1 = expected_min_by_last(&a1);
