fn clamp_to_i8(x: i64) -> i8 {
    if x < -128 { -128i8 } else if x > 127 { 127i8 } else { x as i8 }
}

fn solve(input: Vec<i8>) -> Vec<i8> {
    if input.len() < 3 {
        return Vec::<i8>::new();
    }
    let a = input[0] as i64; // capacity
    let b = input[1] as i64; // current
    let c = input[2] as i64; // incoming
    let available = a - b;
    let mut remaining = c - available;
    if remaining < 0 {
        remaining = 0;
    }
    let out = clamp_to_i8(remaining);
    let mut res: Vec<i8> = Vec::new();
    res.push(out);
    res
}

fn main() {
    // Constraint boundary: input length is positive but fewer than 3 elements
    assert_eq!(solve(vec![10]), Vec::<i8>::new());
    assert_eq!(solve(vec![10, 3]), Vec::<i8>::new());

    // Happy path: no overflow, remaining is 0
    // capacity=10, current=3, incoming=5 => available=7, remaining=max(0, 5-7)=0
    assert_eq!(solve(vec![10, 3, 5]), vec![0]);

    // Happy path: some overflow
    // capacity=10, current=3, incoming=10 => available=7, remaining=3
    assert_eq!(solve(vec![10, 3, 10]), vec![3]);

    // Edge case within intended domain bounds
    // capacity=20, current=20, incoming=20 => available=0, remaining=20
    assert_eq!(solve(vec![20, 20, 20]), vec![20]);

    // Another standard case
    // capacity=15, current=5, incoming=15 => available=10, remaining=5
    assert_eq!(solve(vec![15, 5, 15]), vec![5]);

    // Case where current equals capacity; all incoming overflows
    // capacity=8, current=8, incoming=7 => available=0, remaining=7
    assert_eq!(solve(vec![8, 8, 7]), vec![7]);

    // Clamping behavior: construct values causing large positive result
    // capacity=-128, current=127, incoming=127 => available=-255, remaining=127 - (-255) = 382 -> clamp to 127
    assert_eq!(solve(vec![-128, 127, 127]), vec![127]);

    // Negative incoming: result should be clamped at 0
    // capacity=10, current=3, incoming=-5 => available=7, remaining=-12 -> 0
    assert_eq!(solve(vec![10, 3, -5]), vec![0]);

    // Current greater than capacity (outside intended domain but allowed at runtime)
    // capacity=5, current=10, incoming=0 => available=-5, remaining=0 - (-5) = 5
    assert_eq!(solve(vec![5, 10, 0]), vec![5]);

    println!("All tests passed.");
}

