fn solve_cake_problem(a: i8, b: i8) -> &'static str {
    // Enforce the input constraints as per the problem statement
    assert!(1 <= a && a <= 16, "a must be in [1, 16]");
    assert!(1 <= b && b <= 16, "b must be in [1, 16]");
    assert!((a as i32 + b as i32) <= 16, "a + b must be <= 16");

