    // Happy path: small counts well within the non-adjacent limit
    assert_eq!(solve_cake_problem(1, 1), "Yay!");
    assert_eq!(solve_cake_problem(8, 8), "Yay!");

    // Constraint boundaries: sums at the limit, one over the feasible non-adjacent threshold
    assert_eq!(solve_cake_problem(9, 7), ":("); // a exceeds 8
    assert_eq!(solve_cake_problem(7, 9), ":("); // b exceeds 8

    // Boundary near extremes of range with sum at maximum
    assert_eq!(solve_cake_problem(1, 15), ":(");
    assert_eq!(solve_cake_problem(15, 1), ":(");

    // Mixed cases
    assert_eq!(solve_cake_problem(8, 1), "Yay!");
    assert_eq!(solve_cake_problem(4, 12), ":(");
    assert_eq!(solve_cake_problem(6, 10), ":(");
    assert_eq!(solve_cake_problem(8, 7), "Yay!");

    // Verify outputs are always one of the two allowed strings
    for &(x, y) in &[(1, 1), (8, 8), (9, 7), (7, 9), (1, 15), (15, 1), (8, 1), (4, 12), (6, 10), (8, 7)] {
        let res = solve_cake_problem(x, y);
        assert!(res == "Yay!" || res == ":(");
    }
}

