use std::cmp::Ordering;

fn compute_moves(a: i8, b: i8) -> i8 {
    if a == b {
        return 0;
    }
    let ai = a as i16;
    let bi = b as i16;
    let diff = (bi - ai).abs(); // non-negative
    match ai.cmp(&bi) {
        Ordering::Less => {
            // a < b: one move if (b - a) is odd, otherwise two moves
            if diff % 2 == 1 { 1 } else { 2 }
        }
        Ordering::Greater => {
            // a > b: one move if (a - b) is even, otherwise two moves
            if diff % 2 == 0 { 1 } else { 2 }
        }
        Ordering::Equal => 0,
    }
}

fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    // Assumes all pairs have a >= 1 and b >= 1 as per problem constraints
    input.into_iter().map(|(a, b)| compute_moves(a, b)).collect()
}

fn main() {
    // Edge case: empty input
    let input0: Vec<(i8, i8)> = vec![];
    let out0 = solve(input0);
    assert_eq!(out0, vec![]);

    // Single-element, a == b
    let input1 = vec![(5, 5)];
    let out1 = solve(input1);
    assert_eq!(out1, vec![0]);

    // a < b, odd difference
    let input2 = vec![(3, 8)]; // diff = 5 (odd)
    let out2 = solve(input2);
    assert_eq!(out2, vec![1]);

    // a < b, even difference
    let input3 = vec![(4, 10)]; // diff = 6 (even)
    let out3 = solve(input3);
    assert_eq!(out3, vec![2]);

    // a > b, even difference
    let input4 = vec![(10, 4)]; // diff = 6 (even)
    let out4 = solve(input4);
    assert_eq!(out4, vec![1]);

    // a > b, odd difference
    let input5 = vec![(9, 4)]; // diff = 5 (odd)
    let out5 = solve(input5);
    assert_eq!(out5, vec![2]);

    // Boundary constraints: minimum positive values
    let input6 = vec![(1, 1), (1, 2), (2, 1)];
    let out6 = solve(input6);
    assert_eq!(out6, vec![0, 1, 2]);

    // Multiple queries mixed
    let input7 = vec![(6, 6), (2, 7), (7, 2), (3, 4), (8, 3)];
    // (6,6)->0; (2,7) diff=5 odd ->1; (7,2) diff=5 odd ->2; (3,4) diff=1 odd ->1; (8,3) diff=5 odd ->2
    let out7 = solve(input7);
