proof fn lemma_abs_diff_nonneg(x: int, y: int)
    ensures
        abs_diff(x, y) >= 0,
{
    if x >= y {
        assert(abs_diff(x, y) == x - y);
        assert(x - y >= 0);
    } else {
        assert(abs_diff(x, y) == y - x);
        assert(y - x >= 0);
    }
}
// </vc-helpers>

