    let ai16: i16 = a as i16;
    let bi16: i16 = b as i16;
    let wi16: i16 = w as i16;

    let d16: i16 = if ai16 >= bi16 { ai16 - bi16 } else { bi16 - ai16 };

    let res16: i16 = if d16 <= wi16 { 0i16 } else { d16 - wi16 };

