fn solve(input: Vec<char>) -> Vec<char> {
    // Precondition (for tests):
    // - input.len() >= 3
    // - input[1] == ' '
    // - input[0] and input[2] are each 'H' or 'D'
    // - if input.len() > 3 then input[3] == '\n'
    // Output: ['H', '\n'] if input[0] == input[2], else ['D', '\n']
    let mut out: Vec<char> = Vec::new();
    if input[0] == input[2] {
        out.push('H');
    } else {
        out.push('D');
    }
