use std::cmp::Ordering;

fn compare(s1: Vec<char>, s2: Vec<char>) -> i32 {
    if s1.len() < s2.len() {
        -1
    } else if s1.len() > s2.len() {
        1
    } else {
        let mut i = 0;
        while i < s1.len() {
            if s1[i] < s2[i] {
                return -1;
            } else if s1[i] > s2[i] {
                return 1;
            }
            i += 1;
        }
        0
    }
}

fn to_vec_chars(s: &str) -> Vec<char> {
    s.chars().collect()
}

fn main() {
    // Happy path: different lengths, clear numeric order
    assert_eq!(compare(to_vec_chars("101"), to_vec_chars("110")), -1); // 5 < 6
    assert_eq!(compare(to_vec_chars("1101"), to_vec_chars("1011")), 1); // 13 > 11

    // Happy path: equal numbers
    assert_eq!(compare(to_vec_chars("1010"), to_vec_chars("1010")), 0); // 10 == 10

    // Edge cases: zero and single-bit numbers
    assert_eq!(compare(to_vec_chars("0"), to_vec_chars("0")), 0); // 0 == 0
    assert_eq!(compare(to_vec_chars("1"), to_vec_chars("0")), 1); // 1 > 0

    // Constraint boundary: different lengths but canonical (no leading zeros)
    assert_eq!(compare(to_vec_chars("10"), to_vec_chars("1")), 1); // 2 > 1

    // Larger inputs to test length-first rule
    assert_eq!(compare(to_vec_chars("100000"), to_vec_chars("11111")), 1); // 32 > 31

    // Same length, differ in later position
    assert_eq!(compare(to_vec_chars("1001"), to_vec_chars("1000")), 1); // 9 > 8
    assert_eq!(compare(to_vec_chars("1000001"), to_vec_chars("1000010")), -1); // 65 < 66

    println!("All tests passed.");
}

