fn binary_search(a: &[i32], key: i32) -> usize {
    let mut low: usize = 0;
    let mut high: usize = a.len();

    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < key {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    low
}

fn main() {
    // Edge case: empty array
    let a: [i32; 0] = [];
    assert_eq!(binary_search(&a, 10), 0);

    // Single element: equal to key
    let a = [5];
    assert_eq!(binary_search(&a, 5), 0);

    // Single element: less than key
    let a = [3];
    assert_eq!(binary_search(&a, 5), 1);

    // Single element: greater than key
    let a = [7];
    assert_eq!(binary_search(&a, 5), 0);

    // All elements less than key
    let a = [1, 2, 3];
    assert_eq!(binary_search(&a, 10), 3);

    // All elements greater than or equal to key (greater than key case)
    let a = [5, 6, 7];
    assert_eq!(binary_search(&a, 1), 0);

    // Duplicates with key present: first occurrence index
    let a = [1, 2, 2, 2, 4];
    assert_eq!(binary_search(&a, 2), 1);

    // Key not present, falls between elements
    let a = [1, 3, 5, 7];
    assert_eq!(binary_search(&a, 6), 3);

    // Mixed extremes with duplicates
    let a = [i32::MIN, -1, 0, 0, 0, 1, i32::MAX];
    assert_eq!(binary_search(&a, 0), 2);

    // All elements equal to key
    let a = [0, 0, 0, 0];
    assert_eq!(binary_search(&a, 0), 0);
}

