        assert(m >= a[i]);
        i = i + 1;
    }

    // Check: m equals some element in the array
    let mut found = false;
    let mut j = 0;
    while j < a.len() {
        if a[j] == m {
            found = true;
            break;
        }
        j = j + 1;
    }
    assert(found);
}

