use std::cmp;

fn min_array(a: &[i32]) -> i32 {
    assert!(!a.is_empty(), "input slice must be non-empty");
    let mut min_val = a[0];
    for &x in a.iter().skip(1) {
        if x < min_val {
            min_val = x;
        }
    }
    min_val
}

fn is_lower_bound(a: &[i32], r: i32) -> bool {
    a.iter().all(|&x| r <= x)
}

fn main() {
    // Single element
    let v = vec![5];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, 5);

    // All equal elements
    let v = vec![3, 3, 3, 3];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, 3);

    // Increasing order
    let v = vec![1, 2, 3, 4, 5];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, 1);

    // Decreasing order
    let v = vec![5, 4, 3, 2, 1];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, 1);

    // Mixed with negatives
    let v = vec![0, -1, -2, 10, -100, 50];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, -100);

    // Extremes
    let v = vec![i32::MAX, i32::MIN, 0, -1, 1];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, i32::MIN);

    // Duplicates with minimum repeated
    let v = vec![7, 2, 2, 9, 4, 2];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, 2);

    // Two elements
    let v = vec![9, -9];
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, -9);

    // Larger range input
    let mut v = Vec::new();
    for i in -50..=50 {
        v.push(i);
    }
    let r = min_array(&v);
    assert!(is_lower_bound(&v, r));
    assert_eq!(r, -50);
}

