use std::i32;

fn replace(arr: &mut Vec<i32>, k: i32) {
    let n = arr.len();
    let mut i: usize = 0;
    while i < n {
        if arr[i] > k {
            arr[i] = -1;
        }
        i += 1;
    }
}

fn main() {
    // 1) Empty array
    let mut a1: Vec<i32> = vec![];
    replace(&mut a1, 10);
    assert!(a1.is_empty());

    // 2) Single element equal to k (should remain unchanged)
    let mut a2 = vec![5];
    replace(&mut a2, 5);
    assert_eq!(a2, vec![5]);

    // 3) Single element greater than k (should become -1)
    let mut a3 = vec![6];
    replace(&mut a3, 5);
    assert_eq!(a3, vec![-1]);

    // 4) Mixed values around k
    let mut a4 = vec![-5, 0, 7, 10, 11, i32::MAX];
    replace(&mut a4, 10);
    assert_eq!(a4, vec![-5, 0, 7, 10, -1, -1]);

    // 5) All values less or equal to k (unchanged)
    let mut a5 = vec![-3, -2, 0, 10];
    replace(&mut a5, 10);
    assert_eq!(a5, vec![-3, -2, 0, 10]);

    // 6) All values greater than k (all become -1)
    let mut a6 = vec![1, 2, 3];
    replace(&mut a6, 0);
    assert_eq!(a6, vec![-1, -1, -1]);

    // 7) Negative threshold including i32::MIN (only i32::MIN remains; others become -1)
    let mut a7 = vec![i32::MIN, -100, -1, 0];
    replace(&mut a7, i32::MIN);
    assert_eq!(a7, vec![i32::MIN, -1, -1, -1]);

    // 8) Boundary mix with k close to i32::MAX
    let mut a8 = vec![i32::MAX, i32::MIN, 42];
    replace(&mut a8, i32::MAX - 1);
    assert_eq!(a8, vec![-1, i32::MIN, 42]);

    // 9) k = i32::MAX (no element greater; unchanged)
    let mut a9 = vec![i32::MAX, 0];
    replace(&mut a9, i32::MAX);
    assert_eq!(a9, vec![i32::MAX, 0]);

    // 10) Mixed with k = 0 (only positive values become -1)
    let mut a10 = vec![0, -1, 1];
    replace(&mut a10, 0);
    assert_eq!(a10, vec![0, -1, -1]);
}

