        invariant
            0 <= i <= n / 2,
            a.len() == n,
            forall|j: int| 0 <= j < i ==> a[j] == old(a)[n - 1 - j],
            forall|j: int| n - i <= j < n ==> a[j] == old(a)[n - 1 - j],
