use std::usize;

fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    if n == 0 {
        return result;
    }
    // Use offset modulo n to avoid overflow in addition
    let r = offset % n;
    for i in 0..n {
        let source_idx = (i + r) % n;
        result.push(a[source_idx]);
    }
    result
}

fn main() {
    // Happy Path
    assert_eq!(rotate(&[1, 2, 3, 4], 1), vec![2, 3, 4, 1]);
    assert_eq!(rotate(&[1, 2, 3, 4], 2), vec![3, 4, 1, 2]);

    // Edge Cases
    assert_eq!(rotate(&[], 0), Vec::<i32>::new());
    assert_eq!(rotate(&[5], 0), vec![5]);
    assert_eq!(rotate(&[5], 123_456_789), vec![5]);

    // Constraint Boundaries
    assert_eq!(rotate(&[7, 8, 9], 0), vec![7, 8, 9]);
    assert_eq!(rotate(&[7, 8, 9], 3), vec![7, 8, 9]);

    // Offset greater than length
    assert_eq!(rotate(&[1, 2, 3, 4], 7), vec![4, 1, 2, 3]);

    // Very large offset
    let big = usize::MAX;
    assert_eq!(rotate(&[0, 1, 2, 3, 4], big), vec![4, 0, 1, 2, 3]);

    // Composition property: rotate by x then by y equals rotate by x+y
    let a = vec![10, 20, 30, 40, 50];
    let r1 = rotate(&a, 3);
    let r2 = rotate(&r1, 7);
    let r12 = rotate(&a, 10);
    assert_eq!(r2, r12);
}

