    assert!(c == 7 && d == -8);

    // Equal positive numbers
    let (a, b) = swap(42, 42);
    assert!(a == 42 && b == 42);

    // One zero and negative
    let (a, b) = swap(0, -1);
    assert!(a == -1 && b == 0);
}

