            v.len() == n,
            i <= n,
            forall|k: int|
                0 <= k && k < i as int ==> #[trigger] v@[k] == if old(v)@[k] == x { y } else { old(v)@[k] },
            forall|k: int|
                i as int <= k && k < n as int ==> #[trigger] v@[k] == old(v)@[k],
        decreases (n - i) as int
    {
        assert(i < v.len());
