fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    let mut left = a;
    let k_usize: usize = if n == 0 { 0usize } else { 1usize };
    let right = left.split_off(k_usize);
    (left, right)
}

fn concat(left: &Vec<i32>, right: &Vec<i32>) -> Vec<i32> {
    let mut combined = left.clone();
    combined.extend_from_slice(&right);
    combined
}

