fn find_max(a: &[i32]) -> usize {
    assert!(!a.is_empty(), "Input array must be non-empty");
    let mut max_idx = 0usize;
    for j in 1..a.len() {
        if a[j] > a[max_idx] {
            max_idx = j;
        }
    }
    max_idx
}

fn is_max_index(a: &[i32], idx: usize) -> bool {
    if a.is_empty() || idx >= a.len() { return false; }
    for k in 0..a.len() {
        if a[k] > a[idx] { return false; }
    }
    true
}

fn main() {
    // 1. Single-element array
    let a1 = [42];
    let i1 = find_max(&a1);
    assert!(is_max_index(&a1, i1));
    assert_eq!(i1, 0);
    assert_eq!(a1[i1], 42);

    // 2. Strictly increasing array
    let a2 = [1, 2, 3, 4, 5];
    let i2 = find_max(&a2);
    assert!(is_max_index(&a2, i2));
    assert_eq!(i2, 4);
    assert_eq!(a2[i2], 5);

    // 3. Strictly decreasing array
    let a3 = [5, 4, 3, 2, 1];
    let i3 = find_max(&a3);
    assert!(is_max_index(&a3, i3));
    assert_eq!(i3, 0);
    assert_eq!(a3[i3], 5);

    // 4. Array with duplicates (any max index acceptable)
    let a4 = [3, 1, 3, 2, 3];
    let i4 = find_max(&a4);
    assert!(is_max_index(&a4, i4));
    assert_eq!(a4[i4], 3);

    // 5. Negative numbers
    let a5 = [-10, -20, -30, -5];
    let i5 = find_max(&a5);
    assert!(is_max_index(&a5, i5));
    assert_eq!(i5, 3);
    assert_eq!(a5[i5], -5);

    // 6. All equal elements (any index acceptable)
    let a6 = [5, 5, 5, 5];
    let i6 = find_max(&a6);
    assert!(is_max_index(&a6, i6));
    assert_eq!(a6[i6], 5);

    // 7. Two equal elements (boundary for small size)
    let a7 = [7, 7];
    let i7 = find_max(&a7);
    assert!(is_max_index(&a7, i7));
    assert_eq!(a7[i7], 7);

    // 8. Max at the end with extremes
    let a8 = [i32::MIN, 0, i32::MAX, i32::MAX - 1];
    let i8 = find_max(&a8);
    assert!(is_max_index(&a8, i8));
    assert_eq!(i8, 2);
    assert_eq!(a8[i8], i32::MAX);

    // 9. Max in the middle
    let a9 = [2, 9, 3, 1];
    let i9 = find_max(&a9);
    assert!(is_max_index(&a9, i9));
    assert_eq!(i9, 1);
    assert_eq!(a9[i9], 9);
}

