use std::cmp;

fn search_range_helper(a: &[i32], x: i32, mut lo: usize, mut hi: usize) -> usize {
    // Returns k such that for all r in [lo, k), a[r] < x and for all r in [k, hi), a[r] >= x.
    while lo < hi {
        let mid = (lo + hi) / 2;
        if a[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(a.len() >= 1000, "Array length must be at least 1000");
    // Caller must also ensure the first 1000 elements are nondecreasing.
    search_range_helper(a, x, 0, 1000)
}

fn check_lower_bound_prefix_1000(a: &[i32], x: i32, k: usize) {
    assert!(k <= 1000);
    for r in 0..k {
        assert!(a[r] < x, "Violation: a[{}]={} not < {} before k={}", r, a[r], x, k);
    }
    for r in k..1000 {
        assert!(a[r] >= x, "Violation: a[{}]={} not >= {} from k={} to 1000", r, a[r], x, k);
    }
}

fn main() {
    // Test 1: Increasing sequence, typical case
    let a1: Vec<i32> = (0..2000).map(|v| v as i32).collect();
    let x1 = 500;
    let k1 = search_1000(&a1, x1);
