use std::i32;

fn max(a: &[i32], b: &[i32], i: usize, j: usize) -> i32 {
    let ai = a[i];
    let bj = b[j];
    if ai > bj { ai } else { bj }
}

fn main() {
    // Happy Path: standard inputs
    let a1 = [1, 3, 5];
    let b1 = [2, 4, 6];
    assert_eq!(max(&a1, &b1, 1, 2), 6); // compare 3 vs 6

    // Happy Path: first array's element is larger
    let a2 = [10, 20];
    let b2 = [5, 15];
    assert_eq!(max(&a2, &b2, 1, 1), 20); // compare 20 vs 15

    // Edge Case: equality, must return the element from the second array
    let a3 = [7, 7];
    let b3 = [7, 8];
    let res3 = max(&a3, &b3, 0, 0); // compare 7 vs 7
    assert_eq!(res3, 7);
    assert_eq!(res3, b3[0]); // tie goes to second array element

    // Edge Case: negative numbers
    let a4 = [-10, -5];
    let b4 = [-6, -20];
    assert_eq!(max(&a4, &b4, 1, 0), -5); // compare -5 vs -6

    // Constraint Boundary: single-element arrays
    let a5 = [42];
    let b5 = [12];
    assert_eq!(max(&a5, &b5, 0, 0), 42);

    // Constraint Boundary: use last valid indices
    let a6 = [1, 2, 3, 4];
    let b6 = [4, 3, 2, 1];
    assert_eq!(max(&a6, &b6, 3, 3), 4); // compare 4 vs 1

    // Edge Case: equal negative values, ensure second element is chosen on tie
    let a7 = [-1, 0];
    let b7 = [0, -1];
    let res7 = max(&a7, &b7, 0, 1); // compare -1 vs -1
    assert_eq!(res7, -1);
    assert_eq!(res7, b7[1]);

    // Boundary values: extremes
    let a8 = [i32::MIN, i32::MAX];
    let b8 = [0];
    assert_eq!(max(&a8, &b8, 1, 0), i32::MAX); // compare MAX vs 0

    // Second array larger (non-tie)
    let a9 = [100];
    let b9 = [200];
    assert_eq!(max(&a9, &b9, 0, 0), 200);

    // Edge Case: empty collections (do not call max; indices would be invalid)
    let empty: [i32; 0] = [];
    let single = [42];
    assert_eq!(empty.len(), 0);
    assert_eq!(single.len(), 1);
}

