verus! {
    fn main() {
        // Helper closure to validate post-conditions after calling swap3
        let check = |mut arr: Vec<i32>, h: usize, i: usize, j: usize| {
            let old = arr.clone();
            swap3(&mut arr, h, i, j);

            // Length unchanged
            assert!(arr.len() == old.len());

            // Updated positions follow the 3-cycle from original values
            assert!(arr[h] == old[i]);
            assert!(arr[i] == old[j]);
            assert!(arr[j] == old[h]);

            // All other positions unchanged
            for k in 0..old.len() {
                if k != h && k != i && k != j {
                    assert!(arr[k] == old[k]);
                }
            }
        };

        // Test 1: Minimal valid length (3), straightforward order
        check(vec![1, 2, 3], 0, 1, 2);

        // Test 2: Larger array, indices include last and first positions
        check(vec![10, 20, 30, 40, 50], 4, 0, 2);

        // Test 3: Negative values, mixed indices
        check(vec![-5, -1, -3, -7], 1, 3, 0);

        // Test 4: Duplicate values (ensures correctness without relying on uniqueness)
        check(vec![7, 7, 7, 7, 7, 7], 5, 1, 4);

        // Test 5: Extreme values
        check(vec![i32::MIN, 0, i32::MAX, -100, 100], 2, 3, 4);

        // Test 6: Larger array, indices include last two and first
        check(vec![1, 2, 3, 4, 5, 6, 7, 8], 7, 6, 0);

        // Test 7: Minimal valid length (3), different index order
        check(vec![9, 8, 7], 2, 0, 1);
    }
}

