use std::panic;

fn gcd_calc(m: u32, n: u32) -> u32 {
    assert!(m > 0 && n > 0, "Inputs must be strictly positive");
    let mut a = m;
    let mut b = n;
    while a != b {
        if a > b {
            a -= b;
        } else {
            b -= a;
        }
    }
    a
}

fn main() {
    // Happy Path: standard inputs
    assert_eq!(gcd_calc(12, 18), 6);
    assert_eq!(gcd_calc(18, 12), 6); // swapped order
    assert_eq!(gcd_calc(48, 18), 6);

    // Edge Cases: equal numbers, co-prime, one is 1
    assert_eq!(gcd_calc(7, 7), 7);       // equal numbers
    assert_eq!(gcd_calc(35, 64), 1);     // co-prime
    assert_eq!(gcd_calc(1, 999), 1);     // smallest valid input with a larger number

    // Boundary-like values within reasonable runtime
    assert_eq!(gcd_calc(1024, 64), 64);  // power of two structure
    assert_eq!(gcd_calc(270, 192), 6);   // classic GCD example

    // Additional checks for positivity and correctness
    let r = gcd_calc(13, 26);
    assert_eq!(r, 13);
    assert!(r > 0);

    // Constraint boundaries: ensure positive inputs; demonstrate panic on invalid input by catching it
    let result = panic::catch_unwind(|| gcd_calc(0, 5));
    assert!(result.is_err());
    let result2 = panic::catch_unwind(|| gcd_calc(5, 0));
    assert!(result2.is_err());
}

