use std::cmp;

fn findMax(a: &[i32], n: usize) -> usize {
    assert!(a.len() > 0);
    assert!(n > 0 && n <= a.len());
    let mut max_idx = 0;
    let mut i = 1;
    while i < n {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
        i += 1;
    }
    max_idx
}

fn expected_first_max_idx(a: &[i32], n: usize) -> usize {
    assert!(n > 0 && n <= a.len());
    let max_val = a[..n].iter().cloned().max().unwrap();
    for i in 0..n {
        if a[i] == max_val {
            return i;
        }
    }
    unreachable!();
}

fn is_max_in_prefix(a: &[i32], n: usize, idx: usize) -> bool {
    idx < n && a[..n].iter().all(|&v| a[idx] >= v)
}

fn main() {
    // 1. Single element
    let a1 = [42];
    let r1 = findMax(&a1, 1);
    assert_eq!(r1, 0);
    assert!(is_max_in_prefix(&a1, 1, r1));

    // 2. Full array, distinct positives
    let a2 = [1, 3, 2, 5, 4];
    let r2 = findMax(&a2, 5);
    assert_eq!(r2, expected_first_max_idx(&a2, 5)); // index of 5 is 3
    assert!(is_max_in_prefix(&a2, 5, r2));

    // 3. All negative values
    let a3 = [-10, -50, -3, -4];
    let r3 = findMax(&a3, 4);
    assert_eq!(r3, expected_first_max_idx(&a3, 4)); // index of -3 is 2
    assert!(is_max_in_prefix(&a3, 4, r3));

    // 4. All equal values (ties allowed)
    let a4 = [7, 7, 7, 7];
    let r4 = findMax(&a4, 4);
    assert_eq!(r4, expected_first_max_idx(&a4, 4)); // first occurrence is 0
    assert!(is_max_in_prefix(&a4, 4, r4));

    // 5. Prefix smaller than array length; ignores later large values
    let a5 = [1, 2, 3, 100];
    let r5 = findMax(&a5, 3);
    assert_eq!(r5, expected_first_max_idx(&a5, 3)); // index of 3 is 2
    assert!(is_max_in_prefix(&a5, 3, r5));

    // 6. Mixed with i32 bounds
    let a6 = [i32::MIN, 0, i32::MAX, -1];
    let r6 = findMax(&a6, 4);
    assert_eq!(r6, expected_first_max_idx(&a6, 4)); // index of i32::MAX is 2
    assert!(is_max_in_prefix(&a6, 4, r6));

    // 7. Duplicates with first-maximum tie-breaking
    let a7 = [5, 100, 100, 50];
    let r7 = findMax(&a7, 3);
    assert_eq!(r7, expected_first_max_idx(&a7, 3)); // first 100 at index 1
    assert!(is_max_in_prefix(&a7, 3, r7));

    // 8. Typical random-like sequence with a mid-size prefix
    let a8 = [3, 1, 4, 1, 5, 9, 2, 6];
    let r8 = findMax(&a8, 5); // prefix [3,1,4,1,5]
    assert_eq!(r8, expected_first_max_idx(&a8, 5)); // index of 5 is 4
    assert!(is_max_in_prefix(&a8, 5, r8));
}

