verus! {

fn flip(a: &mut Vec<i32>, num: usize)
    requires 
        old(a).len() > 0,
        num < old(a).len(),
    ensures
        forall|k: int| 0 <= k <= num as int ==> #[trigger] a[k] == old(a)[num as int - k],
        a.len() == old(a).len(),
{
    let mut i = 0;
    while i <= num / 2
        invariant
            a.len() == old(a).len(),
            num < old(a).len(),
            i <= num / 2 + 1,
            forall|k: int| 0 <= k < i ==> #[trigger] a[k] == old(a)[num as int - k],
            forall|k: int| num as int - i < k <= num as int ==> #[trigger] a[k] == old(a)[num as int - k],
            forall|k: int| i <= k <= num as int - i ==> #[trigger] a[k] == old(a)[k],
        decreases num / 2 + 1 - i
    {
        let temp = a[i];
        let temp2 = a[num - i];
        a.set(i, temp2);
        a.set(num - i, temp);
        i += 1;
    }
}

fn main() {
    // Test 1: index = 0 (prefix of length 1)
    let mut a1 = Vec::new();
    a1.push(1); a1.push(2); a1.push(3); a1.push(4); a1.push(5);
