use vstd::prelude::*;

verus! {

fn look_for_min(a: &[int], i: usize) -> (m: usize)
    requires 
        0 <= i < a.len(),
    ensures
        i <= m < a.len(),
        forall|k: int| #![trigger a[k]] i <= k < a.len() ==> a[k] >= a[m as int],
{
    let mut min_idx = i;
    let mut j = i + 1;

    while j < a.len()
        invariant
            i <= min_idx < a.len(),
            i + 1 <= j <= a.len(),
            forall|k: int| #![trigger a[k]] i <= k < j ==> a[k] >= a[min_idx as int],
        decreases a.len() - j,
    {
        if a[j] < a[min_idx] {
            min_idx = j;
        }
        j += 1;
    }

    min_idx
}

fn main() {
    // Helper to check the postcondition with executable assertions
    fn check_min(a: &[int], start: usize, m: usize) {
        assert(start <= m && m < a.len());
        let mut k: usize = start;
        while k < a.len() {
            assert(a[k] >= a[m]);
            k += 1;
        }
    }

    // Edge case: empty array (cannot call the function due to precondition)
    let empty: [int; 0] = [];
    assert(empty.len() == 0);
    let invalid_start: usize = 0;
    // Do not call look_for_min(&empty, invalid_start) because 0 <= start < len is violated.

    // 1) Single-element array
    let a1: [int; 1] = [42 as int];
    let m1 = look_for_min(&a1, 0);
    assert(m1 == 0);
    check_min(&a1, 0, m1);

    // 2) Ascending order, start at 0
    let a2: [int; 4] = [1 as int, 2 as int, 3 as int, 4 as int];
    let m2 = look_for_min(&a2, 0);
    assert(m2 == 0);
    check_min(&a2, 0, m2);

    // 3) Descending order, start at 0
    let a3: [int; 4] = [4 as int, 3 as int, 2 as int, 1 as int];
    let m3 = look_for_min(&a3, 0);
    assert(m3 == 3);
    check_min(&a3, 0, m3);

    // 4) Start in the middle; minimum is at the end of the suffix
    let a4: [int; 5] = [5 as int, 3 as int, 4 as int, 2 as int, 1 as int];
    let m4 = look_for_min(&a4, 2);
    assert(m4 == 4);
    check_min(&a4, 2, m4);

    // 5) Start at the last index
    let a5: [int; 3] = [7 as int, 3 as int, 9 as int];
    let m5 = look_for_min(&a5, 2);
    assert(m5 == 2);
    check_min(&a5, 2, m5);

    // 6) All equal values, start not at 0
    let a6: [int; 4] = [4 as int, 4 as int, 4 as int, 4 as int];
    let m6 = look_for_min(&a6, 1);
    // First occurrence in the suffix is acceptable; property should hold
    assert(m6 == 1);
    check_min(&a6, 1, m6);

    // 7) Contains negatives and duplicates
    let a7: [int; 4] = [0 as int, -1 as int, -1 as int, 2 as int];
    let m7 = look_for_min(&a7, 0);
    assert(m7 == 1);
    check_min(&a7, 0, m7);

    // 8) Start index skips an earlier global minimum
    let a8: [int; 4] = [3 as int, 1 as int, 2 as int, 0 as int];
    let m8 = look_for_min(&a8, 2);
    assert(m8 == 3);
    check_min(&a8, 2, m8);

    // 9) Mixed values with repeated minima in suffix
    let a9: [int; 5] = [10 as int, -5 as int, 0 as int, -5 as int, 8 as int];
    let m9 = look_for_min(&a9, 1);
    assert(m9 == 1);
    check_min(&a9, 1, m9);

    // 10) Large magnitude values
    let a10: [int; 3] = [1000000 as int, -1000000 as int, 100 as int];
    let m10 = look_for_min(&a10, 0);
    assert(m10 == 1);
    check_min(&a10, 0, m10);
}

}

