use std::i32;

fn single(x: &[i32], y: &[i32]) -> Vec<i32> {
    // Concatenate x and y preserving order
    let mut result = Vec::with_capacity(x.len() + y.len());
    for &v in x {
        result.push(v);
    }
    for &v in y {
        result.push(v);
    }
    result
}

fn main() {
    // Happy Path: example from description
    {
        let a = [1, 5, 2, 3];
        let b = [4, 3, 5];
        let r = single(&a, &b);
        assert_eq!(r, vec![1, 5, 2, 3, 4, 3, 5]);
    }

    // Boundary (minimal non-empty): single element each
    {
        let a = [7];
        let b = [9];
        let r = single(&a, &b);
        assert_eq!(r, vec![7, 9]);
    }

    // One very short, one longer
    {
        let a = [0];
        let b = [1, 2, 3];
        let r = single(&a, &b);
        assert_eq!(r, vec![0, 1, 2, 3]);
    }

    // Negatives and zeros
    {
        let a = [-1, 0, -2];
        let b = [0, -3];
        let r = single(&a, &b);
        assert_eq!(r, vec![-1, 0, -2, 0, -3]);
    }

    // Extreme values
    {
        let a = [i32::MAX];
        let b = [i32::MIN];
        let r = single(&a, &b);
        assert_eq!(r, vec![i32::MAX, i32::MIN]);
    }

    // Repeated values
    {
        let a = [5, 5, 5];
        let b = [5, 5];
        let r = single(&a, &b);
        assert_eq!(r, vec![5, 5, 5, 5, 5]);
    }

    // Different signs and lengths
    {
        let a = [10, 20];
        let b = [-10, -20, -30];
        let r = single(&a, &b);
