fn check_case(input: Vec<char>, expected: Vec<char>) {
    // Precondition: input.len() > 0
    assert(input.len() > 0);
    let out = reverse(&input);
    assert_eq!(out.len(), input.len());
    assert_eq!(out, expected);
    for i in 0..input.len() {
        assert(out[i] == input[input.len() - i - 1]);
    }
}

