use std::cmp::Ordering;

fn min_second_value_first(s: &Vec<Vec<i32>>) -> i32 {
    // Precondition checks to mirror the specification
    assert!(!s.is_empty(), "Outer vector must be non-empty");
    for row in s {
        assert!(row.len() >= 2, "Each inner vector must have at least two elements");
    }

    let mut min_idx: usize = 0;
    for i in 1..s.len() {
        if s[i][1] < s[min_idx][1] {
            min_idx = i;
        }
    }
    s[min_idx][0]
}

fn is_valid_output(s: &Vec<Vec<i32>>, out: i32) -> bool {
    assert!(!s.is_empty());
    for row in s { assert!(row.len() >= 2); }
    let mut min_second = s[0][1];
    for i in 1..s.len() {
        if s[i][1] < min_second {
            min_second = s[i][1];
        }
    }
    s.iter().any(|row| row[1] == min_second && row[0] == out)
}

fn main() {
    // Test 1: Happy path, distinct second elements
    let s1 = vec![vec![10, 5], vec![20, 7], vec![30, 9]];
    let r1 = min_second_value_first(&s1);
    assert_eq!(r1, 10);
    assert!(is_valid_output(&s1, r1));

