verus! {

fn min_of_three(a: i32, b: i32, c: i32) -> (min: i32)
    ensures
        min <= a && min <= b && min <= c,
        (min == a) || (min == b) || (min == c),
{
    if a <= b {
        if a <= c {
            a
        } else {
            assert(a <= b);
            assert(c < a);
            assert(c <= a);
            assert(c <= b);
            c
        }
    } else {
        assert(b < a);
        if b <= c {
            assert(b <= a);
            b
        } else {
            assert(c < b);
            assert(c <= b);
            assert(b <= a);
            assert(c <= a);
            c
        }
    }
}

fn main() {
    // Happy path: strictly increasing
    let r1 = min_of_three(1, 2, 3);
    assert(r1 == 1);

    // Minimum in the middle
    let r2 = min_of_three(5, 1, 9);
    assert(r2 == 1);

    // Minimum is the last argument
    let r3 = min_of_three(7, 8, -2);
    assert(r3 == -2);

    // All equal
    let r4 = min_of_three(4, 4, 4);
    assert(r4 == 4);

    // Two equal minimums
    let r5 = min_of_three(0, 0, 5);
    assert(r5 == 0);

    // All negative values
    let r6 = min_of_three(-10, -3, -7);
    assert(r6 == -10);

    // Boundary values: MIN present
    let r7 = min_of_three(i32::MAX, i32::MIN, 0);
    assert(r7 == i32::MIN);

    // Boundary values: MIN among close values
    let r8 = min_of_three(i32::MIN + 1, i32::MIN + 2, i32::MIN);
    assert(r8 == i32::MIN);

    // Mixed duplicates with a distinct minimum
    let r9 = min_of_three(42, -1, 42);
    assert(r9 == -1);
}

}

