fn check_spec(arr: &[i32], out: &Vec<i32>) {
    // 1) Every element of out is even and occurs in arr
    let mut i: usize = 0;
    while i < out.len() {
        let y = out[i];
        assert!(y % 2 == 0);
        let mut found = false;
        let mut j: usize = 0;
        while j < arr.len() {
            if arr[j] == y {
                found = true;
                break;
            }
            j += 1;
        }
        assert!(found);
        i += 1;
    }

    // 2) Every even element of arr appears in out at least once
    let mut k: usize = 0;
    while k < arr.len() {
        if arr[k] % 2 == 0 {
            let target = arr[k];
            let mut found = false;
            let mut t: usize = 0;
            while t < out.len() {
                if out[t] == target {
                    found = true;
                    break;
                }
                t += 1;
            }
            assert!(found);
        }
        k += 1;
    }
}

fn expect_evens(arr: &[i32]) -> Vec<i32> {
    let mut v = Vec::new();
    let mut i: usize = 0;
    while i < arr.len() {
        if arr[i] % 2 == 0 {
            v.push(arr[i]);
        }
        i += 1;
    }
    v
}

fn eq_vec(a: &Vec<i32>, b: &Vec<i32>) -> bool {
    if a.len() != b.len() { return false; }
    let mut i: usize = 0;
    while i < a.len() {
        if a[i] != b[i] { return false; }
        i += 1;
    }
    true
}

fn main() {
    // 1) Empty input
    let arr1: Vec<i32> = vec![];
    let out1 = remove_odd_numbers(&arr1);
    assert!(out1.len() == 0);
    check_spec(&arr1, &out1);
    assert!(eq_vec(&out1, &expect_evens(&arr1)));

    // 2) All odd numbers
    let arr2: Vec<i32> = vec![1, 3, 5, -7];
    let out2 = remove_odd_numbers(&arr2);
    assert!(out2.len() == 0);
    check_spec(&arr2, &out2);
    assert!(eq_vec(&out2, &expect_evens(&arr2)));

    // 3) All even numbers (including zero and negative)
    let arr3: Vec<i32> = vec![2, 4, 0, -8];
    let out3 = remove_odd_numbers(&arr3);
    assert!(out3.len() == 4);
    check_spec(&arr3, &out3);
    assert!(eq_vec(&out3, &expect_evens(&arr3)));

    // 4) Mixed small array
    let arr4: Vec<i32> = vec![1, 2, 3, 4, 5, 6];
    let out4 = remove_odd_numbers(&arr4);
