use std::fmt::Debug;

fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
    // Mirror the precondition: all inner vectors must be non-empty.
    // In standard Rust, we assert this to avoid undefined behavior.
    let mut r = Vec::with_capacity(l.len());
    let mut i = 0usize;
    while i < l.len() {
        assert!(!l[i].is_empty(), "Precondition violated: inner vector at index {} is empty", i);
        r.push(l[i][l[i].len() - 1]);
        i += 1;
    }
    r
}

fn assert_vec_eq<T: PartialEq + Debug>(a: Vec<T>, b: Vec<T>) {
    assert_eq!(a, b);
}

fn main() {
    // Test 1: Happy path with multiple inner vectors
    let input1 = vec![vec!['a', 'b', 'c'], vec!['x', 'y']];
    let expected1 = vec!['c', 'y'];
    let output1 = extract_rear_chars(&input1);
    assert_vec_eq(output1, expected1);

    // Test 2: Single inner vector with a single element
    let input2 = vec![vec!['z']];
