// Assume the functions under test are available in scope:
// fn has_common_element(a: &[i32], b: &[i32]) -> bool;
// fn slice_contains(s: &[i32], val: i32) -> bool;

fn main() {
    // Happy path: common element present
    assert!(has_common_element(&[1, 2, 3], &[4, 5, 2]));

    // No common elements
    assert!(!has_common_element(&[1, 2, 3], &[4, 5, 6]));

    // Edge case: first slice empty
    assert!(!has_common_element(&[], &[1, 2]));

    // Edge case: both slices empty
    assert!(!has_common_element(&[], &[]));

    // Duplicates and common element
    assert!(has_common_element(&[7, 7, 7], &[7]));

    // Negative numbers and zero
    assert!(has_common_element(&[0, -1, -2], &[10, 0, 20]));

    // Boundary values: MIN/MAX
    assert!(has_common_element(&[i32::MIN, 0, i32::MAX], &[i32::MAX]));
    assert!(!has_common_element(&[i32::MIN], &[i32::MAX]));

    // Single-element arrays equal
    assert!(has_common_element(&[42], &[42]));

    // Single-element arrays unequal
    assert!(!has_common_element(&[42], &[43]));

    // Additional tests for the membership function
    assert!(slice_contains(&[1, 2, 3], 2));
    assert!(!slice_contains(&[1, 2, 3], 4));
    assert!(!slice_contains(&[], 10));
    assert!(slice_contains(&[i32::MIN, i32::MAX], i32::MIN));
}

