fn is_greater(n: i32, a: &[i32]) -> bool {
    for &x in a {
        if n <= x {
            return false;
        }
    }
    true
}

fn main() {
    // 1. Empty array: should return true
    assert!(is_greater(5, &[]));

    // 2. Single element smaller than n: true
    assert!(is_greater(2, &[1]));

    // 3. Single element equal to n: false
    assert!(!is_greater(3, &[3]));

    // 4. Single element greater than n: false
    assert!(!is_greater(9, &[10]));

    // 5. Multiple elements, all less than n: true
    assert!(is_greater(4, &[-2, 0, 3]));

    // 6. Multiple elements with an element equal to n: false
    assert!(!is_greater(3, &[-2, 0, 3]));

    // 7. Negative values: element -1 is >= -2, expect false
    assert!(!is_greater(-2, &[-10, -5, -1]));

    // 8. Extreme values: n = i32::MAX, all elements less -> true
    assert!(is_greater(i32::MAX, &[i32::MIN, -100, 0]));

    // 9. Extreme values: array contains i32::MAX, n = i32::MAX -> false
    assert!(!is_greater(i32::MAX, &[i32::MAX]));
}

