verus! {

fn calculate_loss(cost_price: i32, selling_price: i32) -> (loss: i32)
    requires cost_price >= 0 && selling_price >= 0,
    ensures (cost_price > selling_price ==> loss == cost_price - selling_price) && (cost_price <= selling_price ==> loss == 0)
{
  if cost_price > selling_price {
    let d = cost_price - selling_price;
    d
  } else {
    0
  }
}

fn main() {
    // Happy path
    assert_eq!(calculate_loss(100, 60), 40);
    assert_eq!(calculate_loss(75, 75), 0);
    assert_eq!(calculate_loss(0, 0), 0);
    assert_eq!(calculate_loss(123456, 123000), 456);

    // Edge cases within requires
    assert_eq!(calculate_loss(10, 20), 0); // selling >= cost
    assert_eq!(calculate_loss(i32::MAX, 0), i32::MAX); // maximum difference
    assert_eq!(calculate_loss(1, 1), 0);
    assert_eq!(calculate_loss(500, 499), 1);
    assert_eq!(calculate_loss(9_999_999, 9_999_998), 1); // large close values
}

}

