use std::i32;

fn get_first_elements(lst: Vec<Vec<i32>>) -> Vec<i32> {
    // Precondition (assumed by problem): every inner vector is non-empty.
    let mut result = Vec::with_capacity(lst.len());
    for v in lst.iter() {
        result.push(v[0]);
    }
    result
}

fn main() {
    // Test 1: Happy path with mixed inner lengths
    let input1 = vec![vec![1, 2, 3], vec![4, 5], vec![6]];
    let n1 = input1.len();
    let out1 = get_first_elements(input1);
    assert_eq!(out1, vec![1, 4, 6]);
    assert_eq!(out1.len(), n1);

    // Test 2: Edge case - empty outer array
    let input2: Vec<Vec<i32>> = vec![];
    let n2 = input2.len();
    let out2 = get_first_elements(input2);
    assert_eq!(out2, vec![]);
    assert_eq!(out2.len(), n2);

    // Test 3: Single inner array with one element
    let input3 = vec![vec![10]];
    let n3 = input3.len();
    let out3 = get_first_elements(input3);
    assert_eq!(out3, vec![10]);
    assert_eq!(out3.len(), n3);

    // Test 4: All inner arrays have multiple elements
    let input4 = vec![vec![0, 0], vec![7, 8, 9], vec![-1, 2]];
    let n4 = input4.len();
    let out4 = get_first_elements(input4);
    assert_eq!(out4, vec![0, 7, -1]);
    assert_eq!(out4.len(), n4);

    // Test 5: Boundary values (i32::MAX and i32::MIN)
    let input5 = vec![vec![i32::MAX, 1], vec![i32::MIN, 2]];
    let n5 = input5.len();
    let out5 = get_first_elements(input5);
    assert_eq!(out5, vec![i32::MAX, i32::MIN]);
    assert_eq!(out5.len(), n5);

    // Test 6: Mix of zeros and negatives
    let input6 = vec![vec![0], vec![-5, -4], vec![3, 3, 3]];
    let n6 = input6.len();
    let out6 = get_first_elements(input6);
    assert_eq!(out6, vec![0, -5, 3]);
    assert_eq!(out6.len(), n6);

    // Test 7: Varied lengths
    let input7 = vec![vec![9, 8], vec![2], vec![5, 4, 3, 2, 1], vec![100, 101]];
    let n7 = input7.len();
    let out7 = get_first_elements(input7);
    assert_eq!(out7, vec![9, 2, 5, 100]);
    assert_eq!(out7.len(), n7);

    // Test 8: Larger number of inner arrays
    let input8 = vec![vec![1], vec![2], vec![3, 30], vec![4, 40, 400], vec![5], vec![6], vec![7, 70], vec![8]];
    let n8 = input8.len();
    let out8 = get_first_elements(input8);
    assert_eq!(out8, vec![1, 2, 3, 4, 5, 6, 7, 8]);
    assert_eq!(out8.len(), n8);
}

