use std::i32;

fn contains_consecutive_numbers(a: &[i32]) -> bool {
    assert!(a.len() > 0, "Precondition violated: array length must be > 0");
    let mut i: usize = 0;
    while i < a.len() - 1 {
        if let Some(val) = a[i].checked_add(1) {
            if val == a[i + 1] {
                return true;
            }
        }
        i += 1;
    }
    false
}

fn main() {
    // 1) Single-element array (allowed by precondition), cannot have adjacent pair
    let a1 = [5];
    assert_eq!(contains_consecutive_numbers(&a1), false);

    // 2) Consecutive pair at the beginning
    let a2 = [3, 4, 10];
    assert_eq!(contains_consecutive_numbers(&a2), true);

    // 3) Consecutive pair in the middle
    let a3 = [7, 8, 8, 20];
    assert_eq!(contains_consecutive_numbers(&a3), true);

    // 4) Consecutive pair at the end
    let a4 = [0, -1, 100, 101];
    assert_eq!(contains_consecutive_numbers(&a4), true);

    // 5) No consecutive adjacent elements
    let a5 = [2, 4, 6, 8];
    assert_eq!(contains_consecutive_numbers(&a5), false);

    // 6) Negative numbers with a consecutive adjacent pair
    let a6 = [-3, -2, 5];
    assert_eq!(contains_consecutive_numbers(&a6), true);

    // 7) Boundary near i32::MAX: consecutive pair exists
    let a7 = [i32::MAX - 1, i32::MAX];
    assert_eq!(contains_consecutive_numbers(&a7), true);

    // 8) i32::MAX followed by i32::MIN: not consecutive (no overflow wrap)
    let a8 = [i32::MAX, i32::MIN];
    assert_eq!(contains_consecutive_numbers(&a8), false);

    // 9) Multiple consecutive pairs present
    let a9 = [1, 2, 3, 4];
    assert_eq!(contains_consecutive_numbers(&a9), true);

    println!("All tests passed.");
}

