use vstd::prelude::*;

verus! {
fn main() {
    // Helper to compute expected toggled case for ASCII letters
    fn expected_toggle(input: Vec<char>) -> Vec<char> {
        let mut out = Vec::new();
        let mut i = 0;
        while i < input.len() {
            let c = input[i];
            let newc = if (c as u32) >= 97 && (c as u32) <= 122 {
                ((c as u32 - 32) as u8) as char
            } else if (c as u32) >= 65 && (c as u32) <= 90 {
                ((c as u32 + 32) as u8) as char
            } else {
                c
            };
            out.push(newc);
            i += 1;
        }
        out
    }

    // 1) Edge: Empty input
    {
        let input: Vec<char> = vec![];
        let output = toggle_case(input.clone());
        assert!(output.len() == input.len());
        assert!(output == expected_toggle(input));
    }

    // 2) Single lowercase
    {
        let input: Vec<char> = vec!['a'];
        let output = toggle_case(input.clone());
        assert!(output == vec!['A']);
    }

    // 3) Single uppercase
    {
        let input: Vec<char> = vec!['Z'];
        let output = toggle_case(input.clone());
        assert!(output == vec!['z']);
    }

    // 4) Mixed ASCII with punctuation
    {
        let input: Vec<char> = "Hello, World!".chars().collect();
        let output = toggle_case(input.clone());
        let expected = "hELLO, wORLD!".chars().collect::<Vec<char>>();
        assert!(output == expected);
    }

    // 5) Alphanumeric mix
    {
        let input: Vec<char> = "abcXYZ123".chars().collect();
        let output = toggle_case(input.clone());
        let expected = "ABCxyz123".chars().collect::<Vec<char>>();
        assert!(output == expected);
    }

    // 6) Non-ASCII characters remain unchanged
    {
        let input: Vec<char> = vec!['é', 'ß', 'Ç'];
        let output = toggle_case(input.clone());
        assert!(output == input);
    }

    // 7) Boundary letters
    {
        let input: Vec<char> = vec!['a', 'z', 'A', 'Z'];
        let output = toggle_case(input.clone());
        let expected: Vec<char> = vec!['A', 'Z', 'a', 'z'];
        assert!(output == expected);
    }

    // 8) Short patterned string
    {
        let mut input: Vec<char> = Vec::new();
        for ch in "AaZz".chars() {
            input.push(ch);
        }
        let output = toggle_case(input.clone());
        let expected = "aAzZ".chars().collect::<Vec<char>>();
        assert!(output == expected);
    }
}
}

