use vstd::prelude::*;

verus! {

fn array_to_seq(a: &[i32]) -> (s: Vec<i32>)
    ensures
        s.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> s[i] == a[i],
{
    let mut s: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            s.len() == i as int,
            forall|j: int| 0 <= j && j < i as int ==> #[trigger] s[j] == a[j],
        decreases a.len() - i
    {
        let ai = a[i];
        s.push(ai);
        i += 1;
    }
    s
}

fn main() {
    // 1) Empty slice
    let a0: Vec<i32> = vec![];
    let r0 = array_to_seq(&a0);
    assert!(r0.is_empty());

    // 2) Single element
    let a1 = vec![42];
    let r1 = array_to_seq(&a1);
    assert!(r1 == vec![42]);

    // 3) Multiple elements, increasing order
    let a2 = vec![1, 2, 3, 4, 5];
    let r2 = array_to_seq(&a2);
    assert!(r2 == vec![1, 2, 3, 4, 5]);

    // 4) Duplicates
    let a3 = vec![5, 5, 5, 5];
    let r3 = array_to_seq(&a3);
    assert!(r3 == vec![5, 5, 5, 5]);

    // 5) Negative values
    let a4 = vec![-1, -2, -3];
    let r4 = array_to_seq(&a4);
    assert!(r4 == vec![-1, -2, -3]);

    // 6) Boundary values
    let a5 = vec![i32::MIN, 0, i32::MAX];
    let r5 = array_to_seq(&a5);
    assert!(r5 == vec![i32::MIN, 0, i32::MAX]);

    // 7) Mixed values
    let a6 = vec![7, -3, 0, 7, 2];
    let r6 = array_to_seq(&a6);
    assert!(r6 == vec![7, -3, 0, 7, 2]);

    // 8) Independence from original storage after call
    let mut a7 = vec![10, 20, 30];
    let r7 = array_to_seq(&a7);
    a7[1] = 99; // mutate original after copying
    assert!(r7 == vec![10, 20, 30]);

    // 9) Longer input
    let a8 = vec![2; 100];
    let r8 = array_to_seq(&a8);
    assert!(r8.len() == 100 && r8.iter().all(|&x| x == 2));
}

}

