verus! {
    fn swap_first_and_last(a: &mut Vec<i32>)
        requires
            old(a).len() > 0,
        ensures
            a.len() == old(a).len(),
            a[0] == old(a)[old(a).len() - 1],
            a[a.len() - 1] == old(a)[0],
            forall|k: int| 1 <= k < a.len() - 1 ==> a[k] == old(a)[k],
    {
        let last = a.len() - 1;
        let first_val = a[0];
        let last_val = a[last];
        a[0] = last_val;
        a[last] = first_val;
    }

    fn main() {
        // Helper to run a single test case
        fn check_case(mut arr: Vec<i32>) {
            let original = arr.clone();
            let len = original.len();
            swap_first_and_last(&mut arr);

            // Length unchanged
            assert!(arr.len() == len);

            // First and last swapped
            let last_idx = len - 1;
            assert!(arr[0] == original[last_idx]);
            assert!(arr[last_idx] == original[0]);

            // Middle elements unchanged
            if len > 2 {
                for k in 1..(len - 1) {
                    assert!(arr[k] == original[k]);
                }
            }
        }

        // Test 1: Single element (boundary length)
        check_case(vec![42]);

        // Test 2: Two elements
        check_case(vec![10, -10]);

        // Test 3: Three elements with duplicates
        check_case(vec![5, 5, 5]);

        // Test 4: Odd length typical case
        check_case(vec![1, 2, 3, 4, 5]);

        // Test 5: Even length typical case
        check_case(vec![7, 8, 9, 10]);

        // Test 6: Extremes and zero
        check_case(vec![i32::MIN, 0, i32::MAX]);

        // Test 7: Palindromic array
        check_case(vec![7, 8, 9, 8, 7]);

        // Test 8: Two-element extremes
        check_case(vec![i32::MIN, i32::MAX]);
    }
}

