verus! {

fn remove_element(s: &Vec<i32>, k: usize) -> (v: Vec<i32>)
    requires 
        k < s.len(),
    ensures
        v.len() == s.len() - 1,
        forall|i: int| 0 <= i < k ==> v[i] == s[i],
        forall|i: int| k <= i < v.len() ==> v[i] == s[(i + 1) as int],
{
    let mut res: Vec<i32> = Vec::new();

    // Copy elements before k
    let mut i: usize = 0;
    while i < k
        invariant
            (i as int) <= s.len(),
            (k as int) <= s.len(),
            i <= k,
            res.len() == i as int,
            forall|j: int| 0 <= j && j < i as int ==> #[trigger] res@[j] == s@[j],
        decreases (k as int) - (i as int)
    {
        assert(i < s.len());
        res.push(s[i]);
        i += 1;
    }

    assert(i == k);
    // Skip element at k and continue with the rest
    i += 1;

    while i < s.len()
        invariant
            (i as int) <= s.len(),
            i > k,
            res.len() == (i as int) - 1,
            forall|j: int| 0 <= j && j < k as int ==> #[trigger] res@[j] == s@[j],
            forall|j: int| k as int <= j && j < res.len() ==> #[trigger] res@[j] == s@[(j + 1) as int],
        decreases s.len() - (i as int)
    {
        assert(i < s.len());
        res.push(s[i]);
        i += 1;
    }

    res
}

fn main() {
    // Test 1: remove first element
    let mut s1: Vec<i32> = Vec::new();
    s1.push(10); s1.push(20); s1.push(30); s1.push(40);
    let k1: usize = 0;
    let out1 = remove_element(&s1, k1);
    assert(out1.len() == 3);
    assert(0 < out1.len()); assert(out1[0] == 20);
    assert(1 < out1.len()); assert(out1[1] == 30);
    assert(2 < out1.len()); assert(out1[2] == 40);

    // Test 2: remove middle element (index 2)
    let mut s2: Vec<i32> = Vec::new();
    s2.push(1); s2.push(2); s2.push(3); s2.push(4); s2.push(5);
    let k2: usize = 2;
    let out2 = remove_element(&s2, k2);
    assert(out2.len() == 4);
    assert(0 < out2.len()); assert(out2[0] == 1);
    assert(1 < out2.len()); assert(out2[1] == 2);
    assert(2 < out2.len()); assert(out2[2] == 4);
    assert(3 < out2.len()); assert(out2[3] == 5);

    // Test 3: remove last element
    let mut s3: Vec<i32> = Vec::new();
    s3.push(-1); s3.push(0); s3.push(1);
    let k3: usize = 2;
    let out3 = remove_element(&s3, k3);
    assert(out3.len() == 2);
    assert(0 < out3.len()); assert(out3[0] == -1);
    assert(1 < out3.len()); assert(out3[1] == 0);

    // Test 4: single-element vector, removing the only element
    let mut s4: Vec<i32> = Vec::new();
    s4.push(99);
    let k4: usize = 0;
    let out4 = remove_element(&s4, k4);
    assert(out4.len() == 0);

