            res.len() == i as int,
            forall|j: int| 0 <= j && j < i as int ==> #[trigger] res@[j] == s@[j],
        decreases (k as int) - (i as int)
    {
        assert(i < s.len());
        res.push(s[i]);
        i += 1;
    }

    assert(i == k);
    // Skip element at k and continue with the rest
    i += 1;

    while i < s.len()
        invariant
            (i as int) <= s.len(),
            i > k,
            res.len() == (i as int) - 1,
