use std::i32;

fn is_nondecreasing(s: &[i32]) -> bool {
    s.windows(2).all(|w| w[0] <= w[1])
}

fn find_median(a: &[i32], b: &[i32]) -> i32 {
    assert_eq!(a.len(), b.len());
    assert!(a.len() > 0);
    assert!(is_nondecreasing(a));
    assert!(is_nondecreasing(b));

    let n = a.len();
    if n % 2 == 0 {
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        let sum = x + y;
        // Euclidean-style floor division for negatives
        let avg = if sum >= 0 { sum / 2 } else { (sum - 1) / 2 };
        avg as i32
    } else {
        a[n / 2]
    }
}

fn main() {
    // 1) Single element (odd length)
    let a1 = [5];
    let b1 = [10];
    assert_eq!(find_median(&a1, &b1), 5);

    // 2) Odd length, typical case
    let a2 = [1, 2, 3];
    let b2 = [4, 5, 6];
    assert_eq!(find_median(&a2, &b2), 2);

    // 3) Even length, positive numbers
    let a3 = [2, 3];
    let b3 = [4, 5];
    // average of a[0] and b[0] => (2 + 4) / 2 = 3
    assert_eq!(find_median(&a3, &b3), 3);

    // 4) Even length, negative numbers (floor division behavior)
    let a4 = [-5, -4];
    let b4 = [-4, -3];
    // (−5 + −4) / 2 floor => (−9) / 2 => −5
    assert_eq!(find_median(&a4, &b4), -5);

    // 5) Even length, mixed signs
    let a5 = [-1, 0];
    let b5 = [3, 10];
    // (−1 + 3) / 2 = 2 / 2 = 1
    assert_eq!(find_median(&a5, &b5), 1);

    // 6) Odd length with duplicates
    let a6 = [1, 1, 1, 2, 2];
    let b6 = [0, 0, 1, 1, 1];
    // middle of first array is a6[2] = 1
    assert_eq!(find_median(&a6, &b6), 1);

    // 7) Even length, large positive values
    let a7 = [i32::MAX - 1, i32::MAX];
    let b7 = [i32::MAX, i32::MAX];
    // (MAX-1 + MAX) / 2 = (2147483646 + 2147483647) / 2 = 2147483646
    assert_eq!(find_median(&a7, &b7), 2_147_483_646);

    // 8) Even length, large negative values
    let a8 = [i32::MIN, i32::MIN];
    let b8 = [i32::MIN, i32::MIN];
    // (MIN + MIN) / 2 floor = (-2147483648 + -2147483648) / 2 = -2147483648
    assert_eq!(find_median(&a8, &b8), -2_147_483_648);

    println!("All tests passed.");
}

