use std::fmt::Debug;

fn expected_prefix_reversed(mut v: Vec<i32>, k: usize) -> Vec<i32> {
    v[..k].reverse();
    v
}

fn run_case(name: &str, v: Vec<i32>, k: usize) {
    // Precondition: 2 <= k <= v.len()
    assert!(k >= 2 && k <= v.len(), "Precondition violated in {}: k={}, len={}", name, k, v.len());
    let expected = expected_prefix_reversed(v.clone(), k);
    let mut w = v.clone();
    reverse_upto_k(&mut w, k);
    assert_eq!(w.len(), v.len(), "{}: length changed", name);
    assert_eq!(w, expected, "{} failed: got {:?}, expected {:?}", name, w, expected);
}

fn main() {
    // Happy path: basic reversal of a prefix
    run_case("basic_1", vec![1, 2, 3, 4, 5], 3);

    // Entire array reversed (k == len)
    run_case("all_rev", vec![1, 2, 3, 4, 5], 5);

    // Constraint boundary: minimal allowed k = 2
    run_case("min_k", vec![9, 8, 7], 2);

    // Edge case: array length exactly 2, k = 2
    run_case("length2", vec![1, 2], 2);

    // Duplicates and negatives
    run_case("dups_neg", vec![0, -1, -1, -2, 3], 4);

    // Already reversed prefix becomes sorted part after reversal
    run_case("already_rev_prefix", vec![3, 2, 1, 4, 5], 3);

    // General case with k not equal to half or full length
    run_case("k4_mid", vec![10, 20, 30, 40, 50, 60], 4);

    // Large values including extremes
    run_case("extremes", vec![i32::MAX, 0, i32::MIN, 7], 3);
}

