fn is_min_heap(a: &Vec<i32>) -> bool {
    assert!(!a.is_empty(), "Precondition violated: input array must be non-empty");
    let n = a.len();
    let mut i = 0usize;
    while i < n / 2 {
        let left = 2 * i + 1;
        if left < n {
            if a[i] > a[left] { return false; }
        }
        let right = 2 * i + 2;
        if right < n {
            if a[i] > a[right] { return false; }
        }
        i += 1;
    }
    true
}

fn main() {
    // 1) Single element (edge within requires): should be a min-heap
    let v1 = vec![5];
    assert!(is_min_heap(&v1));

    // 2) Valid min-heap with complete tree
    let v2 = vec![1, 3, 2, 7, 9, 4, 8];
    assert!(is_min_heap(&v2));

    // 3) Violation on left child
    let v3 = vec![2, 1, 3];
    assert!(!is_min_heap(&v3));

    // 4) Violation on right child
    let v4 = vec![2, 3, 1];
    assert!(!is_min_heap(&v4));

    // 5) Valid min-heap with last nodes missing children
    let v5 = vec![1, 2, 3, 4, 5];
    assert!(is_min_heap(&v5));

    // 6) All equal values: valid min-heap
    let v6 = vec![5, 5, 5, 5, 5, 5];
    assert!(is_min_heap(&v6));

    // 7) All equal values, smaller size
    let v7 = vec![10, 10, 10, 10];
    assert!(is_min_heap(&v7));

    // 8) Increasing level order: valid min-heap
    let v8 = vec![0, 1, 2, 3, 4, 5, 6, 7];
    assert!(is_min_heap(&v8));

    // 9) Deep violation at a lower level
    let v9 = vec![1, 2, 3, 4, 5, 0];
    assert!(!is_min_heap(&v9));

    println!("All tests passed!");
}

