fn has_only_one_distinct_element(a: &[i32]) -> bool {
    if a.len() <= 1 {
        return true;
    }
    let first = a[0];
    for &x in &a[1..] {
        if x != first {
            return false;
        }
    }
    true
}

fn main() {
    // Empty array: treated as having only one distinct value
    assert!(has_only_one_distinct_element(&[]));

    // Single element
    assert!(has_only_one_distinct_element(&[42]));

    // All elements equal
    assert!(has_only_one_distinct_element(&[7, 7, 7, 7]));

    // Two different elements
    assert!(!has_only_one_distinct_element(&[1, 2]));

    // Difference appears later in the array
    assert!(!has_only_one_distinct_element(&[5, 5, 3, 5]));

    // Boundary values equal
    assert!(has_only_one_distinct_element(&[i32::MIN, i32::MIN]));

    // Boundary values differ
    assert!(!has_only_one_distinct_element(&[i32::MIN, i32::MAX]));

    // All zeros
    assert!(has_only_one_distinct_element(&[0, 0, 0, 0, 0]));

    // Mostly equal but one different
    assert!(!has_only_one_distinct_element(&[9, 9, 9, 10]));

    // All equal negative numbers
    assert!(has_only_one_distinct_element(&[-1, -1, -1]));
}

