use std::ops::Range;

fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // Preconditions (as per problem statement):
    assert!(lst.len() >= 2, "length must be >= 2");
    let mut even_idx: Option<usize> = None;
    let mut odd_idx: Option<usize> = None;
    for (i, &x) in lst.iter().enumerate() {
        if even_idx.is_none() && x % 2 == 0 {
            even_idx = Some(i);
        }
        if odd_idx.is_none() && x % 2 != 0 {
            odd_idx = Some(i);
        }
        if even_idx.is_some() && odd_idx.is_some() {
            break;
        }
    }
    let i = even_idx.expect("array must contain at least one even");
    let j = odd_idx.expect("array must contain at least one odd");
    (i, j)
}

fn preconditions_satisfied(a: &[i32]) -> bool {
    if a.len() < 2 { return false; }
    let mut has_even = false;
    let mut has_odd = false;
    for &x in a {
        if x % 2 == 0 { has_even = true; }
        if x % 2 != 0 { has_odd = true; }
    }
    has_even && has_odd
}

fn check_first_even(a: &[i32], idx: usize) {
    assert!(idx < a.len());
    assert!(a[idx] % 2 == 0);
    for k in 0..idx { assert!(a[k] % 2 != 0); }
