fn count_equal_numbers(a: i32, b: i32, c: i32) -> i32 {
    if a == b {
        if b == c {
            3
        } else {
            2
        }
    } else if b == c {
        2
    } else if a == c {
        2
    } else {
        1
    }
}

fn main() {
    // Happy path: all equal
    assert_eq!(count_equal_numbers(5, 5, 5), 3);

    // Exactly two equal (a == b)
    assert_eq!(count_equal_numbers(7, 7, 8), 2);

    // Exactly two equal (b == c)
    assert_eq!(count_equal_numbers(9, 10, 10), 2);

    // Exactly two equal (a == c)
    assert_eq!(count_equal_numbers(3, 4, 3), 2);

    // All distinct
    assert_eq!(count_equal_numbers(1, 2, 3), 1);

    // Negative numbers: all equal
    assert_eq!(count_equal_numbers(-1, -1, -1), 3);

    // Mixed zero: two equal
    assert_eq!(count_equal_numbers(0, 0, 1), 2);

    // Extremes: all distinct
    assert_eq!(count_equal_numbers(i32::MIN, i32::MAX, 0), 1);

    // Extremes: two equal (first two)
    assert_eq!(count_equal_numbers(i32::MAX, i32::MAX, i32::MIN), 2);

    // Additional verification of range constraints
    for &(a, b, c) in &[
        (5, 5, 5),
        (7, 7, 8),
        (9, 10, 10),
        (3, 4, 3),
        (1, 2, 3),
        (-1, -1, -1),
        (0, 0, 1),
        (i32::MIN, i32::MAX, 0),
        (i32::MAX, i32::MAX, i32::MIN),
    ] {
        let count = count_equal_numbers(a, b, c);
        assert!(count >= 0 && count <= 3);
    }
}

