// Reference implementation for testing purposes (non-Verus Rust)
// Precondition: 0 <= from < to <= a.len()
fn find_min(a: &mut [i32], from: usize, to: usize) -> usize {
    assert!(from < to && to <= a.len());
    let mut min_index = from;
    let mut i = from + 1;
    while i < to {
        if a[i] < a[min_index] {
            min_index = i;
        }
        i += 1;
    }
    min_index
}

fn check_min(a: &[i32], from: usize, to: usize, idx: usize) {
    assert!(from <= idx && idx < to);
    let v = a[idx];
    for k in from..to {
        assert!(a[k] >= v);
    }
}

fn main() {
    // Test 1: Happy path, full range, multiple minima
    let mut arr1 = vec![3, 1, 4, 1, 5, 9];
    let idx1 = find_min(&mut arr1, 0, arr1.len());
    check_min(&arr1, 0, arr1.len(), idx1);

    // Test 2: Subrange in the middle
    let mut arr2 = vec![3, 1, 4, 1, 5, 9];
    let idx2 = find_min(&mut arr2, 2, 5); // subarray [4, 1, 5]
    check_min(&arr2, 2, 5, idx2);

    // Test 3: Single-element subarray (boundary case from < to with to = from + 1)
    let mut arr3 = vec![10, -2, 7];
