            min_index = i;
        }
        i += 1;
    }
    min_index
}

fn verify_min_index(a: &[i64], s: usize, e: usize, m: usize) {
    assert!(m >= s && m < e, "Result index not in [s, e)");
    for k in s..e {
        assert!(a[m] <= a[k], "Element at returned index is not minimal in the range");
    }
}

fn main() {
    // Test 1: Single-element array, full range
    let a1 = vec![42];
    let s1 = 0usize; let e1 = 1usize;
    let m1 = find_min_index_runtime(&a1, s1, e1);
    assert_eq!(m1, 0);
    verify_min_index(&a1, s1, e1, m1);

    // Test 2: Full array, distinct values; unique minimum
    let a2 = vec![5, 2, 7, 1, 9];
    let s2 = 0usize; let e2 = a2.len();
    let m2 = find_min_index_runtime(&a2, s2, e2);
    assert_eq!(m2, 3); // element 1 at index 3 is the unique minimum
    verify_min_index(&a2, s2, e2, m2);

    // Test 3: Subarray range within the array; unique minimum in the subrange
    // Subrange [1, 5) => [3, 6, 2, 4], minimum is 2 at original index 3
    let a3 = vec![8, 3, 6, 2, 4, 7];
    let s3 = 1usize; let e3 = 5usize;
    let m3 = find_min_index_runtime(&a3, s3, e3);
    assert_eq!(m3, 3);
    verify_min_index(&a3, s3, e3, m3);

    // Test 4: Multiple minima allowed; any min index acceptable
    let a4 = vec![4, 1, 1, 3, 1];
    let s4 = 0usize; let e4 = a4.len();
    let m4 = find_min_index_runtime(&a4, s4, e4);
    // Valid answers: 1, 2, or 4
    assert!([1usize, 2usize, 4usize].contains(&m4));
    verify_min_index(&a4, s4, e4, m4);

    // Test 5: Negative numbers and zero; multiple minima
    let a5 = vec![-5, -1, -5, 0];
    let s5 = 0usize; let e5 = a5.len();
    let m5 = find_min_index_runtime(&a5, s5, e5);
    assert!([0usize, 2usize].contains(&m5));
    verify_min_index(&a5, s5, e5, m5);

    // Test 6: Minimal subarray length (e = s + 1) in the middle of the array
    let a6 = vec![10, 9, 8, 7];
    let s6 = 2usize; let e6 = 3usize; // subarray [8]
    let m6 = find_min_index_runtime(&a6, s6, e6);
    assert_eq!(m6, 2);
    verify_min_index(&a6, s6, e6, m6);

    // Test 7: Boundary values within full range
    let a7 = vec![i64::MAX - 1, i64::MIN + 2, i64::MAX, i64::MIN + 2];
    let s7 = 0usize; let e7 = a7.len();
    let m7 = find_min_index_runtime(&a7, s7, e7);
    assert!([1usize, 3usize].contains(&m7));
    verify_min_index(&a7, s7, e7, m7);
}

