use std::fmt::Debug;

fn delete(line: &mut Vec<char>, l: usize, at: usize, p: usize) {
    assert!(l <= line.len(), "precondition violated: l must be <= line.len()");
    assert!(at + p <= l, "precondition violated: at + p must be <= l");
    let mut i = at;
    while i < l - p {
        line[i] = line[i + p];
        i += 1;
    }
    line.truncate(l - p);
}

fn vec_from(s: &str) -> Vec<char> { s.chars().collect() }
fn str_from(v: &Vec<char>) -> String { v.iter().collect() }

fn main() {
    // 1) Happy path: delete inside full prefix
    let mut v1 = vec_from("abcde");
    delete(&mut v1, 5, 1, 2);
    assert_eq!(str_from(&v1), "ade");

    // 2) Delete from start of prefix
    let mut v2 = vec_from("abcde");
    delete(&mut v2, 5, 0, 3);
    assert_eq!(str_from(&v2), "de");

    // 3) p = 0 (no deletion), but array is truncated to the prefix of length l
    let mut v3 = vec_from("abcdef");
    delete(&mut v3, 4, 2, 0);
    // Equivalent to taking the first l characters
    assert_eq!(str_from(&v3), "abcd");

    // 4) Delete suffix to the end of the prefix (at + p == l)
    let mut v4 = vec_from("abcde");
    delete(&mut v4, 5, 3, 2);
    assert_eq!(str_from(&v4), "abc");

    // 5) l less than full length; tail beyond l is discarded
    let mut v5 = vec_from("abcdefg");
    delete(&mut v5, 5, 1, 1);
    // Operate only on first 5: "abcde" -> remove 1 at index 1 -> "acde"
    assert_eq!(str_from(&v5), "acde");

    // 6) l = 0, only possible with at = 0 and p = 0; result must be empty
    let mut v6 = vec_from("abc");
    delete(&mut v6, 0, 0, 0);
    assert_eq!(str_from(&v6), "");

    // 7) Single element removed entirely
    let mut v7 = vec_from("z");
    delete(&mut v7, 1, 0, 1);
    assert_eq!(str_from(&v7), "");

    // 8) Delete entire prefix even if vector has extra tail
    let mut v8 = vec_from("wxyzpq");
    delete(&mut v8, 4, 0, 4);
    assert_eq!(str_from(&v8), "");
}

