fn main() {
    // 1. Empty input: should return unchanged
    let nums: Vec<i8> = vec![];
    let delim: i8 = 0;
    let out = insert_delimiter(nums.clone(), delim);
    assert_eq!(out, nums);

    // 2. Single element: should return unchanged
    let nums = vec![42i8];
    let delim = 99i8;
    let out = insert_delimiter(nums.clone(), delim);
    assert_eq!(out, nums);

    // 3. Two elements, simple delimiter
    let nums = vec![1i8, 2i8];
    let delim = 0i8;
    let out = insert_delimiter(nums, delim);
    assert_eq!(out, vec![1i8, 0i8, 2i8]);

    // 4. Three elements, negative delimiter
    let nums = vec![10i8, 20i8, 30i8];
    let delim = -1i8;
    let out = insert_delimiter(nums, delim);
    assert_eq!(out, vec![10i8, -1i8, 20i8, -1i8, 30i8]);

    // 5. Delimiter equals the element value
    let nums = vec![5i8, 5i8, 5i8];
    let delim = 5i8;
    let out = insert_delimiter(nums, delim);
    assert_eq!(out, vec![5i8, 5i8, 5i8, 5i8, 5i8]);

    // 6. Extreme values: max and min i8 with min as delimiter
    let nums = vec![127i8, -128i8];
    let delim = -128i8;
    let out = insert_delimiter(nums, delim);
    assert_eq!(out, vec![127i8, -128i8, -128i8]);

    // 7. Larger input with positive delimiter
    let nums = vec![0i8, 1i8, 2i8, 3i8, 4i8];
    let delim = 7i8;
    let out = insert_delimiter(nums, delim);
    assert_eq!(out, vec![0i8, 7i8, 1i8, 7i8, 2i8, 7i8, 3i8, 7i8, 4i8]);

    // 8. Negative elements with positive delimiter
    let nums = vec![-10i8, -20i8, -30i8, -40i8];
    let delim = 100i8;
    let out = insert_delimiter(nums, delim);
    assert_eq!(out, vec![-10i8, 100i8, -20i8, 100i8, -30i8, 100i8, -40i8]);

    // 9. Zero delimiter with mixed values
    let nums = vec![3i8, -3i8, 0i8, 3i8];
    let delim = 0i8;
    let out = insert_delimiter(nums, delim);
    assert_eq!(out, vec![3i8, 0i8, -3i8, 0i8, 0i8, 0i8, 3i8]);

    println!("All tests passed.");
}

