    // 3) Mixed lengths -> longest one
    let r3 = longest(vec![s("a"), s("abcd"), s("bc")]);
    assert_eq!(r3, Some(s("abcd")));

    // 4) Ties -> earliest maximum (index 1: "bbb" vs index 3: "ddd")
    let r4 = longest(vec![s("aa"), s("bbb"), s("cc"), s("ddd"), s("e")]);
    assert_eq!(r4, Some(s("bbb")));

    // 5) Multiple empties with a longer one later -> choose the longer one
    let r5 = longest(vec![s(""), s(""), s("a")]);
    assert_eq!(r5, Some(s("a")));

    // 6) Unicode characters; length is in chars, not bytes
    // "a😀bc" has length 4 in chars
    let r6 = longest(vec![s("😀"), s("ab"), s("a😀bc"), s("zz")]);
    assert_eq!(r6, Some(s("a😀bc")));

