    let r8 = longest(vec![s("ab"), s("cd"), s("ef")]);
    assert_eq!(r8, Some(s("ab")));

    // 9) All empty strings -> earliest one (first empty)
    let r9 = longest(vec![s(""), s(""), s("")]);
    assert_eq!(r9, Some(s("")));
