fn largest_divisor(n: i8) -> i8 {
    assert!(n > 1);
    let mut i = n - 1;
    while i > 0 {
        if n % i == 0 {
            return i;
        }
        i -= 1;
    }
    unreachable!();
}

fn main() {
    // Happy path and boundary tests
    assert_eq!(largest_divisor(2), 1);   // smallest valid input
    assert_eq!(largest_divisor(3), 1);   // prime
    assert_eq!(largest_divisor(4), 2);   // even, n/2
    assert_eq!(largest_divisor(12), 6);  // composite with multiple divisors
    assert_eq!(largest_divisor(25), 5);  // square of a prime

    // Upper boundary in i8 range
    assert_eq!(largest_divisor(127), 1); // prime at i8 max

    // Additional composites
    assert_eq!(largest_divisor(100), 50); // even, n/2
    assert_eq!(largest_divisor(81), 27);  // power of a prime (3^4)
    assert_eq!(largest_divisor(48), 24);  // even, multiple factors
    assert_eq!(largest_divisor(121), 11); // 11^2
}

