use std::i8;

fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let n = s.len();
    let limit = n - n % 3;
    let mut res = s.clone();
    let mut i = 0;
    while i < limit {
        let a = s[i];
        let b = s[i + 1];
        let c = s[i + 2];
        res[i] = b;
        res[i + 1] = c;
        res[i + 2] = a;
        i += 3;
    }
    res
}

fn main() {
    // 1. Empty array
    let v: Vec<i8> = vec![];
    let r = encode_cyclic(v.clone());
    assert_eq!(r, v);

    // 2. Single element
    let v = vec![42i8];
    let r = encode_cyclic(v.clone());
    assert_eq!(r, v);

    // 3. Two elements
    let v = vec![1i8, -1i8];
    let r = encode_cyclic(v.clone());
    assert_eq!(r, v);

    // 4. Exactly three elements (one full block)
    let v = vec![1i8, 2i8, 3i8];
    let r = encode_cyclic(v.clone());
    assert_eq!(r, vec![2i8, 3i8, 1i8]);

    // 5. Four elements (one full block + one leftover)
    let v = vec![1i8, 2i8, 3i8, 4i8];
    let r = encode_cyclic(v.clone());
    assert_eq!(r, vec![2i8, 3i8, 1i8, 4i8]);

