use std::fmt::Debug;

fn encode_shift(s: Vec<char>) -> Vec<char> {
    // Runtime implementation consistent with the specification:
    // - input must contain only 'a'..'z'
    // - output length equals input length
    // - each char shifted by +5 with wrap-around
    let mut t: Vec<char> = Vec::with_capacity(s.len());
    for c in s {
        assert!(c >= 'a' && c <= 'z', "Input must be lowercase 'a'..'z'");
        let encoded = ((((c as u8) - b'a') + 5) % 26 + b'a') as char;
        t.push(encoded);
    }
    t
}

fn vec_chars(s: &str) -> Vec<char> { s.chars().collect() }
fn to_string(v: &[char]) -> String { v.iter().collect() }

fn assert_eq_vec<T: PartialEq + Debug>(a: T, b: T) {
    assert!(a == b, "left = {:?}, right = {:?}", a, b);
}

fn main() {
    // 1) Edge Case: Empty input (vacuously satisfies requires)
    let input1: Vec<char> = vec![];
    let out1 = encode_shift(input1.clone());
    assert_eq_vec(out1, vec![]);

    // 2) Single element at lower boundary
    let input2 = vec_chars("a");
    let out2 = encode_shift(input2);
    assert_eq_vec(to_string(&out2), String::from("f"));

    // 3) Single element at upper boundary
    let input3 = vec_chars("z");
    let out3 = encode_shift(input3);
    assert_eq_vec(to_string(&out3), String::from("e"));

    // 4) Full alphabet to test wrap-around and length preservation
    let input4 = vec_chars("abcdefghijklmnopqrstuvwxyz");
    let out4 = encode_shift(input4);
    assert_eq_vec(to_string(&out4), String::from("fghijklmnopqrstuvwxyzabcde"));

    // 5) Wrap-around segment
    let input5 = vec_chars("vwxyz");
    let out5 = encode_shift(input5);
    assert_eq_vec(to_string(&out5), String::from("abcde"));

    // 6) Typical word
    let input6 = vec_chars("hello");
    let out6 = encode_shift(input6);
    assert_eq_vec(to_string(&out6), String::from("mjqqt"));

    // 7) Repeated letters including upper boundary and lower boundary
    let input7 = vec_chars("zzzaa");
    let out7 = encode_shift(input7);
    assert_eq_vec(to_string(&out7), String::from("eeeff"));

    // 8) Random lowercase word
    let input8 = vec_chars("verus");
    let out8 = encode_shift(input8);
    assert_eq_vec(to_string(&out8), String::from("ajwzx"));

    // 9) Mixed boundaries and mid-range letters
    let input9 = vec_chars("azbycxdwevfugthsirjqkplomn"); // pattern across range
    let out9 = encode_shift(input9.clone());
    // Compute expected via the same rule to ensure correctness and length preservation
    let expected9: String = input9.into_iter().map(|c| ((((c as u8) - b'a') + 5) % 26 + b'a') as char).collect();
    assert_eq_vec(to_string(&out9), expected9);
}

