spec fn below_threshold(l: Seq<int>, t: int) -> bool {
    forall|i: int| 0 <= i < l.len() ==> l[i] < t
}

fn check_below_threshold(l: Vec<i8>, t: i8) -> (result: bool)
    ensures result == below_threshold(l@.map(|_i: int, x: i8| x as int), t as int)
{
    let mut i = 0;
    while i < l.len()
        invariant
            0 <= i <= l.len(),
            forall|j: int| 0 <= j < i ==> l@[j] < t as int,
        decreases l.len() - i
    {
        if l[i] >= t {
            proof {
                let mapped_seq = l@.map(|_k: int, x: i8| x as int);
                assert(mapped_seq[i as int] == l@[i as int] as int);
                assert(l@[i as int] >= t as int);
                assert(mapped_seq[i as int] >= t as int);
                assert(!(mapped_seq[i as int] < t as int));
                assert(!below_threshold(mapped_seq, t as int));
            }
            return false;
        }
        i += 1;
    }
    proof {
        let mapped_seq = l@.map(|_k: int, x: i8| x as int);
        assert(forall|j: int| 0 <= j < l.len() ==> {
            mapped_seq[j] == l@[j] as int && l@[j] < t as int
        });
        assert(forall|j: int| 0 <= j < mapped_seq.len() ==> mapped_seq[j] < t as int);
        assert(below_threshold(mapped_seq, t as int));
    }
    true
}

}

fn main() {
    // 1. Empty array: vacuously true
    assert!(check_below_threshold(vec![], 0));

    // 2. Single element less than threshold
    assert!(check_below_threshold(vec![3], 5));

    // 3. Single element equal to threshold (should be false)
    assert!(!check_below_threshold(vec![5], 5));

    // 4. All elements less than threshold
    assert!(check_below_threshold(vec![-10, -5, 0], 1));

    // 5. Some element greater than threshold
    assert!(!check_below_threshold(vec![1, 2, 10], 5));

    // 6. Threshold at minimum i8 value with empty array (true)
    assert!(check_below_threshold(vec![], -128));

    // 7. Threshold at minimum i8 value with non-empty array (false)
    assert!(!check_below_threshold(vec![-128], -128));

    // 8. Threshold at maximum i8 value with elements below (true)
    assert!(check_below_threshold(vec![126, -5], 127));

    // 9. Threshold at maximum i8 value with an element equal to threshold (false)
    assert!(!check_below_threshold(vec![127, 0], 127));

    // 10. Negative threshold with all elements strictly below (true)
    assert!(check_below_threshold(vec![-100, -99, -51], -50));
}

