use std::collections::HashSet;

fn same_chars(s0: Vec<char>, s1: Vec<char>) -> bool {
    let set0: HashSet<char> = s0.into_iter().collect();
    let set1: HashSet<char> = s1.into_iter().collect();
    set0 == set1
}

fn main() {
    // 1) Both empty -> true (empty set equals empty set)
    let v0: Vec<char> = vec![];
    let v1: Vec<char> = vec![];
    assert!(same_chars(v0, v1));

    // 2) One empty, one non-empty -> false
    let v0: Vec<char> = "".chars().collect();
    let v1: Vec<char> = "a".chars().collect();
    assert!(!same_chars(v0, v1));

    // 3) Same distinct set, different order and multiplicities -> true
    let v0: Vec<char> = "abca".chars().collect();
    let v1: Vec<char> = "cabb".chars().collect();
    assert!(same_chars(v0, v1)); // both have {'a','b','c'}

    // 4) Extra character in one -> false
    let v0: Vec<char> = "abc".chars().collect();
    let v1: Vec<char> = "abcd".chars().collect();
    assert!(!same_chars(v0, v1));

    // 5) Single-element equal -> true
    let v0: Vec<char> = "x".chars().collect();
    let v1: Vec<char> = "x".chars().collect();
    assert!(same_chars(v0, v1));

    // 6) Single-element different -> false
    let v0: Vec<char> = "x".chars().collect();
    let v1: Vec<char> = "y".chars().collect();
    assert!(!same_chars(v0, v1));

    // 7) Heavy duplicates vs single occurrence -> true
    let v0: Vec<char> = "aaaaaa".chars().collect();
    let v1: Vec<char> = "a".chars().collect();
    assert!(same_chars(v0, v1));

    // 8) Case sensitivity -> false ('a' != 'A')
    let v0: Vec<char> = "a".chars().collect();
