use vstd::prelude::*;

verus! {

spec fn valid_length(s: Seq<char>) -> bool {
    s.len() >= 3
}

spec fn all_windows_distinct(s: Seq<char>) -> bool {
    forall|i: int| 0 <= i <= s.len() - 3 ==> #[trigger] s[i] != s[i+1] && s[i] != s[i+2] && s[i+1] != s[i+2]
}

spec fn is_happy_spec(s: Seq<char>) -> bool {
    valid_length(s) && all_windows_distinct(s)
}

fn is_happy(s: Vec<char>) -> (result: bool)
    ensures result == is_happy_spec(s@)
{
    if s.len() < 3 {
        return false;
    }

    let mut i = 0;
    while i <= s.len() - 3
        invariant
            0 <= i <= s.len() - 3 + 1,
            s.len() >= 3,
            forall|j: int| 0 <= j < i ==> #[trigger] s@[j] != s@[j+1] && s@[j] != s@[j+2] && s@[j+1] != s@[j+2],
        decreases s.len() - i
    {
        if s[i] == s[i+1] || s[i] == s[i+2] || s[i+1] == s[i+2] {
            return false;
        }
        i += 1;
    }

    true
}

}

fn main() {
    use std::iter::FromIterator;

    fn vc(s: &str) -> Vec<char> {
        Vec::from_iter(s.chars())
    }

    // Edge cases: length < 3
    assert_eq!(is_happy(vc("")), false);
    assert_eq!(is_happy(vc("a")), false);
    assert_eq!(is_happy(vc("ab")), false);

    // Exactly length 3: all distinct -> true; any duplicate -> false
    assert_eq!(is_happy(vc("abc")), true);
    assert_eq!(is_happy(vc("aab")), false);
    assert_eq!(is_happy(vc("aba")), false);
    assert_eq!(is_happy(vc("baa")), false);
    assert_eq!(is_happy(vc("aaa")), false);

    // Longer strings: windows all distinct -> true
    assert_eq!(is_happy(vc("abcd")), true);          // "abc" and "bcd" are pairwise distinct
    assert_eq!(is_happy(vc("abca")), true);          // "abc" and "bca" are pairwise distinct

    // Longer strings: some window has duplicates -> false
