fn largest_smallest_integers(arr: Vec<i8>) -> (Option<i8>, Option<i8>) {
    if arr.is_empty() {
        return (None, None);
    }
    let mut min_v = arr[0];
    let mut max_v = arr[0];
    for &v in &arr {
        if v < min_v { min_v = v; }
        if v > max_v { max_v = v; }
    }
    (Some(max_v), Some(min_v))
}

fn main() {
    // Edge case: empty array
    let res_empty = largest_smallest_integers(vec![]);
    assert_eq!(res_empty, (Option::<i8>::None, Option::<i8>::None));

    // Single element
    let res_single = largest_smallest_integers(vec![5]);
    assert_eq!(res_single, (Some(5), Some(5)));

    // All negative values
    let res_neg = largest_smallest_integers(vec![-1, -5, -3]);
    assert_eq!(res_neg, (Some(-1), Some(-5)));

    // Mixed with i8 boundaries
    let res_bounds = largest_smallest_integers(vec![i8::MIN, 0, i8::MAX]);
    assert_eq!(res_bounds, (Some(i8::MAX), Some(i8::MIN)));

    // All equal values
    let res_equal = largest_smallest_integers(vec![7, 7, 7]);
    assert_eq!(res_equal, (Some(7), Some(7)));

    // Increasing order
    let res_inc = largest_smallest_integers(vec![1, 2, 3, 4]);
    assert_eq!(res_inc, (Some(4), Some(1)));

    // Decreasing order
    let res_dec = largest_smallest_integers(vec![4, 3, 2, 1]);
    assert_eq!(res_dec, (Some(4), Some(1)));

    // Mixed values including near-boundaries
    let res_mixed = largest_smallest_integers(vec![i8::MIN, -10, 0, 10, i8::MAX - 1]);
