fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // Runtime checks mirroring the specification's preconditions
    assert_eq!(vals_1.len(), vals_2.len(), "vals_1 and vals_2 must have equal length");
    assert_eq!(vals_1.len(), conds_1.len(), "vals_1 and conds_1 must have equal length");
    assert_eq!(vals_1.len(), conds_2.len(), "vals_1 and conds_2 must have equal length");

    for i in 0..vals_1.len() {
        assert!(conds_1[i] || conds_2[i], "At each index, at least one condition must be true");
        assert!(vals_1[i] < 1000, "All values in vals_1 must be < 1000");
        assert!(vals_2[i] < 1000, "All values in vals_2 must be < 1000");
    }

    avgs.clear();
    for i in 0..vals_1.len() {
        let avg_val = if conds_1[i] && conds_2[i] {
            (vals_1[i] + vals_2[i]) / 2
        } else if conds_1[i] {
            vals_1[i]
        } else {
            vals_2[i]
        };
        avgs.push(avg_val);
    }
}

fn main() {
    // Test 1: Both conditions true everywhere -> pairwise integer average
    {
        let v1 = vec![2_u64, 6, 9, 10];
        let v2 = vec![4_u64, 8, 3, 11];
        let c1 = vec![true, true, true, true];
        let c2 = vec![true, true, true, true];
        let mut out = Vec::new();
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert_eq!(out, vec![(2+4)/2, (6+8)/2, (9+3)/2, (10+11)/2]); // [3, 7, 6, 10]
    }

    // Test 2: Only first condition true everywhere -> copy from first array
    {
        let v1 = vec![0_u64, 1, 2, 3, 4];
        let v2 = vec![5_u64, 6, 7, 8, 9];
        let c1 = vec![true, true, true, true, true];
        let c2 = vec![false, false, false, false, false];
        let mut out = Vec::new();
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert_eq!(out, v1);
    }

    // Test 3: Only second condition true everywhere -> copy from second array
    {
        let v1 = vec![9_u64, 8, 7];
        let v2 = vec![1_u64, 2, 3];
        let c1 = vec![false, false, false];
        let c2 = vec![true, true, true];
        let mut out = Vec::new();
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert_eq!(out, v2);
    }

    // Test 4: Mixed conditions per index
    // i=0: both true -> avg
    // i=1: only first true -> first
    // i=2: only second true -> second
    // i=3: both true -> avg
    {
        let v1 = vec![10_u64, 20, 30, 40];
        let v2 = vec![2_u64, 3, 4, 5];
        let c1 = vec![true,  true,  false, true];
        let c2 = vec![true,  false, true,  true];
        let mut out = Vec::new();
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        let expected = vec![(10+2)/2, 20, 4, (40+5)/2];
        assert_eq!(out, expected); // [6, 20, 4, 22]
    }

    // Test 5: Empty arrays (n = 0)
    {
        let v1: Vec<u64> = vec![];
        let v2: Vec<u64> = vec![];
        let c1: Vec<bool> = vec![];
        let c2: Vec<bool> = vec![];
        let mut out = Vec::new();
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert!(out.is_empty());
    }

    // Test 6: Single element, both true at boundary value 999
    {
        let v1 = vec![999_u64];
        let v2 = vec![999_u64];
        let c1 = vec![true];
        let c2 = vec![true];
        let mut out = Vec::new();
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert_eq!(out, vec![(999 + 999) / 2]); // 999
    }

    // Test 7: Integer division truncation check
    // (5 + 6) / 2 = 11 / 2 = 5
    {
        let v1 = vec![5_u64, 0, 7];
        let v2 = vec![6_u64, 9, 8];
        let c1 = vec![true, true, false];
        let c2 = vec![true, false, true];
        let mut out = Vec::new();
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert_eq!(out, vec![5, 0, 8]);
    }

    // Test 8: Larger n with varied patterns ensuring preconditions
    {
        let v1 = vec![1_u64, 2, 3, 4, 5, 6, 7];
