        let next = prev2 + prev1;
        v.push(next);

        proof {
            assert(v@[i as int] == next);
            assert(next == prev2 + prev1);
            assert(next == fibo((i-2) as int) + fibo((i-1) as int));
            assert(next == fibo(i as int));
            assert(forall |j: int| 0 <= j < i + 1 ==> v@[j] == fibo(j));
        }

