use std::cmp::Ordering;

fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    // Plain Rust implementation matching the described behavior
    for (i, &x) in nums.iter().enumerate() {
        if x == target {
            return i as i32;
        }
    }
    -1
}

fn assert_first_occurrence_properties(nums: &Vec<i32>, target: i32, ret: i32) {
    // Assumption boundary (not enforced at runtime, but tests will satisfy it):
    assert!(nums.len() < 0x8000_0000usize);

    if ret >= 0 {
        let idx = ret as usize;
        assert!(idx < nums.len());
        assert!(nums[idx] == target);
        for i in 0..idx {
            assert!(nums[i] != target);
        }
    } else {
        for &x in nums.iter() {
            assert!(x != target);
        }
    }
}

fn main() {
    // 1) Empty array, target absent
    let nums1: Vec<i32> = vec![];
    let ret1 = linear_search(nums1.clone(), 5);
    assert!(ret1 < nums1.len() as i32);
    assert!(ret1 < 0);
    assert_first_occurrence_properties(&nums1, 5, ret1);

    // 2) Single-element array, target present
    let nums2 = vec![7];
    let ret2 = linear_search(nums2.clone(), 7);
    assert!(ret2 >= 0);
    assert!(ret2 < nums2.len() as i32);
    assert_first_occurrence_properties(&nums2, 7, ret2);

    // 3) Single-element array, target absent
    let nums3 = vec![7];
    let ret3 = linear_search(nums3.clone(), 5);
    assert!(ret3 < nums3.len() as i32);
    assert!(ret3 < 0);
    assert_first_occurrence_properties(&nums3, 5, ret3);

    // 4) Multiple elements with duplicates, target appears; ensure first occurrence
    let nums4 = vec![1, 2, 3, 2, 4];
    let ret4 = linear_search(nums4.clone(), 2);
    assert_eq!(ret4, 1);
    assert_first_occurrence_properties(&nums4, 2, ret4);

    // 5) Target at the first index
    let nums5 = vec![9, 8, 7];
    let ret5 = linear_search(nums5.clone(), 9);
    assert_eq!(ret5, 0);
    assert_first_occurrence_properties(&nums5, 9, ret5);

    // 6) Target at the last index
    let nums6 = vec![3, 4, 5, 6];
    let ret6 = linear_search(nums6.clone(), 6);
    assert_eq!(ret6, 3);
    assert_first_occurrence_properties(&nums6, 6, ret6);

    // 7) Target absent in a non-empty array
    let nums7 = vec![0, 1, 2, 3];
    let ret7 = linear_search(nums7.clone(), -1);
    assert!(ret7 < 0);
    assert_first_occurrence_properties(&nums7, -1, ret7);

    // 8) Negative numbers with duplicates
    let nums8 = vec![-3, -2, -2, -1];
    let ret8 = linear_search(nums8.clone(), -2);
    assert_eq!(ret8, 1);
    assert_first_occurrence_properties(&nums8, -2, ret8);

    // 9) Larger array; target near the end
    let mut nums9: Vec<i32> = (0..100_000).map(|x| x as i32).collect();
    let ret9 = linear_search(nums9.clone(), 99_999);
    assert_eq!(ret9, 99_999);
    assert_first_occurrence_properties(&nums9, 99_999, ret9);

    // 10) All elements equal to the target
    let nums10 = vec![5, 5, 5, 5];
    let ret10 = linear_search(nums10.clone(), 5);
    assert_eq!(ret10, 0);
    assert_first_occurrence_properties(&nums10, 5, ret10);
}

