verus! {

spec fn is_digit_sepc(c: char) -> (res: bool) {
    (c as u32) >= 48 && (c as u32) <= 57
}

fn is_digit_exec(c: char) -> (res: bool)
    ensures
        res == is_digit_sepc(c)
{
    let v: u32 = c as u32;
    v >= 48 && v <= 57
}

spec fn all_digits(text: &Vec<char>) -> bool { forall|i: int| 0 <= i < text.len() ==> (#[trigger] is_digit_sepc(text[i])) }

fn is_integer(text: &Vec<char>) -> (result: bool)
    ensures
        result == (forall|i: int| 0 <= i < text.len() ==> (#[trigger] is_digit_sepc(text[i])))
{
    let mut k: usize = 0;
    let mut res: bool = true;
    while k < text.len()
        invariant
            k <= text.len(),
            0 <= k as int <= text.len() as int,
            res == (forall|j: int| 0 <= j < k as int ==> (#[trigger] is_digit_sepc(text[j]))),
        decreases text.len() - k
    {
        let c = text[k];
        let d = is_digit_exec(c);
        proof {
            assert(d == is_digit_sepc(c));
        }
        res = res && d;
        k = k + 1;
    }
    assert(k == text.len());
    res
}

}

fn main() {
    // Helper to build Vec<char> from &str
    fn to_chars(s: &str) -> Vec<char> { s.chars().collect() }

    // 1. Empty input: should be true
    let v1 = to_chars("");
    assert!(is_integer(&v1) == true);

    // 2. Single digit '0'
    let v2 = to_chars("0");
    assert!(is_integer(&v2) == true);

    // 3. Single digit '9'
    let v3 = to_chars("9");
    assert!(is_integer(&v3) == true);

    // 4. Multiple digits
    let v4 = to_chars("1234567890");
    assert!(is_integer(&v4) == true);

    // 5. Contains a letter
    let v5 = to_chars("123a456");
    assert!(is_integer(&v5) == false);

    // 6. Contains spaces only
    let v6 = to_chars("   ");
    assert!(is_integer(&v6) == false);

    // 7. Contains a leading plus sign
    let v7 = to_chars("+123");
    assert!(is_integer(&v7) == false);

    // 8. Contains punctuation
    let v8 = to_chars("42!");
    assert!(is_integer(&v8) == false);

    // 9. Boundary just outside: ':' (58) should be false, '/' (47) should be false
    let v9a = to_chars(":");
    let v9b = to_chars("/");
    assert!(is_integer(&v9a) == false);
    assert!(is_integer(&v9b) == false);

    // 10. All zeros
    let v10 = to_chars("0000");
    assert!(is_integer(&v10) == true);
}

