use std::fmt::Debug;

fn main() {
    // Test 1: Empty input
    let input: Vec<char> = vec![];
    let out = replace_blanks_with_chars(&input, 'x');
    assert!(out.is_empty());

    // Test 2: No spaces
    let input: Vec<char> = "abc".chars().collect();
    let out = replace_blanks_with_chars(&input, '*');
    assert_eq!(out, input);

    // Test 3: All spaces
    let input: Vec<char> = "    ".chars().collect();
    let out = replace_blanks_with_chars(&input, '*');
    let expected: Vec<char> = "****".chars().collect();
    assert_eq!(out, expected);

    // Test 4: Mixed spaces and letters
    let input: Vec<char> = "a b c d".chars().collect();
    let out = replace_blanks_with_chars(&input, '_');
    let expected: Vec<char> = "a_b_c_d".chars().collect();
    assert_eq!(out, expected);

    // Test 5: Single non-space element
    let input: Vec<char> = vec!['x'];
    let out = replace_blanks_with_chars(&input, 'y');
    assert_eq!(out, vec!['x']);

    // Test 6: Single space element
    let input: Vec<char> = vec![' '];
    let out = replace_blanks_with_chars(&input, 'y');
    assert_eq!(out, vec!['y']);

    // Test 7: Replacement character is also a space
    let input: Vec<char> = "a b".chars().collect();
    let out = replace_blanks_with_chars(&input, ' ');
    assert_eq!(out, input);

    // Test 8: Unicode NBSP should not be replaced; only ASCII space is replaced
    let input: Vec<char> = "a\u{00A0} b".chars().collect();
    let out = replace_blanks_with_chars(&input, '-');
    let expected: Vec<char> = "a\u{00A0}-b".chars().collect();
    assert_eq!(out, expected);

    // Test 9: Multiple spaces throughout the string
    let input: Vec<char> = "  leading and  multiple  spaces  ".chars().collect();
    let out = replace_blanks_with_chars(&input, '#');
    let expected: Vec<char> = "##leading#and##multiple##spaces##".chars().collect();
    assert_eq!(out, expected);
}

