use vstd::prelude::*;

verus! {
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
        ensures
            result@.len() == (2 * arr.len()),
            forall|k: int| 0 <= k < arr.len() ==> #[trigger] result[2 * k] == elem,
            forall|k: int| 0 <= k < arr.len() ==> #[trigger] result[2 * k + 1] == arr[k],
    {
        let mut out: Vec<i32> = Vec::new();
        let mut i: usize = 0;
        while i < arr.len()
            invariant
                0 <= i as int <= arr.len() as int,
                out@.len() == 2 * (i as int),
                forall|k: int| 0 <= k < i as int ==> #[trigger] out@[2 * k] == elem,
                forall|k: int| 0 <= k < i as int ==> #[trigger] out@[2 * k + 1] == arr@[k],
            decreases (arr.len() - i)
        {
            out.push(elem);
            out.push(arr[i]);
            i += 1;
        }
        out
    }
}

fn build_expected(arr: &Vec<i32>, elem: i32) -> Vec<i32> {
    let mut v = Vec::with_capacity(2 * arr.len());
    for &x in arr.iter() {
        v.push(elem);
        v.push(x);
    }
    v
}

fn main() {
    // 1. Empty array
    {
        let arr: Vec<i32> = vec![];
        let elem: i32 = 99;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 2. Single element
    {
        let arr = vec![42];
        let elem = 0;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 3. Multiple elements
    {
        let arr = vec![1, 2, 3];
        let elem = -7;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 4. Negative numbers
    {
        let arr = vec![-1, -2, -3, -4];
        let elem = 123;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 5. Duplicates in input
    {
        let arr = vec![5, 5, 5, 5];
        let elem = -100;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 6. Boundary values
    {
        let arr = vec![i32::MIN, i32::MAX];
        let elem = 7;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 7. Zero element interleaving
    {
        let arr = vec![0, 10, -10];
        let elem = 0;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 8. Longer array
    {
        let arr = vec![10, 20, 30, 40, 50, 60];
        let elem = 888;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }

    // 9. Single zero
    {
        let arr = vec![0];
        let elem = -1;
        let res = insert_before_each(&arr, elem);
        assert_eq!(res.len(), 2 * arr.len());
        let expected = build_expected(&arr, elem);
        assert_eq!(res, expected);
    }
}

