use vstd::prelude::*;

verus! {
    fn element_wise_subtract(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (result: Vec<i32>)
        requires
            arr1.len() == arr2.len(),
            forall|i: int|
                (0 <= i < arr1.len()) ==> (i32::MIN <= #[trigger] (arr1[i] - arr2[i]) <= i32::MAX),
        ensures
            result.len() == arr1.len(),
            forall|i: int|
                0 <= i < result.len() ==> #[trigger] result[i] == #[trigger] (arr1[i] - arr2[i]),
    {
        let mut result = Vec::new();
        let mut i = 0;
        while i < arr1.len()
            invariant
                i <= arr1.len(),
                result.len() == i,
                forall|j: int| 0 <= j < i ==> result[j] == arr1[j] - arr2[j],
                arr1.len() == arr2.len(),
                forall|j: int| 0 <= j < arr1.len() ==> i32::MIN <= #[trigger] (arr1[j] - arr2[j]) <= i32::MAX,
            decreases arr1.len() - i,
        {
            let diff = arr1[i] - arr2[i];
            result.push(diff);
            i = i + 1;
        }
        result
    }

    fn main() {
        // Test 1: Empty arrays (vacuously satisfies preconditions)
        let arr1: Vec<i32> = Vec::new();
        let arr2: Vec<i32> = Vec::new();
        let res = element_wise_subtract(&arr1, &arr2);
        assert(res.len() == 0);

        // Test 2: Small positive numbers
        let arr1 = Vec::from(vec![1, 2, 3]);
        let arr2 = Vec::from(vec![3, 2, 1]);
        // Precondition note: each difference is within i32 bounds: [-2, 0, 2].
        let res = element_wise_subtract(&arr1, &arr2);
        assert(res.len() == arr1.len());
        assert(res[0] == -2);
        assert(res[1] == 0);
        assert(res[2] == 2);

