fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Precondition: lengths must be equal
    assert!(arr1.len() == arr2.len(), "Precondition violated: lengths must be equal");
    let mut result = Vec::with_capacity(arr1.len());
    for i in 0..arr1.len() {
        result.push(arr1[i] ^ arr2[i]);
    }
    result
}

fn main() {
    // Test 1: Empty arrays (edge case)
    let a: Vec<i32> = vec![];
    let b: Vec<i32> = vec![];
    let r = bit_wise_xor(&a, &b);
    assert!(r.is_empty());

    // Test 2: Single-element arrays
    let a = vec![5];
    let b = vec![3];
    let r = bit_wise_xor(&a, &b);
    assert_eq!(r, vec![5 ^ 3]);

    // Test 3: Multiple elements, typical case
    let a = vec![1, 2, 3, 4];
    let b = vec![4, 3, 2, 1];
    assert_eq!(bit_wise_xor(&a, &b), vec![1 ^ 4, 2 ^ 3, 3 ^ 2, 4 ^ 1]);

    // Test 4: Identical arrays (XOR with self yields 0)
    let a = vec![7, 7, 7];
    let b = vec![7, 7, 7];
    assert_eq!(bit_wise_xor(&a, &b), vec![0, 0, 0]);

    // Test 5: Zeros and negative values
    let a = vec![0, 0, 0];
