        10 ^ 3, 20 ^ 6, 30 ^ 9, 40 ^ 12, 50 ^ 15,
        60 ^ 18, 70 ^ 21, 80 ^ 24, 90 ^ 27, 100 ^ 30,
    ]);

    // Test 8: Boundary values using i32::MAX and i32::MIN
    let a = vec![i32::MAX, i32::MIN, -1, 0];
    let b = vec![0, 0, -1, i32::MIN];
    assert_eq!(bit_wise_xor(&a, &b), vec![
        i32::MAX ^ 0,
        i32::MIN ^ 0,
        -1 ^ -1,
        0 ^ i32::MIN,
