fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    let mut out: Vec<char> = Vec::with_capacity(str1.len());
    for &c in str1.iter() {
        let t = if c >= 'a' && c <= 'z' {
            ((c as u8) - 32) as char
        } else if c >= 'A' && c <= 'Z' {
            ((c as u8) + 32) as char
        } else {
            c
        };
        out.push(t);
    }
    out
}

fn vec_from_str(s: &str) -> Vec<char> { s.chars().collect() }

fn main() {
    // 1) Edge case: empty input
    let input1: Vec<char> = vec![];
    let output1 = to_toggle_case(&input1);
    assert_eq!(output1, vec![]);

    // 2) Single lowercase letter
    let input2 = vec!['a'];
    let output2 = to_toggle_case(&input2);
    assert_eq!(output2, vec!['A']);

    // 3) Single uppercase letter
    let input3 = vec!['Z'];
    let output3 = to_toggle_case(&input3);
    assert_eq!(output3, vec!['z']);

    // 4) Mixed ASCII letters
    let input4 = vec_from_str("aBcDeF");
    let output4 = to_toggle_case(&input4);
    let expected4 = vec_from_str("AbCdEf");
    assert_eq!(output4, expected4);

    // 5) Non-letter characters remain unchanged
    let input5 = vec!['1', '2', '!', '#', ' '];
    let output5 = to_toggle_case(&input5);
    assert_eq!(output5, vec!['1', '2', '!', '#', ' ']);

    // 6) Unicode characters outside ASCII A-Z/a-z remain unchanged
    let input6 = vec!['é', 'ß', 'Ω', 'π'];
