    assert_eq!(output6, vec!['é', 'ß', 'Ω', 'π']);

    // 7) Sentence with punctuation and spaces
    let input7 = vec_from_str("HELLO, world!");
    let output7 = to_toggle_case(&input7);
    let expected7 = vec_from_str("hello, WORLD!");
    assert_eq!(output7, expected7);

    // 8) Idempotence under double toggle: toggling twice yields original
    let input8 = vec_from_str("AbC123xYz!");
    let once = to_toggle_case(&input8);
    let twice = to_toggle_case(&once);
    assert_eq!(twice, input8);

