    let input9 = vec_from_str("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ");
    let output9 = to_toggle_case(&input9);
    let expected9 = vec_from_str("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz");
    assert_eq!(output9, expected9);

    println!("All tests passed.");
}

