use std::i32;

fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // Preconditions (assumed by the specification); asserted here for tests
    assert!(s1.len() == s2.len() && s2.len() == s3.len(), "Input arrays must have equal length");
    assert!((s1.len() as u128) * 3 <= (i32::MAX as u128), "3 * length must fit in i32::MAX");

    let n = s1.len();
    let mut res = Vec::with_capacity(n * 3);
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }
    res
}

fn main() {
    // Test 1: Empty arrays
    let a: Vec<i32> = vec![];
    let b: Vec<i32> = vec![];
    let c: Vec<i32> = vec![];
    let r = interleave(&a, &b, &c);
    assert_eq!(r, vec![]);

    // Test 2: Single element arrays
    let a = vec![10];
    let b = vec![20];
    let c = vec![30];
    let r = interleave(&a, &b, &c);
    assert_eq!(r, vec![10, 20, 30]);

    // Test 3: Two elements (happy path)
    let a = vec![1, 4];
    let b = vec![2, 5];
    let c = vec![3, 6];
    let r = interleave(&a, &b, &c);
    assert_eq!(r, vec![1, 2, 3, 4, 5, 6]);

    // Test 4: Mix of negatives and zeros
    let a = vec![0, -1];
    let b = vec![7, 8];
    let c = vec![-5, -6];
    let r = interleave(&a, &b, &c);
    assert_eq!(r, vec![0, 7, -5, -1, 8, -6]);

    // Test 5: Repeated values, verify length and pattern
    let n = 5usize;
    let a = vec![1; n];
    let b = vec![2; n];
    let c = vec![3; n];
    let r = interleave(&a, &b, &c);
    assert_eq!(r.len(), 3 * n);
    for i in 0..n {
        assert_eq!(r[3 * i], 1);
        assert_eq!(r[3 * i + 1], 2);
        assert_eq!(r[3 * i + 2], 3);
    }

    // Test 6: Diverse values including extremes
    let a = vec![-100, 0, 100, i32::MAX, i32::MIN + 1];
    let b = vec![5, -5, 5, -5, 0];
    let c = vec![9, 8, 7, 6, 5];
    let r = interleave(&a, &b, &c);
    let expected = vec![
        -100, 5, 9,
        0, -5, 8,
        100, 5, 7,
        i32::MAX, -5, 6,
        i32::MIN + 1, 0, 5,
    ];
    assert_eq!(r, expected);

    // Test 7: Larger size to exercise length constraint path (still small enough for quick run)
    let n = 100_000usize; // 3*n << i32::MAX
    let a: Vec<i32> = (0..n as i32).collect();
    let b: Vec<i32> = (0..n as i32).map(|x| x * 2).collect();
    let c: Vec<i32> = (0..n as i32).map(|x| x * 3).collect();
    let r = interleave(&a, &b, &c);
    assert_eq!(r.len(), 3 * n);
    // spot-check a few positions
    for &idx in &[0usize, 1usize, 2usize, n - 1] {
        assert_eq!(r[3 * idx], a[idx]);
        assert_eq!(r[3 * idx + 1], b[idx]);
        assert_eq!(r[3 * idx + 2], c[idx]);
    }
}

