fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Precondition checks to mirror the specification
    assert!(!list.is_empty(), "precondition violated: input array must be non-empty");
    assert!(n > 0 && n < list.len(), "precondition violated: 0 < n < array length");

    let mut left = list.clone();
    let mut right = left.split_off(n);
    right.append(&mut left);
    right
}

fn main() {
    // Happy path: standard inputs
    let a1 = vec![1, 2, 3, 4, 5];
    let r1 = split_and_append(&a1, 2);
    assert_eq!(r1, vec![3, 4, 5, 1, 2]);

    let a2 = vec![10, 20, 30];
    let r2 = split_and_append(&a2, 1);
    assert_eq!(r2, vec![20, 30, 10]);

    // Boundary: minimal valid length (2) and n=1
    let a3 = vec![7, 8];
    let r3 = split_and_append(&a3, 1);
    assert_eq!(r3, vec![8, 7]);

    // Repeated elements
    let a4 = vec![5, 5, 5];
    let r4 = split_and_append(&a4, 2);
    assert_eq!(r4, vec![5, 5, 5]);

