fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Enforce the specified preconditions in tests
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");
    assert!(arr2.iter().all(|&x| x != 0), "All elements of the second array must be non-zero");
    // Ensure each modulo result fits in i32 range
    assert!(arr1.iter().zip(arr2.iter()).all(|(&a, &b)| (a % b) as u64 <= i32::MAX as u64));

    let mut res = Vec::with_capacity(arr1.len());
    for i in 0..arr1.len() {
        res.push(arr1[i] % arr2[i]);
    }
    res
}

fn main() {
    // 1) Edge case: empty arrays
    let a1: Vec<u32> = vec![];
    let a2: Vec<u32> = vec![];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![]);

    // 2) Single element
    let a1 = vec![5u32];
    let a2 = vec![2u32];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![1u32]);

    // 3) Standard case
    let a1 = vec![10u32, 20u32, 30u32];
    let a2 = vec![7u32, 6u32, 5u32];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![3u32, 2u32, 0u32]);

    // 4) Second array elements are 1 (result must be all zeros)
    let a1 = vec![0u32, 123u32, u32::MAX - 1];
    let a2 = vec![1u32, 1u32, 1u32];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![0u32, 0u32, 0u32]);

    // 5) Divisors larger than dividends (result equals the dividend)
    let a1 = vec![1_000_000_000u32, 2_000_000_000u32, 42u32];
    let a2 = vec![u32::MAX, u32::MAX, u32::MAX];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![1_000_000_000u32, 2_000_000_000u32, 42u32]);

    // 6) Boundary: modulo equals i32::MAX
    let a1 = vec![i32::MAX as u32];
    let a2 = vec![u32::MAX];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![i32::MAX as u32]);

    // 7) Mixed small values
    let a1 = vec![100u32, 101u32, 102u32, 103u32];
    let a2 = vec![3u32, 4u32, 5u32, 6u32];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![1u32, 1u32, 2u32, 1u32]);

    // 8) Large divisors with small dividends
    let a1 = vec![100u32, 200u32];
    let a2 = vec![u32::MAX, u32::MAX - 5];
    let r = element_wise_module(&a1, &a2);
    assert_eq!(r, vec![100u32, 200u32]);
}

