fn vec_from_str(s: &str) -> Vec<char> {
    s.chars().collect()
}

fn to_string(v: &Vec<char>) -> String {
    v.iter().collect()
}

fn expected_map(s: &str) -> String {
    s.chars()
        .map(|c| if c == ' ' || c == ',' || c == '.' { ':' } else { c })
        .collect()
}

fn assert_case(input: &str, expected: &str) {
    let v = vec_from_str(input);
    let r = replace_with_colon(&v);
    let out = to_string(&r);
    assert_eq!(out, expected);
    assert_eq!(r.len(), v.len());
}

fn main() {
    // 1. Empty input
    assert_case("", "");

    // 2. Single non-target character
    assert_case("a", "a");

    // 3. Single target character (period)
    assert_case(".", ":");

    // 4. Mixed input with comma, space, and period
    assert_case("Hello, World.", "Hello::World:");

    // 5. Only target characters
    assert_case(" ,.", ":::");

    // 6. Digits and punctuation
    assert_case("123, 456.789", "123::456:789");

    // 7. Colon should remain unchanged
    assert_case(":", ":");

    // 8. Multiple occurrences of target characters
    assert_case("   ,,,...", ":::::::::");

    // 9. Unicode punctuation not affected; ASCII comma replaced
    assert_case("é，,", "é，:");

    // 10. Long input (boundary case)
    let long = " .,".repeat(100); // 300 characters
    let long_expected = expected_map(&long);
    let long_vec = vec_from_str(&long);
    let long_res = replace_with_colon(&long_vec);
    let long_out = to_string(&long_res);
    assert_eq!(long_out, long_expected);
    assert_eq!(long_res.len(), long_vec.len());
}

