fn main() {
    // Helper to check the postconditions at runtime
    fn check_post(arr: &Vec<i32>, target: i32, res: Option<usize>) {
        match res {
            Some(idx) => {
                assert!(idx < arr.len());
                assert!(arr[idx] == target);
                let mut k: usize = 0;
                while k < idx {
                    assert!(arr[k] != target);
                    k += 1;
                }
            }
            None => {
                let mut k: usize = 0;
                while k < arr.len() {
                    assert!(arr[k] != target);
                    k += 1;
                }
            }
        }
    }

    // 1. Empty array -> None
    let arr1: Vec<i32> = vec![];
    let target1: i32 = 10;
    let res1 = find_first_occurrence(&arr1, target1);
    assert!(res1.is_none());
    check_post(&arr1, target1, res1);

    // 2. Single-element array where element equals target -> Some(0)
    let arr2 = vec![7];
    let target2 = 7;
    let res2 = find_first_occurrence(&arr2, target2);
    assert!(res2 == Some(0));
    check_post(&arr2, target2, res2);

    // 3. Single-element array where element does not equal target -> None
    let arr3 = vec![7];
    let target3 = 5;
    let res3 = find_first_occurrence(&arr3, target3);
    assert!(res3.is_none());
    check_post(&arr3, target3, res3);

    // 4. Multiple elements, unique occurrence in the middle -> Some(3)
    let arr4 = vec![1, 3, 5, 7, 9];
    let target4 = 7;
    let res4 = find_first_occurrence(&arr4, target4);
    assert!(res4 == Some(3));
    check_post(&arr4, target4, res4);

    // 5. Multiple duplicates, non-decreasing array -> first occurrence at index 1
    let arr5 = vec![1, 2, 2, 2, 3];
    let target5 = 2;
    let res5 = find_first_occurrence(&arr5, target5);
    assert!(res5 == Some(1));
    check_post(&arr5, target5, res5);

    // 6. Target at the first position with duplicates following -> Some(0)
    let arr6 = vec![5, 5, 6];
    let target6 = 5;
    let res6 = find_first_occurrence(&arr6, target6);
    assert!(res6 == Some(0));
    check_post(&arr6, target6, res6);

    // 7. Target at the last position -> Some(2)
    let arr7 = vec![-10, 0, 10];
    let target7 = 10;
    let res7 = find_first_occurrence(&arr7, target7);
    assert!(res7 == Some(2));
    check_post(&arr7, target7, res7);

    // 8. All elements less than target -> None
