use std::vec::Vec;

fn all_characters_same(char_arr: &Vec<char>) -> bool {
    if char_arr.len() <= 1 {
        return true;
    }
    let first = char_arr[0];
    for i in 1..char_arr.len() {
        if char_arr[i] != first {
            return false;
        }
    }
    true
}

fn main() {
    // Edge cases
    let v0: Vec<char> = vec![];
    assert_eq!(all_characters_same(&v0), true); // empty array -> true

    let v1 = vec!['a'];
    assert_eq!(all_characters_same(&v1), true); // single element -> true

    // Happy paths
    let v2 = vec!['x', 'x', 'x'];
    assert_eq!(all_characters_same(&v2), true);

    let v3 = vec!['a', 'a', 'b'];
    assert_eq!(all_characters_same(&v3), false); // differs at index 2

    let v4 = vec!['z', 'z', 'z', 'y'];
    assert_eq!(all_characters_same(&v4), false); // differs at the end

    // Unicode characters
    let v5 = vec!['😀', '😀'];
    assert_eq!(all_characters_same(&v5), true);

    // Case sensitivity check
    let v6 = vec!['A', 'a'];
    assert_eq!(all_characters_same(&v6), false);

    // Larger input - all same
    let v7: Vec<char> = std::iter::repeat('q').take(100).collect();
    assert_eq!(all_characters_same(&v7), true);

    // Larger input - difference in the middle
    let mut v8: Vec<char> = std::iter::repeat('q').take(100).collect();
    v8[50] = 'r';
    assert_eq!(all_characters_same(&v8), false);

    println!("All tests passed.");
}

