fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    for (i, &v) in arr.iter().enumerate() {
        if (i % 2) != (v % 2) {
            return false;
        }
    }
    true
}

fn main() {
    // Edge case: empty array (vacuously true)
    let a: Vec<usize> = vec![];
    assert_eq!(is_odd_at_odd_index(&a), true);

    // Single-element cases
    let b = vec![0usize]; // index 0 even, value even -> true
    assert_eq!(is_odd_at_odd_index(&b), true);

    let c = vec![1usize]; // index 0 even, value odd -> false
    assert_eq!(is_odd_at_odd_index(&c), false);

    // Two elements: correct parity alignment
    let d = vec![2usize, 3usize]; // 0->even, 1->odd
    assert_eq!(is_odd_at_odd_index(&d), true);

    // Two elements: mismatch at odd index
    let e = vec![2usize, 4usize]; // index 1 odd, value even -> false
    assert_eq!(is_odd_at_odd_index(&e), false);

    // Longer array: all aligned
    let f = vec![0usize, 1usize, 2usize, 3usize, 4usize, 5usize];
    assert_eq!(is_odd_at_odd_index(&f), true);

    // Longer array: all aligned, mixed values
    let g = vec![10usize, 11usize, 12usize, 13usize, 14usize, 15usize, 16usize];
    assert_eq!(is_odd_at_odd_index(&g), true);

    // Larger values to test parity only
    let h = vec![1_000_000_000usize, 1_000_000_001usize, 1_000_000_002usize, 1_000_000_003usize];
    assert_eq!(is_odd_at_odd_index(&h), true);

    // Mixed with a single violation in the middle
    let i = vec![0usize, 1usize, 2usize, 4usize, 4usize]; // index 3 odd, value even -> false
    assert_eq!(is_odd_at_odd_index(&i), false);
}

