use std::fmt::Debug;

fn reverse(a: &[i32]) -> Vec<i32> {
    let mut result = Vec::with_capacity(a.len());
    let mut i = a.len();
    while i > 0 {
        i -= 1;
        result.push(a[i]);
    }
    result
}

fn assert_eq_vec<T: PartialEq + Debug>(got: Vec<T>, expected: Vec<T>) {
    assert!(got == expected, "got {:?}, expected {:?}", got, expected);
}

fn main() {
    // 1) Empty input
    let arr1: Vec<i32> = vec![];
    assert_eq_vec(reverse(&arr1), vec![]);

    // 2) Single element
    let arr2 = vec![42];
    assert_eq_vec(reverse(&arr2), vec![42]);

    // 3) Two elements
    let arr3 = vec![1, 2];
    assert_eq_vec(reverse(&arr3), vec![2, 1]);

    // 4) Palindromic array
    let arr4 = vec![1, 2, 3, 2, 1];
    assert_eq_vec(reverse(&arr4), vec![1, 2, 3, 2, 1]);

    // 5) Negative numbers
    let arr5 = vec![-1, -2, -3];
    assert_eq_vec(reverse(&arr5), vec![-3, -2, -1]);

    // 6) Mixed extremes and zero
    let arr6 = vec![0, -1, 5, i32::MIN, i32::MAX];
    assert_eq_vec(reverse(&arr6), vec![i32::MAX, i32::MIN, 5, -1, 0]);

    // 7) Larger array (1..=10)
    let arr7: Vec<i32> = (1..=10).collect();
    let mut expected7: Vec<i32> = arr7.clone();
    expected7.reverse();
    assert_eq_vec(reverse(&arr7), expected7);

    // 8) Repeated values
    let arr8 = vec![5, 5, 5, 5];
    assert_eq_vec(reverse(&arr8), vec![5, 5, 5, 5]);

    println!("All tests passed.");
}

