    assert_eq!(r1.len(), a1.len());
    assert_eq_vec(r1, vec![1 ^ 4, 2 ^ 5, 3 ^ 6]); // [5, 7, 5]

    // 2) Boundary case: minimal allowed size (non-empty, length = 1)
    let a2 = vec![0u8];
