    assert_eq!(r2.len(), a2.len());
    assert_eq_vec(r2, vec![0 ^ 0]); // [0]

    // 3) Edge values: test with 0, 1, 128, 255
    let a3 = vec![255u8, 128, 1, 0];
    let b3 = vec![1u8, 128, 254, 255];
    let r3 = bitwise_xor(a3.clone(), b3.clone());
    assert_eq!(r3.len(), a3.len());
    assert_eq_vec(r3, vec![255 ^ 1, 128 ^ 128, 1 ^ 254, 0 ^ 255]); // [254, 0, 255, 255]

