use std::fmt::Debug;

fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Extract the j-th column (0 <= j < m) as a vector of length n.
    let mut col: Vec<i8> = Vec::with_capacity(n);
    let mut i: usize = 0;
    while i < n {
        col.push(input[i][j]);
        i += 1;
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Return the transpose: m rows each of length n, where result[j][i] == input[i][j].
    let mut result: Vec<Vec<i8>> = Vec::with_capacity(m);
    let mut j: usize = 0;
    while j < m {
        let col = get_column(&input, j, m, n);
        result.push(col);
        j += 1;
    }
    result
}

fn assert_transpose(input: Vec<Vec<i8>>, m: usize, n: usize) {
    let result = column_stack(input.clone(), m, n);
    assert_eq!(result.len(), m, "Output must have m rows");
    for j in 0..m {
        assert_eq!(result[j].len(), n, "Each output row must have n elements");
        for i in 0..n {
            assert_eq!(result[j][i], input[i][j], "Mismatch at output[{j}][{i}] vs input[{i}][{j}]");
        }
    }
    assert_eq!(result.len() * n, m * n, "Total element count must be m * n");
}

