fn main() {
    // Helper to run a single test case and validate both length and elementwise truth values
    fn run_case(a: Vec<i8>, b: Vec<i8>) {
        assert_eq!(a.len(), b.len(), "Precondition violated: input arrays must have equal length");
        let got = less(a.clone(), b.clone());
        let expected: Vec<bool> = a.iter().zip(b.iter()).map(|(x, y)| x < y).collect();
        assert_eq!(got.len(), a.len(), "Result length must match input length");
        assert_eq!(got, expected, "Element-wise comparison result mismatch");
    }

    // 1) Edge case: empty inputs
    run_case(vec![], vec![]);

    // 2) Single element, equal values => false
    run_case(vec![5], vec![5]);

    // 3) Single element, strictly less => true
    run_case(vec![-1], vec![0]);

    // 4) Boundary values for i8
    //    Compare combinations of -128 and 127
    run_case(vec![127, -128, -128, 127], vec![127, -128, 127, -128]);

    // 5) All comparisons are true
    run_case(vec![-10, 0, 1], vec![-9, 1, 2]);

    // 6) All comparisons are false (including equal and greater-or-equal)
    run_case(vec![3, 4, 5], vec![-1, 4, 5]);

    // 7) Alternating true/false outcomes
    run_case(vec![-128, 0, 127, 50, -50], vec![-127, 0, 126, 100, -100]);

    // 8) Mixed duplicates, only one true in the middle
    run_case(vec![10, 10, 10, 10, 10], vec![9, 10, 11, 10, 10]);

    // 9) Negative values with equality and strict less
    run_case(vec![-5, -5], vec![-5, -4]);
}

