use std::fmt::Debug;

fn transpose_plain(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    assert!(!arr.is_empty(), "input must be non-empty");
    let cols = arr[0].len();
    for r in &arr {
        assert_eq!(r.len(), cols, "all rows must have equal length");
    }
    let rows = arr.len();
    let mut ret: Vec<Vec<i8>> = Vec::with_capacity(cols);
    for j in 0..cols {
        let mut new_row: Vec<i8> = Vec::with_capacity(rows);
        for i in 0..rows {
            new_row.push(arr[i][j]);
        }
        ret.push(new_row);
    }
    ret
}

fn matrix_rows<T>(m: &Vec<Vec<T>>) -> usize { m.len() }
fn matrix_cols<T>(m: &Vec<Vec<T>>) -> usize { if m.is_empty() { 0 } else { m[0].len() } }
fn matrix_size<T>(m: &Vec<Vec<T>>) -> usize { matrix_rows(m) * matrix_cols(m) }

fn assert_transpose_correct(orig: &Vec<Vec<i8>>, trans: &Vec<Vec<i8>>) {
    let rows = matrix_rows(orig);
    let cols = matrix_cols(orig);
    assert_eq!(matrix_rows(trans), cols);
    assert_eq!(matrix_cols(trans), rows);
    assert_eq!(matrix_size(trans), rows * cols);
    for i in 0..rows {
        for j in 0..cols {
            assert_eq!(trans[j][i], orig[i][j]);
        }
    }
}

fn main() {
    // 1) 1x1 matrix
    let a1: Vec<Vec<i8>> = vec![vec![5]];
    let t1 = transpose_plain(a1.clone());
    assert_transpose_correct(&a1, &t1);
    assert_eq!(t1, vec![vec![5]]);

    // 2) 1xN row matrix
    let a2: Vec<Vec<i8>> = vec![vec![1, 2, 3]];
    let t2 = transpose_plain(a2.clone());
    assert_transpose_correct(&a2, &t2);
    assert_eq!(t2, vec![vec![1], vec![2], vec![3]]);

    // 3) Nx1 column matrix
    let a3: Vec<Vec<i8>> = vec![vec![7], vec![8], vec![9]];
    let t3 = transpose_plain(a3.clone());
    assert_transpose_correct(&a3, &t3);
    assert_eq!(t3, vec![vec![7, 8, 9]]);

    // 4) 2x2 square with negatives
    let a4: Vec<Vec<i8>> = vec![vec![-1, 2], vec![3, -4]];
    let t4 = transpose_plain(a4.clone());
    assert_transpose_correct(&a4, &t4);
    assert_eq!(t4, vec![vec![-1, 3], vec![2, -4]]);

    // 5) 2x3 rectangular
    let a5: Vec<Vec<i8>> = vec![vec![1, 0, -1], vec![2, 5, 6]];
    let t5 = transpose_plain(a5.clone());
    assert_transpose_correct(&a5, &t5);
    assert_eq!(t5, vec![vec![1, 2], vec![0, 5], vec![-1, 6]]);

    // 6) 3x2 rectangular
    let a6: Vec<Vec<i8>> = vec![vec![10, 20], vec![30, 40], vec![50, 60]];
    let t6 = transpose_plain(a6.clone());
    assert_transpose_correct(&a6, &t6);
    assert_eq!(t6, vec![vec![10, 30, 50], vec![20, 40, 60]]);

    // 7) 3x4 with i8 extremes
    let a7: Vec<Vec<i8>> = vec![
        vec![-128, 0, 127, 5],
        vec![1, 2, 3, 4],
        vec![9, 8, 7, 6],
    ];
    let t7 = transpose_plain(a7.clone());
    assert_transpose_correct(&a7, &t7);
    let expected7 = vec![
        vec![-128, 1, 9],
        vec![0, 2, 8],
        vec![127, 3, 7],
        vec![5, 4, 6],
    ];
    assert_eq!(t7, expected7);

    // 8) 4x3 mixed values
    let a8: Vec<Vec<i8>> = vec![
        vec![3, -2, 4],
        vec![0, 0, 1],
        vec![-5, 6, -7],
        vec![9, -9, 9],
    ];
    let t8 = transpose_plain(a8.clone());
    assert_transpose_correct(&a8, &t8);
    let expected8 = vec![
        vec![3, 0, -5, 9],
        vec![-2, 0, 6, -9],
        vec![4, 1, -7, 9],
    ];
    assert_eq!(t8, expected8);
}

