    for i in 0..n { result.push(top_right[i]); }
    for i in 0..n { result.push(bottom_left[i]); }
    for i in 0..n { result.push(bottom_right[i]); }

    result
}

fn assert_segments(result: &Vec<f32>, a: &Vec<f32>, b: &Vec<f32>, c: &Vec<f32>, d: &Vec<f32>) {
