    for i in 0..n { assert!(result[i] == a[i], "Mismatch in segment A at {}: {:?} vs {:?}", i, result[i], a[i]); }
    for i in 0..n { assert!(result[n + i] == b[i], "Mismatch in segment B at {}: {:?} vs {:?}", i, result[n + i], b[i]); }
    for i in 0..n { assert!(result[2 * n + i] == c[i], "Mismatch in segment C at {}: {:?} vs {:?}", i, result[2 * n + i], c[i]); }
    for i in 0..n { assert!(result[3 * n + i] == d[i], "Mismatch in segment D at {}: {:?} vs {:?}", i, result[3 * n + i], d[i]); }
}

fn main() {
