use std::vec::Vec;

fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Preconditions as runtime checks for testing purposes
    assert!(offset + count <= buffer.len());
    assert!(offset < buffer.len() || count == 0);

    let mut result = Vec::with_capacity(count);
    let mut i: usize = 0;
    while i < count {
        result.push(buffer[offset + i]);
        i += 1;
    }
    result
}

fn main() {
    // 1. Happy path: copy a middle slice
    let src1 = vec![1u8, 2, 3, 4, 5];
    let r1 = frombuffer(&src1, 3, 1);
    assert_eq!(r1.len(), 3);
    assert_eq!(r1, vec![2, 3, 4]);
    assert_eq!(r1, src1[1..1 + 3].to_vec());

    // 2. Copy entire buffer
    let src2 = vec![10u8, 20, 30, 40, 50];
    let r2 = frombuffer(&src2, src2.len(), 0);
    assert_eq!(r2.len(), src2.len());
    assert_eq!(r2, src2.clone());

    // 3. Copy last element (boundary where offset + count == len)
    let src3 = vec![7u8, 8, 9, 10, 11];
    let r3 = frombuffer(&src3, 1, src3.len() - 1);
    assert_eq!(r3.len(), 1);
    assert_eq!(r3, vec![11]);

    // 4. Zero-length copy from a valid starting position
    let src4 = vec![100u8, 101, 102, 103, 104];
    let r4 = frombuffer(&src4, 0, 2);
    assert_eq!(r4.len(), 0);
    assert!(r4.is_empty());

    // 5. Zero-length copy where starting position equals length (allowed)
    let src5 = vec![1u8, 2, 3];
    let r5 = frombuffer(&src5, 0, src5.len());
    assert_eq!(r5.len(), 0);
    assert!(r5.is_empty());

    // 6. Empty source array with zero-length copy (starting position equals length 0)
    let src6: Vec<u8> = vec![];
    let r6 = frombuffer(&src6, 0, 0);
    assert!(r6.is_empty());

    // 7. Larger array: copy a sizable middle slice
    let src7: Vec<u8> = (0u8..=200u8).collect(); // 201 elements: 0..=200
    let r7 = frombuffer(&src7, 50, 100);
    assert_eq!(r7.len(), 50);
    assert_eq!(r7, src7[100..150].to_vec());

    // 8. Boundary case offset + count == len with non-zero count
    let src8 = vec![9u8, 9, 9, 9, 9, 9, 9, 9, 9, 9];
    let r8 = frombuffer(&src8, 3, 7);
    assert_eq!(r8.len(), 3);
    assert_eq!(r8, src8[7..10].to_vec());

    // 9. Copy with repeated values and zeros
    let src9 = vec![0u8, 0, 5, 0, 5, 0];
    let r9 = frombuffer(&src9, 2, 1);
    assert_eq!(r9.len(), 2);
    assert_eq!(r9, vec![0, 5]);
