    let r6 = numpy_full_like(a6.clone(), f32::NEG_INFINITY);
    assert_eq!(r6.len(), a6.len());
    assert_all_equal(&r6, f32::NEG_INFINITY);

    // Test 7: Negative zero fill
    let a7 = vec![7.7, -8.8, 9.9, -10.1, 11.2, -12.3, 13.4, -14.5];
    let r7 = numpy_full_like(a7.clone(), -0.0);
    assert_eq!(r7.len(), a7.len());
    assert_all_equal(&r7, -0.0);
