use std::cmp::PartialEq;

fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut mat: Vec<Vec<f64>> = Vec::with_capacity(n);
    for i in 0..n {
        let mut row: Vec<f64> = Vec::with_capacity(n);
        for j in 0..n {
            let v = if i == j { 1.0 } else { 0.0 };
            row.push(v);
        }
        mat.push(row);
    }
    mat
}

fn is_identity(mat: &Vec<Vec<f64>>, n: usize) -> bool {
    if mat.len() != n { return false; }
    for i in 0..n {
        if mat[i].len() != n { return false; }
        for j in 0..n {
            let expected = if i == j { 1.0 } else { 0.0 };
            if mat[i][j] != expected { return false; }
        }
    }
    true
}

fn main() {
    // Test 1: n = 0 (empty matrix)
    let m0 = identity(0);
    assert!(is_identity(&m0, 0));

    // Test 2: n = 1 (single-element matrix)
    let m1 = identity(1);
    assert!(is_identity(&m1, 1));
    assert_eq!(m1.len(), 1);
    assert_eq!(m1[0].len(), 1);
    assert_eq!(m1[0][0], 1.0);

    // Test 3: n = 2 (small matrix)
    let m2 = identity(2);
    assert!(is_identity(&m2, 2));
    assert_eq!(m2[0][0], 1.0);
    assert_eq!(m2[0][1], 0.0);
    assert_eq!(m2[1][0], 0.0);
    assert_eq!(m2[1][1], 1.0);

    // Test 4: n = 3 (standard case)
    let m3 = identity(3);
    assert!(is_identity(&m3, 3));

    // Test 5: n = 5 (larger case)
    let m5 = identity(5);
    assert!(is_identity(&m5, 5));

    // Test 6: n = 7 (another larger case)
    let m7 = identity(7);
    assert!(is_identity(&m7, 7));

    // Test 7: n = 10 (boundary-style larger case)
    let m10 = identity(10);
    assert!(is_identity(&m10, 10));

    // Test 8: Spot-check off-diagonal zeros and diagonal ones for n = 4
    let m4 = identity(4);
    for i in 0..4 {
