use std::fmt::Debug;

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    assert!(!x.is_empty(), "x must be non-empty");
    assert!(!y.is_empty(), "y must be non-empty");
    let mut xx: Vec<Vec<f32>> = Vec::with_capacity(y.len());
    let mut yy: Vec<Vec<f32>> = Vec::with_capacity(y.len());
    for &yv in &y {
        let mut x_row: Vec<f32> = Vec::with_capacity(x.len());
        let mut y_row: Vec<f32> = Vec::with_capacity(x.len());
        for &xv in &x {
            x_row.push(xv);
            y_row.push(yv);
        }
        xx.push(x_row);
        yy.push(y_row);
    }
    (xx, yy)
}

fn assert_eq_vec<T: PartialEq + Debug>(a: &Vec<T>, b: &Vec<T>) {
    assert_eq!(a, b);
}

fn assert_meshgrid_properties(x: &Vec<f32>, y: &Vec<f32>, xx: &Vec<Vec<f32>>, yy: &Vec<Vec<f32>>) {
    // Shape checks
