    assert_eq!(yy.len(), y.len());
    for i in 0..y.len() {
        assert_eq!(xx[i].len(), x.len());
        assert_eq!(yy[i].len(), x.len());
    }
    // Element checks
    for i in 0..y.len() {
        for j in 0..x.len() {
            assert!((xx[i][j] == x[j]), "xx[{}][{}] mismatch", i, j);
