                    assert((d as int) > (kuz as int));
                    assert((kuz as int) == (k as int));
                    assert(!((j as int) <= (i as int) + (k as int)));
                    assert((if cond(i, j, k) { 1.0 } else { 0.0 }) == 0.0);
