fn assert_identity_property(res: &Vec<i32>, v: &Vec<i32>) {
    assert!(res.len() == v.len(), "Length mismatch: res.len()={}, v.len()={}", res.len(), v.len());
    for i in 0..res.len() {
        let r = res[i];
        let vi = v[i];
        assert!(r == 0, "res[{}] expected 0, found {}", i, r);
        assert!(r + vi == vi, "Left identity failed at {}: {} + {} != {}", i, r, vi, vi);
        assert!(vi + r == vi, "Right identity failed at {}: {} + {} != {}", i, vi, r, vi);
    }
}

