fn verify_concat(a: &Vec<f32>, b: &Vec<f32>, r: &Vec<f32>) {
    assert!(r.len() == a.len() + b.len());
    let mut i: usize = 0;
    while i < a.len() {
        assert!(r[i] == a[i]);
        i += 1;
    }
    let mut j: usize = 0;
    while j < b.len() {
        assert!(r[a.len() + j] == b[j]);
        j += 1;
    }
}

