    let b1: Vec<f32> = vec![];
    let a1c = a1.clone();
    let b1c = b1.clone();
    let r1 = numpy_append(a1, b1);
    verify_concat(&a1c, &b1c, &r1);

    // Test 2: first empty, second non-empty
    let a2: Vec<f32> = vec![];
    let b2: Vec<f32> = vec![1.0, 2.0, 3.0];
    let a2c = a2.clone();
    let b2c = b2.clone();
