use std::fmt::Debug;

fn copyto<T: Copy>(mut dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    assert_eq!(dst.len(), src.len());
    assert_eq!(dst.len(), mask.len());
    for i in 0..dst.len() {
        if mask[i] {
            dst[i] = src[i];
        }
    }
    dst
}

fn assert_vec_eq<T: PartialEq + Debug>(a: Vec<T>, b: Vec<T>) {
    assert_eq!(a, b);
}

fn main() {
    // 1) Edge case: empty inputs
    let dst: Vec<i32> = vec![];
    let src: Vec<i32> = vec![];
    let mask: Vec<bool> = vec![];
    let result = copyto(dst, src, mask);
    assert_eq!(result.len(), 0);

    // 2) Single element, mask = false
    let result = copyto(vec![5], vec![9], vec![false]);
    assert_vec_eq(result, vec![5]);

    // 3) Single element, mask = true
    let result = copyto(vec![5], vec![9], vec![true]);
    assert_vec_eq(result, vec![9]);

    // 4) Mixed mask on integers
    let result = copyto(
        vec![1, 2, 3, 4, 5],
        vec![9, 8, 7, 6, 5],
        vec![false, true, false, true, false],
    );
    assert_vec_eq(result, vec![1, 8, 3, 6, 5]);

    // 5) All mask entries false (should equal first array)
    let result = copyto(vec![10, 20, 30], vec![100, 200, 300], vec![false, false, false]);
    assert_vec_eq(result, vec![10, 20, 30]);

    // 6) All mask entries true (should equal second array)
    let result = copyto(vec![10, 20, 30], vec![100, 200, 300], vec![true, true, true]);
    assert_vec_eq(result, vec![100, 200, 300]);

    // 7) Different copyable type: chars
    let result = copyto(
        vec!['a', 'b', 'c', 'd'],
        vec!['x', 'y', 'z', 'w'],
        vec![true, false, true, false],
    );
    assert_vec_eq(result, vec!['x', 'b', 'z', 'd']);

    // 8) Copyable boolean elements
    let result = copyto(
        vec![true, false, true],
        vec![false, false, false],
        vec![false, true, true],
    );
    assert_vec_eq(result, vec![true, false, false]);
}

