use std::fmt::Debug;

#[derive(Debug, PartialEq)]
pub enum ExpandedVector<T> {
    RowVector(Vec<T>),
    ColumnVector(Vec<T>),
}

fn expand_dims<T>(a: Vec<T>, axis: usize) -> ExpandedVector<T> {
    // Precondition: axis <= 1
    assert!(axis <= 1, "axis must be 0 or 1");
    if axis == 0 {
        ExpandedVector::RowVector(a)
    } else {
        ExpandedVector::ColumnVector(a)
    }
}

fn assert_row_eq<T: PartialEq + Debug>(out: ExpandedVector<T>, expected: &Vec<T>) {
    match out {
        ExpandedVector::RowVector(v) => assert_eq!(v, *expected),
        ExpandedVector::ColumnVector(_) => panic!("Expected RowVector, got ColumnVector"),
    }
}

fn assert_col_eq<T: PartialEq + Debug>(out: ExpandedVector<T>, expected: &Vec<T>) {
    match out {
        ExpandedVector::ColumnVector(v) => assert_eq!(v, *expected),
        ExpandedVector::RowVector(_) => panic!("Expected ColumnVector, got RowVector"),
    }
}

fn main() {
    // 1) Empty vector, axis = 0 -> RowVector
    let v0: Vec<i32> = vec![];
    let out0 = expand_dims(v0.clone(), 0);
    assert_row_eq(out0, &v0);

    // 2) Empty vector, axis = 1 -> ColumnVector
    let v1: Vec<i32> = vec![];
    let out1 = expand_dims(v1.clone(), 1);
    assert_col_eq(out1, &v1);

    // 3) Single element, axis = 0 -> RowVector
    let v2 = vec![42];
    let out2 = expand_dims(v2.clone(), 0);
    assert_row_eq(out2, &v2);

    // 4) Single element, axis = 1 -> ColumnVector
    let v3 = vec![7];
    let out3 = expand_dims(v3.clone(), 1);
    assert_col_eq(out3, &v3);

    // 5) Multiple elements, axis = 0 -> RowVector
    let v4 = vec![1, 2, 3, 4, 5];
    let out4 = expand_dims(v4.clone(), 0);
    assert_row_eq(out4, &v4);

    // 6) Multiple elements, axis = 1 -> ColumnVector
    let v5 = vec![10, 20, 30];
    let out5 = expand_dims(v5.clone(), 1);
    assert_col_eq(out5, &v5);

    // 7) Strings, axis = 1 -> ColumnVector
    let v6 = vec![String::from("a"), String::from("b"), String::from("c")];
    let out6 = expand_dims(v6.clone(), 1);
    assert_col_eq(out6, &v6);

    // 8) Strings, axis = 0 -> RowVector (boundary axis=0)
    let v7 = vec![String::from("row"), String::from("vector")];
    let out7 = expand_dims(v7.clone(), 0);
    assert_row_eq(out7, &v7);
}

