use std::f32;

fn numpy_flip(m: Vec<f32>) -> Vec<f32> {
    let n = m.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);
    let mut i: usize = 0;
    while i < n {
        let index = n - 1 - i;
        result.push(m[index]);
        i += 1;
    }
    result
}

fn main() {
    // Test 1: Empty vector
    let m1: Vec<f32> = vec![];
    let r1 = numpy_flip(m1.clone());
    assert_eq!(r1, vec![]);

    // Test 2: Single element
    let m2: Vec<f32> = vec![3.14];
    let r2 = numpy_flip(m2.clone());
    assert_eq!(r2, vec![3.14]);

    // Test 3: Two elements
    let m3: Vec<f32> = vec![1.0, 2.0];
    let r3 = numpy_flip(m3.clone());
    assert_eq!(r3, vec![2.0, 1.0]);

    // Test 4: Even number of elements
    let m4: Vec<f32> = vec![1.0, 2.0, 3.0, 4.0];
    let r4 = numpy_flip(m4.clone());
    assert_eq!(r4, vec![4.0, 3.0, 2.0, 1.0]);

    // Test 5: Odd number of elements including negatives and zero
    let m5: Vec<f32> = vec![-1.5, 0.0, 2.5];
    let r5 = numpy_flip(m5.clone());
    assert_eq!(r5, vec![2.5, 0.0, -1.5]);

    // Test 6: Duplicates
    let m6: Vec<f32> = vec![5.5, 5.5, 5.5];
    let r6 = numpy_flip(m6.clone());
    assert_eq!(r6, vec![5.5, 5.5, 5.5]);

    // Test 7: Boundary float values
    let m7: Vec<f32> = vec![f32::MIN, 0.0, f32::MAX];
    let r7 = numpy_flip(m7.clone());
    assert_eq!(r7, vec![f32::MAX, 0.0, f32::MIN]);

    // Test 8: Infinity values
    let m8: Vec<f32> = vec![f32::INFINITY, 1.0, f32::NEG_INFINITY];
    let r8 = numpy_flip(m8.clone());
    assert_eq!(r8, vec![f32::NEG_INFINITY, 1.0, f32::INFINITY]);

    // Test 9: Larger input
    let m9: Vec<f32> = (0..100).map(|x| x as f32).collect();
    let mut expected9: Vec<f32> = m9.iter().rev().cloned().collect();
    let r9 = numpy_flip(m9.clone());
    assert_eq!(r9, expected9);

    println!("All tests passed.");
}

