    let v = vec![42.0f32];
    let r = flipud(v.clone());
    assert_eq!(r, vec![42.0]);
    assert_eq!(r.len(), v.len());

    // Test 3: Two elements
    let v = vec![1.5f32, -2.5f32];
    let r = flipud(v.clone());
    assert_eq!(r, vec![-2.5, 1.5]);
    assert_eq!(r.len(), v.len());

    // Test 4: Multiple elements with duplicates and zero
    let v = vec![0.0f32, 1.0f32, 1.0f32, 2.0f32];
    let r = flipud(v.clone());
