fn hstack(a: Vec<f32>, b: Vec<f32>) -> Vec<f32> {
    let mut res: Vec<f32> = Vec::with_capacity(a.len() + b.len());
    for &x in a.iter() {
        res.push(x);
    }
    for &x in b.iter() {
        res.push(x);
    }
    res
}

fn main() {
    // Test 1: Both empty
    let a: Vec<f32> = vec![];
    let b: Vec<f32> = vec![];
    let r = hstack(a, b);
    assert_eq!(r.len(), 0);
    assert!(r.is_empty());

    // Test 2: Second empty, first non-empty
    let a = vec![1.0f32, 2.5, -3.0];
    let b: Vec<f32> = vec![];
    let r = hstack(a.clone(), b);
    assert_eq!(r.len(), 3);
    assert_eq!(r, a);

    // Test 3: First empty, second non-empty
    let a: Vec<f32> = vec![];
    let b = vec![-1.2f32, 0.0, 3.3];
    let r = hstack(a, b.clone());
    assert_eq!(r.len(), 3);
    assert_eq!(r, b);

    // Test 4: Single element in each
    let a = vec![7.0f32];
    let b = vec![8.0f32];
    let r = hstack(a.clone(), b.clone());
    assert_eq!(r.len(), 2);
    assert_eq!(r, vec![7.0f32, 8.0f32]);

    // Test 5: General case with multiple elements
    let a = vec![1.0f32, 4.0];
    let b = vec![5.0f32, 6.0, 7.0];
    let r = hstack(a.clone(), b.clone());
    assert_eq!(r.len(), a.len() + b.len());
    assert_eq!(r, vec![1.0f32, 4.0, 5.0, 6.0, 7.0]);

    // Test 6: Duplicates
    let a = vec![1.1f32, 1.1, 1.1];
    let b = vec![1.1f32];
    let r = hstack(a.clone(), b.clone());
    assert_eq!(r.len(), 4);
    assert_eq!(r, vec![1.1f32, 1.1, 1.1, 1.1]);

    // Test 7: Large concatenation
    let a = vec![0.5f32; 1000];
    let b = vec![-0.5f32; 500];
    let r = hstack(a.clone(), b.clone());
    assert_eq!(r.len(), 1500);
    assert_eq!(r[0], 0.5f32);
    assert_eq!(r[999], 0.5f32);
    assert_eq!(r[1000], -0.5f32);
    assert_eq!(r[1499], -0.5f32);

    // Test 8: Boundary-like large magnitudes (avoid NaN)
    let a = vec![f32::MAX, -f32::MAX];
