    let r = hstack(a.clone(), b.clone());
    assert_eq!(r.len(), a.len() + b.len());
    assert_eq!(r[0], f32::MAX);
    assert_eq!(r[1], -f32::MAX);
    assert_eq!(r[2], 1.0f32);
    assert_eq!(r[3], -1.0f32);
    assert_eq!(r[4], 0.0f32);
