use std::fmt::Debug;

fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Precondition expected by the specification: idx <= arr.len()
    assert!(idx <= arr.len());
    let mut v = arr;
    v.insert(idx, value);
    v
}

fn assert_insert_properties<T: PartialEq + Debug + Clone>(original: &Vec<T>, idx: usize, value: T, result: &Vec<T>) {
    // Length check
    assert_eq!(result.len(), original.len() + 1);

    // Elements before idx remain unchanged
    for i in 0..idx {
        assert_eq!(result[i], original[i], "Mismatch at position {} before idx", i);
    }

    // Inserted value at idx
    assert_eq!(result[idx], value, "Inserted value mismatch at idx");

    // Elements after idx shifted right by 1
    for i in (idx + 1)..result.len() {
        assert_eq!(result[i], original[i - 1], "Mismatch at shifted position {}", i);
    }

    // Equivalence formulation: for every j in original
    for j in 0..original.len() {
        if j < idx {
            assert_eq!(result[j], original[j], "Equivalence check failed at j={}" , j);
        } else {
            assert_eq!(result[j + 1], original[j], "Equivalence check failed at shifted j={}", j);
        }
    }
}

#[derive(Clone, PartialEq, Debug)]
struct Point { x: i32, y: i32 }

fn main() {
    // 1) Empty vector, insert at 0 (boundary, satisfies idx <= len)
    let arr1: Vec<i32> = vec![];
    let idx1 = 0usize;
    let val1 = 42;
    let result1 = numpy_insert(arr1.clone(), idx1, val1);
    assert_insert_properties(&arr1, idx1, val1, &result1);

    // 2) Single-element vector, insert at beginning (idx = 0)
    let arr2 = vec![10];
    let idx2 = 0usize;
    let val2 = -1;
    let result2 = numpy_insert(arr2.clone(), idx2, val2);
    assert_insert_properties(&arr2, idx2, val2, &result2);

    // 3) Single-element vector, insert at end (idx = len)
    let arr3 = vec![10];
    let idx3 = arr3.len();
    let val3 = 99;
    let result3 = numpy_insert(arr3.clone(), idx3, val3);
    assert_insert_properties(&arr3, idx3, val3, &result3);

    // 4) Multiple elements, insert in the middle
    let arr4 = vec![1, 2, 3, 4, 5];
    let idx4 = 2usize; // between 2 and 3
    let val4 = 100;
    let result4 = numpy_insert(arr4.clone(), idx4, val4);
    assert_insert_properties(&arr4, idx4, val4, &result4);

    // 5) Insert at beginning of non-empty vector
