description:
Implement two functions that expose the Euler–Mascheroni constant using 64-bit floating point arithmetic. There are no inputs and no preconditions. The first function must return exactly the numeric value 0.5772156649015329. The second function must return the same value by delegating to the first function (i.e., it obtains the constant from the first function and returns it). Postconditions: both functions return exactly 0.5772156649015329.
fn euler_gamma_const() -> (result: f64)
fn euler_gamma() -> (result: f64)

meta.test_cases:
use std::f64;

fn euler_gamma_const() -> f64 {
    0.5772156649015329
}

fn euler_gamma() -> f64 {
    let gamma = euler_gamma_const();
    gamma
}

fn main() {
    // Happy Path: direct equality checks
    assert_eq!(euler_gamma_const(), 0.5772156649015329);
    assert_eq!(euler_gamma(), 0.5772156649015329);

    // Equality between the two functions
    assert!(euler_gamma() == euler_gamma_const());

    // Boundary/precision checks around the constant
    assert!((euler_gamma() - 0.5772156649015329).abs() < f64::EPSILON);

    // Range sanity check
    assert!(euler_gamma() >= 0.5772 && euler_gamma() < 0.5773);

    // Consistency across multiple calls
    let a = euler_gamma();
    let b = euler_gamma();
    assert_eq!(a, b);

    // Aggregated value check
    let sum = euler_gamma() + euler_gamma_const();
    assert_eq!(sum, 2.0 * 0.5772156649015329);
}

