        // Case 4: Both provided, different kinds ('i' vs 'f'); choose scalar max
        let arrays4 = vec![DType::Int32, DType::Int16];
        let scalars4 = vec![DType::Float32];
        let r4 = find_common_type(arrays4, scalars4);
        assert(r4 == Some(DType::Float32));

        // Case 5: Different kinds ('u' vs 'i'); choose scalar max
        let arrays5 = vec![DType::UInt16, DType::UInt32];
        let scalars5 = vec![DType::Int64];
        let r5 = find_common_type(arrays5, scalars5);
