        DTypeKind::Integral => match dtype {
            NumpyDType::Int8 | NumpyDType::Int16 | NumpyDType::Int32 | NumpyDType::Int64
            | NumpyDType::UInt8 | NumpyDType::UInt16 | NumpyDType::UInt32 | NumpyDType::UInt64 => true,
            _ => false,
        },
        DTypeKind::RealFloating => match dtype {
            NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64 => true,
            _ => false,
        },
        DTypeKind::ComplexFloating => match dtype {
            NumpyDType::Complex64 | NumpyDType::Complex128 => true,
            _ => false,
        },
        DTypeKind::Numeric => match dtype {
            NumpyDType::Bool
            | NumpyDType::Int8 | NumpyDType::Int16 | NumpyDType::Int32 | NumpyDType::Int64
            | NumpyDType::UInt8 | NumpyDType::UInt16 | NumpyDType::UInt32 | NumpyDType::UInt64
            | NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64
            | NumpyDType::Complex64 | NumpyDType::Complex128 => true,
        },
    }
}

fn main() {
    // Bool kind
    assert!(numpy_isdtype(NumpyDType::Bool, DTypeKind::Bool));
    assert!(!numpy_isdtype(NumpyDType::Int32, DTypeKind::Bool));

    // SignedInteger kind
    assert!(numpy_isdtype(NumpyDType::Int32, DTypeKind::SignedInteger));
    assert!(!numpy_isdtype(NumpyDType::UInt8, DTypeKind::SignedInteger));
    assert!(!numpy_isdtype(NumpyDType::Float64, DTypeKind::SignedInteger));

    // UnsignedInteger kind
    assert!(numpy_isdtype(NumpyDType::UInt16, DTypeKind::UnsignedInteger));
    assert!(!numpy_isdtype(NumpyDType::Int8, DTypeKind::UnsignedInteger));

    // Integral kind (union of signed and unsigned integers)
    assert!(numpy_isdtype(NumpyDType::Int64, DTypeKind::Integral));
    assert!(numpy_isdtype(NumpyDType::UInt32, DTypeKind::Integral));
    assert!(!numpy_isdtype(NumpyDType::Float32, DTypeKind::Integral));

    // RealFloating kind
    assert!(numpy_isdtype(NumpyDType::Float32, DTypeKind::RealFloating));
    assert!(!numpy_isdtype(NumpyDType::Int16, DTypeKind::RealFloating));

    // ComplexFloating kind
    assert!(numpy_isdtype(NumpyDType::Complex128, DTypeKind::ComplexFloating));
    assert!(!numpy_isdtype(NumpyDType::Float32, DTypeKind::ComplexFloating));

    // Numeric kind (union of all numeric-like types including Bool)
    assert!(numpy_isdtype(NumpyDType::Bool, DTypeKind::Numeric));
    assert!(numpy_isdtype(NumpyDType::Int64, DTypeKind::Numeric));
    assert!(numpy_isdtype(NumpyDType::UInt64, DTypeKind::Numeric));
    assert!(numpy_isdtype(NumpyDType::Float64, DTypeKind::Numeric));
    assert!(numpy_isdtype(NumpyDType::Complex64, DTypeKind::Numeric));
}

