use std::fmt;

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
enum NumpyTypeClass {
    IntegerType,
    FloatingType,
    ComplexType,
    BooleanType,
    ScalarType,
    NumberType,
    InexactType,
    Int8Type,
    Int16Type,
    Int32Type,
    Int64Type,
    UInt8Type,
    UInt16Type,
    UInt32Type,
    UInt64Type,
    Float32Type,
    Float64Type,
    Complex64Type,
    Complex128Type,
    ObjectType,
}

fn issubclass_(a: NumpyTypeClass, b: NumpyTypeClass) -> bool {
    if a == b { return true; }
    match (a, b) {
        (NumpyTypeClass::Int8Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::Int16Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::Int32Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::Int64Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt8Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt16Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt32Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt64Type, NumpyTypeClass::IntegerType) => true,

        (NumpyTypeClass::Float32Type, NumpyTypeClass::FloatingType) => true,
        (NumpyTypeClass::Float64Type, NumpyTypeClass::FloatingType) => true,

        (NumpyTypeClass::Complex64Type, NumpyTypeClass::ComplexType) => true,
        (NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType) => true,

        (NumpyTypeClass::IntegerType, NumpyTypeClass::NumberType) => true,

        (NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType) => true,
        (NumpyTypeClass::FloatingType, NumpyTypeClass::NumberType) => true,

        (NumpyTypeClass::ComplexType, NumpyTypeClass::InexactType) => true,
        (NumpyTypeClass::ComplexType, NumpyTypeClass::NumberType) => true,

        (NumpyTypeClass::NumberType, NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::BooleanType, NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::IntegerType, NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::FloatingType, NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::ComplexType, NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::InexactType, NumpyTypeClass::ScalarType) => true,

        _ => false,
    }
}

fn main() {
    // Equality (reflexivity)
    assert!(issubclass_(NumpyTypeClass::Int16Type, NumpyTypeClass::Int16Type));

    // Integer leaves to IntegerType
    assert!(issubclass_(NumpyTypeClass::UInt64Type, NumpyTypeClass::IntegerType));

    // Floating leaves to FloatingType
    assert!(issubclass_(NumpyTypeClass::Float64Type, NumpyTypeClass::FloatingType));

    // Complex leaves to ComplexType
    assert!(issubclass_(NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType));

    // Mid-level and scalar relations
    assert!(issubclass_(NumpyTypeClass::NumberType, NumpyTypeClass::ScalarType));
    assert!(issubclass_(NumpyTypeClass::BooleanType, NumpyTypeClass::ScalarType));
    assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType));

    // Negative: no transitive closure (direct edges only)
    assert!(!issubclass_(NumpyTypeClass::Int32Type, NumpyTypeClass::FloatingType));
    assert!(!issubclass_(NumpyTypeClass::Complex64Type, NumpyTypeClass::NumberType));

    // Negative: unrelated pair
    assert!(!issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ScalarType));
}

use std::fmt::Debug;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Int8,
    Int16,
    Int32,
    Int64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

fn dtype_size(dt: NumpyDType) -> u32 {
    match dt {
        NumpyDType::UInt8 => 8,
        NumpyDType::UInt16 => 16,
        NumpyDType::UInt32 => 32,
        NumpyDType::UInt64 => 64,
        NumpyDType::Int8 => 8,
        NumpyDType::Int16 => 16,
        NumpyDType::Int32 => 32,
        NumpyDType::Int64 => 64,
        NumpyDType::Float16 => 16,
        NumpyDType::Float32 => 32,
        NumpyDType::Float64 => 64,
        NumpyDType::Complex64 => 64,
        NumpyDType::Complex128 => 128,
    }
}

fn dtype_kind_order(dt: NumpyDType) -> u32 {
    match dt {
        NumpyDType::UInt8 | NumpyDType::UInt16 | NumpyDType::UInt32 | NumpyDType::UInt64 => 0,
        NumpyDType::Int8 | NumpyDType::Int16 | NumpyDType::Int32 | NumpyDType::Int64 => 1,
        NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64 => 2,
        NumpyDType::Complex64 | NumpyDType::Complex128 => 3,
    }
}

fn can_represent_value(dt: NumpyDType, value: i128) -> bool {
    match dt {
        NumpyDType::UInt8 => 0 <= value && value <= 255,
        NumpyDType::UInt16 => 0 <= value && value <= 65_535,
        NumpyDType::UInt32 => 0 <= value && value <= 4_294_967_295,
        NumpyDType::UInt64 => 0 <= value && value <= 18_446_744_073_709_551_615,
        NumpyDType::Int8 => -128 <= value && value <= 127,
        NumpyDType::Int16 => -32_768 <= value && value <= 32_767,
        NumpyDType::Int32 => -2_147_483_648 <= value && value <= 2_147_483_647,
        NumpyDType::Int64 => -9_223_372_036_854_775_808 <= value && value <= 9_223_372_036_854_775_807,
        NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64 | NumpyDType::Complex64 | NumpyDType::Complex128 => true,
    }
}

fn min_scalar_type(value: i8) -> NumpyDType {
    if value >= 0 { NumpyDType::UInt8 } else { NumpyDType::Int8 }
}

const ALL_DTYPES: [NumpyDType; 13] = [
    NumpyDType::UInt8,
    NumpyDType::UInt16,
    NumpyDType::UInt32,
    NumpyDType::UInt64,
    NumpyDType::Int8,
    NumpyDType::Int16,
    NumpyDType::Int32,
    NumpyDType::Int64,
    NumpyDType::Float16,
    NumpyDType::Float32,
    NumpyDType::Float64,
    NumpyDType::Complex64,
    NumpyDType::Complex128,
];

fn check_ensures(value: i8, result: NumpyDType) {
    let vi = value as i128;
    // 1) result can represent the value
    assert!(can_represent_value(result, vi));
    // 2) no strictly smaller dtype can represent the value
    for dt in ALL_DTYPES.iter().copied() {
        if dtype_size(dt) < dtype_size(result) {
            assert!(!can_represent_value(dt, vi));
        }
    }
    // 3) among equal-size representable types, result has minimal kind order
    for dt in ALL_DTYPES.iter().copied() {
        if dtype_size(dt) == dtype_size(result) && can_represent_value(dt, vi) {
            assert!(dtype_kind_order(result) <= dtype_kind_order(dt));
        }
    }
}

fn main() {
    // Happy path and boundary cases
    let cases: [i8; 8] = [0, 1, 42, 127, -1, -42, -127, -128];
    for &c in &cases {
        let r = min_scalar_type(c);
        // Expected mapping based on criteria
        if c >= 0 {
            assert_eq!(r, NumpyDType::UInt8);
        } else {
            assert_eq!(r, NumpyDType::Int8);
        }
        check_ensures(c, r);
    }

    // Additional spot checks
    let r_zero = min_scalar_type(0);
    assert_eq!(r_zero, NumpyDType::UInt8);
    check_ensures(0, r_zero);

    let r_min = min_scalar_type(i8::MIN);
    assert_eq!(r_min, NumpyDType::Int8);
    check_ensures(i8::MIN, r_min);

    let r_max = min_scalar_type(i8::MAX);
    assert_eq!(r_max, NumpyDType::UInt8);
    check_ensures(i8::MAX, r_max);
}

