        NumpyOperand::Scalar(NumpyDType::Int8),
        NumpyOperand::Scalar(NumpyDType::Float64),
        NumpyOperand::Array(NumpyDType::Complex64, vec![0]),
    ];
    let r4 = result_type(ops4.clone());
    assert!(r4 == NumpyDType::Complex64);
    // Verify pairwise promotion bound
    for i in 0..ops4.len() {
        for j in 0..ops4.len() {
            let ti = exec_operand_type(&ops4[i]);
            let tj = exec_operand_type(&ops4[j]);
