use vstd::prelude::*;

verus! {
    fn argmax(arr: &Vec<i8>) -> (result: usize)
        requires arr.len() > 0,
        ensures 
            result < arr.len(),
            forall|i: int| 0 <= i && i < arr.len() ==> arr@[i] <= arr@[result as int],
            forall|i: int| 0 <= i && i < result as int ==> arr@[i] < arr@[result as int],
            forall|i: int| (result as int) < i && i < arr.len() ==> arr@[i] <= arr@[result as int],
    {
        let mut max_idx: usize = 0;
        let mut i: usize = 1;
        while i < arr.len()
            invariant
                max_idx < arr.len(),
                i <= arr.len(),
                forall|j: int| 0 <= j && j < i ==> arr@[j] <= arr@[max_idx as int],
                forall|j: int| 0 <= j && j < max_idx as int ==> arr@[j] < arr@[max_idx as int],
            decreases arr.len() - i
        {
            if arr[i] > arr[max_idx] {
                max_idx = i;
            }
            i = i + 1;
        }
        max_idx
    }
}

fn check_leftmost_max(arr: &Vec<i8>, idx: usize) {
    assert!(arr.len() > 0, "Precondition: array must be non-empty");
    assert!(idx < arr.len(), "Index must be within bounds");
    // All elements are <= arr[idx]
    for i in 0..arr.len() {
        assert!(arr[i] <= arr[idx], "Value at index {} (={}) should be <= value at result {} (={})", i, arr[i], idx, arr[idx]);
    }
    // All elements before idx are strictly < arr[idx]
    for i in 0..idx {
        assert!(arr[i] < arr[idx], "Value at index {} (={}) should be < value at result {} (={})", i, arr[i], idx, arr[idx]);
    }
}

fn main() {
    // Note: Empty arrays are not tested because the function requires the array to be non-empty.

    // 1) Single-element
    let a1: Vec<i8> = vec![7i8];
    let r1 = argmax(&a1);
    assert_eq!(r1, 0);
    check_leftmost_max(&a1, r1);

    // 2) All equal values
    let a2: Vec<i8> = vec![3i8, 3i8, 3i8];
    let r2 = argmax(&a2);
    assert_eq!(r2, 0);
    check_leftmost_max(&a2, r2);

    // 3) Strictly increasing values
    let a3: Vec<i8> = vec![-128i8, -1i8, 0i8, 5i8, 10i8];
    let r3 = argmax(&a3);
    assert_eq!(r3, 4);
    check_leftmost_max(&a3, r3);

    // 4) Strictly decreasing values
    let a4: Vec<i8> = vec![10i8, 5i8, 0i8, -1i8, -128i8];
    let r4 = argmax(&a4);
    assert_eq!(r4, 0);
    check_leftmost_max(&a4, r4);

    // 5) Multiple maxima, choose leftmost
    let a5: Vec<i8> = vec![-5i8, 2i8, 2i8, 1i8];
    let r5 = argmax(&a5);
    assert_eq!(r5, 1);
    check_leftmost_max(&a5, r5);

    // 6) Mixed negatives and zeros with repeated maximum
    let a6: Vec<i8> = vec![-10i8, 0i8, -10i8, 0i8, -1i8];
    let r6 = argmax(&a6);
    assert_eq!(r6, 1);
    check_leftmost_max(&a6, r6);

    // 7) Maximum in the middle with duplicates
    let a7: Vec<i8> = vec![-5i8, -2i8, -2i8, -3i8];
    let r7 = argmax(&a7);
    assert_eq!(r7, 1);
    check_leftmost_max(&a7, r7);

    // 8) i8 boundaries
    let a8: Vec<i8> = vec![-128i8, 127i8, 127i8, 126i8];
    let r8 = argmax(&a8);
    assert_eq!(r8, 1);
    check_leftmost_max(&a8, r8);

    // 9) Another with last equal to earlier maximum
    let a9: Vec<i8> = vec![1i8, 3i8, 2i8, 3i8];
    let r9 = argmax(&a9);
    assert_eq!(r9, 1);
    check_leftmost_max(&a9, r9);
}

