use std::f32;

fn main() {
    // Helper to check the diagflat property for a given input
    fn check(v: Vec<f32>) {
        let n = v.len();
        let m = diagflat(v.clone());
        assert_eq!(m.len(), n, "Matrix row count must equal input length");
        for i in 0..n {
            assert_eq!(m[i].len(), n, "Each row length must equal input length");
            for j in 0..n {
                if i == j {
                    assert!(m[i][j] == v[i], "Diagonal entry mismatch at ({}, {})", i, j);
                } else {
                    assert!(m[i][j] == 0.0f32, "Off-diagonal must be zero at ({}, {})", i, j);
                }
            }
        }
    }

    // Test 1: Single element (boundary of non-empty)
    check(vec![5.0f32]);

    // Test 2: Two elements with positive and negative values
    check(vec![1.5f32, -2.0f32]);

    // Test 3: Includes zeros
    check(vec![0.0f32, 0.0f32, 3.0f32]);

    // Test 4: Mixed negative and fractional values
    check(vec![-1.0f32, 0.0f32, 2.5f32, -0.75f32]);

    // Test 5: Small fractional values
    check(vec![0.1f32, 0.2f32, 0.3f32, 0.4f32, 0.5f32]);

    // Test 6: Large magnitude values
