use std::cmp::Ordering;

fn create_row(n: u8) -> Vec<u8> {
    let mut row = Vec::with_capacity(n as usize);
    let mut i: u8 = 0;
    while i < n {
        row.push(i);
        i = i.wrapping_add(1); // safe because loop guard prevents wrapping past n
    }
    row
}

fn indices(n: u8) -> Vec<Vec<u8>> {
    vec![create_row(n)]
}

fn is_strictly_increasing(xs: &[u8]) -> bool {
    if xs.len() <= 1 { return true; }
    for i in 1..xs.len() {
        if xs[i - 1] >= xs[i] { return false; }
    }
    true
}

fn main() {
    // Test 1: n = 0 (empty row)
    let g0 = indices(0);
    assert_eq!(g0.len(), 1);
    assert_eq!(g0[0].len(), 0);
    assert!(is_strictly_increasing(&g0[0]));

    // Test 2: n = 1 (single element)
    let g1 = indices(1);
    assert_eq!(g1.len(), 1);
