use std::fmt::Debug;

fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    assert_eq!(arr.len(), mask.len(), "Precondition violated: lengths must match");
    assert!(!vals.is_empty(), "Precondition violated: replacement values must be non-empty");
    let mut result: Vec<f32> = Vec::with_capacity(arr.len());
    let mut val_idx: usize = 0;
    for i in 0..arr.len() {
        if mask[i] {
            result.push(vals[val_idx]);
            val_idx = if val_idx + 1 == vals.len() { 0 } else { val_idx + 1 };
        } else {
            result.push(arr[i]);
        }
    }
    result
}

fn assert_vec_eq<T: PartialEq + Debug>(a: Vec<T>, b: Vec<T>) {
    assert!(a == b, "Left: {:?}\nRight: {:?}", a, b);
}

fn main() {
    // Test 1: Empty input arrays, non-empty replacement
    let arr1: Vec<f32> = vec![];
    let mask1: Vec<bool> = vec![];
    let vals1: Vec<f32> = vec![5.0];
    let out1 = place(arr1.clone(), mask1.clone(), vals1.clone());
    assert_vec_eq(out1, vec![]);

    // Test 2: Single element, mask is false -> copy original
    let arr2 = vec![7.0f32];
    let mask2 = vec![false];
    let vals2 = vec![1.0f32, 2.0f32];
    let out2 = place(arr2.clone(), mask2.clone(), vals2.clone());
    assert_vec_eq(out2, vec![7.0]);

    // Test 3: Single element, mask is true -> use replacement
    let arr3 = vec![7.0f32];
    let mask3 = vec![true];
    let vals3 = vec![3.5f32];
    let out3 = place(arr3.clone(), mask3.clone(), vals3.clone());
    assert_vec_eq(out3, vec![3.5]);

    // Test 4: All mask entries false -> output equals input
    let arr4 = vec![1.0f32, 2.0, 3.0];
    let mask4 = vec![false, false, false];
    let vals4 = vec![9.9f32];
    let out4 = place(arr4.clone(), mask4.clone(), vals4.clone());
    assert_vec_eq(out4, arr4.clone());

    // Test 5: All mask entries true with cycling through replacement values
    let arr5 = vec![0.0f32, 0.0, 0.0, 0.0, 0.0];
    let mask5 = vec![true, true, true, true, true];
    let vals5 = vec![1.0f32, 2.0];
    let out5 = place(arr5.clone(), mask5.clone(), vals5.clone());
    assert_vec_eq(out5, vec![1.0, 2.0, 1.0, 2.0, 1.0]);

    // Test 6: Mixed mask with cycling and preserved originals
    let arr6 = vec![10.0f32, 20.0, 30.0, 40.0, 50.0, 60.0];
    let mask6 = vec![false, true, false, true, true, false];
    let vals6 = vec![100.0f32, 200.0, 300.0];
    let out6 = place(arr6.clone(), mask6.clone(), vals6.clone());
    assert_vec_eq(out6, vec![10.0, 100.0, 30.0, 200.0, 300.0, 60.0]);

    // Test 7: Negative and zero values
    let arr7 = vec![-1.0f32, 0.0, 3.14];
    let mask7 = vec![true, false, true];
    let vals7 = vec![-2.5f32];
    let out7 = place(arr7.clone(), mask7.clone(), vals7.clone());
    assert_vec_eq(out7, vec![-2.5, 0.0, -2.5]);

    // Test 8: More replacements than true positions
    let arr8 = vec![1.0f32, 2.0, 3.0];
    let mask8 = vec![true, false, false];
    let vals8 = vec![8.0f32, 9.0, 10.0, 11.0];
    let out8 = place(arr8.clone(), mask8.clone(), vals8.clone());
    assert_vec_eq(out8, vec![8.0, 2.0, 3.0]);

    // Test 9: Alternating mask with single replacement value
    let arr9 = vec![5.5f32, 6.6, 7.7, 8.8];
    let mask9 = vec![true, false, true, false];
    let vals9 = vec![9.9f32];
    let out9 = place(arr9.clone(), mask9.clone(), vals9.clone());
    assert_vec_eq(out9, vec![9.9, 6.6, 9.9, 8.8]);

