    let mut bb = b;
    r.append(&mut bb);
    r
}

fn assert_eq_vec<T: PartialEq + Debug>(a: Vec<T>, b: Vec<T>) {
    assert_eq!(a, b);
}

fn main() {
    // Test 1: Both inputs empty
    let v1: Vec<i8> = vec![];
    let v2: Vec<i8> = vec![];
    let res = r_(v1.clone(), v2.clone());
    assert_eq!(res.len(), 0);
    assert_eq_vec(res, vec![]);

    // Test 2: First empty, second non-empty
    let v1: Vec<i8> = vec![];
    let v2: Vec<i8> = vec![1, 2, 3];
    let res = r_(v1.clone(), v2.clone());
    assert_eq!(res.len(), v1.len() + v2.len());
    assert_eq_vec(res, vec![1, 2, 3]);

    // Test 3: First non-empty, second empty
    let v1: Vec<i8> = vec![4, 5];
    let v2: Vec<i8> = vec![];
    let res = r_(v1.clone(), v2.clone());
    assert_eq!(res.len(), v1.len() + v2.len());
    assert_eq_vec(res, vec![4, 5]);

    // Test 4: Both non-empty, typical case
    let v1: Vec<i8> = vec![1, 2];
    let v2: Vec<i8> = vec![3, 4];
    let res = r_(v1.clone(), v2.clone());
    assert_eq!(res.len(), v1.len() + v2.len());
    assert_eq_vec(res, vec![1, 2, 3, 4]);

    // Test 5: Include negative values and i8 boundaries
    let v1: Vec<i8> = vec![-128, 0];
    let v2: Vec<i8> = vec![127, -1];
    let res = r_(v1.clone(), v2.clone());
    assert_eq!(res.len(), v1.len() + v2.len());
    assert_eq_vec(res, vec![-128, 0, 127, -1]);

    // Test 6: Longer inputs
    let v1: Vec<i8> = vec![7; 50];
    let v2: Vec<i8> = vec![8; 50];
    let res = r_(v1.clone(), v2.clone());
    assert_eq!(res.len(), 100);
    assert!(res.iter().take(50).all(|&x| x == 7));
    assert!(res.iter().skip(50).all(|&x| x == 8));

    // Test 7: Mixed values with duplicates
    let v1: Vec<i8> = vec![-5, -5, 10];
    let v2: Vec<i8> = vec![0, -5, 10, 10];
    let res = r_(v1.clone(), v2.clone());
    assert_eq!(res.len(), v1.len() + v2.len());
    assert_eq_vec(res, vec![-5, -5, 10, 0, -5, 10, 10]);
}

