use std::fmt::Debug;

fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32> {
    let mut result = Vec::with_capacity(indices.len());
    for &idx in indices.iter() {
        result.push(arr[idx]);
    }
    result
}

fn assert_vec_eq<T: PartialEq + Debug>(a: Vec<T>, b: Vec<T>) {
    assert_eq!(a, b);
}

fn main() {
    // Happy path: basic selection
    let arr1 = vec![1.0f32, 2.5, -3.75, 4.0];
    let idx1 = vec![0usize, 2];
    let out1 = take(arr1.clone(), idx1.clone());
    assert_vec_eq(out1, vec![1.0, -3.75]);

    // Edge case: empty input array and empty indices
    let arr2: Vec<f32> = vec![];
    let idx2: Vec<usize> = vec![];
    let out2 = take(arr2.clone(), idx2.clone());
    assert_vec_eq(out2, vec![]);

    // Happy path: repeated indices
    let arr3 = vec![10.0f32];
    let idx3 = vec![0usize, 0, 0];
    let out3 = take(arr3.clone(), idx3.clone());
    assert_vec_eq(out3, vec![10.0, 10.0, 10.0]);

    // Happy path: arbitrary order of indices
    let arr4 = vec![0.1f32, 0.2, 0.3, 0.4];
    let idx4 = vec![3usize, 1, 2, 0];
    let out4 = take(arr4.clone(), idx4.clone());
    assert_vec_eq(out4, vec![0.4, 0.2, 0.3, 0.1]);

    // Edge case: non-empty array with empty indices
    let arr5 = vec![5.5f32, 6.6, 7.7];
    let idx5: Vec<usize> = vec![];
    let out5 = take(arr5.clone(), idx5.clone());
    assert_vec_eq(out5, vec![]);

    // Constraint boundary: single index at start
    let arr6 = vec![9.9f32, -1.1, 2.2];
    let idx6 = vec![2usize];
    let out6 = take(arr6.clone(), idx6.clone());
    assert_vec_eq(out6, vec![2.2]);

    // Constraint boundary: includes last valid index multiple times
    let arr7 = vec![1.0f32, 2.0, 3.0, 4.0, 5.0];
    let idx7 = vec![4usize, 4, 0, 1, 3];
    let out7 = take(arr7.clone(), idx7.clone());
    assert_vec_eq(out7, vec![5.0, 5.0, 1.0, 2.0, 4.0]);

    // Happy path: mixed indices covering full range
    let arr8 = vec![3.14f32, 2.71, -0.0, 42.0, -7.5, 8.8];
    let idx8 = vec![5usize, 0, 2, 3];
    let out8 = take(arr8.clone(), idx8.clone());
    assert_vec_eq(out8, vec![8.8, 3.14, -0.0, 42.0]);
}

