    // Test 1: Empty matrix, offset 0
    let a1: Vec<Vec<f32>> = vec![];
    assert_eq!(trace(a1, 0), 0.0);

    // Test 2: Single-element matrix with various offsets
    let a2: Vec<Vec<f32>> = vec![vec![5.0]];
    assert_eq!(trace(a2.clone(), 0), 5.0); // main diagonal
    assert_eq!(trace(a2.clone(), 1), 0.0); // superdiagonal out of bounds
    assert_eq!(trace(a2.clone(), -1), 0.0); // subdiagonal out of bounds

    // Test 3: 3x3 rectangular matrix
    let a3: Vec<Vec<f32>> = vec![
        vec![1.0, 2.0, 3.0],
        vec![4.0, 5.0, 6.0],
        vec![7.0, 8.0, 9.0],
    ];
    assert_eq!(trace(a3.clone(), 0), 15.0); // 1 + 5 + 9
    assert_eq!(trace(a3.clone(), 1), 8.0);  // 2 + 6
    assert_eq!(trace(a3.clone(), -1), 12.0); // 4 + 8
    assert_eq!(trace(a3.clone(), 2), 3.0); // 3 only
    assert_eq!(trace(a3.clone(), -2), 7.0); // 7 only

    // Test 4: Ragged matrix (rows with different lengths)
    let a4: Vec<Vec<f32>> = vec![
        vec![10.0],
        vec![],
        vec![3.0, 5.0],
        vec![1.0],
    ];
    assert_eq!(trace(a4.clone(), 0), 10.0); // (0,0) only
    assert_eq!(trace(a4.clone(), -1), 5.0); // (2,1) only
    assert_eq!(trace(a4.clone(), 1), 0.0); // all out of bounds

    // Test 5: Single row with multiple columns
    let a5: Vec<Vec<f32>> = vec![vec![1.0, 2.0, 3.0]];
    assert_eq!(trace(a5.clone(), 0), 1.0);
    assert_eq!(trace(a5.clone(), 1), 2.0);
    assert_eq!(trace(a5.clone(), 2), 3.0);
    assert_eq!(trace(a5.clone(), 3), 0.0);

    // Test 6: Large positive offset beyond any feasible column
    let a6: Vec<Vec<f32>> = vec![
        vec![1.0, 2.0],
        vec![3.0, 4.0],
    ];
    assert_eq!(trace(a6.clone(), 100), 0.0);

    // Test 7: Extreme negative offset (i32::MIN) should always be out of bounds
    let a7: Vec<Vec<f32>> = vec![vec![1.0], vec![2.0], vec![3.0]];
    assert_eq!(trace(a7.clone(), i32::MIN), 0.0);

    // Test 8: Another ragged matrix, negative offset -2
    let a8: Vec<Vec<f32>> = vec![
        vec![1.0, 2.0],
        vec![3.0],
        vec![4.0, 5.0, 6.0],
        vec![],
        vec![7.0, 8.0, 9.0, 10.0],
