fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    assert!(condition.len() == x.len() && x.len() == y.len());
    let mut result = Vec::with_capacity(condition.len());
    for i in 0..condition.len() {
        if condition[i] {
            result.push(x[i]);
        } else {
            result.push(y[i]);
        }
    }
    result
}

fn main() {
    // Test 1: Empty arrays
    let c1: Vec<bool> = vec![];
    let x1: Vec<f32> = vec![];
    let y1: Vec<f32> = vec![];
    let r1 = where_fn(c1.clone(), x1.clone(), y1.clone());
    assert_eq!(r1, vec![]);

    // Test 2: Single element, true mask
    let c2 = vec![true];
    let x2 = vec![1.5f32];
    let y2 = vec![2.5f32];
    let r2 = where_fn(c2.clone(), x2.clone(), y2.clone());
    assert_eq!(r2, vec![1.5f32]);

    // Test 3: Single element, false mask
    let c3 = vec![false];
    let x3 = vec![1.5f32];
    let y3 = vec![2.5f32];
    let r3 = where_fn(c3.clone(), x3.clone(), y3.clone());
    assert_eq!(r3, vec![2.5f32]);

    // Test 4: All true mask selects from first array
    let c4 = vec![true, true, true, true, true];
    let x4 = vec![1.0f32, -2.0, 3.0, 4.5, 0.0];
    let y4 = vec![9.0f32, 9.0, 9.0, 9.0, 9.0];
    let r4 = where_fn(c4.clone(), x4.clone(), y4.clone());
    assert_eq!(r4, x4);

    // Test 5: All false mask selects from second array
    let c5 = vec![false, false, false, false, false];
    let x5 = vec![1.0f32, -2.0, 3.0, 4.5, 0.0];
    let y5 = vec![9.0f32, 8.0, 7.0, 6.0, 5.0];
    let r5 = where_fn(c5.clone(), x5.clone(), y5.clone());
    assert_eq!(r5, y5);

    // Test 6: Mixed mask
    let c6 = vec![true, false, true, false];
    let x6 = vec![0.1f32, 0.2, 0.3, 0.4];
    let y6 = vec![5.1f32, 5.2, 5.3, 5.4];
    let r6 = where_fn(c6.clone(), x6.clone(), y6.clone());
    assert_eq!(r6, vec![0.1f32, 5.2, 0.3, 5.4]);

    // Test 7: Larger array with alternating mask; verify element-wise
    let n7 = 100usize;
    let mut c7 = Vec::with_capacity(n7);
    let mut x7 = Vec::with_capacity(n7);
    let mut y7 = Vec::with_capacity(n7);
    for i in 0..n7 {
        c7.push(i % 2 == 0);
        x7.push(i as f32);
        y7.push(-(i as f32));
    }
    let r7 = where_fn(c7.clone(), x7.clone(), y7.clone());
    assert_eq!(r7.len(), n7);
    for i in 0..n7 {
