#[derive(Debug, PartialEq, Eq)]
enum LinAlgError {
    NonConvergence(String),
    SingularMatrix(String),
    NonSquareMatrix(String),
    IncompatibleDimensions(String),
    InvalidInput(String),
    NumericalInstability(String),
    Other(String),
}

fn select_error(error_variant: u8, message: String) -> LinAlgError {
    match error_variant {
        0 => LinAlgError::NonConvergence(message),
        1 => LinAlgError::SingularMatrix(message),
        2 => LinAlgError::NonSquareMatrix(message),
        3 => LinAlgError::IncompatibleDimensions(message),
        4 => LinAlgError::InvalidInput(message),
        5 => LinAlgError::NumericalInstability(message),
        _ => LinAlgError::Other(message),
    }
}

fn check_lin_alg_error(condition: bool, error_variant: u8, message: String) -> Option<LinAlgError> {
    if condition {
        let err = select_error(error_variant, message);
        Some(err)
    } else {
        None
    }
}

fn main() {
    // Edge case: condition false => must be None
    let r1 = check_lin_alg_error(false, 0, "no issue".to_string());
    assert!(r1.is_none());

    // Happy path: code 0 => NonConvergence
    let r2 = check_lin_alg_error(true, 0, "did not converge".to_string());
    assert!(matches!(r2, Some(LinAlgError::NonConvergence(s)) if s == "did not converge"));

    // Happy path: code 1 => SingularMatrix
    let r3 = check_lin_alg_error(true, 1, "singular".to_string());
    assert!(matches!(r3, Some(LinAlgError::SingularMatrix(s)) if s == "singular"));

    // Happy path: code 2 => NonSquareMatrix
    let r4 = check_lin_alg_error(true, 2, "non-square".to_string());
    assert!(matches!(r4, Some(LinAlgError::NonSquareMatrix(s)) if s == "non-square"));

    // Happy path: code 3 => IncompatibleDimensions
    let r5 = check_lin_alg_error(true, 3, "incompatible dims".to_string());
    assert!(matches!(r5, Some(LinAlgError::IncompatibleDimensions(s)) if s == "incompatible dims"));

    // Happy path: code 4 => InvalidInput
    let r6 = check_lin_alg_error(true, 4, "invalid".to_string());
    assert!(matches!(r6, Some(LinAlgError::InvalidInput(s)) if s == "invalid"));

    // Happy path: code 5 => NumericalInstability
    let r7 = check_lin_alg_error(true, 5, "unstable".to_string());
    assert!(matches!(r7, Some(LinAlgError::NumericalInstability(s)) if s == "unstable"));

    // Boundary: unknown code (e.g., 255) => Other
    let r8 = check_lin_alg_error(true, 255, "unknown".to_string());
    assert!(matches!(r8, Some(LinAlgError::Other(s)) if s == "unknown"));

    // Edge case: empty message with false condition => None
    let r9 = check_lin_alg_error(false, 255, "".to_string());
    assert!(r9.is_none());

    // Edge case: empty message with true condition and known code
    let r10 = check_lin_alg_error(true, 0, "".to_string());
    assert!(matches!(r10, Some(LinAlgError::NonConvergence(s)) if s.is_empty()));
}

