use std::fmt;

#[derive(PartialEq, Eq, Clone, Copy)]
enum DateTime64 {
    Valid(i64),
    Nat,
}

fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    let mut res: Vec<bool> = Vec::with_capacity(x.len());
    for xi in x {
        let b = match xi {
            DateTime64::Nat => true,
            DateTime64::Valid(_) => false,
        };
        res.push(b);
    }
    res
}

fn main() {
    // 1. Empty array
    let input1: Vec<DateTime64> = vec![];
    let output1 = isnat(input1);
    assert_eq!(output1.len(), 0);
    assert_eq!(output1, vec![]);

    // 2. Mixed elements
    let input2 = vec![
        DateTime64::Nat,
        DateTime64::Valid(0),
        DateTime64::Nat,
        DateTime64::Valid(-5),
        DateTime64::Valid(i64::MAX),
    ];
    let output2 = isnat(input2);
    assert_eq!(output2, vec![true, false, true, false, false]);

    // 3. Only Nat elements
    let input3 = vec![DateTime64::Nat, DateTime64::Nat, DateTime64::Nat];
    let output3 = isnat(input3);
    assert_eq!(output3, vec![true, true, true]);

    // 4. Only Valid elements
    let input4 = vec![DateTime64::Valid(42), DateTime64::Valid(-1), DateTime64::Valid(7)];
    let output4 = isnat(input4);
    assert_eq!(output4, vec![false, false, false]);

    // 5. Single-element Nat
    let input5 = vec![DateTime64::Nat];
    let output5 = isnat(input5);
    assert_eq!(output5, vec![true]);

    // 6. Single-element Valid (negative value)
    let input6 = vec![DateTime64::Valid(-123456789)];
    let output6 = isnat(input6);
    assert_eq!(output6, vec![false]);

    // 7. Boundary values for i64
    let input7 = vec![DateTime64::Valid(i64::MIN), DateTime64::Valid(i64::MAX)];
    let output7 = isnat(input7);
