use std::fmt::Debug;

fn logical_or(x1: Vec<bool>, x2: Vec<bool>) -> Vec<bool> {
    assert_eq!(x1.len(), x2.len(), "Input arrays must have the same length");
    let n = x1.len();
    let mut r = Vec::with_capacity(n);
    for i in 0..n {
        r.push(x1[i] || x2[i]);
    }
    r
}

fn check_properties(x1: &[bool], x2: &[bool], result: &[bool]) {
    assert_eq!(x1.len(), x2.len());
    assert_eq!(result.len(), x1.len());
    for i in 0..result.len() {
        let a = x1[i];
        let b = x2[i];
        let r = result[i];
        // Element-wise OR definition
        assert_eq!(r, a || b);
        // Commutativity
        assert_eq!(a || b, b || a);
        // Identity with false
        assert_eq!(a || false, a);
        // Domination with true
        assert_eq!(a || true, true);
        // Idempotence
        assert_eq!(a || a, a);
        // Implication properties
        if a || b {
            assert_eq!(r, true);
        }
        if !a && !b {
            assert_eq!(r, false);
        }
    }
}

fn main() {
    // Test 1: Empty arrays (edge case)
    let a1: Vec<bool> = vec![];
    let b1: Vec<bool> = vec![];
