use std::fmt::Debug;

fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    let mut result = Vec::with_capacity(arr.len());
    if min_val <= max_val {
        for &x in arr.iter() {
            if x < min_val {
                result.push(min_val);
            } else if x > max_val {
                result.push(max_val);
            } else {
                result.push(x);
            }
        }
    } else {
        // Invalid range: fill entirely with max_val
        for _ in 0..arr.len() {
            result.push(max_val);
        }
    }
    result
}

fn assert_eq_vec<T: PartialEq + Debug>(a: Vec<T>, b: Vec<T>) {
    assert!(a == b, "Expected {:?}, got {:?}", b, a);
}

fn main() {
    // 1) Happy path: mixed values with proper range
    let arr1 = vec![-5, 0, 5, 10];
    let out1 = clip(&arr1, -3, 6);
    assert_eq_vec(out1, vec![-3, 0, 5, 6]);

    // 2) Values already within range remain unchanged
    let arr2 = vec![1, 2, 3];
    let out2 = clip(&arr2, 0, 10);
    assert_eq_vec(out2, vec![1, 2, 3]);

    // 3) All below range get lifted to min
    let arr3 = vec![-128, -100];
    let out3 = clip(&arr3, -50, 50);
    assert_eq_vec(out3, vec![-50, -50]);

    // 4) Some above range get capped at max
    let arr4 = vec![60, 127];
    let out4 = clip(&arr4, -10, 50);
    assert_eq_vec(out4, vec![50, 50]);

    // 5) Edge case: empty input yields empty output
    let arr5: Vec<i8> = vec![];
    let out5 = clip(&arr5, -5, 5);
    assert_eq_vec(out5, vec![]);

    // 6) Single element and exact bound equality
    let arr6 = vec![7];
    let out6 = clip(&arr6, 7, 7);
    assert_eq_vec(out6, vec![7]);

    // 7) Negative bounds, mixed values
    let arr7 = vec![-3, -2, -1, 0];
    let out7 = clip(&arr7, -2, -1);
    assert_eq_vec(out7, vec![-2, -2, -1, -1]);

    // 8) Full i8 bounds
    let arr8 = vec![-128, 127];
    let out8 = clip(&arr8, -128, 127);
    assert_eq_vec(out8, vec![-128, 127]);

    // 9) Degenerate range (min > max): fill with max regardless of input
    let arr9 = vec![-5, 0, 5, 12, -100, 100];
    let out9 = clip(&arr9, 10, 2);
    assert_eq_vec(out9, vec![2, 2, 2, 2, 2, 2]);

    // 10) Boundary where only some values equal bounds
    let arr10 = vec![-128, -127, -126, 0, 126, 127];
    let out10 = clip(&arr10, 0, 0);
    assert_eq_vec(out10, vec![0, 0, 0, 0, 0, 0]);
}

