use std::fmt;

#[derive(Debug, Clone)]
struct ChebyshevPoly {
    coef: Vec<i32>,
    domain_min: i32,
    domain_max: i32,
    window_min: i32,
    window_max: i32,
}

fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Precondition: input must be non-empty
    assert!(!coef.is_empty(), "input coefficients must be non-empty");
    let mut result_coef: Vec<i32> = Vec::with_capacity(coef.len());
    for c in coef.into_iter() {
        result_coef.push(c as i32);
    }
    ChebyshevPoly {
        coef: result_coef,
        domain_min: -1,
        domain_max: 1,
        window_min: -1,
        window_max: 1,
    }
}

fn assert_valid_intervals(p: &ChebyshevPoly) {
    assert!(p.domain_min < p.domain_max, "domain interval must be valid");
    assert!(p.window_min < p.window_max, "window interval must be valid");
    assert!(p.domain_min == -1 && p.domain_max == 1, "domain must be set to [-1, 1]");
    assert!(p.window_min == -1 && p.window_max == 1, "window must be set to [-1, 1]");
}

fn main() {
    // Test 1: Single coefficient (boundary: minimal valid size)
    let input1 = vec![1i8];
    let p1 = chebyshev(input1.clone());
    assert_eq!(p1.coef.len(), input1.len());
    assert_eq!(p1.coef[0], input1[0] as i32);
    assert_valid_intervals(&p1);

    // Test 2: Mixed small values including negative, zero, positive
    let input2 = vec![-1i8, 0i8, 1i8];
    let p2 = chebyshev(input2.clone());
