use std::f32;

// Plain Rust implementation matching the specified behavior
fn chebweight(x: Vec<f32>) -> Vec<f32> {
    assert!(!x.is_empty(), "Precondition violated: input must be non-empty");
    let n = x.len();
    let last = n - 1;
    let mut w: Vec<f32> = Vec::with_capacity(n);
    let mut i: usize = 0;
    while i < n {
        let val: f32 = if i == 0 || i == last { 0.5f32 } else { 1.0f32 };
        w.push(val);
        i += 1;
    }
    w
}

fn main() {
    // Test 1: Single element (only endpoint)
    let x1 = vec![3.14f32];
    let w1 = chebweight(x1.clone());
    assert_eq!(w1.len(), x1.len());
    assert_eq!(w1, vec![0.5f32]);

    // Test 2: Two elements (both endpoints)
    let x2 = vec![1.0f32, 2.0f32];
    let w2 = chebweight(x2.clone());
    assert_eq!(w2.len(), x2.len());
    assert_eq!(w2, vec![0.5f32, 0.5f32]);
    // Sum check: 0.5 + 0.5 = 1.0
    let sum2: f32 = w2.iter().copied().sum();
    assert!((sum2 - 1.0f32).abs() < 1e-6);

    // Test 3: Three elements (middle is interior)
    let x3 = vec![0.0f32, 42.0f32, -7.0f32];
    let w3 = chebweight(x3.clone());
    assert_eq!(w3.len(), x3.len());
    assert_eq!(w3, vec![0.5f32, 1.0f32, 0.5f32]);

    // Test 4: Five elements with mixed values
    let x4 = vec![-1.0f32, 0.0f32, 2.5f32, -3.7f32, 4.2f32];
    let w4 = chebweight(x4.clone());
    assert_eq!(w4.len(), x4.len());
    assert_eq!(w4, vec![0.5f32, 1.0f32, 1.0f32, 1.0f32, 0.5f32]);
    // Sum check: 0.5 + 3*1.0 + 0.5 = 4.0
    let sum4: f32 = w4.iter().copied().sum();
    assert!((sum4 - 4.0f32).abs() < 1e-6);

    // Test 5: Ten elements, verify endpoints and interiors
    let x5: Vec<f32> = (0..10).map(|i| i as f32).collect();
    let w5 = chebweight(x5.clone());
    assert_eq!(w5.len(), x5.len());
    assert_eq!(w5[0], 0.5f32);
    assert_eq!(w5[9], 0.5f32);
    for i in 1..9 {
        assert_eq!(w5[i], 1.0f32);
    }

    // Test 6: Large size, verify count and sum property (sum should be n - 1)
    let n6 = 100usize;
    let x6: Vec<f32> = (0..n6).map(|i| i as f32).collect();
    let w6 = chebweight(x6.clone());
    assert_eq!(w6.len(), x6.len());
    let sum6: f32 = w6.iter().copied().sum();
    assert!((sum6 - ((n6 as f32) - 1.0)).abs() < 1e-5);
    assert_eq!(w6[0], 0.5f32);
    assert_eq!(w6[n6 - 1], 0.5f32);
    assert_eq!(w6.iter().filter(|&&v| (v - 1.0f32).abs() < 1e-6).count(), n6 - 2);

    // Test 7: Boundary case n = 2 (already covered), add n = 3 sum check
    let x7 = vec![10.0f32, 20.0f32, 30.0f32];
    let w7 = chebweight(x7.clone());
    let sum7: f32 = w7.iter().copied().sum();
    assert!((sum7 - 2.0f32).abs() < 1e-6);

    // Note: Passing an empty vector would violate the precondition (non-empty input) and will panic.
    // Example (commented out):
    // let w_empty = chebweight(vec![]); // should not be called according to the specification
}

