use std::f64;

fn hermemulx(c: Vec<f64>) -> Vec<f64> {
    // Construct a new vector with a leading 0.0 followed by all elements of c
    let mut res: Vec<f64> = Vec::with_capacity(c.len() + 1);
    res.push(0.0f64);
    for &v in c.iter() {
        res.push(v);
    }
    res
}

fn assert_spec(input: &Vec<f64>, output: &Vec<f64>) {
    // Check the specified properties
    assert_eq!(output.len(), input.len() + 1, "Output length must be input length + 1");
    assert!(output.len() > 0, "Output must be non-empty");
    assert_eq!(output[0], 0.0, "First element must be 0.0");
    for i in 1..input.len() {
        assert_eq!(output[i + 1], input[i], "Shift property failed at i={}", i);
    }
}

fn main() {
    // 1) Empty input
    let c1: Vec<f64> = vec![];
    let r1 = hermemulx(c1.clone());
    assert_spec(&c1, &r1);
    assert_eq!(r1, vec![0.0]);

    // 2) Single-element input
    let c2 = vec![3.5];
    let r2 = hermemulx(c2.clone());
    assert_spec(&c2, &r2);
    assert_eq!(r2, vec![0.0, 3.5]);

    // 3) Multiple elements
    let c3 = vec![1.0, 2.0, 3.0];
    let r3 = hermemulx(c3.clone());
    assert_spec(&c3, &r3);
    assert_eq!(r3, vec![0.0, 1.0, 2.0, 3.0]);

    // 4) Negative values
    let c4 = vec![-2.5, -3.0];
    let r4 = hermemulx(c4.clone());
    assert_spec(&c4, &r4);
    assert_eq!(r4, vec![0.0, -2.5, -3.0]);

    // 5) Mixed values including zero
    let c5 = vec![1.5, -4.75, 0.0, 2.25];
    let r5 = hermemulx(c5.clone());
    assert_spec(&c5, &r5);
    assert_eq!(r5, vec![0.0, 1.5, -4.75, 0.0, 2.25]);

    // 6) Infinity values
    let c6 = vec![f64::INFINITY, f64::NEG_INFINITY, 42.0];
    let r6 = hermemulx(c6.clone());
    assert_spec(&c6, &r6);
    assert_eq!(r6[0], 0.0);
    assert!(r6[1].is_infinite() && r6[1].is_sign_positive());
    assert!(r6[2].is_infinite() && r6[2].is_sign_negative());
    assert_eq!(r6[3], 42.0);

    // 7) Large magnitude values
    let c7 = vec![1e308, -1e308];
    let r7 = hermemulx(c7.clone());
    assert_spec(&c7, &r7);
    assert_eq!(r7, vec![0.0, 1e308, -1e308]);

    // 8) Longer input
    let c8: Vec<f64> = (0..10).map(|i| i as f64 + 0.5).collect();
    let r8 = hermemulx(c8.clone());
    assert_spec(&c8, &r8);
    let mut expected8 = vec![0.0];
    expected8.extend(c8.iter().cloned());
    assert_eq!(r8, expected8);
}

