fn assert_vec2(v: &Vec<f32>, a: f32, b: f32) {
    assert!(v.len() == 2, "expected len 2, got {}", v.len());
    assert!(v[0] == a, "first element mismatch: {} != {}", v[0], a);
    assert!(v[1] == b, "second element mismatch: {} != {}", v[1], b);
}

fn main() {
    // Happy Path: zeros
    let v = lagline(0.0, 0.0);
    assert_vec2(&v, 0.0, 0.0);

    // Happy Path: positive values
    let v = lagline(1.5, 2.5);
    assert_vec2(&v, 1.5, 2.5);

    // Edge Case: negative values
    let v = lagline(-3.0, -4.5);
    assert_vec2(&v, -3.0, -4.5);

    // Mixed sign
    let v = lagline(-1.25, 3.75);
    assert_vec2(&v, -1.25, 3.75);

    // Boundary-like: infinities
    let v = lagline(f32::INFINITY, f32::NEG_INFINITY);
    assert_vec2(&v, f32::INFINITY, f32::NEG_INFINITY);

    // Very small magnitudes (subnormal range vicinity)
    let v = lagline(1.0e-38, -1.0e-38);
    assert_vec2(&v, 1.0e-38, -1.0e-38);

    // Very large finite values
    let v = lagline(1.0e30, -1.0e30);
    assert_vec2(&v, 1.0e30, -1.0e30);

    // Also test the helper directly
    let v = make_pair(7.0, 8.0);
    assert_vec2(&v, 7.0, 8.0);
}

