    assert!(r3.iter().all(|&v| v == 0.0));

    // Test 4: Mx1 coefficient grid (not 1x1), expect zeros
    let x4 = vec![10.0, 20.0];
    let y4 = vec![30.0, 40.0];
    let c4 = vec![vec![3.0], vec![4.0]]; // 2x1
    let r4 = lagval2d(x4.clone(), y4.clone(), c4.clone());
    assert_eq!(r4.len(), x4.len());
