fn mk_filled_vec(n: usize, val: f32) -> Vec<f32> {
    // Helper that returns a vector of length n filled with val
    // Mirrors the verified behavior: length is n and each element equals val
    let mut v = Vec::with_capacity(n);
    let mut i = 0usize;
    while i < n {
        v.push(val);
        i += 1;
    }
    v
}

