use std::f32;

fn legline(first: f32, second: f32) -> Vec<f32> {
    let mut v = Vec::new();
    v.push(first);
    v.push(second);
    v
}

fn main() {
    // 1) Happy path: distinct positive values
    {
        let v = legline(1.5, 2.5);
        assert_eq!(v.len(), 2);
        assert!(v[0] == 1.5 && v[1] == 2.5);
    }

    // 2) Edge case: zero and negative value
    {
        let v = legline(0.0, -3.75);
        assert_eq!(v.len(), 2);
        assert!(v[0] == 0.0 && v[1] == -3.75);
    }

    // 3) Boundary-like: very large magnitude values within f32 range
    {
        let v = legline(1.0e38_f32, -1.0e38_f32);
        assert_eq!(v.len(), 2);
        assert!(v[0] == 1.0e38_f32 && v[1] == -1.0e38_f32);
    }

    // 4) Special values: positive and negative infinity
    {
        let v = legline(f32::INFINITY, f32::NEG_INFINITY);
        assert_eq!(v.len(), 2);
        assert!(v[0].is_infinite() && v[0].is_sign_positive());
        assert!(v[1].is_infinite() && v[1].is_sign_negative());
    }

    // 5) Edge case: negative zero and positive zero
    {
        let v = legline(-0.0, 0.0);
        assert_eq!(v.len(), 2);
        // -0.0 == 0.0 evaluates true, so check exact values pushed
        assert!(v[0] == -0.0 && v[1] == 0.0);
        // Additionally check bit patterns to ensure positions are correct
        assert!(v[0].to_bits() == (-0.0f32).to_bits());
        assert!(v[1].to_bits() == (0.0f32).to_bits());
    }

    // 6) Repeated values: both inputs equal
    {
        let v = legline(7.0, 7.0);
        assert_eq!(v.len(), 2);
        assert!(v[0] == 7.0 && v[1] == 7.0);
    }

    // 7) Small magnitudes: epsilon and -epsilon
    {
        let v = legline(f32::EPSILON, -f32::EPSILON);
        assert_eq!(v.len(), 2);
        assert!(v[0] == f32::EPSILON && v[1] == -f32::EPSILON);
    }

    // 8) Mixed fractional values
    {
        let v = legline(-123.456_f32, 789.012_f32);
        assert_eq!(v.len(), 2);
        assert!(v[0] == -123.456_f32 && v[1] == 789.012_f32);
    }
}

