use std::fmt::Debug;

fn legmulx(c: Vec<f32>) -> Vec<f32> {
    // Enforce the precondition from the specification: input must be non-empty.
    assert!(!c.is_empty(), "Precondition violated: input length must be > 0");
    let mut result: Vec<f32> = Vec::with_capacity(c.len() + 1);
    result.push(0.0f32);
    for x in c {
        result.push(x);
    }
    result
}

fn assert_all_shifted<T: PartialEq + Debug>(input: &[T], output: &[T]) {
    assert_eq!(output.len(), input.len() + 1);
    for i in 0..input.len() {
        assert_eq!(output[i + 1], input[i], "Mismatch at shifted index {}", i);
    }
}

fn main() {
    // Test 1: Typical case with multiple positive floats
    let c1 = vec![1.0f32, 2.0, 3.0];
    let r1 = legmulx(c1.clone());
    assert_eq!(r1.len(), c1.len() + 1);
    assert_eq!(r1[0], 0.0f32);
    assert_eq!(r1[1], c1[0]);
    assert_all_shifted(&c1, &r1);

    // Test 2: Single-element input (boundary for non-empty arrays)
    let c2 = vec![7.5f32];
    let r2 = legmulx(c2.clone());
    assert_eq!(r2.len(), c2.len() + 1);
    assert_eq!(r2[0], 0.0f32);
    assert_eq!(r2[1], c2[0]);
    assert_all_shifted(&c2, &r2);

    // Test 3: Includes negative and -0.0 values
    let c3 = vec![-0.0f32, 0.5f32, -2.75f32];
    let r3 = legmulx(c3.clone());
    assert_eq!(r3.len(), c3.len() + 1);
    assert_eq!(r3[0], 0.0f32);
    assert_eq!(r3[1], c3[0]);
    assert_all_shifted(&c3, &r3);
    assert_eq!(r3, vec![0.0f32, -0.0f32, 0.5f32, -2.75f32]);

    // Test 4: Larger input with mixed values
    let c4 = vec![1e-3f32, 2.0f32, -5.0f32, 0.0f32, 999.999f32];
    let r4 = legmulx(c4.clone());
    assert_eq!(r4.len(), c4.len() + 1);
    assert_eq!(r4[0], 0.0f32);
    assert_eq!(r4[1], c4[0]);
    assert_all_shifted(&c4, &r4);
    assert_eq!(r4, vec![0.0f32, 1e-3f32, 2.0f32, -5.0f32, 0.0f32, 999.999f32]);

    // Test 5: Extreme finite values
    let c5 = vec![f32::MIN, f32::MAX];
    let r5 = legmulx(c5.clone());
    assert_eq!(r5.len(), c5.len() + 1);
    assert_eq!(r5[0], 0.0f32);
    assert_eq!(r5[1], c5[0]);
    assert_all_shifted(&c5, &r5);

    // Test 6: Zeros only
    let c6 = vec![0.0f32, 0.0f32, 0.0f32];
    let r6 = legmulx(c6.clone());
    assert_eq!(r6.len(), c6.len() + 1);
    assert_eq!(r6[0], 0.0f32);
    assert_eq!(r6[1], c6[0]);
    assert_all_shifted(&c6, &r6);
    assert_eq!(r6, vec![0.0f32, 0.0f32, 0.0f32, 0.0f32]);

    // Test 7: Non-trivial negative and positive mix
    let c7 = vec![-1.25f32, 3.5f32, -4.125f32, 2.0f32];
    let r7 = legmulx(c7.clone());
    assert_eq!(r7.len(), c7.len() + 1);
    assert_eq!(r7[0], 0.0f32);
    assert_eq!(r7[1], c7[0]);
    assert_all_shifted(&c7, &r7);
    assert_eq!(r7, vec![0.0f32, -1.25f32, 3.5f32, -4.125f32, 2.0f32]);

    println!("All tests passed.");
}

