use std::u32;

// Reference implementation for testing (wrap-around arithmetic)
fn mt19937_reference(seed: u32) -> Vec<u32> {
    let mut state: Vec<u32> = Vec::with_capacity(624);
    state.push(seed);
    for i in 0..623 {
        let prev = state[i];
        let shifted = prev >> 30;
        let xor_val = prev ^ shifted;
        let mult = 1812433253u32.wrapping_mul(xor_val);
        let next = mult.wrapping_add((i as u32) + 1);
        state.push(next);
    }
    state
}

fn verify_recurrence(state: &[u32]) {
    assert!(state.len() == 624, "State length must be 624");
    for i in 0..623 {
        let prev = state[i];
        let expected_next = 1812433253u32
            .wrapping_mul(prev ^ (prev >> 30))
            .wrapping_add((i as u32) + 1);
        assert!(state[i + 1] == expected_next, "Recurrence failed at i={}", i);
    }
}

fn main() {
    // Test 1: Seed = 0 (boundary, simple early constants)
    let s0 = mt19937_reference(0);
    assert!(s0.len() == 624);
    assert!(s0[0] == 0);
    assert!(s0[1] == 1, "For seed=0, state[1] should be 1");
    assert!(s0[2] == 1812433255u32, "For seed=0, state[2] should be 1812433255");
    verify_recurrence(&s0);

    // Test 2: Seed = 1 (small positive)
    let s1 = mt19937_reference(1);
    assert!(s1.len() == 624);
    assert!(s1[0] == 1);
    assert!(s1[1] == 1812433254u32, "For seed=1, state[1] should be 1812433254");
    verify_recurrence(&s1);

    // Test 3: Seed = 5489 (commonly used MT19937 default seed)
    let s_def = mt19937_reference(5489);
    assert!(s_def.len() == 624);
    assert!(s_def[0] == 5489);
    verify_recurrence(&s_def);

    // Test 4: Seed = u32::MAX (upper boundary)
    let s_max = mt19937_reference(u32::MAX);
    assert!(s_max.len() == 624);
    assert!(s_max[0] == u32::MAX);
    verify_recurrence(&s_max);

    // Test 5: Seed = arbitrary mid-range value
    let s_mid = mt19937_reference(1234567890);
    assert!(s_mid.len() == 624);
    assert!(s_mid[0] == 1234567890);
    verify_recurrence(&s_mid);

    // Test 6: Another arbitrary value to stress wrapping behavior
    let s_wrap = mt19937_reference(0x8000_0001);
    assert!(s_wrap.len() == 624);
    assert!(s_wrap[0] == 0x8000_0001);
    verify_recurrence(&s_wrap);

    // Test 7: Small seed to check early behavior thoroughly
    let s_small = mt19937_reference(42);
    assert!(s_small.len() == 624);
    assert!(s_small[0] == 42);
    verify_recurrence(&s_small);

    println!("All tests passed.");
}

