use std::fmt::Debug;

#[derive(Debug, Clone, Copy)]
struct BitGenerator {
    state: u64,
    seed: Option<u64>,
}

#[derive(Debug, Clone, Copy)]
struct Generator {
    bit_generator: BitGenerator,
    initialized: bool,
}

fn compute_state(seed: Option<u64>) -> u64 {
    match seed {
        Some(x) => if x == 0 { 1 } else { x },
        None => 0,
    }
}

fn default_rng(seed: Option<u64>) -> Generator {
    let s = compute_state(seed);
    let bg = BitGenerator { state: s, seed };
    Generator { bit_generator: bg, initialized: true }
}

fn main() {
    // Test 1: No seed provided (None)
    let seed1: Option<u64> = None;
    let g1 = default_rng(seed1);
    assert!(g1.initialized, "Generator must be initialized");
    assert!(g1.bit_generator.seed == seed1, "Seed must be stored exactly");
    // No constraint on state when None; allowed to be zero

    // Test 2: Seed is zero; internal state must be non-zero
    let seed2 = Some(0u64);
    let g2 = default_rng(seed2);
    assert!(g2.initialized, "Generator must be initialized");
    assert!(g2.bit_generator.seed == seed2, "Seed must be stored exactly");
    assert!(g2.bit_generator.state != 0, "State must be non-zero when a seed is provided");

    // Test 3: Small non-zero seed
    let seed3 = Some(1u64);
    let g3 = default_rng(seed3);
    assert!(g3.initialized);
    assert!(g3.bit_generator.seed == seed3);
    assert!(g3.bit_generator.state != 0);

    // Test 4: Typical seed value
    let seed4 = Some(42u64);
