verus! {

fn argmax(a: Vec<i8>) -> (result: usize)
    requires a.len() > 0,
    ensures 
        result < a.len(),
        forall|j: int| 0 <= j < a@.len() ==> a@[j] <= a@[result as int],
        forall|j: int| 0 <= j < a@.len() && a@[j] == a@[result as int] ==> result <= j as usize,
{
    let mut argmax_idx: usize = 0;
    let mut max_val = a[0];
    let mut i: usize = 1;

    while i < a.len()
        invariant
            1 <= i <= a.len(),
            0 <= argmax_idx < i,
            max_val == a@[argmax_idx as int],
            forall|k: int| 0 <= k < i ==> a@[k] <= max_val,
            forall|k: int| 0 <= k < i && a@[k] == max_val ==> argmax_idx <= k as usize,
        decreases a.len() - i
    {
        if a[i] > max_val {
            max_val = a[i];
            argmax_idx = i;
        }
        i = i + 1;
    }

    argmax_idx
}

fn assert_argmax_properties(a: Vec<i8>, expected: usize) {
    // Precondition: a.len() > 0
    assert!(a.len() > 0);
    let idx = argmax(a.clone());
    assert!(idx == expected);
    assert!(idx < a.len());
    let val = a[idx];
    let mut j: usize = 0;
    while j < a.len() {
        assert!(a[j] <= val);
        if a[j] == val {
            assert!(idx <= j);
        }
        j += 1;
    }
}

fn main() {
    // 1. Single element
    assert_argmax_properties(vec![42i8], 0);

    // 2. All equal elements
    assert_argmax_properties(vec![3i8, 3, 3], 0);

    // 3. Multiple maxima, earliest not at index 0
    assert_argmax_properties(vec![-5i8, -2, -2, -3], 1);

    // 4. Strictly increasing sequence
    assert_argmax_properties(vec![1i8, 2, 3, 4, 5], 4);

    // 5. Strictly decreasing sequence
    assert_argmax_properties(vec![5i8, 4, 3, 2, 1], 0);

    // 6. Includes i8 bounds and duplicate maxima
    assert_argmax_properties(vec![127i8, -128, 0, 127, 126], 0);

    // 7. All at minimum i8
    assert_argmax_properties(vec![-128i8, -128, -128], 0);

    // 8. Mixed values with repeated maxima
    assert_argmax_properties(vec![-10i8, 20, 20, 5], 1);
}

}

