use std::f64;

fn reduce(arr: Vec<f64>) -> f64 {
    assert!(!arr.is_empty(), "Precondition violated: input array must be non-empty.");
    if arr.len() == 1 {
        arr[0]
    } else {
        arr[arr.len() - 1]
    }
}

fn main() {
    // 1) Single element, positive value
    let v1 = vec![42.0];
    let r1 = reduce(v1);
    assert_eq!(r1, 42.0);

    // 2) Two elements, typical case
    let v2 = vec![1.5, 3.5];
    let r2 = reduce(v2);
    assert_eq!(r2, 3.5);

    // 3) Multiple elements, mixed signs
    let v3 = vec![0.0, -1.0, 2.0, 10.0];
    let r3 = reduce(v3);
    assert_eq!(r3, 10.0);

    // 4) Two elements, last is negative
    let v4 = vec![3.14, -2.718];
    let r4 = reduce(v4);
    assert_eq!(r4, -2.718);

    // 5) Last element is NaN
    let v5 = vec![1.0, f64::NAN];
    let r5 = reduce(v5);
    assert!(r5.is_nan());

    // 6) Larger vector
    let v6: Vec<f64> = (0..100).map(|x| x as f64).collect();
    let r6 = reduce(v6);
    assert_eq!(r6, 99.0);

    // 7) Infinity as last element
    let v7 = vec![10.0, f64::INFINITY];
    let r7 = reduce(v7);
    assert!(r7.is_infinite() && r7.is_sign_positive());

    // 8) Negative zero as last element
    let v8 = vec![1.0, -0.0];
    let r8 = reduce(v8);
    assert!(r8 == 0.0 && r8.is_sign_negative());
}

