use std::fmt::Debug;

#[derive(Clone, Copy, Debug)]
enum OpType {
    Add,
    Multiply,
    LogicalAnd,
    LogicalOr,
}

// Reference behavior for the problem statement (used by tests to check properties)
fn apply_op(op: OpType, x: i64, y: i64) -> i64 {
    match op {
        OpType::Add => x + y,
        OpType::Multiply => x * y,
        OpType::LogicalAnd => {
            if x != 0 && y != 0 { 1 } else { 0 }
        }
        OpType::LogicalOr => {
            if x != 0 || y != 0 { 1 } else { 0 }
        }
    }
}

// Function under test: expected behavior per the description
fn ufunc_identity(op: OpType) -> Option<i8> {
    match op {
        OpType::Add => Some(0i8),
        OpType::Multiply => Some(1i8),
        OpType::LogicalAnd => None,
        OpType::LogicalOr => None,
    }
}

fn assert_identity_for_samples<T: Into<i64> + Copy + Debug>(op: OpType, id: i8, samples: &[T]) {
    let id64 = id as i64;
    for &x in samples.iter() {
        let xi = x.into();
        let lhs = apply_op(op, xi, id64);
        let rhs = apply_op(op, id64, xi);
        assert!(lhs == xi, "Right-identity failed for op {:?}, x={:?}, id={}", op, x, id);
        assert!(rhs == xi, "Left-identity failed for op {:?}, x={:?}, id={}", op, x, id);
    }
}

fn assert_no_identity_exists(op: OpType, candidates: &[i64], witnesses: &[i64]) {
    // For each candidate id, find some witness x where identity property fails.
    for &id in candidates.iter() {
        let mut found_counterexample = false;
        for &x in witnesses.iter() {
            let lhs = apply_op(op, x, id);
            let rhs = apply_op(op, id, x);
            if lhs != x || rhs != x {
                found_counterexample = true;
                break;
            }
        }
        assert!(
            found_counterexample,
            "Unexpected identity for op {:?} with id {} over given witnesses",
            op,
            id
        );
    }
}

fn main() {
    // Sample set of integers to test identity property concretely
    let samples: [i64; 6] = [-2, -1, 0, 1, 2, 7];

    // 1) Happy path: Addition should return Some(0)
    let add_id = ufunc_identity(OpType::Add);
    assert!(matches!(add_id, Some(0)), "Add identity should be Some(0), got {:?}", add_id);
