spec fn apply_op(op: OpType, x: int, y: int) -> int {
    match op {
        OpType::Add => x + y,
        OpType::Multiply => x * y,
        OpType::LogicalAnd => if x != 0 && y != 0 { 1 } else { 0 },
        OpType::LogicalOr => if x != 0 || y != 0 { 1 } else { 0 },
    }
}

spec fn has_identity(op: OpType, id: int) -> bool {
