use std::cmp;

fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }
    let mut max_streak: usize = 1;
    let mut current_streak: usize = 1;
    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            current_streak += 1;
        } else {
            current_streak = 1;
        }
        if current_streak > max_streak {
            max_streak = current_streak;
        }
    }
    max_streak
}

fn main() {
    // 1) Empty array -> 0
    let v1: Vec<i32> = vec![];
    let r1 = longest_increasing_streak(&v1);
    assert_eq!(r1, 0);
    assert!(r1 <= v1.len());

    // 2) Single element -> 1
    let v2 = vec![42];
    let r2 = longest_increasing_streak(&v2);
    assert_eq!(r2, 1);
    assert!(r2 <= v2.len());

    // 3) Strictly increasing -> length
    let v3 = vec![1, 2, 3, 4, 5];
    let r3 = longest_increasing_streak(&v3);
    assert_eq!(r3, 5);
    assert!(r3 <= v3.len());

    // 4) Strictly decreasing -> 1
    let v4 = vec![5, 4, 3, 2, 1];
    let r4 = longest_increasing_streak(&v4);
    assert_eq!(r4, 1);
    assert!(r4 <= v4.len());

    // 5) All equal -> 1
    let v5 = vec![7, 7, 7, 7];
    let r5 = longest_increasing_streak(&v5);
    assert_eq!(r5, 1);
    assert!(r5 <= v5.len());

    // 6) Mixed increases and resets -> longest is 4
    let v6 = vec![1, 2, 3, 1, 2, 3, 4, 0];
    let r6 = longest_increasing_streak(&v6);
    assert_eq!(r6, 4);
    assert!(r6 <= v6.len());

    // 7) Duplicate breaks streak -> 3
    let v7 = vec![1, 2, 2, 3, 4];
    let r7 = longest_increasing_streak(&v7);
    assert_eq!(r7, 3);
    assert!(r7 <= v7.len());

    // 8) Negative to positive -> 5
    let v8 = vec![-3, -2, -1, 0, 1];
    let r8 = longest_increasing_streak(&v8);
    assert_eq!(r8, 5);
    assert!(r8 <= v8.len());

    // 9) Extremes including i32::MIN and i32::MAX -> 3
    let v9 = vec![i32::MIN, i32::MIN + 1, i32::MAX];
    let r9 = longest_increasing_streak(&v9);
    assert_eq!(r9, 3);
    assert!(r9 <= v9.len());
}

