use std::i32;

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    for i in 0..nums.len() {
        for j in (i + 1)..nums.len() {
            if nums[i].checked_add(nums[j]).is_some() && nums[i] + nums[j] == target {
                return Some((i, j));
            }
        }
    }
    None
}

fn main() {
    // 1. Happy path: classic example
    let nums1 = vec![2, 7, 11, 15];
    let target1 = 9;
    let res1 = two_sum(nums1, target1);
    assert_eq!(res1, Some((0, 1)));

    // 2. Multiple valid pairs: must return lexicographically smallest
    let nums2 = vec![1, 8, 3, 7, 2, 6]; // valid pairs: (0,1)=9, (3,4)=9, (2,5)=9
    let target2 = 9;
    let res2 = two_sum(nums2, target2);
    assert_eq!(res2, Some((0, 1)));

    // 3. No pair exists
    let nums3 = vec![1, 2, 3];
    let target3 = 100;
    let res3 = two_sum(nums3, target3);
    assert_eq!(res3, None);

    // 4. Single-element array: cannot form a pair
    let nums4 = vec![5];
    let target4 = 5;
    let res4 = two_sum(nums4, target4);
    assert_eq!(res4, None);

    // 5. Empty array: no pairs
    let nums5: Vec<i32> = vec![];
    let target5 = 0;
    let res5 = two_sum(nums5, target5);
    assert_eq!(res5, None);

    // 6. Duplicates leading to multiple pairs: choose earliest by indices
    let nums6 = vec![4, 4, 4];
    let target6 = 8;
    let res6 = two_sum(nums6, target6);
    assert_eq!(res6, Some((0, 1)));

    // 7. Overflow prevention: a pair that would overflow must not be counted
    // MAX + 1 would overflow; target is MAX - 1, matched by (MAX) + (-1)
    let nums7 = vec![i32::MAX, 1, -1];
    let target7 = i32::MAX - 1; // 2147483646
    let res7 = two_sum(nums7, target7);
    assert_eq!(res7, Some((0, 2)));

    // 8. Negative numbers and zero
    let nums8 = vec![0, -3, 3];
    let target8 = 0;
    let res8 = two_sum(nums8, target8);
    assert_eq!(res8, Some((1, 2)));

    // 9. Many identical elements: ensure second index is minimal for smallest first index
    let nums9 = vec![2, 2, 2, 2];
    let target9 = 4;
    let res9 = two_sum(nums9, target9);
    assert_eq!(res9, Some((0, 1)));

    println!("All tests passed.");
}

