fn is_odd(n: i32) -> bool {
    // Treats negative odd numbers as odd as well
    n % 2 != 0
}

fn is_odd_at_index_odd(a: &Vec<i32>) -> bool {
    let mut i: usize = 0;
    while i < a.len() {
        if i % 2 == 1 {
            if !is_odd(a[i]) {
                return false;
            }
        }
        i += 1;
    }
    true
}

fn main() {
    // Edge case: empty array (vacuous truth)
    let a0: Vec<i32> = vec![];
    assert_eq!(is_odd_at_index_odd(&a0), true);

    // Single-element arrays (only index 0 exists, which is even index)
    let a1 = vec![2];
    assert_eq!(is_odd_at_index_odd(&a1), true);

    let a2 = vec![1];
    assert_eq!(is_odd_at_index_odd(&a2), true);

    // Happy path: odd index has odd value
    let a3 = vec![0, 1];
    assert_eq!(is_odd_at_index_odd(&a3), true);

    // Failure at odd index: odd index has even value
    let a4 = vec![0, 2];
    assert_eq!(is_odd_at_index_odd(&a4), false);

    // Negative odd numbers at odd indices should be accepted
    let a5 = vec![5, -3, 8, -7];
    assert_eq!(is_odd_at_index_odd(&a5), true);

    // Negative even at odd index should fail
    let a6 = vec![2, -4, 3, -6];
    assert_eq!(is_odd_at_index_odd(&a6), false);

    // Multiple odd indices all valid
    let a7 = vec![10, 11, 12, 13, 14];
    assert_eq!(is_odd_at_index_odd(&a7), true);

    // Longer array with a violation late
    let a8 = vec![0, 1, 0, 3, 0, 4];
    assert_eq!(is_odd_at_index_odd(&a8), false);
