use std::i32;

fn check_post(a: &Vec<i32>, e: i32, result: usize) {
    assert!(result <= a.len());
    if result == a.len() {
        // If not found, all elements must be different from e
        for i in 0..result {
            assert!(a[i] != e);
        }
    } else {
        // If found, array[result] must be e and all prior elements are not e
        assert!(a[result] == e);
        for i in 0..result {
            assert!(a[i] != e);
        }
    }
}

fn main() {
    // Test 1: Empty array, target not present
    let a1: Vec<i32> = vec![];
    let e1 = 5;
    let r1 = linear_search(&a1, e1);
    assert_eq!(r1, a1.len());
    check_post(&a1, e1, r1);

    // Test 2: Single element, target present
    let a2 = vec![7];
    let e2 = 7;
    let r2 = linear_search(&a2, e2);
    assert_eq!(r2, 0);
    check_post(&a2, e2, r2);

    // Test 3: Single element, target absent
    let a3 = vec![7];
    let e3 = 8;
    let r3 = linear_search(&a3, e3);
    assert_eq!(r3, a3.len());
    check_post(&a3, e3, r3);

    // Test 4: Multiple occurrences, ensure first index returned
    let a4 = vec![1, 2, 3, 2, 2];
    let e4 = 2;
    let r4 = linear_search(&a4, e4);
    assert_eq!(r4, 1);
    check_post(&a4, e4, r4);

    // Test 5: Target at last index
    let a5 = vec![4, 5, 6];
    let e5 = 6;
    let r5 = linear_search(&a5, e5);
    assert_eq!(r5, 2);
    check_post(&a5, e5, r5);

    // Test 6: Negative values and duplicates
    let a6 = vec![-1, -2, -3, -2];
    let e6 = -2;
    let r6 = linear_search(&a6, e6);
    assert_eq!(r6, 1);
    check_post(&a6, e6, r6);

    // Test 7: No match in a non-empty array
    let a7 = vec![0, 1, 2, 3];
    let e7 = 10;
    let r7 = linear_search(&a7, e7);
    assert_eq!(r7, a7.len());
    check_post(&a7, e7, r7);

    // Test 8: All elements equal to target, first index is 0
    let a8 = vec![9, 9, 9];
    let e8 = 9;
    let r8 = linear_search(&a8, e8);
    assert_eq!(r8, 0);
    check_post(&a8, e8, r8);

    // Test 9: Boundary integer values
    let a9 = vec![i32::MIN, 0, i32::MAX];
    let e9 = i32::MAX;
    let r9 = linear_search(&a9, e9);
    assert_eq!(r9, 2);
    check_post(&a9, e9, r9);
}

