use vstd::prelude::*;

verus! {
fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> (result: Vec<char>)
    ensures
        result.len() <= str1.len(),
        result.len() <= str2.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == str1[i] && result[i] == str2[i],
        result.len() == str1.len() || result.len() == str2.len() ||
            (result.len() < str1.len() && result.len() < str2.len() && str1[result.len() as int] != str2[result.len() as int]),
{
    let mut result = Vec::new();
    let mut i = 0;
    while i < str1.len() && i < str2.len() && str1[i] == str2[i]
        invariant
            i <= str1.len(),
            i <= str2.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == str1[j] && result[j] == str2[j],
        decreases str1.len() - i
    {
        result.push(str1[i]);
        i += 1;
    }
    result
}
}

fn vec_from_str(s: &str) -> Vec<char> {
    s.chars().collect::<Vec<char>>()
}

fn assert_eq_vec(a: &Vec<char>, b: &Vec<char>) {
    assert!(a.len() == b.len(), "lengths differ: {} vs {}", a.len(), b.len());
    for i in 0..a.len() {
        assert!(a[i] == b[i], "at {} got {:?} vs {:?}", i, a[i], b[i]);
    }
}

fn main() {
    // 1: Both empty
    let a = vec_from_str("");
    let b = vec_from_str("");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("");
    assert_eq_vec(&res, &exp);
    assert!(res.len() <= a.len() && res.len() <= b.len());
    if res.len() < a.len() && res.len() < b.len() {
        assert!(a[res.len()] != b[res.len()]);
    }

    // 2: One empty, one non-empty
    let a = vec_from_str("");
    let b = vec_from_str("abc");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("");
    assert_eq_vec(&res, &exp);
    assert!(res.len() <= a.len() && res.len() <= b.len());
    if res.len() < a.len() && res.len() < b.len() {
        assert!(a[res.len()] != b[res.len()]);
    }

    // 3: Identical strings
    let a = vec_from_str("verus");
    let b = vec_from_str("verus");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("verus");
    assert_eq_vec(&res, &exp);
    assert!(res.len() == a.len() || res.len() == b.len());

    // 4: One is a prefix of the other
    let a = vec_from_str("car");
    let b = vec_from_str("cartoon");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("car");
    assert_eq_vec(&res, &exp);
    assert!(res.len() == a.len());

    // 5: First character differs
    let a = vec_from_str("abc");
    let b = vec_from_str("xyz");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("");
    assert_eq_vec(&res, &exp);
    if res.len() < a.len() && res.len() < b.len() {
        assert!(a[res.len()] != b[res.len()]);
    }

    // 6: Partial common prefix
    let a = vec_from_str("prefix");
    let b = vec_from_str("preform");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("pre");
    assert_eq_vec(&res, &exp);
    if res.len() < a.len() && res.len() < b.len() {
        assert!(a[res.len()] != b[res.len()]);
    }

    // 7: Long common prefix then mismatch
    let a = vec_from_str("aaaaab");
    let b = vec_from_str("aaaaac");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("aaaaa");
    assert_eq_vec(&res, &exp);
    if res.len() < a.len() && res.len() < b.len() {
        assert!(a[res.len()] != b[res.len()]);
    }

    // 8: Second shorter, equal to prefix
    let a = vec_from_str("abcde");
    let b = vec_from_str("ab");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("ab");
    assert_eq_vec(&res, &exp);
    assert!(res.len() == b.len());

    // 9: Unicode characters
    let a = vec_from_str("αβγ");
    let b = vec_from_str("αβδ");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("αβ");
    assert_eq_vec(&res, &exp);
    if res.len() < a.len() && res.len() < b.len() {
        assert!(a[res.len()] != b[res.len()]);
    }

    // 10: Case sensitivity
    let a = vec_from_str("Rust");
    let b = vec_from_str("rustacean");
    let res = longest_common_prefix(&a, &b);
    let exp = vec_from_str("");
    assert_eq_vec(&res, &exp);
    if res.len() < a.len() && res.len() < b.len() {
        assert!(a[res.len()] != b[res.len()]);
    }
}

