verus! {

spec fn max_array_precond(a: &Vec<i32>) -> bool {
    a.len() > 0
}

spec fn usize_to_int(x: usize) -> int { x as int }

fn max_array(a: &Vec<i32>) -> (result: i32)
    requires max_array_precond(a),
    ensures
        forall|k: int| 0 <= k < a.len() ==> result >= a[k],
        exists|k: int| 0 <= k < a.len() && result == a[k],
{
    let mut i: usize = 1;
    let mut max: i32 = a[0];
    let mut idx: usize = 0;
    while i < a.len()
        invariant
            0 <= i as int && i as int <= a.len() as int,
            forall|k: int| 0 <= k < i as int ==> max >= a[k],
            exists|k: int| 0 <= k < i as int && max == a[k],
        decreases (a.len() as int) - (i as int)
    {
        if a[i] > max {
            max = a[i];
            idx = i;
        }
        i += 1;
    }
    proof {
        assert(i == a.len());
        assert(forall|k: int| 0 <= k < a.len() as int ==> max >= a[k]);
        assert(exists|k: int| 0 <= k < a.len() as int && max == a[k]);
    }
    max
}

fn main() {
    // Happy path: mixed positive values
    let v1 = vec![1, 3, 2, 5, 4];
    let r1 = max_array(&v1);
    assert(r1 == 5);

    // Edge case: single element
    let v2 = vec![42];
    let r2 = max_array(&v2);
    assert(r2 == 42);

    // Duplicates: all equal
    let v3 = vec![7, 7, 7, 7];
    let r3 = max_array(&v3);
    assert(r3 == 7);

    // Negative numbers
    let v4 = vec![-5, -2, -3];
    let r4 = max_array(&v4);
    assert(r4 == -2);

    // Decreasing order
    let v5 = vec![9, 7, 5, 3, 1];
    let r5 = max_array(&v5);
    assert(r5 == 9);

    // Includes i32::MIN and i32::MAX
    let v6 = vec![i32::MIN, 0, i32::MAX, -1];
    let r6 = max_array(&v6);
    assert(r6 == i32::MAX);

    // Boundary near i32::MAX
    let v7 = vec![i32::MAX - 1, i32::MAX - 2];
    let r7 = max_array(&v7);
    assert(r7 == i32::MAX - 1);

    // Mixed with zeros and negatives
    let v8 = vec![0, -1, -1, -1, 0];
