fn main() {
    // Helper to check the shift property when preconditions hold
    fn assert_shift_property(orig: &Vec<i32>, res: &Vec<i32>) {
        assert!(orig.len() > 0, "Precondition violated: input must be non-empty");
        assert_eq!(res.len(), orig.len() - 1);
        for i in 0..res.len() {
            assert_eq!(res[i], orig[i + 1]);
        }
    }

    // Test 1: Single-element input -> empty output
    let a1 = vec![42];
    let r1 = remove_front(&a1);
    assert_eq!(r1.len(), 0);
    assert_eq!(a1.len(), 1); // input is unchanged

    // Test 2: Two elements
    let a2 = vec![5, 7];
    let r2 = remove_front(&a2);
    assert_eq!(r2, vec![7]);
    assert_shift_property(&a2, &r2);

    // Test 3: Multiple elements
    let a3 = vec![1, 2, 3, 4];
    let r3 = remove_front(&a3);
    assert_eq!(r3, vec![2, 3, 4]);
    assert_shift_property(&a3, &r3);

    // Test 4: Mix of negative and positive
    let a4 = vec![-1, 0, 1];
    let r4 = remove_front(&a4);
    assert_eq!(r4, vec![0, 1]);
    assert_shift_property(&a4, &r4);

    // Test 5: Boundary values for i32
    let a5 = vec![i32::MIN, 0, i32::MAX];
    let r5 = remove_front(&a5);
    assert_eq!(r5, vec![0, i32::MAX]);
    assert_shift_property(&a5, &r5);

    // Test 6: Duplicates
    let a6 = vec![3, 3, 3];
    let r6 = remove_front(&a6);
    assert_eq!(r6, vec![3, 3]);
    assert_shift_property(&a6, &r6);

    // Test 7: Input remains unchanged
    let a7 = vec![9, 10, 11];
    let r7 = remove_front(&a7);
    assert_eq!(a7, vec![9, 10, 11]);
    assert_shift_property(&a7, &r7);

    // Test 8: Edge case (invalid per precondition) - empty input should panic
    // Demonstrates that calling with empty input violates the precondition and results in a panic.
    let result = panic::catch_unwind(|| {
        let _ = remove_front(&vec![]);
    });
    assert!(result.is_err());
}

