fn replace(arr: &Vec<i32>, k: i32) -> Vec<i32> {
    let mut res: Vec<i32> = Vec::with_capacity(arr.len());
    for &a in arr.iter() {
        if a > k {
            res.push(-1);
        } else {
            res.push(a);
        }
    }
    res
}

fn main() {
    // 1. Empty array
