    let k2 = 5;
    assert_eq!(replace(&arr2, k2), vec![3]);

    // 3. Single element equal to threshold
    let arr3 = vec![5];
    let k3 = 5;
    assert_eq!(replace(&arr3, k3), vec![5]);

    // 4. Single element greater than threshold
    let arr4 = vec![7];
    let k4 = 5;
