use std::i32;

fn triple(x: i32) -> i32 {
    // Precondition (from specification): x * 3 must not overflow i32.
    // Here we assume callers satisfy it; tests will assert this before calling.
    3 * x
}

fn check(x: i32) {
    assert!(x.checked_mul(3).is_some(), "Precondition violated: 3*x would overflow i32");
    let r = triple(x);
    // Postconditions
    assert_eq!(r / 3, x, "r/3 should equal the original input");
    assert_eq!((r / 3) * 3, r, "(r/3)*3 should reconstruct r");
    // Direct correctness
    assert_eq!(r, 3 * x, "Result should be exactly three times the input");
}

fn main() {
    // Happy path
    check(0);
    check(1);
    check(7);
    check(-1);
    check(-10);

    // Boundary values that satisfy the precondition
    // Maximum positive x that does not overflow when multiplied by 3
    let max_safe_pos = i32::MAX / 3; // 715,827,882
    check(max_safe_pos);

    // Just below the maximum safe positive
    check(max_safe_pos - 1); // 715,827,881

    // Minimum (most negative) x that still allows 3*x in range
    let min_safe_neg = i32::MIN / 3; // -715,827,882 (truncation toward zero)
    check(min_safe_neg);

    // Another safe negative value near the boundary
    check(min_safe_neg + 1); // -715,827,881
}

