    // Enforce preconditions as runtime checks for testing
    assert!(a.len() <= 100, "length must be <= 100");
    assert!(a.len() == b.len(), "arrays must have equal length");
    for i in 0..a.len() {
        assert!(a[i] + b[i] < 1000, "element-wise sum must be < 1000");
    }

    let mut c = Vec::with_capacity(a.len());
    let mut n: usize = 0;
    let len: usize = a.len();
    while n != len {
        let s = a[n] + b[n];
        c.push(s);
        n += 1;
    }
    c
}

fn main() {
    // Test 1: Empty arrays
    let a1: Vec<u32> = vec![];
    let b1: Vec<u32> = vec![];
    let c1 = sum(&a1, &b1);
    assert_eq!(c1, vec![]);

    // Test 2: Single element
    let a2 = vec![1u32];
    let b2 = vec![2u32];
    let c2 = sum(&a2, &b2);
    assert_eq!(c2, vec![3]);

    // Test 3: Multiple elements, typical values
    let a3 = vec![10, 20, 30, 40, 50];
    let b3 = vec![1, 2, 3, 4, 5];
    let c3 = sum(&a3, &b3);
    assert_eq!(c3, vec![11, 22, 33, 44, 55]);

    // Test 4: All zeros
    let a4 = vec![0, 0, 0, 0];
    let b4 = vec![0, 0, 0, 0];
    let c4 = sum(&a4, &b4);
    assert_eq!(c4, vec![0, 0, 0, 0]);

    // Test 5: Boundary on length (100), sums near upper limit
    let a5 = vec![500u32; 100];
    let b5 = vec![499u32; 100];
    let c5 = sum(&a5, &b5);
    assert_eq!(c5.len(), 100);
    for i in 0..100 {
        assert_eq!(c5[i], 999);
    }

    // Test 6: Mixed near boundary values
    let a6 = vec![999, 0, 100, 700, 300, 450];
    let b6 = vec![0, 999, 899, 200, 699, 549 - 450]; // sums: 999, 999, 999, 900, 999, 99
    let c6 = sum(&a6, &b6);
    assert_eq!(c6, vec![999, 999, 999, 900, 999, 99]);

    // Test 7: Varied small numbers
    let a7 = vec![3, 5, 7, 11, 13, 17, 19];
    let b7 = vec![2, 4, 6, 8, 10, 12, 14];
    let c7 = sum(&a7, &b7);
    assert_eq!(c7, vec![5, 9, 13, 19, 23, 29, 33]);

    // Test 8: Length just below boundary, all sums under 1000
    let n8 = 99usize;
    let a8 = vec![250u32; n8];
    let b8 = vec![200u32; n8];
    let c8 = sum(&a8, &b8);
    assert_eq!(c8.len(), n8);
    for i in 0..n8 {
        assert_eq!(c8[i], 450);
    }
}

