use vstd::prelude::*;

verus! {

spec fn divides(factor: nat, candidate: nat) -> bool {
    candidate % factor == 0
}

spec fn is_prime(candidate: nat) -> bool {
    &&& 1 < candidate
    &&& forall|factor: nat| 1 < factor && factor < candidate ==> !divides(factor, candidate)
}

fn test_prime(candidate: u64) -> (result: bool)
    requires
        1 < candidate,
    ensures
        result == is_prime(candidate as nat),
{
    let mut factor: u64 = 2;
    while factor < candidate
        invariant
            1 < factor <= candidate,
            forall|smallerfactor: nat|
                1 < smallerfactor < factor ==> !divides(smallerfactor, candidate as nat),
        decreases
            candidate - factor
    {
        if candidate % factor == 0 {
            assert(divides(factor as nat, candidate as nat));
            assert(!is_prime(candidate as nat));
            return false;
        }
        factor = factor + 1;
    }
    true
}

fn main() {
    // Happy Path and boundary tests (all satisfy candidate > 1)
    assert(test_prime(2));       // 2 is prime
    assert(test_prime(3));       // 3 is prime
    assert(!test_prime(4));      // 4 = 2*2 is not prime
    assert(test_prime(5));       // 5 is prime
    assert(!test_prime(9));      // 9 = 3*3 is not prime
    assert(!test_prime(10));     // 10 = 2*5 is not prime
    assert(test_prime(29));      // 29 is prime
    assert(test_prime(97));      // 97 is prime
    assert(!test_prime(121));    // 121 = 11*11 is not prime
    assert(!test_prime(289));    // 289 = 17*17 is not prime
}

} // verus!

