fn make_vec(len: i32) -> Vec<i32>
    requires
        len >= 0,
    ensures
        result.len() == len,
{
    let mut v: Vec<i32> = Vec::new();
    let mut i: i32 = 0;
    while i < len
        invariant
            0 <= i <= len,
            v.len() == i as usize,
        decreases (len - i) as int
    {
        v.push(0);
        i = i + 1;
    }
    v
}

fn expected_sum_excluding_first(N: i32) -> i32
    requires N > 0,
{
    // Computes sum_{i=1}^{N-1} (i mod 3)
    let m = N - 1;
    let t = m / 3;      // number of complete triples
    let r = m % 3;      // remainder (0,1,2)
    let mut sum = t * 3; // each complete triple contributes 0+1+2 = 3
    if r == 0 {
        // nothing to add
    } else if r == 1 {
        sum = sum + 1; // add the '1' from the next partial triple
    } else {
        // r == 2: add 1 + 2 = 3
        sum = sum + 3;
    }
    sum
}

fn test_case(N: i32) {
    // Precondition setup: a.len() == N, sum.len() == 1, 0 < N < 1000
    let mut a = make_vec(N);
    let mut s = make_vec(1);

    myfun(&mut a, &mut s, N);

    // Basic properties
    assert(a.len() == N);
    assert(s.len() == 1);
