use std::cmp::min;

// Reference implementation consistent with the described behavior
pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Preconditions (mimic requires)
    assert!(N > 0, "Precondition violated: N must be > 0");
    assert!(N < 1000, "Precondition violated: N must be < 1000");
    assert!(a.len() as i32 == N, "Precondition violated: a.len() must equal N");
    assert!(sum.len() == 1, "Precondition violated: sum.len() must be 1");

    // Initialize accumulator
    sum[0] = 0;

    // First pass: set all elements to 3
    let mut i: usize = 0;
    while i < N as usize {
        a[i] = 3;
        i += 1;
    }

    // Second pass: sum up the elements
    i = 0;
    while i < N as usize {
        if a[i] == 3 {
            sum[0] = sum[0] + a[i];
        } else {
            sum[0] = sum[0] * a[i];
        }
        i += 1;
    }
}

fn assert_all_threes(v: &Vec<i32>) {
    assert!(v.iter().all(|&x| x == 3), "Vector is not all 3s: {:?}", v);
}

fn main() {
    // Test 1: Happy path, arbitrary initial values
    {
        let N = 5;
        let mut a = vec![10, 20, 30, 40, 50];
        let mut sum = vec![0];
        myfun(&mut a, &mut sum, N);
        assert_eq!(sum[0], 3 * N);
        assert_all_threes(&a);
    }

    // Test 2: Single element (edge case N=1)
    {
        let N = 1;
        let mut a = vec![42];
        let mut sum = vec![7]; // initial value should be ignored (reset inside)
        myfun(&mut a, &mut sum, N);
        assert_eq!(sum[0], 3 * N);
        assert_all_threes(&a);
    }

    // Test 3: Mixed initial negatives and zeros
    {
        let N = 2;
        let mut a = vec![-1, 0];
        let mut sum = vec![1000];
        myfun(&mut a, &mut sum, N);
        assert_eq!(sum[0], 3 * N);
        assert_all_threes(&a);
    }

    // Test 4: Boundary near upper limit (N = 999)
    {
        let N = 999;
        let mut a = vec![0; N as usize];
        let mut sum = vec![0];
        myfun(&mut a, &mut sum, N);
        assert_eq!(sum[0], 3 * N);
        assert_all_threes(&a);
    }

