use std::iter::repeat;

// Reference implementation consistent with the specification.
// Preconditions (asserted):
// - N > 0
// - a.len() == N
// - sum.len() == 1
// Postcondition (checked by tests):
// - For all k in 0..N, a[k] == N
fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    assert!(N > 0, "Precondition violated: N must be > 0");
    assert!(a.len() as i32 == N, "Precondition violated: a.len() must equal N");
    assert!(sum.len() == 1, "Precondition violated: sum.len() must be 1");

    // First phase: set sum[0] to N via counting
    sum[0] = 0;
    let mut i: usize = 0;
    while i < N as usize {
        sum[0] += 1;
        i += 1;
    }

    // Second phase: fill a with N using sum[0]
    i = 0;
    while i < N as usize {
        a[i] = sum[0];
        i += 1;
    }
}

fn assert_all_eq(a: &Vec<i32>, x: i32) {
    assert!(a.iter().all(|&v| v == x), "Array not filled with the expected value {}: {:?}", x, a);
}

fn main() {
    // Test 1: Smallest valid N (boundary case)
    {
        let N = 1;
        let mut a = vec![123];
        let mut sum = vec![7];
        myfun(&mut a, &mut sum, N);
        assert_eq!(a.len() as i32, N);
        assert_all_eq(&a, N);
