    assert!(N < 1000, "Precondition failed: N must be < 1000");
    assert!(a.len() == N as usize, "Precondition failed: a.len() == N");
    assert!(b.len() == N as usize, "Precondition failed: b.len() == N");
    assert!(sum.len() == 1, "Precondition failed: sum.len() == 1");

    // Implementation consistent with the specification:
    sum[0] = 0;
    for i in 0..(N as usize) {
        a[i] = 1;
    }
    for i in 0..(N as usize) {
        sum[0] += a[i];
    }
    for i in 0..(N as usize) {
        a[i] = a[i] + sum[0]; // a[i] becomes N + 1
    }
    for i in 0..(N as usize) {
        b[i] = a[i] + 1; // b[i] becomes N + 2
    }
}

fn assert_all_equal(xs: &Vec<i32>, val: i32) {
    assert!(xs.iter().all(|&x| x == val), "not all elements equal to {}: {:?}", val, xs);
