use vstd::prelude::*;

verus! {

spec fn count_boolean(seq: Seq<bool>) -> int
    decreases seq.len(),
{
    if seq.len() == 0 {
        0
    } else {
        count_boolean(seq.drop_last()) + if (seq.last()) {
            1 as int
        } else {
            0 as int
        }
    }
}

fn count_true(arr: &Vec<bool>) -> (count: u64)
    ensures
        0 <= count <= arr.len(),
        count_boolean(arr@) == count,
{
    let mut index = 0;
    let mut counter = 0;

    while index < arr.len()
        invariant
            0 <= index <= arr.len(),
            0 <= counter <= index,
            count_boolean(arr@.subrange(0, index as int)) == counter,
        decreases
            arr.len() - index
    {
        if (arr[index]) {
            counter += 1;
        }
        index += 1;
        assert(arr@.subrange(0, index - 1 as int) == arr@.subrange(0, index as int).drop_last());

    }
    assert(arr@ == arr@.subrange(0, index as int));
    counter
}

} // verus!

fn main() {
    // Happy path
    let v1 = vec![true, false, true];
    let c1 = count_true(&v1);
    assert_eq!(c1, 2);
    assert!((c1 as usize) <= v1.len());

    let v2 = vec![false, false];
    let c2 = count_true(&v2);
    assert_eq!(c2, 0);
    assert!((c2 as usize) <= v2.len());

    let v3 = vec![true, true, true];
