    assert_eq!(c5, 1);
    assert!((c5 as usize) <= v5.len());

    let v6 = vec![false];
    let c6 = count_true(&v6);
    assert_eq!(c6, 0);
    assert!((c6 as usize) <= v6.len());

    // Larger mixed input
    let mut v7: Vec<bool> = Vec::new();
    for i in 0..100 {
        v7.push(i % 2 == 0); // true at even indices
    }
    let expected7 = 50u64; // 0..99 has 50 even positions
