use std::i64;

fn sum_negatives(arr: &Vec<i64>) -> i128 {
    let mut sum: i128 = 0;
    for &x in arr.iter() {
        if x < 0 {
            sum += x as i128;
        }
    }
    sum
}

fn main() {
    // Provided examples
    assert_eq!(sum_negatives(&vec![2, 4, -6, -9, 11, -12, 14, -5, 17]), -32);
    assert_eq!(sum_negatives(&vec![10, 15, -14, 13, -18, 12, -20]), -52);
    assert_eq!(sum_negatives(&vec![19, -65, 57, 39, 152, -639, 121, 44, 90, -190]), -894);

    // Edge cases
    assert_eq!(sum_negatives(&vec![]), 0); // empty list
    assert_eq!(sum_negatives(&vec![1, 2, 3, 4, 5]), 0); // all positives
    assert_eq!(sum_negatives(&vec![-1]), -1); // single negative

    // Mixed with zeros
    assert_eq!(sum_negatives(&vec![0, -3, 0, -2, 5, -1]), -6);

    // Boundary values and constraint boundaries
    assert_eq!(sum_negatives(&vec![i64::MIN, -1, i64::MAX]), (i64::MIN as i128) + (-1i128));
    assert_eq!(sum_negatives(&vec![i64::MIN, i64::MIN]), (i64::MIN as i128) * 2);

    // Additional mixed case
    assert_eq!(sum_negatives(&vec![-100, -200, 300, -400, 500, -600]), -1300);
}

