fn sum_negatives(arr: &Vec<i64>) -> (sum_neg: i128)
    ensures
        sum_negative_to(arr@) == sum_neg,
{
    let mut index = 0;
    let mut sum_neg = 0i128;

    while index < arr.len()
        invariant
            0 <= index <= arr.len(),
            forall|j: int|
                0 <= j <= index ==> (i64::MIN * index <= (sum_negative_to(
                    #[trigger] arr@.subrange(0, j),
