use std::vec::Vec;

fn count_identical_position(arr1: &Vec<i32>, arr2: &Vec<i32>, arr3: &Vec<i32>) -> usize {
    // Precondition: arrays must have equal length
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have equal length");
    assert_eq!(arr2.len(), arr3.len(), "Input arrays must have equal length");

    let mut count: usize = 0;
    for i in 0..arr1.len() {
        if arr1[i] == arr2[i] && arr2[i] == arr3[i] {
            count += 1;
        }
    }
    count
}

fn main() {
    // Happy path tests from the prompt
    assert_eq!(
        count_identical_position(
            &vec![1, 2, 3, 4, 5, 6, 7, 8],
            &vec![2, 2, 3, 1, 2, 6, 7, 9],
            &vec![2, 1, 3, 1, 2, 6, 7, 9]
        ),
        3
    );
    assert_eq!(
        count_identical_position(
            &vec![1, 2, 3, 4, 5, 6, 7, 8],
            &vec![2, 2, 3, 1, 2, 6, 7, 8],
            &vec![2, 1, 3, 1, 2, 6, 7, 8]
        ),
        4
    );
    assert_eq!(
        count_identical_position(
            &vec![1, 2, 3, 4, 2, 6, 7, 8],
            &vec![2, 2, 3, 1, 2, 6, 7, 8],
            &vec![2, 1, 3, 1, 2, 6, 7, 8]
        ),
        5
    );

    // All arrays identical -> count equals length
    assert_eq!(
        count_identical_position(
            &vec![10, 20, 30, 40, 50],
            &vec![10, 20, 30, 40, 50],
            &vec![10, 20, 30, 40, 50]
        ),
        5
    );

    // No positions with triple equality
    assert_eq!(
        count_identical_position(
            &vec![0, 1, 2, 3],
            &vec![1, 2, 3, 4],
            &vec![2, 3, 4, 5]
        ),
        0
    );

    // Empty arrays (edge case)
    assert_eq!(
        count_identical_position(
            &vec![],
            &vec![],
            &vec![]
        ),
        0
    );

    // Single-element arrays: equal
    assert_eq!(
        count_identical_position(
            &vec![42],
            &vec![42],
            &vec![42]
        ),
        1
    );

    // Single-element arrays: not all equal
    assert_eq!(
        count_identical_position(
            &vec![1],
            &vec![2],
            &vec![1]
        ),
        0
    );

    // Mixed values with some equal positions
    assert_eq!(
        count_identical_position(
            &vec![5, 7, 7, 8, 9, 10],
            &vec![5, 6, 7, 0, 9, 11],
            &vec![5, 7, 7, 1, 9, 12]
        ),
        3
    );
}

