fn max_difference(arr: &Vec<i32>) -> i32 {
    assert!(!arr.is_empty(), "Array must be non-empty.");
    // Ensure elements satisfy the specified bounds to avoid overflow
    for &x in arr.iter() {
        assert!(x > i32::MIN / 2 && x < i32::MAX / 2, "Element out of allowed range");
    }

    let mut min_val = arr[0];
    let mut max_val = arr[0];
    for &x in arr.iter().skip(1) {
        if x < min_val {
            min_val = x;
        }
        if x > max_val {
            max_val = x;
        }
    }
    max_val - min_val
}

fn main() {
    // Happy path tests
    assert_eq!(max_difference(&vec![2, 1, 5, 3]), 4); // max=5, min=1
    assert_eq!(max_difference(&vec![9, 3, 2, 5, 1]), 8); // max=9, min=1
    assert_eq!(max_difference(&vec![3, 2, 1]), 2); // max=3, min=1

    // Edge cases
    assert_eq!(max_difference(&vec![42]), 0); // single element => 0
    assert_eq!(max_difference(&vec![5, 5, 5, 5]), 0); // all equal => 0

    // Mixed negatives and positives
    assert_eq!(max_difference(&vec![-100, 0, 50, -50, 25]), 150); // max=50, min=-100

    // All negatives
    assert_eq!(max_difference(&vec![-10, -20, -30]), 20); // max=-10, min=-30

    // Large values within the allowed half-range bounds
    assert_eq!(max_difference(&vec![1_000_000_000, -1_000_000_000]), 2_000_000_000);

    // Near the strict bounds (still within (i32::MIN/2, i32::MAX/2))
    assert_eq!(
        max_difference(&vec![1_073_741_822, -1_073_741_822, 0]),
        2_147_483_644
    );
}

