use std::fmt::Debug;

fn remove_chars(str1: &[u8], str2: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    for &b in str1 {
        if !str2.contains(&b) {
            out.push(b);
        }
    }
    out
}

fn contains(str: &[u8], key: u8) -> bool {
    for &b in str {
        if b == key {
            return true;
        }
    }
    false
}

fn main() {
    // Happy paths from prompt
    assert_eq!(remove_chars(b"probasscurve", b"pros"), b"bacuve");
    assert_eq!(remove_chars(b"digitalindia", b"talent"), b"digiidi");
    assert_eq!(remove_chars(b"exoticmiles", b"toxic"), b"emles");

    // Edge cases: empty inputs
    assert_eq!(remove_chars(b"", b"anything"), b"");
    assert_eq!(remove_chars(b"anything", b""), b"anything");
    assert_eq!(remove_chars(b"", b""), b"");

    // Constraint boundaries and additional cases
    // All characters removed
    assert_eq!(remove_chars(b"aaaa", b"a"), b"");
    assert_eq!(remove_chars(b"abc", b"abc"), b"");

    // No overlap (nothing removed)
    assert_eq!(remove_chars(b"abc", b"xyz"), b"abc");

    // Duplicates retained when not forbidden
    assert_eq!(remove_chars(b"aabbcc", b"c"), b"aabb");

    // Mixed punctuation and digits
    assert_eq!(remove_chars(b"Rust-123!", b"-!"), b"Rust123");

    // Non-printable byte
    assert_eq!(remove_chars(b"\0\0ab", b"\0"), b"ab");

    // Validate contains helper
    assert!(contains(b"hello", b'l'));
    assert!(!contains(b"hello", b'z'));
}

