use std::cmp::Ordering;

fn contains(arr: &Vec<i32>, key: i32) -> bool {
    arr.iter().any(|&x| x == key)
}

fn shared_elements(list1: &Vec<i32>, list2: &Vec<i32>) -> Vec<i32> {
    let mut shared = Vec::new();
