    assert_eq!(intersection(&vec![1, 2, 2, 3, 3, 3, 4], &vec![2, 3, 5, 3, 2]), vec![2, 3]);

    // Negative values and zero
    assert_eq!(intersection(&vec![-3, -1, 0, 1], &vec![-1, 1, 2]), vec![-1, 1]);

