fn element_wise_division(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Enforce the specified assumptions for testing
    assert_eq!(arr1.len(), arr2.len(), "arrays must have equal length");
    assert!(arr2.iter().all(|&x| x != 0), "divisors must be non-zero");
    // Each quotient fits in u32 by Rust's semantics for u32 division.
    arr1.iter().zip(arr2.iter()).map(|(&a, &b)| a / b).collect()
}

fn main() {
    // Happy paths (from the prompt samples)
    assert_eq!(
        element_wise_division(&vec![10, 4, 6, 9], &vec![5, 2, 3, 3]),
        vec![2, 2, 2, 3]
    );
    assert_eq!(
        element_wise_division(&vec![12, 6, 8, 16], &vec![6, 3, 4, 4]),
        vec![2, 2, 2, 4]
    );
    assert_eq!(
        element_wise_division(&vec![20, 14, 36, 18], &vec![5, 7, 6, 9]),
        vec![4, 2, 6, 2]
    );

    // Edge case: empty arrays
    let empty: Vec<u32> = vec![];
    assert_eq!(element_wise_division(&empty, &empty), vec![]);

    // Single-element input, zero dividend
    assert_eq!(element_wise_division(&vec![0], &vec![7]), vec![0]);

    // Dividing by ones preserves the original values
    assert_eq!(
        element_wise_division(&vec![1, 2, 3, 4], &vec![1, 1, 1, 1]),
        vec![1, 2, 3, 4]
    );

    // Large values and boundary behavior
    assert_eq!(
        element_wise_division(&vec![u32::MAX, u32::MAX - 1, 1, 0], &vec![1, 2, 1, 1]),
        vec![u32::MAX, (u32::MAX - 1) / 2, 1, 0]
    );

    // Truncation behavior of integer division
    assert_eq!(element_wise_division(&vec![7, 9], &vec![2, 4]), vec![3, 2]);

    // Additional mixed values
    assert_eq!(
        element_wise_division(&vec![15, 100, 27, 1, 42], &vec![3, 25, 5, 1, 7]),
        vec![5, 4, 5, 1, 6]
    );
}

