    );

    // Happy path: clear maximum at the end (two lists)
    assert_eq!(
        max_length_list(&(vec![vec![5], vec![15, 20, 25]])),
        &vec![15, 20, 25]
    );

    // Edge case: single inner list
    assert_eq!(
        max_length_list(&(vec![vec![42, 43]])),
        &vec![42, 43]
    );

    // Edge case: includes empty inner lists
    assert_eq!(
        max_length_list(&(vec![vec![], vec![1], vec![], vec![2, 3, 4]])),
        &vec![2, 3, 4]
