    assert_eq!(count_uppercase(b"A1!zZ"), 2); // A, Z
    assert_eq!(count_uppercase(b"@AZ[az]"), 2); // only A and Z counted

    // Non-ASCII bytes (ensure they are not counted unless in 65..=90)
    let data = vec![200u8, 65u8, 90u8, 91u8]; // 200 (non-ASCII), 'A'(65), 'Z'(90), '['(91)
