use std::fmt::Debug;

fn to_lowercase(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(input.len());
    for &b in input {
        if (b'A'..=b'Z').contains(&b) {
            out.push(b + 32);
        } else {
            out.push(b);
        }
    }
    out
