    assert_eq_bytes(to_lowercase(b""), b""); // empty input
    assert_eq_bytes(to_lowercase(b"a"), b"a"); // single lowercase
    assert_eq_bytes(to_lowercase(b"A"), b"a"); // single uppercase

    // Boundary and mixed cases
    assert_eq_bytes(to_lowercase(b"ABCXYZ"), b"abcxyz"); // all uppercase
    assert_eq_bytes(to_lowercase(b"already lower"), b"already lower"); // already lowercase
    assert_eq_bytes(to_lowercase(b"123!@#AZaz"), b"123!@#azaz"); // digits, punctuation, and boundaries
