fn count_frequency(arr: &Vec<i32>, key: i32) -> usize {
    let mut count = 0usize;
    for &x in arr.iter() {
        if x == key {
            count += 1;
        }
    }
    count
}

fn remove_duplicates(arr: &Vec<i32>) -> Vec<i32> {
    let mut out = Vec::new();
    for &x in arr.iter() {
        if count_frequency(arr, x) == 1 {
