    assert_eq!(remove_duplicates(&extreme), vec![i32::MAX]);

    // All elements same, repeated many times
    assert_eq!(remove_duplicates(&vec![42, 42, 42, 42, 42]), vec![]);

    // Multiple duplicates across different counts
