use std::i32;

fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    assert!(s1.len() == s2.len() && s2.len() == s3.len(), "Input arrays must have equal length");
    let n = s1.len();
    // Ensure 3 * n fits in i32 range (mirrors the specification constraint)
    assert!(3usize.checked_mul(n).is_some() && (3usize * n) <= i32::MAX as usize, "3*n must fit in i32 range");

    let mut out = Vec::with_capacity(3 * n);
    for i in 0..n {
        out.push(s1[i]);
        out.push(s2[i]);
        out.push(s3[i]);
    }
    out
}

fn main() {
    // Happy path: example with ascending sequences
    let a1 = vec![1, 2, 3, 4, 5, 6, 7];
    let a2 = vec![10, 20, 30, 40, 50, 60, 70];
    let a3 = vec![100, 200, 300, 400, 500, 600, 700];
    let r = interleave(&a1, &a2, &a3);
    assert_eq!(
        r,
        vec![1, 10, 100, 2, 20, 200, 3, 30, 300, 4, 40, 400, 5, 50, 500, 6, 60, 600, 7, 70, 700]
    );

    // Happy path: small vectors
    let r2 = interleave(&vec![10, 20], &vec![15, 2], &vec![5, 10]);
    assert_eq!(r2, vec![10, 15, 5, 20, 2, 10]);

    // Happy path: mixed order
    let r3 = interleave(&vec![11, 44], &vec![10, 15], &vec![20, 5]);
    assert_eq!(r3, vec![11, 10, 20, 44, 15, 5]);

    // Edge case: empty vectors
    let e1: Vec<i32> = vec![];
    let e2: Vec<i32> = vec![];
    let e3: Vec<i32> = vec![];
    let r_empty = interleave(&e1, &e2, &e3);
    assert!(r_empty.is_empty());

    // Edge case: single element with negative and zero
    let r_single = interleave(&vec![-1], &vec![0], &vec![5]);
    assert_eq!(r_single, vec![-1, 0, 5]);

    // Duplicates across arrays
    let r_dup = interleave(&vec![7, 7, 7], &vec![8, 8, 8], &vec![9, 9, 9]);
    assert_eq!(r_dup, vec![7, 8, 9, 7, 8, 9, 7, 8, 9]);

    // Mixed negative values
    let r_neg = interleave(&vec![-10, -20], &vec![-1, -2], &vec![-100, -200]);
    assert_eq!(r_neg, vec![-10, -1, -100, -20, -2, -200]);

    // Medium length vector
    let r_med = interleave(&vec![3, 1, 4, 1, 5], &vec![9, 2, 6, 5, 3], &vec![5, 8, 9, 7, 9]);
    assert_eq!(r_med, vec![3, 9, 5, 1, 2, 8, 4, 6, 9, 1, 5, 7, 5, 3, 9]);

    // Boundary values in elements (not length)
    let r_bounds = interleave(&vec![i32::MAX, i32::MIN], &vec![0, -1], &vec![-2, 2]);
    assert_eq!(r_bounds, vec![i32::MAX, 0, -2, i32::MIN, -1, 2]);
}

