fn find_dissimilar(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    let mut result = Vec::new();

    // Take unique elements from arr1 that are not in arr2
    for &x in arr1.iter() {
        if !contains(arr2, x) && !contains(&result, x) {
            result.push(x);
        }
    }

    // Then take unique elements from arr2 that are not in arr1 and not already in result
    for &y in arr2.iter() {
        if !contains(arr1, y) && !contains(&result, y) {
