verus! {

spec fn is_divisible(n: int, divisor: int) -> bool {
    (n % divisor) == 0
}

fn prime_num(n: u64) -> (result: bool)
    requires
        n >= 2,
    ensures
        result == (forall|k: int| 2 <= k < n ==> !is_divisible(n as int, k)),
{
    if n <= 1 {
        return false;
    }
    let mut candidate = 2u64;
    while candidate < n
        invariant
            2 <= candidate <= n,
            forall|k: int| 2 <= k < candidate ==> !is_divisible(n as int, k),
        decreases
            n - candidate
    {
        if n % candidate == 0 {
            assert(is_divisible(n as int, candidate as int));
            return false;
        }
        candidate += 1;
    }
    true
}

} // verus!

