    assert!(!prime_num(25));    // composite (5 * 5)
    assert!(!prime_num(49));    // composite (7 * 7)
    assert!(prime_num(97));     // prime
    assert!(!prime_num(1010));  // composite (2 * 5 * 101)
    assert!(prime_num(211));    // prime
}

