use std::cmp;

fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Precondition checks to mirror the specification
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");
    for &d in arr2.iter() {
        assert!(d != 0, "Divisor elements must be nonzero");
    }
    for i in 0..arr1.len() {
        let r = arr1[i] % arr2[i];
        // Remainder must fit within signed 32-bit integer range
        assert!(r <= i32::MAX as u32, "Remainder must fit in i32 range");
    }

    let mut out = Vec::with_capacity(arr1.len());
    for i in 0..arr1.len() {
        out.push(arr1[i] % arr2[i]);
    }
    out
}

fn main() {
    // Happy path examples
    assert_eq!(
        element_wise_module(&vec![10, 4, 5, 6], &vec![5, 6, 7, 5]),
        vec![0, 4, 5, 1]
    );
    assert_eq!(
        element_wise_module(&vec![11, 5, 6, 7], &vec![6, 7, 8, 6]),
        vec![5, 5, 6, 1]
    );
    assert_eq!(
        element_wise_module(&vec![12, 6, 7, 8], &vec![7, 8, 9, 7]),
        vec![5, 6, 7, 1]
    );

    // Edge case: empty arrays
    assert_eq!(element_wise_module(&vec![], &vec![]), vec![]);

    // Edge case: single-element arrays
    assert_eq!(element_wise_module(&vec![5], &vec![2]), vec![1]);

    // Boundary of divisors: all ones (remainder always zero)
    assert_eq!(
        element_wise_module(&vec![0, 1, 2, 3], &vec![1, 1, 1, 1]),
        vec![0, 0, 0, 0]
    );

    // Large values but remainder fits in i32
    // 4294967295 % 2147483648 = 2147483647 (i32::MAX)
    // 2147483648 % 2147483648 = 0
    // 2147483647 % 4294967295 = 2147483647
    assert_eq!(
        element_wise_module(
            &vec![u32::MAX, 2147483648u32, 2147483647u32],
            &vec![2147483648u32, 2147483648u32, 4294967295u32]
        ),
        vec![2147483647u32, 0u32, 2147483647u32]
    );

    // Additional mixed values
    assert_eq!(
        element_wise_module(&vec![100, 200, 300], &vec![7, 13, 17]),
        vec![2, 5, 11]
    );

    println!("All tests passed.");
}

