use std::cmp::min;

fn is_sub_list_at_index(main: &Vec<i32>, sub: &Vec<i32>, idx: usize) -> bool {
    // Assumes sub.len() <= main.len() and 0 <= idx <= main.len() - sub.len().
    if sub.len() > main.len() { return false; }
    if idx > main.len().saturating_sub(sub.len()) { return false; }
    for i in 0..sub.len() {
        if main[idx + i] != sub[i] {
            return false;
        }
    }
    true
}

fn is_sub_list(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Assumes sub.len() <= main.len(). If not, returns false defensively.
    if sub.len() > main.len() { return false; }
    for index in 0..=main.len() - sub.len() {
        if is_sub_list_at_index(main, sub, index) {
            return true;
        }
    }
    false
}

fn main() {
    // Happy path examples
    assert!(!is_sub_list(&vec![2, 4, 3, 5, 7], &vec![3, 7]));
    assert!(is_sub_list(&vec![2, 4, 3, 5, 7], &vec![4, 3]));
    assert!(!is_sub_list(&vec![2, 4, 3, 5, 7], &vec![1, 6]));

    // Edge case: empty sublist is always contained
    assert!(is_sub_list(&vec![1, 2, 3], &vec![]));

    // Sublist equals main list
    assert!(is_sub_list(&vec![1, 2, 3], &vec![1, 2, 3]));
    assert!(is_sub_list(&vec![5], &vec![5]));

    // Sublist at the beginning
    assert!(is_sub_list(&vec![9, 8, 7], &vec![9, 8]));

    // Sublist at the end
    assert!(is_sub_list(&vec![1, 2, 3, 4], &vec![3, 4]));

    // Repeated elements, overlapping potential
    assert!(is_sub_list(&vec![1, 1, 1, 1], &vec![1, 1, 1]));

    // Not present though elements exist in different order
    assert!(!is_sub_list(&vec![2, 4, 3, 5, 7], &vec![2, 3]));

    // Boundary: same length (already tested above), and another small boundary
    assert!(is_sub_list(&vec![0, 0], &vec![0, 0]));
}

