use vstd::prelude::*;

verus! {
    // ASCII --> space=32, comma=44 , dot=46 , colon=58
    spec fn is_space_comma_dot_spec(c: u8) -> bool {
        (c == 32) || (c == 44) || (c == 46)
    }

    fn replace_with_colon(str1: &[u8]) -> (result: Vec<u8>)
        ensures
            str1@.len() == result@.len(),
            forall|k: int|
                0 <= k < result.len() ==> #[trigger] result[k] == (if is_space_comma_dot_spec(str1[k]) {
                    58  //ASCII -> colon=58
                } else {
                    str1[k]
                }),
    {
        let mut result: Vec<u8> = Vec::with_capacity(str1.len());
        let mut index = 0;
        while index < str1.len()
            invariant
                0 <= index <= str1.len(),
                result@.len() == index,
                forall|k: int|
                    0 <= k < index ==> #[trigger] result[k] == (if is_space_comma_dot_spec(str1[k]) {
                        58  //ASCII -> colon=58
                    } else {
                        str1[k]
                    }),
            decreases
                str1.len() - index
        {
            if ((str1[index] == 32) || (str1[index] == 44) || (str1[index] == 46)) {
                result.push(58);  //ASCII -> colon=58
            } else {
                result.push(str1[index]);
            }
            index += 1;
        }
        result
    }
}

fn main() {
    // Happy path examples
    assert_eq!(replace_with_colon(b"Python language, Programming language."), b"Python:language::Programming:language:");
    assert_eq!(replace_with_colon(b"a b c,d e f"), b"a:b:c:d:e:f");
    assert_eq!(replace_with_colon(b"ram reshma,ram rahim"), b"ram:reshma:ram:rahim");

    // Edge cases: empty input
    assert_eq!(replace_with_colon(b""), b"");

    // Single-element inputs
    assert_eq!(replace_with_colon(b" "), b":");
    assert_eq!(replace_with_colon(b","), b":");
    assert_eq!(replace_with_colon(b"."), b":");
    assert_eq!(replace_with_colon(b"x"), b"x");

    // No separators present
    assert_eq!(replace_with_colon(b"hello"), b"hello");

    // All separators mixed
    assert_eq!(replace_with_colon(b" ., ,."), b"::::::");

    // Boundary-adjacent bytes (should remain unchanged)
    assert_eq!(replace_with_colon(b"\x1F!-/0"), b"\x1F!-/0");

    // Non-ASCII bytes (should remain unchanged)
    assert_eq!(replace_with_colon(b"\x80\xFF,."), b"\x80\xFF::");
}

