fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut index: usize = 0;
    while index < arr.len() {
        if arr[index] == target {
            return Some(index);
        }
        index += 1;
    }
    None
}

fn main() {
    // Happy path: duplicates, target appears multiple times
    let a1 = vec![2, 5, 5, 5, 6, 6, 8, 9, 9, 9];
    assert_eq!(find_first_occurrence(&a1, 5), Some(1));

    // Happy path: target appears, first occurrence later
    let a2 = vec![2, 3, 5, 5, 6, 6, 8, 9, 9, 9];
    assert_eq!(find_first_occurrence(&a2, 5), Some(2));

    // Happy path: duplicates with target in middle
    let a3 = vec![1, 2, 3, 4, 5, 6, 6, 8];
    assert_eq!(find_first_occurrence(&a3, 6), Some(5));

    // Target not present
    let a4 = vec![1, 2, 3, 4, 5];
    assert_eq!(find_first_occurrence(&a4, 10), None);

    // Edge case: empty array (vacuously sorted)
    let a5: Vec<i32> = vec![];
    assert_eq!(find_first_occurrence(&a5, 3), None);

    // Edge case: single-element array, target present
    let a6 = vec![7];
    assert_eq!(find_first_occurrence(&a6, 7), Some(0));

    // Edge case: single-element array, target absent
    let a7 = vec![7];
    assert_eq!(find_first_occurrence(&a7, 5), None);

    // Boundary: target at the first position with duplicates
    let a8 = vec![1, 1, 1, 2, 3];
    assert_eq!(find_first_occurrence(&a8, 1), Some(0));

    // Boundary: target at the last position
    let a9 = vec![1, 2, 3, 4, 5, 6];
    assert_eq!(find_first_occurrence(&a9, 6), Some(5));

    // Negative values and duplicates
    let a10 = vec![-5, -3, -3, -1, 0, 2];
    assert_eq!(find_first_occurrence(&a10, -3), Some(1));
}

