fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    if arr.len() <= 1 {
        return true;
    }
    let first = arr[0];
    for &x in &arr[1..] {
        if x != first {
            return false;
        }
    }
    true
}

fn main() {
    // Empty list: vacuously only one distinct element
    assert_eq!(has_only_one_distinct_element(&vec![]), true);

    // Single element: trivially one distinct value
    assert_eq!(has_only_one_distinct_element(&vec![5]), true);

    // All elements equal
    assert_eq!(has_only_one_distinct_element(&vec![1, 1, 1]), true);
    assert_eq!(has_only_one_distinct_element(&vec![0, 0, 0, 0, 0]), true);
    assert_eq!(has_only_one_distinct_element(&vec![-3, -3, -3, -3]), true);

    // Multiple distinct values
    assert_eq!(has_only_one_distinct_element(&vec![1, 2, 1, 2]), false);
    assert_eq!(has_only_one_distinct_element(&vec![7, 7, 7, 8]), false);
    assert_eq!(has_only_one_distinct_element(&vec![8, 7]), false);

    // Large uniform list
    assert_eq!(has_only_one_distinct_element(&vec![42; 100]), true);

    // Differing element appears late
    assert_eq!(has_only_one_distinct_element(&vec![10, 10, 10, 9, 10]), false);
}

