use std::fmt::Debug;

fn contains(arr: &Vec<i32>, key: i32) -> bool {
    for &v in arr.iter() {
        if v == key {
            return true;
        }
    }
    false
}

fn difference(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    let mut result = Vec::new();
    // Include elements from arr1 that are not in arr2, without duplicates
    for &v in arr1.iter() {
        if !contains(arr2, v) && !contains(&result, v) {
            result.push(v);
        }
    }
    // Include elements from arr2 that are not in arr1, without duplicates
    for &v in arr2.iter() {
        if !contains(arr1, v) && !contains(&result, v) {
            result.push(v);
        }
    }
    result
}

fn main() {
    // Happy paths
    assert_eq!(difference(&vec![10, 15, 20, 25, 30, 35, 40], &vec![25, 40, 35]), vec![10, 15, 20, 30]);
    assert_eq!(difference(&vec![1, 2, 3, 4, 5], &vec![6, 7, 1]), vec![2, 3, 4, 5, 6, 7]);
    assert_eq!(difference(&vec![1, 2, 3], &vec![6, 7, 1]), vec![2, 3, 6, 7]);

    // Edge cases: empty collections
    assert_eq!(difference(&vec![], &vec![]), Vec::<i32>::new());
    assert_eq!(difference(&vec![], &vec![1, 1, 2]), vec![1, 2]);
    assert_eq!(difference(&vec![3, 3, 3], &vec![]), vec![3]);

    // Duplicates across lists
    assert_eq!(difference(&vec![1, 1, 2], &vec![2, 2, 3]), vec![1, 3]);
    assert_eq!(difference(&vec![5, 5, 5], &vec![5]), Vec::<i32>::new());

    // Order preservation: first from the first list, then from the second
    assert_eq!(difference(&vec![3, 2, 1], &vec![2, 4]), vec![3, 1, 4]);

    // Boundary values
    assert_eq!(difference(&vec![i32::MIN, 0, i32::MAX], &vec![0]), vec![i32::MIN, i32::MAX]);
    assert_eq!(difference(&vec![1, 2], &vec![0, 1, 2, 3]), vec![0, 3]);

    // contains helper checks
    assert!(contains(&vec![1, 2, 3], 2));
    assert!(!contains(&vec![1, 2, 3], 4));
}

