    // Single-element cases
    assert_eq!(sum(&vec![0]), 0);
    assert_eq!(sum(&vec![42]), 42);
    assert_eq!(sum(&vec![-7]), -7);

    // Boundary values
    assert_eq!(sum(&vec![i64::MAX]), i64::MAX as i128);
    assert_eq!(sum(&vec![i64::MIN]), i64::MIN as i128);
    assert_eq!(sum(&vec![i64::MAX, i64::MAX]), (i64::MAX as i128) * 2);
    assert_eq!(sum(&vec![i64::MIN, i64::MAX]), (i64::MIN as i128) + (i64::MAX as i128));

    // Mixed values
    assert_eq!(sum(&vec![-5, 5, -10, 10, 0]), 0);
    assert_eq!(sum(&vec![1000000000i64, -1000000000i64, 123456789i64, -987654321i64]), (1000000000i128 - 1000000000i128 + 123456789i128 - 987654321i128));
}

