use std::vec::Vec;

fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    assert!(!list.is_empty(), "Precondition violated: outer list must be non-empty");
    let mut min_len = list[0].len();
    for inner in list.iter() {
        if inner.len() < min_len {
            min_len = inner.len();
        }
    }
    min_len
}

fn main() {
    // Happy path examples
    assert_eq!(smallest_list_length(&vec![vec![1], vec![1, 2]]), 1);
    assert_eq!(
        smallest_list_length(&vec![vec![1, 2], vec![1, 2, 3], vec![1, 2, 3, 4]]),
        2
    );
    assert_eq!(smallest_list_length(&vec![vec![3, 3, 3], vec![4, 4, 4, 4]]), 3);

    // Constraint boundary: single inner list
    assert_eq!(smallest_list_length(&vec![vec![10, 20, 30]]), 3);

    // Edge case: inner empty vector present
    assert_eq!(smallest_list_length(&vec![vec![], vec![1, 2, 3]]), 0);

    // Edge case: all inner vectors empty
    assert_eq!(smallest_list_length(&vec![vec![], vec![], vec![]]), 0);

    // All inner vectors same length
    assert_eq!(smallest_list_length(&vec![vec![5], vec![6], vec![7]]), 1);

    // Larger sizes
    assert_eq!(smallest_list_length(&vec![vec![0; 100], vec![1; 50]]), 50);
}

