fn main() {
    // Test 1: Empty array
    let mut v1: Vec<u32> = vec![];
    let n1: u32 = v1.len() as u32; // satisfies n1 == len
    let sum1 = myfun(&mut v1, n1);
    assert!(sum1 == 0);
    assert!(sum1 <= 2 * n1);
    assert!(v1.len() as u32 == n1);
    assert_all_leq_2(&v1);

    // Test 2: Single element <= 2
    let mut v2: Vec<u32> = vec![1];
    let n2: u32 = v2.len() as u32;
    let sum2 = myfun(&mut v2, n2);
    assert!(sum2 == 1);
    assert!(sum2 <= 2 * n2);
    assert!(v2 == vec![1]);
    assert_all_leq_2(&v2);

    // Test 3: Single element > 2 gets capped
    let mut v3: Vec<u32> = vec![3];
    let n3: u32 = v3.len() as u32;
    let sum3 = myfun(&mut v3, n3);
    assert!(sum3 == 2);
    assert!(sum3 <= 2 * n3);
    assert!(v3 == vec![2]);
    assert_all_leq_2(&v3);

    // Test 4: Mixed values
    let mut v4: Vec<u32> = vec![0, 2, 5, 1, 100];
    let n4: u32 = v4.len() as u32;
    let sum4 = myfun(&mut v4, n4);
    assert!(sum4 == 7); // capped array becomes [0, 2, 2, 1, 2]
    assert!(sum4 <= 2 * n4);
    assert!(v4 == vec![0, 2, 2, 1, 2]);
    assert_all_leq_2(&v4);

    // Test 5: All elements greater than 2
    let mut v5: Vec<u32> = vec![10, u32::MAX, 3, 42];
    let n5: u32 = v5.len() as u32;
    let sum5 = myfun(&mut v5, n5);
    assert!(sum5 == 8); // capped to [2, 2, 2, 2]
    assert!(sum5 <= 2 * n5);
    assert!(v5 == vec![2, 2, 2, 2]);
    assert_all_leq_2(&v5);

    // Test 6: Already all equal to 2
    let mut v6: Vec<u32> = vec![2, 2, 2, 2, 2];
    let n6: u32 = v6.len() as u32;
    let sum6 = myfun(&mut v6, n6);
    assert!(sum6 == 10);
    assert!(sum6 <= 2 * n6);
    assert!(v6 == vec![2, 2, 2, 2, 2]);
    assert_all_leq_2(&v6);

    // Test 7: Multiple elements requiring capping
    let mut v7: Vec<u32> = vec![3, 4, 5, 6, 7, 8, 9, 10];
    let n7: u32 = v7.len() as u32;
    let sum7 = myfun(&mut v7, n7);
    assert!(sum7 == 16); // capped to eight 2's
    assert!(sum7 <= 2 * n7);
    assert!(v7 == vec![2, 2, 2, 2, 2, 2, 2, 2]);
    assert_all_leq_2(&v7);

    // Test 8: Mixed with zeros
    let mut v8: Vec<u32> = vec![0, 0, 3, 2, 1, 4, 0];
    let n8: u32 = v8.len() as u32;
    let sum8 = myfun(&mut v8, n8);
