    let x6: Vec<u64> = vec![6, 12, 18];
    let mut y6: Vec<u64> = vec![];
    myfun4(&x6, &mut y6);
    assert_eq_vec(&y6, &vec![6, 12, 18]);

    // 7. No elements divisible by 3
    let x7: Vec<u64> = vec![4, 5, 7, 11];
    let mut y7: Vec<u64> = vec![];
    myfun4(&x7, &mut y7);
    assert_eq_vec(&y7, &vec![]);

    // 8. Longer mixed vector to test ordering preservation
    let x8: Vec<u64> = vec![3, 6, 10, 12, 13, 15, 17, 18, 21, 22, 24];
    let mut y8: Vec<u64> = vec![];
    myfun4(&x8, &mut y8);
    assert_eq_vec(&y8, &vec![3, 6, 12, 15, 18, 21, 24]);
}

