use std::fmt::Debug;

fn remove_all_greater(v: Vec<i32>, e: i32) -> Vec<i32> {
    // A straightforward filtering implementation consistent with the specification.
    v.into_iter().filter(|&x| x <= e).collect()
}

fn assert_vec_eq<T: PartialEq + Debug>(a: Vec<T>, b: Vec<T>) {
    assert_eq!(a, b);
}

fn main() {
    // Edge case: empty input
    let v: Vec<i32> = vec![];
    let e = 5;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![]);

    // Single element: qualifies
    let v = vec![7]; // distinct elements satisfied
    let e = 7;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![7]);

    // Single element: does not qualify
    let v = vec![7];
    let e = 6;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![]);

    // Mixed elements: standard case
    let v = vec![3, 1, 4, 2]; // all distinct
    let e = 2;
    let res = remove_all_greater(v.clone(), e);
    // Only elements <= 2 from v
    assert_vec_eq(res, vec![1, 2]);

    // All elements qualify
    let v = vec![-2, 0, 5]; // all distinct
    let e = 5;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![-2, 0, 5]);

    // No elements qualify
    let v = vec![10, 20, 30]; // all distinct
    let e = 9;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![]);

    // Negative threshold with negative and non-negative numbers
    let v = vec![-5, -1, 0, 2]; // all distinct
    let e = -1;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![-5, -1]);

    // Threshold equals the minimum element
    let v = vec![2, 4, 6, 8]; // all distinct
    let e = 2;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![2]);

    // Threshold equals the maximum element
    let v = vec![2, 4, 6, 8]; // all distinct
    let e = 8;
    let res = remove_all_greater(v.clone(), e);
    assert_vec_eq(res, vec![2, 4, 6, 8]);
}

