use std::u64;

fn reverse(v: &mut Vec<u64>) {
    let n = v.len();
    let mut i: usize = 0;
    while i < n / 2 {
        v.swap(i, n - 1 - i);
        i += 1;
    }
}

fn main() {
    // Edge case: empty vector
    let mut a: Vec<u64> = vec![];
    reverse(&mut a);
    assert_eq!(a, vec![]);

    // Edge case: single element
    let mut b: Vec<u64> = vec![42];
    reverse(&mut b);
    assert_eq!(b, vec![42]);

    // Two elements
    let mut c: Vec<u64> = vec![1, 2];
    reverse(&mut c);
    assert_eq!(c, vec![2, 1]);

    // Odd length
    let mut d: Vec<u64> = vec![1, 2, 3, 4, 5];
    reverse(&mut d);
    assert_eq!(d, vec![5, 4, 3, 2, 1]);

    // Even length
    let mut e: Vec<u64> = vec![10, 20, 30, 40];
    reverse(&mut e);
    assert_eq!(e, vec![40, 30, 20, 10]);

    // Palindromic vector remains the same after reversal
    let mut f: Vec<u64> = vec![7, 8, 8, 7];
    let expected_f = f.clone();
    reverse(&mut f);
    assert_eq!(f, expected_f);

    // Values including boundary u64::MAX
    let mut g: Vec<u64> = vec![0, 1, u64::MAX, 42, 999];
    reverse(&mut g);
    assert_eq!(g, vec![999, 42, u64::MAX, 1, 0]);

    // Larger random-like vector: compare to a computed reversed copy
    let mut h: Vec<u64> = vec![3, 5, 8, 13, 21, 34, 55];
    let expected_h: Vec<u64> = h.iter().cloned().rev().collect();
    reverse(&mut h);
    assert_eq!(h, expected_h);

    // Duplicate-heavy vector
    let mut i: Vec<u64> = vec![9, 9, 9, 9, 9, 9];
    reverse(&mut i);
    assert_eq!(i, vec![9, 9, 9, 9, 9, 9]);
}

