            triangle_is_monotonic(i, (j - 1) as nat);
        }
    }

    fn tail_triangle(n: u32, idx: u32, sum: &mut u32)
        requires
            idx <= n,
            *old(sum) == triangle(idx as nat),
            triangle(n as nat) < 0x1_0000_0000,
        ensures
            *sum == triangle(n as nat),
        decreases 
            n - idx
    {
        if idx < n {
            let idx = idx + 1;
            assert(*sum + idx < 0x1_0000_0000) by {
                triangle_is_monotonic(idx as nat, n as nat);
            }
            *sum = *sum + idx;
            tail_triangle(n, idx, sum);
        }
    }

    // Exec helper to compute triangular numbers safely for testing
    fn tri_exec(n: u32) -> u32 {
        let res = (n as u128) * ((n as u128) + 1) / 2;
        assert!(res < (1u128 << 32));
        res as u32
    }

    fn main() {
        // Test 1: n = 0, idx = 0
        {
            let n: u32 = 0;
            let idx: u32 = 0;
            let mut sum: u32 = tri_exec(idx);
            tail_triangle(n, idx, &mut sum);
            assert!(sum == tri_exec(n));
        }

        // Test 2: n = 1, idx = 0
        {
            let n: u32 = 1;
            let idx: u32 = 0;
            let mut sum: u32 = tri_exec(idx);
            tail_triangle(n, idx, &mut sum);
            assert!(sum == tri_exec(n));
        }

        // Test 3: n = 10, idx = 3 (mid-range start)
        {
            let n: u32 = 10;
            let idx: u32 = 3;
            let mut sum: u32 = tri_exec(idx);
            tail_triangle(n, idx, &mut sum);
            assert!(sum == tri_exec(n));
        }

        // Test 4: n = 1000, idx = 1000 (already at target)
        {
            let n: u32 = 1000;
            let idx: u32 = 1000;
            let mut sum: u32 = tri_exec(idx);
            tail_triangle(n, idx, &mut sum);
            assert!(sum == tri_exec(n));
        }

        // Test 5: n = 50, idx = 49 (single recursive step)
        {
            let n: u32 = 50;
            let idx: u32 = 49;
            let mut sum: u32 = tri_exec(idx);
            tail_triangle(n, idx, &mut sum);
            assert!(sum == tri_exec(n));
        }

        // Test 6: n = 500, idx = 0 (longer tail recursion)
        {
            let n: u32 = 500;
            let idx: u32 = 0;
            let mut sum: u32 = tri_exec(idx);
            tail_triangle(n, idx, &mut sum);
            assert!(sum == tri_exec(n));
        }

        // Test 7: n = 2, idx = 2 (no-op)
        {
            let n: u32 = 2;
            let idx: u32 = 2;
            let mut sum: u32 = tri_exec(idx);
            tail_triangle(n, idx, &mut sum);
            assert!(sum == tri_exec(n));
        }
    }
}

