use vstd::prelude::*;

verus! {
    // The factorize function is assumed to be defined as in the solution.
}

fn is_prime_runtime(x: u8) -> bool {
    if x < 2 { return false; }
    for i in 2..x {
        if x % i == 0 { return false; }
    }
    true
}

fn product(factors: &Vec<u8>) -> u32 {
    let mut p: u32 = 1;
    for &f in factors { p *= f as u32; }
    p
}

fn is_sorted_nondecreasing(factors: &Vec<u8>) -> bool {
    for i in 1..factors.len() {
        if factors[i - 1] > factors[i] { return false; }
    }
    true
}

fn check_factorization(n: u8) {
    let factors = factorize(n);
    assert!(is_sorted_nondecreasing(&factors), "Factors must be in nondecreasing order");
    assert_eq!(product(&factors), n as u32, "Product of factors must equal n");
    for &f in &factors {
        assert!(is_prime_runtime(f), "Each factor must be prime");
        assert!(f >= 2, "Factors must be >= 2");
    }
}

fn main() {
    // Edge case: n = 1 (no prime factors)
    let f1 = factorize(1);
    assert!(f1.is_empty());
    assert!(is_sorted_nondecreasing(&f1));
    assert_eq!(product(&f1), 1);

    // Prime inputs
    let f2 = factorize(2);
    assert_eq!(f2, vec![2]);
    let f3 = factorize(3);
    assert_eq!(f3, vec![3]);
    check_factorization(2);
    check_factorization(3);

    // Small composites
    let f4 = factorize(4);
    assert_eq!(f4, vec![2, 2]);
    check_factorization(4);

    let f6 = factorize(6);
    assert_eq!(f6, vec![2, 3]);
    check_factorization(6);

    let f8 = factorize(8);
    assert_eq!(f8, vec![2, 2, 2]);
    check_factorization(8);

    // Larger composites
    let f60 = factorize(60);
    assert_eq!(f60, vec![2, 2, 3, 5]);
    check_factorization(60);

    // Boundary value: n = 255 (u8::MAX)
    let f255 = factorize(255);
    assert_eq!(f255, vec![3, 5, 17]);
    check_factorization(255);

    // Provided example and another composite
    let f254 = factorize(254);
    assert_eq!(f254, vec![2, 127]);
    check_factorization(254);

    let f100 = factorize(100);
    assert_eq!(f100, vec![2, 2, 5, 5]);
    check_factorization(100);

    println!("All tests passed.");
}

