    // Test 5: N = 5, b[i] = i + 1 for all i => sum = 2*N, a[i] = 2
    let mut a6: Vec<i32> = vec![0; 5];
    let mut b6: Vec<i32> = Vec::with_capacity(5);
    for i in 0..5 { b6.push((i as i32) + 1); }
    let s6 = simple_nested(&mut a6, &b6, 5);
    assert(s6 == 10);
    for i in 0..5 { assert(a6[i] == 2); }

    // Test 6: N = 5, alternating pattern (even: i+1 -> 2, odd: i -> 1)
    let N7: i32 = 5;
    let mut a7: Vec<i32> = vec![0; N7 as usize];
    let mut b7: Vec<i32> = Vec::with_capacity(N7 as usize);
    for i in 0..N7 as usize {
        let val = if i % 2 == 0 { (i as i32) + 1 } else { i as i32 };
        b7.push(val);
    }
    let s7 = simple_nested(&mut a7, &b7, N7);
    assert(s7 == 8); // N + count of (i+1) = 5 + 3 = 8
    for i in 0..N7 as usize {
        let expected = if i % 2 == 0 { 2 } else { 1 };
        assert(a7[i] == expected);
    }

    // Test 7: N = 6, mixed values
    let N8: i32 = 6;
    let mut a8: Vec<i32> = vec![0; N8 as usize];
    let b8: Vec<i32> = vec![1, 1, 2, 4, 4, 6];
    let s8 = simple_nested(&mut a8, &b8, N8);
    assert(s8 == 9);
    let expected8 = vec![2, 1, 1, 2, 1, 2];
    for i in 0..N8 as usize { assert(a8[i] == expected8[i]); }

    // Test 8: N = 3, boundary check within constraints
    let N9: i32 = 3;
    let mut a9: Vec<i32> = vec![0; N9 as usize];
    let b9: Vec<i32> = vec![0, 2, 3];
    let s9 = simple_nested(&mut a9, &b9, N9);
    assert(N9 <= s9 && s9 <= 2 * N9);
    assert(a9 == vec![1, 2, 2]);
}
}

